	[DefineGameNetworkMessageType(GameNetworkMessageSendType.FromServer)]
	public sealed class CultureVoteServer : GameNetworkMessage
	{
		public NetworkCommunicator Peer { get; private set; }

		public BasicCultureObject VotedCulture { get; private set; }

		public CultureVoteTypes VotedType { get; private set; }

		public CultureVoteServer()
		{
		}

		public CultureVoteServer(NetworkCommunicator peer, CultureVoteTypes type, BasicCultureObject culture)
		{
			Peer = peer;
			VotedType = type;
			VotedCulture = culture;
		}

		protected override void OnWrite()
		{
			GameNetworkMessage.WriteNetworkPeerReferenceToPacket(Peer);
			GameNetworkMessage.WriteIntToPacket((int)VotedType, CompressionMission.TeamSideCompressionInfo);
			MBReadOnlyList<BasicCultureObject> objectTypeList = MBObjectManager.Instance.GetObjectTypeList<BasicCultureObject>();
			GameNetworkMessage.WriteIntToPacket((VotedCulture == null) ? (-1) : objectTypeList.IndexOf(VotedCulture), CompressionBasic.CultureIndexCompressionInfo);
		}

		protected override bool OnRead()
		{
			bool bufferReadValid = true;
			Peer = GameNetworkMessage.ReadNetworkPeerReferenceFromPacket(ref bufferReadValid);
			VotedType = (CultureVoteTypes)GameNetworkMessage.ReadIntFromPacket(CompressionMission.TeamSideCompressionInfo, ref bufferReadValid);
			int num = GameNetworkMessage.ReadIntFromPacket(CompressionBasic.CultureIndexCompressionInfo, ref bufferReadValid);
			if (bufferReadValid)
			{
				MBReadOnlyList<BasicCultureObject> objectTypeList = MBObjectManager.Instance.GetObjectTypeList<BasicCultureObject>();
				VotedCulture = ((num < 0) ? null : objectTypeList[num]);
			}
			return bufferReadValid;
		}

		protected override MultiplayerMessageFilter OnGetLogFilter()
		{
			return MultiplayerMessageFilter.Mission;
		}

		protected override string OnGetLogFormat()
		{
			return string.Concat("Culture ", VotedCulture.Name, " has been ", VotedType.ToString().ToLower(), (VotedType == CultureVoteTypes.Ban) ? "ned." : "ed.");
		}
	}
	[DefineGameNetworkMessageType(GameNetworkMessageSendType.FromServer)]
	public sealed class FlagRaisingStatus : GameNetworkMessage
	{
		public float Progress { get; private set; }

		public CaptureTheFlagFlagDirection Direction { get; private set; }

		public float Speed { get; private set; }

		public FlagRaisingStatus()
		{
		}

		public FlagRaisingStatus(float currProgress, CaptureTheFlagFlagDirection direction, float speed)
		{
			Progress = currProgress;
			Direction = direction;
			Speed = speed;
		}

		protected override bool OnRead()
		{
			bool bufferReadValid = true;
			Progress = GameNetworkMessage.ReadFloatFromPacket(CompressionMission.FlagClassicProgressCompressionInfo, ref bufferReadValid);
			Direction = (CaptureTheFlagFlagDirection)GameNetworkMessage.ReadIntFromPacket(CompressionMission.FlagDirectionEnumCompressionInfo, ref bufferReadValid);
			if (bufferReadValid && Direction != CaptureTheFlagFlagDirection.None && Direction != CaptureTheFlagFlagDirection.Static)
			{
				Speed = GameNetworkMessage.ReadFloatFromPacket(CompressionMission.FlagSpeedCompressionInfo, ref bufferReadValid);
			}
			return bufferReadValid;
		}

		protected override void OnWrite()
		{
			GameNetworkMessage.WriteFloatToPacket(Progress, CompressionMission.FlagClassicProgressCompressionInfo);
			GameNetworkMessage.WriteIntToPacket((int)Direction, CompressionMission.FlagDirectionEnumCompressionInfo);
			if (Direction != CaptureTheFlagFlagDirection.None && Direction != CaptureTheFlagFlagDirection.Static)
			{
				GameNetworkMessage.WriteFloatToPacket(Speed, CompressionMission.FlagSpeedCompressionInfo);
			}
		}

		protected override MultiplayerMessageFilter OnGetLogFilter()
		{
			return MultiplayerMessageFilter.GameMode;
		}

		protected override string OnGetLogFormat()
		{
			return string.Concat("Updating flag movement: Progress: ", Progress, ", Direction: ", Direction, ", Speed: ", Speed);
		}
	}
