	[DefineGameNetworkMessageType(GameNetworkMessageSendType.FromServer)]
	public sealed class SyncObjectDestructionLevel : GameNetworkMessage
	{
		public MissionObjectId MissionObjectId { get; private set; }

		public int DestructionLevel { get; private set; }

		public int ForcedIndex { get; private set; }

		public float BlowMagnitude { get; private set; }

		public Vec3 BlowPosition { get; private set; }

		public Vec3 BlowDirection { get; private set; }

		public SyncObjectDestructionLevel(MissionObjectId missionObjectId, int destructionLevel, int forcedIndex, float blowMagnitude, Vec3 blowPosition, Vec3 blowDirection)
		{
			MissionObjectId = missionObjectId;
			DestructionLevel = destructionLevel;
			ForcedIndex = forcedIndex;
			BlowMagnitude = blowMagnitude;
			BlowPosition = blowPosition;
			BlowDirection = blowDirection;
		}

		public SyncObjectDestructionLevel()
		{
		}

		protected override bool OnRead()
		{
			bool bufferReadValid = true;
			MissionObjectId = GameNetworkMessage.ReadMissionObjectIdFromPacket(ref bufferReadValid);
			DestructionLevel = GameNetworkMessage.ReadIntFromPacket(CompressionMission.UsableGameObjectDestructionStateCompressionInfo, ref bufferReadValid);
			ForcedIndex = (GameNetworkMessage.ReadBoolFromPacket(ref bufferReadValid) ? GameNetworkMessage.ReadIntFromPacket(CompressionBasic.MissionObjectIDCompressionInfo, ref bufferReadValid) : (-1));
			BlowMagnitude = GameNetworkMessage.ReadFloatFromPacket(CompressionMission.UsableGameObjectBlowMagnitude, ref bufferReadValid);
			BlowPosition = GameNetworkMessage.ReadVec3FromPacket(CompressionBasic.PositionCompressionInfo, ref bufferReadValid);
			BlowDirection = GameNetworkMessage.ReadVec3FromPacket(CompressionMission.UsableGameObjectBlowDirection, ref bufferReadValid);
			return bufferReadValid;
		}

		protected override void OnWrite()
		{
			GameNetworkMessage.WriteMissionObjectIdToPacket(MissionObjectId);
			GameNetworkMessage.WriteIntToPacket(DestructionLevel, CompressionMission.UsableGameObjectDestructionStateCompressionInfo);
			GameNetworkMessage.WriteBoolToPacket(ForcedIndex != -1);
			if (ForcedIndex != -1)
			{
				GameNetworkMessage.WriteIntToPacket(ForcedIndex, CompressionBasic.MissionObjectIDCompressionInfo);
			}
			GameNetworkMessage.WriteFloatToPacket(BlowMagnitude, CompressionMission.UsableGameObjectBlowMagnitude);
			GameNetworkMessage.WriteVec3ToPacket(BlowPosition, CompressionBasic.PositionCompressionInfo);
			GameNetworkMessage.WriteVec3ToPacket(BlowDirection, CompressionMission.UsableGameObjectBlowDirection);
		}

		protected override MultiplayerMessageFilter OnGetLogFilter()
		{
			return MultiplayerMessageFilter.MissionObjectsDetailed | MultiplayerMessageFilter.SiegeWeaponsDetailed;
		}

		protected override string OnGetLogFormat()
		{
			return string.Concat("Synchronize DestructionLevel: ", DestructionLevel, " of MissionObject with Id: ", MissionObjectId, (ForcedIndex != -1) ? (" (New object will have ID: " + ForcedIndex + ")") : "");
		}
	}
