	[DefineGameNetworkMessageType(GameNetworkMessageSendType.FromServer)]
	public sealed class NotificationMessage : GameNetworkMessage
	{
		public int Message { get; private set; }

		public int ParameterOne { get; private set; }

		public int ParameterTwo { get; private set; }

		private bool HasParameterOne => ParameterOne != -1;

		private bool HasParameterTwo => ParameterOne != -1;

		public NotificationMessage(int message, int param1, int param2)
		{
			Message = message;
			ParameterOne = param1;
			ParameterTwo = param2;
		}

		public NotificationMessage()
		{
		}

		protected override void OnWrite()
		{
			GameNetworkMessage.WriteIntToPacket(Message, CompressionMission.MultiplayerNotificationCompressionInfo);
			GameNetworkMessage.WriteBoolToPacket(HasParameterOne);
			if (HasParameterOne)
			{
				GameNetworkMessage.WriteIntToPacket(ParameterOne, CompressionMission.MultiplayerNotificationParameterCompressionInfo);
				GameNetworkMessage.WriteBoolToPacket(HasParameterTwo);
				if (HasParameterTwo)
				{
					GameNetworkMessage.WriteIntToPacket(ParameterTwo, CompressionMission.MultiplayerNotificationParameterCompressionInfo);
				}
			}
		}

		protected override bool OnRead()
		{
			bool bufferReadValid = true;
			int parameterOne = (ParameterTwo = -1);
			ParameterOne = parameterOne;
			Message = GameNetworkMessage.ReadIntFromPacket(CompressionMission.MultiplayerNotificationCompressionInfo, ref bufferReadValid);
			if (GameNetworkMessage.ReadBoolFromPacket(ref bufferReadValid))
			{
				ParameterOne = GameNetworkMessage.ReadIntFromPacket(CompressionMission.MultiplayerNotificationParameterCompressionInfo, ref bufferReadValid);
				if (GameNetworkMessage.ReadBoolFromPacket(ref bufferReadValid))
				{
					ParameterTwo = GameNetworkMessage.ReadIntFromPacket(CompressionMission.MultiplayerNotificationParameterCompressionInfo, ref bufferReadValid);
				}
			}
			return bufferReadValid;
		}

		protected override MultiplayerMessageFilter OnGetLogFilter()
		{
			return MultiplayerMessageFilter.Messaging;
		}

		protected override string OnGetLogFormat()
		{
			return "Receiving message: " + Message + (HasParameterOne ? (" With first parameter: " + ParameterOne) : "") + (HasParameterTwo ? (" and second parameter: " + ParameterTwo) : "");
		}
	}
	[DefineGameNetworkMessageType(GameNetworkMessageSendType.FromServer)]
	public sealed class RemovePeerComponent : GameNetworkMessage
	{
		public NetworkCommunicator Peer { get; private set; }

		public uint ComponentId { get; private set; }

		public RemovePeerComponent(NetworkCommunicator peer, uint componentId)
		{
			Peer = peer;
			ComponentId = componentId;
		}

		public RemovePeerComponent()
		{
		}

		protected override void OnWrite()
		{
			GameNetworkMessage.WriteNetworkPeerReferenceToPacket(Peer);
			GameNetworkMessage.WriteUintToPacket(ComponentId, CompressionBasic.PeerComponentCompressionInfo);
		}

		protected override bool OnRead()
		{
			bool bufferReadValid = true;
			Peer = GameNetworkMessage.ReadNetworkPeerReferenceFromPacket(ref bufferReadValid);
			ComponentId = GameNetworkMessage.ReadUintFromPacket(CompressionBasic.PeerComponentCompressionInfo, ref bufferReadValid);
			return bufferReadValid;
		}

		protected override MultiplayerMessageFilter OnGetLogFilter()
		{
			return MultiplayerMessageFilter.Peers;
		}

		protected override string OnGetLogFormat()
		{
			return "Remove component with ID: " + ComponentId + " from peer: " + Peer.UserName + " with peer-index: " + Peer.Index;
		}
	}
	[DefineGameNetworkMessageType(GameNetworkMessageSendType.FromServer)]
	public sealed class SynchronizingDone : GameNetworkMessage
	{
		public NetworkCommunicator Peer { get; private set; }

		public bool Synchronized { get; private set; }

		public SynchronizingDone(NetworkCommunicator peer, bool synchronized)
		{
			Peer = peer;
			Synchronized = synchronized;
		}

		public SynchronizingDone()
		{
		}

		protected override bool OnRead()
		{
			bool bufferReadValid = true;
			Peer = GameNetworkMessage.ReadNetworkPeerReferenceFromPacket(ref bufferReadValid);
			Synchronized = GameNetworkMessage.ReadBoolFromPacket(ref bufferReadValid);
			return bufferReadValid;
		}

		protected override void OnWrite()
		{
			GameNetworkMessage.WriteNetworkPeerReferenceToPacket(Peer);
			GameNetworkMessage.WriteBoolToPacket(Synchronized);
		}

		protected override MultiplayerMessageFilter OnGetLogFilter()
		{
			return MultiplayerMessageFilter.General;
		}

		protected override string OnGetLogFormat()
		{
			string text = "peer with name: " + Peer.UserName + ", and index: " + Peer.Index;
			if (!Synchronized)
			{
				return "Synchronized: FALSE for " + text + " (Peer will not receive broadcasted messages)";
			}
			return "Synchronized: TRUE for " + text + " (received all initial data from the server and will now receive broadcasted messages)";
		}
	}
	[DefineGameNetworkMessageType(GameNetworkMessageSendType.FromServer)]
	public sealed class SendVoiceToPlay : GameNetworkMessage
	{
		public NetworkCommunicator Peer { get; private set; }

		public byte[] Buffer { get; private set; }

		public int BufferLength { get; private set; }

		public SendVoiceToPlay()
		{
		}

		public SendVoiceToPlay(NetworkCommunicator peer, byte[] buffer, int bufferLength)
		{
			Peer = peer;
			Buffer = buffer;
			BufferLength = bufferLength;
		}

		protected override void OnWrite()
		{
			GameNetworkMessage.WriteNetworkPeerReferenceToPacket(Peer);
			GameNetworkMessage.WriteByteArrayToPacket(Buffer, 0, BufferLength);
		}

		protected override bool OnRead()
		{
			bool bufferReadValid = true;
			Peer = GameNetworkMessage.ReadNetworkPeerReferenceFromPacket(ref bufferReadValid);
			Buffer = new byte[1440];
			BufferLength = GameNetworkMessage.ReadByteArrayFromPacket(Buffer, 0, 1440, ref bufferReadValid);
			return bufferReadValid;
		}

		protected override MultiplayerMessageFilter OnGetLogFilter()
		{
			return MultiplayerMessageFilter.None;
		}

		protected override string OnGetLogFormat()
		{
			return string.Empty;
		}
	}
