			{
				get
				{
					return index switch
					{
						0 => _element0, 
						1 => _element1, 
						2 => _element2, 
						3 => _element3, 
						4 => _element4, 
						5 => _element5, 
						6 => _element6, 
						7 => _element7, 
						_ => null, 
