		public Mat3 LookRotation
		{
			get
			{
				Mat3 result = default(Mat3);
				result.f = LookDirection;
				result.u = Vec3.Up;
				result.s = Vec3.CrossProduct(result.f, result.u);
				result.s.Normalize();
				result.u = Vec3.CrossProduct(result.s, result.f);
				return result;
			}
		}

