			else if (!GameNetwork.IsClientOrReplay)
			{
				ActionIndexCache actionIndexCache2 = CosmeticsManagerHelper.GetSuitableTauntAction(this, tauntIndex);
				if (actionIndexCache2.Index >= 0)
