	public sealed class BehaviorAdvance : BehaviorComponent
	{
		private bool _isInShieldWallDistance;

		private bool _switchedToShieldWallRecently;

		private TaleWorlds.Core.Timer _switchedToShieldWallTimer;

		private Vec2 _reformPosition = Vec2.Invalid;

		public BehaviorAdvance(Formation formation)
			: base(formation)
		{
			base.BehaviorCoherence = 0.8f;
			_switchedToShieldWallTimer = new TaleWorlds.Core.Timer(0f, 0f);
			CalculateCurrentOrder();
		}

		protected override void CalculateCurrentOrder()
		{
			Formation.FormationIntegrityDataGroup cachedFormationIntegrityData = base.Formation.CachedFormationIntegrityData;
			if (_switchedToShieldWallRecently && !_switchedToShieldWallTimer.Check(Mission.Current.CurrentTime) && cachedFormationIntegrityData.DeviationOfPositionsExcludeFarAgents > cachedFormationIntegrityData.AverageMaxUnlimitedSpeedExcludeFarAgents * 0.5f)
			{
				WorldPosition cachedMedianPosition = base.Formation.CachedMedianPosition;
				if (_reformPosition.IsValid)
				{
					cachedMedianPosition.SetVec2(_reformPosition);
				}
				else
				{
					Vec2 vec = (base.Formation.QuerySystem.Team.MedianTargetFormationPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized();
					_reformPosition = base.Formation.CachedAveragePosition + vec * 5f;
					cachedMedianPosition.SetVec2(_reformPosition);
				}
				base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
				return;
			}
			_switchedToShieldWallRecently = false;
			bool flag = false;
			FormationQuerySystem cachedClosestEnemyFormation = base.Formation.CachedClosestEnemyFormation;
			if (cachedClosestEnemyFormation != null && cachedClosestEnemyFormation.IsCavalryFormation)
			{
				Vec2 vec2 = base.Formation.CachedAveragePosition - cachedClosestEnemyFormation.Formation.CachedAveragePosition;
				float num = vec2.Normalize();
				Vec2 cachedCurrentVelocity = cachedClosestEnemyFormation.Formation.CachedCurrentVelocity;
				float num2 = cachedCurrentVelocity.Normalize();
				if (num < 30f && num2 > 2f && vec2.DotProduct(cachedCurrentVelocity) > 0.5f)
				{
					flag = true;
					WorldPosition cachedMedianPosition2 = base.Formation.CachedMedianPosition;
					if (_reformPosition.IsValid)
					{
						cachedMedianPosition2.SetVec2(_reformPosition);
					}
					else
					{
						Vec2 vec3 = (base.Formation.QuerySystem.Team.MedianTargetFormationPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized();
						_reformPosition = base.Formation.CachedAveragePosition + vec3 * 5f;
						cachedMedianPosition2.SetVec2(_reformPosition);
					}
					base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition2);
				}
			}
			if (flag)
			{
				return;
			}
			_reformPosition = Vec2.Invalid;
			int num3 = 0;
			bool flag2 = false;
			foreach (Team team in Mission.Current.Teams)
			{
				if (!team.IsEnemyOf(base.Formation.Team))
				{
					continue;
				}
				foreach (Formation item in team.FormationsIncludingSpecialAndEmpty)
				{
					if (item.CountOfUnits > 0)
					{
						num3++;
						flag2 = num3 == 1;
						if (num3 > 1)
						{
							break;
						}
					}
				}
			}
			FormationQuerySystem formationQuerySystem = (flag2 ? base.Formation.CachedClosestEnemyFormation : base.Formation.QuerySystem.Team.MedianTargetFormation);
			if (formationQuerySystem != null)
			{
				WorldPosition cachedMedianPosition3 = formationQuerySystem.Formation.CachedMedianPosition;
				cachedMedianPosition3.SetVec2(cachedMedianPosition3.AsVec2 + formationQuerySystem.Formation.Direction * formationQuerySystem.Formation.Depth * 0.5f);
				Vec2 direction = -formationQuerySystem.Formation.Direction;
				base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition3);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(direction);
				return;
			}
			FormationQuerySystem medianTargetFormation = base.Formation.QuerySystem.Team.MedianTargetFormation;
			WorldPosition position = (flag2 ? base.Formation.CachedClosestEnemyFormation.Formation.CachedMedianPosition : ((medianTargetFormation != null) ? base.Formation.QuerySystem.Team.MedianTargetFormationPosition : WorldPosition.Invalid));
			Vec2 direction2 = ((medianTargetFormation != null) ? (base.Formation.QuerySystem.Team.MedianTargetFormationPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized() : Vec2.Invalid);
			if (position.IsValid)
			{
				base.CurrentOrder = MovementOrder.MovementOrderMove(position);
			}
			if (direction2.IsValid)
			{
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(direction2);
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			_isInShieldWallDistance = false;
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (base.Formation.PhysicalClass.IsMeleeInfantry())
			{
				bool flag = false;
				if (base.Formation.CachedClosestEnemyFormation != null && base.Formation.QuerySystem.IsUnderRangedAttack)
				{
					float num = base.Formation.CachedAveragePosition.DistanceSquared(base.Formation.CachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2);
					if (num < 6400f + (_isInShieldWallDistance ? 3600f : 0f) && num > 100f - (_isInShieldWallDistance ? 75f : 0f))
					{
						flag = true;
					}
				}
				if (flag != _isInShieldWallDistance)
				{
					_isInShieldWallDistance = flag;
					if (_isInShieldWallDistance)
					{
						if (base.Formation.QuerySystem.HasShield)
						{
							base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderShieldWall);
						}
						else
						{
							base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLoose);
						}
						_switchedToShieldWallRecently = true;
						_switchedToShieldWallTimer.Reset(Mission.Current.CurrentTime, 5f);
					}
					else
					{
						base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
					}
				}
			}
			base.Formation.SetMovementOrder(base.CurrentOrder);
		}

		protected override float GetAiWeight()
		{
			return 1f;
		}
	}
	public class BehaviorAssaultWalls : BehaviorComponent
	{
		private enum BehaviorState
		{
			Deciding,
			ClimbWall,
			AttackEntity,
			TakeControl,
			MoveToGate,
			Charging,
			Stop
		}

		private BehaviorState _behaviorState;

		private List<IPrimarySiegeWeapon> _primarySiegeWeapons;

		private WallSegment _wallSegment;

		private CastleGate _innerGate;

		private TeamAISiegeComponent _teamAISiegeComponent;

		private MovementOrder _attackEntityOrderInnerGate;

		private MovementOrder _attackEntityOrderOuterGate;

		private MovementOrder _chargeOrder;

		private MovementOrder _stopOrder;

		private MovementOrder _castleGateMoveOrder;

		private MovementOrder _wallSegmentMoveOrder;

		private FacingOrder _facingOrder;

		protected ArrangementOrder CurrentArrangementOrder;

		private bool _isGateLane;

		public override float NavmeshlessTargetPositionPenalty => 1f;

		private void ResetOrderPositions()
		{
			_primarySiegeWeapons = _teamAISiegeComponent.PrimarySiegeWeapons.ToList();
			_primarySiegeWeapons.RemoveAll((IPrimarySiegeWeapon uM) => uM.WeaponSide != _behaviorSide || !(uM is SiegeWeapon siegeWeapon) || (siegeWeapon.IsDeactivated && !siegeWeapon.IsDestroyed && (!(siegeWeapon is IPrimarySiegeWeapon primarySiegeWeapon2) || !primarySiegeWeapon2.HasCompletedAction())));
			IEnumerable<ICastleKeyPosition> source = TeamAISiegeComponent.SiegeLanes.Where((SiegeLane sl) => sl.LaneSide == _behaviorSide).SelectMany((SiegeLane sila) => sila.DefensePoints);
			_innerGate = _teamAISiegeComponent.InnerGate;
			_isGateLane = _teamAISiegeComponent.OuterGate.DefenseSide == _behaviorSide;
			if (_isGateLane)
			{
				_wallSegment = null;
			}
			else if (source.FirstOrDefault((ICastleKeyPosition dp) => dp is WallSegment && (dp as WallSegment).IsBreachedWall) is WallSegment wallSegment)
			{
				_wallSegment = wallSegment;
			}
			else
			{
				IPrimarySiegeWeapon primarySiegeWeapon = _primarySiegeWeapons.MaxBy((IPrimarySiegeWeapon psw) => psw.SiegeWeaponPriority);
				_wallSegment = primarySiegeWeapon.TargetCastlePosition as WallSegment;
			}
			_stopOrder = MovementOrder.MovementOrderStop;
			_chargeOrder = MovementOrder.MovementOrderCharge;
			bool flag = _teamAISiegeComponent.OuterGate != null && _behaviorSide == _teamAISiegeComponent.OuterGate.DefenseSide;
			_attackEntityOrderOuterGate = ((flag && !_teamAISiegeComponent.OuterGate.IsDeactivated && _teamAISiegeComponent.OuterGate.State != 0) ? MovementOrder.MovementOrderAttackEntity(GameEntity.CreateFromWeakEntity(_teamAISiegeComponent.OuterGate.GameEntity), surroundEntity: false) : MovementOrder.MovementOrderStop);
			_attackEntityOrderInnerGate = ((flag && _teamAISiegeComponent.InnerGate != null && !_teamAISiegeComponent.InnerGate.IsDeactivated && _teamAISiegeComponent.InnerGate.State != 0) ? MovementOrder.MovementOrderAttackEntity(GameEntity.CreateFromWeakEntity(_teamAISiegeComponent.InnerGate.GameEntity), surroundEntity: false) : MovementOrder.MovementOrderStop);
			WorldPosition origin = _teamAISiegeComponent.OuterGate.MiddleFrame.Origin;
			_castleGateMoveOrder = MovementOrder.MovementOrderMove(origin);
			if (_isGateLane)
			{
				_wallSegmentMoveOrder = _castleGateMoveOrder;
			}
			else
			{
				WorldPosition origin2 = _wallSegment.MiddleFrame.Origin;
				_wallSegmentMoveOrder = MovementOrder.MovementOrderMove(origin2);
			}
			_facingOrder = FacingOrder.FacingOrderLookAtEnemy;
		}

		public BehaviorAssaultWalls(Formation formation)
			: base(formation)
		{
			base.BehaviorCoherence = 0f;
			_behaviorSide = formation.AI.Side;
			_teamAISiegeComponent = (TeamAISiegeComponent)formation.Team.TeamAI;
			_behaviorState = BehaviorState.Deciding;
			ResetOrderPositions();
			base.CurrentOrder = _stopOrder;
		}

		public override TextObject GetBehaviorString()
		{
			TextObject behaviorString = base.GetBehaviorString();
			TextObject variable = GameTexts.FindText("str_formation_ai_side_strings", base.Formation.AI.Side.ToString());
			behaviorString.SetTextVariable("SIDE_STRING", variable);
			behaviorString.SetTextVariable("IS_GENERAL_SIDE", "0");
			return behaviorString;
		}

		private BehaviorState CheckAndChangeState()
		{
			switch (_behaviorState)
			{
			case BehaviorState.Deciding:
				if (!_isGateLane && _wallSegment == null)
				{
					return BehaviorState.Charging;
				}
				if (_isGateLane)
				{
					if (_teamAISiegeComponent.OuterGate.IsGateOpen && _teamAISiegeComponent.InnerGate.IsGateOpen)
					{
						return BehaviorState.Charging;
					}
					return BehaviorState.AttackEntity;
				}
				return BehaviorState.ClimbWall;
			case BehaviorState.ClimbWall:
			{
				if (_wallSegment == null)
				{
					return BehaviorState.Charging;
				}
				bool flag = false;
				if (_behaviorSide < FormationAI.BehaviorSide.BehaviorSideNotSet)
				{
					SiegeLane siegeLane = TeamAISiegeComponent.SiegeLanes[(int)_behaviorSide];
					flag = siegeLane.IsUnderAttack() && !siegeLane.IsDefended();
				}
				if (flag || base.Formation.CachedMedianPosition.GetNavMeshVec3().DistanceSquared(_wallSegment.MiddleFrame.Origin.GetNavMeshVec3()) < base.Formation.Depth * base.Formation.Depth)
				{
					return BehaviorState.TakeControl;
				}
				return BehaviorState.ClimbWall;
			}
			case BehaviorState.TakeControl:
				if (base.Formation.CachedClosestEnemyFormation != null)
				{
					if (!TeamAISiegeComponent.SiegeLanes.FirstOrDefault((SiegeLane sl) => sl.LaneSide == _behaviorSide).IsDefended())
					{
						if (!_teamAISiegeComponent.OuterGate.IsGateOpen || !_teamAISiegeComponent.InnerGate.IsGateOpen)
						{
							return BehaviorState.MoveToGate;
						}
						return BehaviorState.Charging;
					}
					return BehaviorState.TakeControl;
				}
				return BehaviorState.Stop;
			case BehaviorState.AttackEntity:
				if (_teamAISiegeComponent.OuterGate.IsGateOpen && _teamAISiegeComponent.InnerGate.IsGateOpen)
				{
					return BehaviorState.Charging;
				}
				return BehaviorState.AttackEntity;
			case BehaviorState.MoveToGate:
				if (_teamAISiegeComponent.OuterGate.IsGateOpen && _teamAISiegeComponent.InnerGate.IsGateOpen)
				{
					return BehaviorState.Charging;
				}
				return BehaviorState.MoveToGate;
			case BehaviorState.Charging:
				if ((!_isGateLane || !_teamAISiegeComponent.OuterGate.IsGateOpen || !_teamAISiegeComponent.InnerGate.IsGateOpen) && _behaviorSide < FormationAI.BehaviorSide.BehaviorSideNotSet)
				{
					if (!TeamAISiegeComponent.SiegeLanes[(int)_behaviorSide].IsOpen && !TeamAISiegeComponent.IsFormationInsideCastle(base.Formation, includeOnlyPositionedUnits: true))
					{
						return BehaviorState.Deciding;
					}
					if (base.Formation.CachedClosestEnemyFormation == null)
					{
						return BehaviorState.Stop;
					}
				}
				return BehaviorState.Charging;
			default:
				if (base.Formation.CachedClosestEnemyFormation != null)
				{
					return BehaviorState.Deciding;
				}
				return BehaviorState.Stop;
			}
		}

		protected override void CalculateCurrentOrder()
		{
			switch (_behaviorState)
			{
			case BehaviorState.Deciding:
				base.CurrentOrder = _stopOrder;
				break;
			case BehaviorState.ClimbWall:
				base.CurrentOrder = _wallSegmentMoveOrder;
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(-_wallSegment.MiddleFrame.Rotation.f.AsVec2.Normalized());
				CurrentArrangementOrder = ArrangementOrder.ArrangementOrderLine;
				break;
			case BehaviorState.TakeControl:
				base.CurrentOrder = ((base.Formation.CachedClosestEnemyFormation != null) ? MovementOrder.MovementOrderChargeToTarget(base.Formation.CachedClosestEnemyFormation.Formation) : MovementOrder.MovementOrderCharge);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(-_wallSegment.MiddleFrame.Rotation.f.AsVec2.Normalized());
				CurrentArrangementOrder = ArrangementOrder.ArrangementOrderLine;
				break;
			case BehaviorState.AttackEntity:
				base.CurrentOrder = ((!_teamAISiegeComponent.OuterGate.IsGateOpen) ? _attackEntityOrderOuterGate : _attackEntityOrderInnerGate);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
				CurrentArrangementOrder = ArrangementOrder.ArrangementOrderLine;
				break;
			case BehaviorState.MoveToGate:
				base.CurrentOrder = _castleGateMoveOrder;
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(-_innerGate.MiddleFrame.Rotation.f.AsVec2.Normalized());
				CurrentArrangementOrder = ArrangementOrder.ArrangementOrderLine;
				break;
			case BehaviorState.Charging:
				base.CurrentOrder = _chargeOrder;
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
				CurrentArrangementOrder = ArrangementOrder.ArrangementOrderLoose;
				break;
			case BehaviorState.Stop:
				base.CurrentOrder = _chargeOrder;
				break;
			}
		}

		public override void OnValidBehaviorSideChanged()
		{
			base.OnValidBehaviorSideChanged();
			ResetOrderPositions();
			_behaviorState = BehaviorState.Deciding;
		}

		public override void TickOccasionally()
		{
			BehaviorState behaviorState = CheckAndChangeState();
			_behaviorState = behaviorState;
			CalculateCurrentOrder();
			foreach (IPrimarySiegeWeapon primarySiegeWeapon in _primarySiegeWeapons)
			{
				UsableMachine usableMachine = primarySiegeWeapon as UsableMachine;
				if (!usableMachine.IsDeactivated && !primarySiegeWeapon.HasCompletedAction() && !usableMachine.IsUsedByFormation(base.Formation))
				{
					base.Formation.StartUsingMachine(primarySiegeWeapon as UsableMachine);
				}
			}
			if (_behaviorState == BehaviorState.MoveToGate || _behaviorState == BehaviorState.Stop || _behaviorState == BehaviorState.Charging || _behaviorState == BehaviorState.TakeControl)
			{
				CastleGate innerGate = _teamAISiegeComponent.InnerGate;
				if (innerGate != null && !innerGate.IsGateOpen && !innerGate.IsDestroyed)
				{
					if (!innerGate.IsUsedByFormation(base.Formation))
					{
						base.Formation.StartUsingMachine(innerGate);
					}
				}
				else
				{
					innerGate = _teamAISiegeComponent.OuterGate;
					if (innerGate != null && !innerGate.IsGateOpen && !innerGate.IsDestroyed && !innerGate.IsUsedByFormation(base.Formation))
					{
						base.Formation.StartUsingMachine(innerGate);
					}
				}
			}
			else
			{
				if (base.Formation.Detachments.Contains(_teamAISiegeComponent.OuterGate))
				{
					base.Formation.StopUsingMachine(_teamAISiegeComponent.OuterGate);
				}
				if (base.Formation.Detachments.Contains(_teamAISiegeComponent.InnerGate))
				{
					base.Formation.StopUsingMachine(_teamAISiegeComponent.InnerGate);
				}
			}
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(CurrentArrangementOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderHoldYourFire);
			base.Formation.SetFormOrder(FormOrder.FormOrderDeep);
		}

		protected override float GetAiWeight()
		{
			float result = 0f;
			if (_teamAISiegeComponent != null)
			{
				if (_primarySiegeWeapons.Any((IPrimarySiegeWeapon psw) => psw.HasCompletedAction()) || _wallSegment != null)
				{
					result = ((!_teamAISiegeComponent.IsCastleBreached()) ? 0.25f : 0.75f);
				}
				else if (_teamAISiegeComponent.OuterGate.DefenseSide == _behaviorSide)
				{
					result = 0.1f;
				}
			}
			return result;
		}
	}
	public sealed class BehaviorCautiousAdvance : BehaviorComponent
	{
		private enum BehaviorState
		{
			Approaching,
			Shooting,
			PullingBack
		}

		private bool _isInShieldWallDistance;

		private bool _switchedToShieldWallRecently;

		private TaleWorlds.Core.Timer _switchedToShieldWallTimer;

		private Vec2 _reformPosition = Vec2.Invalid;

		private Formation _archerFormation;

		private bool _cantShoot;

		private float _cantShootDistance = float.MaxValue;

		private BehaviorState _behaviorState = BehaviorState.Shooting;

		private TaleWorlds.Core.Timer _cantShootTimer;

		private Vec2 _shootPosition = Vec2.Invalid;

		private FormationQuerySystem _targetFormation;

		public BehaviorCautiousAdvance()
		{
			base.BehaviorCoherence = 1f;
			_cantShootTimer = new TaleWorlds.Core.Timer(0f, 0f);
			_switchedToShieldWallTimer = new TaleWorlds.Core.Timer(0f, 0f);
		}

		public BehaviorCautiousAdvance(Formation formation)
			: base(formation)
		{
			base.BehaviorCoherence = 1f;
			_cantShootTimer = new TaleWorlds.Core.Timer(0f, 0f);
			_switchedToShieldWallTimer = new TaleWorlds.Core.Timer(0f, 0f);
			CalculateCurrentOrder();
		}

		protected override void CalculateCurrentOrder()
		{
			WorldPosition cachedMedianPosition = base.Formation.CachedMedianPosition;
			bool flag = false;
			Vec2 vec;
			if (_targetFormation == null || _archerFormation == null)
			{
				vec = base.Formation.Direction;
				cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
			}
			else
			{
				vec = _targetFormation.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition;
				float num = vec.Normalize();
				float num2 = _archerFormation.QuerySystem.RangedUnitRatio * 0.5f / (float)_archerFormation.Arrangement.RankCount;
				switch (_behaviorState)
				{
				case BehaviorState.Shooting:
					if (_archerFormation.QuerySystem.MakingRangedAttackRatio <= num2)
					{
						if (num > _archerFormation.QuerySystem.MaximumMissileRange)
						{
							_behaviorState = BehaviorState.Approaching;
							_cantShootDistance = TaleWorlds.Library.MathF.Min(_cantShootDistance, _archerFormation.QuerySystem.MaximumMissileRange * 0.9f);
							_shootPosition = Vec2.Invalid;
						}
						else if (!_cantShoot)
						{
							_cantShoot = true;
							_cantShootTimer.Reset(Mission.Current.CurrentTime, (_archerFormation == null) ? 10f : MBMath.Lerp(10f, 15f, (MBMath.ClampFloat(_archerFormation.CountOfUnits, 10f, 60f) - 10f) * 0.02f));
						}
						else if (_cantShootTimer.Check(Mission.Current.CurrentTime))
						{
							_behaviorState = BehaviorState.Approaching;
							_cantShootDistance = TaleWorlds.Library.MathF.Min(_cantShootDistance, num);
							_shootPosition = Vec2.Invalid;
						}
					}
					else
					{
						_cantShootDistance = TaleWorlds.Library.MathF.Max(_cantShootDistance, num);
						_cantShoot = false;
						if (((!_targetFormation.IsRangedFormation && !_targetFormation.IsRangedCavalryFormation) || (num < _targetFormation.MissileRangeAdjusted && _targetFormation.MakingRangedAttackRatio < 0.1f)) && num < TaleWorlds.Library.MathF.Min(_archerFormation.QuerySystem.MissileRangeAdjusted * 0.4f, _cantShootDistance * 0.667f))
						{
							_behaviorState = BehaviorState.PullingBack;
							_shootPosition = Vec2.Invalid;
						}
					}
					break;
				case BehaviorState.Approaching:
					if (num < _cantShootDistance * 0.8f)
					{
						_behaviorState = BehaviorState.Shooting;
						_cantShoot = false;
						flag = true;
					}
					else if (_archerFormation.QuerySystem.MakingRangedAttackRatio >= num2 * 1.2f)
					{
						_behaviorState = BehaviorState.Shooting;
						_cantShoot = false;
						flag = true;
					}
					if (_behaviorState == BehaviorState.Shooting)
					{
						_shootPosition = base.Formation.CachedAveragePosition + vec * 5f;
					}
					break;
				case BehaviorState.PullingBack:
					if (num > TaleWorlds.Library.MathF.Min(_cantShootDistance, _archerFormation.QuerySystem.MissileRangeAdjusted) * 0.8f)
					{
						_behaviorState = BehaviorState.Shooting;
						_cantShoot = false;
						_shootPosition = base.Formation.CachedAveragePosition + vec * 5f;
						flag = true;
					}
					break;
				}
				switch (_behaviorState)
				{
				case BehaviorState.Shooting:
					if (_shootPosition.IsValid)
					{
						cachedMedianPosition.SetVec2(_shootPosition);
					}
					else
					{
						cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
					}
					break;
				case BehaviorState.Approaching:
				{
					cachedMedianPosition = _targetFormation.Formation.CachedMedianPosition;
					Formation.FormationIntegrityDataGroup cachedFormationIntegrityData = base.Formation.CachedFormationIntegrityData;
					if (_switchedToShieldWallRecently && !_switchedToShieldWallTimer.Check(Mission.Current.CurrentTime) && cachedFormationIntegrityData.DeviationOfPositionsExcludeFarAgents > cachedFormationIntegrityData.AverageMaxUnlimitedSpeedExcludeFarAgents * 0.5f)
					{
						if (_reformPosition.IsValid)
						{
							cachedMedianPosition.SetVec2(_reformPosition);
							break;
						}
						vec = (base.Formation.QuerySystem.Team.MedianTargetFormationPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized();
						_reformPosition = base.Formation.CachedAveragePosition + vec * 5f;
						cachedMedianPosition.SetVec2(_reformPosition);
					}
					else
					{
						_switchedToShieldWallRecently = false;
						_reformPosition = Vec2.Invalid;
						cachedMedianPosition.SetVec2(_targetFormation.Formation.CachedAveragePosition);
					}
					break;
				}
				case BehaviorState.PullingBack:
					cachedMedianPosition = base.Formation.CachedMedianPosition;
					cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
					break;
				}
			}
			if (!base.CurrentOrder.CreateNewOrderWorldPositionMT(base.Formation, WorldPosition.WorldPositionEnforcedCache.None).IsValid || _behaviorState != BehaviorState.Shooting || flag || base.CurrentOrder.CreateNewOrderWorldPositionMT(base.Formation, WorldPosition.WorldPositionEnforcedCache.NavMeshVec3).GetNavMeshVec3().DistanceSquared(cachedMedianPosition.GetNavMeshVec3()) >= base.Formation.Depth * base.Formation.Depth)
			{
				base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
			}
			if (!CurrentFacingOrder.GetDirection(base.Formation).IsValid || _behaviorState != BehaviorState.Shooting || flag || CurrentFacingOrder.GetDirection(base.Formation).DotProduct(vec) <= MBMath.Lerp(0.5f, 1f, 1f - MBMath.ClampFloat(base.Formation.Width, 1f, 20f) * 0.05f))
			{
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(vec);
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			IEnumerable<Formation> source = base.Formation.Team.FormationsIncludingEmpty.WhereQ((Formation f) => f.CountOfUnits > 0 && f != base.Formation && f.QuerySystem.IsRangedFormation);
			if (source.AnyQ())
			{
				_archerFormation = source.MaxBy((Formation f) => f.QuerySystem.FormationPower);
			}
			_cantShoot = false;
			_cantShootDistance = float.MaxValue;
			_behaviorState = BehaviorState.Shooting;
			_cantShootTimer.Reset(Mission.Current.CurrentTime, (_archerFormation == null) ? 10f : MBMath.Lerp(10f, 15f, (MBMath.ClampFloat(_archerFormation.CountOfUnits, 10f, 60f) - 10f) * 0.02f));
			_targetFormation = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation ?? base.Formation.CachedClosestEnemyFormation;
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			_isInShieldWallDistance = true;
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		public override void OnBehaviorCanceled()
		{
		}

		public override void TickOccasionally()
		{
			_targetFormation = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation ?? base.Formation.CachedClosestEnemyFormation;
			if (base.Formation.PhysicalClass.IsMeleeInfantry())
			{
				bool flag = _targetFormation != null && (base.Formation.QuerySystem.IsUnderRangedAttack || base.Formation.CachedAveragePosition.DistanceSquared(base.CurrentOrder.GetPosition(base.Formation)) < 25f + (_isInShieldWallDistance ? 75f : 0f)) && base.Formation.CachedAveragePosition.DistanceSquared(_targetFormation.Formation.CachedMedianPosition.AsVec2) > 100f - (_isInShieldWallDistance ? 75f : 0f);
				if (flag != _isInShieldWallDistance)
				{
					_isInShieldWallDistance = flag;
					if (_isInShieldWallDistance)
					{
						ArrangementOrder arrangementOrder = (base.Formation.QuerySystem.HasShield ? ArrangementOrder.ArrangementOrderShieldWall : ArrangementOrder.ArrangementOrderLoose);
						if (base.Formation.ArrangementOrder != arrangementOrder)
						{
							base.Formation.SetArrangementOrder(arrangementOrder);
							_switchedToShieldWallRecently = true;
							_switchedToShieldWallTimer.Reset(Mission.Current.CurrentTime, 5f);
						}
					}
					else if (!(base.Formation.ArrangementOrder == ArrangementOrder.ArrangementOrderLine))
					{
						base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
					}
				}
			}
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
		}

		protected override float GetAiWeight()
		{
			return 1f;
		}
	}
	public class BehaviorCavalryScreen : BehaviorComponent
	{
		private Formation _mainFormation;

		private Formation _flankingEnemyCavalryFormation;

		private float _threatFormationCacheTime;

		private const float _threatFormationCacheExpireTime = 5f;

		public BehaviorCavalryScreen(Formation formation)
			: base(formation)
		{
			_behaviorSide = formation.AI.Side;
			_mainFormation = formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
			CalculateCurrentOrder();
		}

		public override void OnValidBehaviorSideChanged()
		{
			base.OnValidBehaviorSideChanged();
			_mainFormation = base.Formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
		}

		protected override void CalculateCurrentOrder()
		{
			if (_mainFormation == null || base.Formation.AI.IsMainFormation || (base.Formation.AI.Side != 0 && base.Formation.AI.Side != FormationAI.BehaviorSide.Right))
			{
				_flankingEnemyCavalryFormation = null;
				WorldPosition cachedMedianPosition = base.Formation.CachedMedianPosition;
				cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
				base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
				return;
			}
			float currentTime = Mission.Current.CurrentTime;
			if (_threatFormationCacheTime + 5f < currentTime)
			{
				_threatFormationCacheTime = currentTime;
				Vec2 vec = ((base.Formation.AI.Side == FormationAI.BehaviorSide.Left) ? _mainFormation.Direction.LeftVec() : _mainFormation.Direction.RightVec()).Normalized() - _mainFormation.Direction.Normalized();
				_flankingEnemyCavalryFormation = null;
				float num = float.MinValue;
				foreach (Team team in Mission.Current.Teams)
				{
					if (!team.IsEnemyOf(base.Formation.Team))
					{
						continue;
					}
					foreach (Formation item in team.FormationsIncludingSpecialAndEmpty)
					{
						if (item.CountOfUnits <= 0)
						{
							continue;
						}
						Vec2 vec2 = item.CachedMedianPosition.AsVec2 - _mainFormation.CachedMedianPosition.AsVec2;
						if (vec.Normalized().DotProduct(vec2.Normalized()) > 0.9238795f)
						{
							float formationPower = item.QuerySystem.FormationPower;
							if (formationPower > num)
							{
								num = formationPower;
								_flankingEnemyCavalryFormation = item;
							}
						}
					}
				}
			}
			WorldPosition cachedMedianPosition2;
			if (_flankingEnemyCavalryFormation == null)
			{
				cachedMedianPosition2 = base.Formation.CachedMedianPosition;
				cachedMedianPosition2.SetVec2(base.Formation.CachedAveragePosition);
			}
			else
			{
				Vec2 vec3 = _flankingEnemyCavalryFormation.CachedMedianPosition.AsVec2 - _mainFormation.CachedMedianPosition.AsVec2;
				float num2 = vec3.Normalize() * 0.5f;
				cachedMedianPosition2 = _mainFormation.CachedMedianPosition;
				cachedMedianPosition2.SetVec2(cachedMedianPosition2.AsVec2 + num2 * vec3);
			}
			base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition2);
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderSkein);
			base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtEnemy);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderDeep);
		}

		public override TextObject GetBehaviorString()
		{
			TextObject behaviorString = base.GetBehaviorString();
			TextObject variable = GameTexts.FindText("str_formation_ai_side_strings", base.Formation.AI.Side.ToString());
			behaviorString.SetTextVariable("SIDE_STRING", variable);
			if (_mainFormation != null)
			{
				behaviorString.SetTextVariable("AI_SIDE", GameTexts.FindText("str_formation_ai_side_strings", _mainFormation.AI.Side.ToString()));
				behaviorString.SetTextVariable("CLASS", GameTexts.FindText("str_formation_class_string", _mainFormation.PhysicalClass.GetName()));
			}
			return behaviorString;
		}

		protected override float GetAiWeight()
		{
			if (_mainFormation == null || !_mainFormation.AI.IsMainFormation)
			{
				_mainFormation = base.Formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
			}
			if (_flankingEnemyCavalryFormation == null)
			{
				return 0f;
			}
			return 1.2f;
		}
	}
	public class BehaviorCharge : BehaviorComponent
	{
		public override float NavmeshlessTargetPositionPenalty => 1f;

		public BehaviorCharge(Formation formation)
			: base(formation)
		{
			CalculateCurrentOrder();
			base.BehaviorCoherence = 0.5f;
		}

		protected override void CalculateCurrentOrder()
		{
			base.CurrentOrder = ((base.Formation.CachedClosestEnemyFormation == null) ? MovementOrder.MovementOrderCharge : MovementOrder.MovementOrderChargeToTarget(base.Formation.CachedClosestEnemyFormation.Formation));
		}

		public override void TickOccasionally()
		{
			base.TickOccasionally();
			if (base.Formation.Team.TeamAI is TeamAISiegeComponent { OuterGate: not null } teamAISiegeComponent && !teamAISiegeComponent.OuterGate.IsGateOpen && teamAISiegeComponent.InnerGate != null && !teamAISiegeComponent.InnerGate.IsGateOpen)
			{
				CastleGate castleGate = teamAISiegeComponent.InnerGate ?? teamAISiegeComponent.OuterGate;
				if (castleGate != null && !castleGate.IsUsedByFormation(base.Formation))
				{
					base.Formation.StartUsingMachine(castleGate);
				}
			}
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			if (base.Formation.ArrangementOrder.OrderEnum == ArrangementOrder.ArrangementOrderEnum.ShieldWall)
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			}
		}

		private float CalculateAIWeight(bool isSiege, bool isInsideCastle)
		{
			FormationQuerySystem querySystem = base.Formation.QuerySystem;
			FormationQuerySystem cachedClosestEnemyFormation = base.Formation.CachedClosestEnemyFormation;
			float num = base.Formation.CachedAveragePosition.Distance(cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2) / querySystem.MovementSpeedMaximum;
			float num3;
			if (!querySystem.IsCavalryFormation && !querySystem.IsRangedCavalryFormation)
			{
				float num2 = MBMath.ClampFloat(num, 4f, 10f);
				num3 = MBMath.Lerp(0.1f, 1f, 1f - (num2 - 4f) / 6f);
			}
			else if (num <= 4f)
			{
				float num4 = MBMath.ClampFloat(num, 0f, 4f);
				num3 = MBMath.Lerp(0.1f, 1.4f, num4 / 4f);
			}
			else
			{
				float num5 = MBMath.ClampFloat(num, 4f, 10f);
				num3 = MBMath.Lerp(0.1f, 1.4f, 1f - (num5 - 4f) / 6f);
			}
			float num6 = 0f;
			foreach (Team team in Mission.Current.Teams)
			{
				if (!team.IsEnemyOf(base.Formation.Team))
				{
					continue;
				}
				foreach (Formation item in team.FormationsIncludingSpecialAndEmpty)
				{
					if (item.CountOfUnits <= 0 || cachedClosestEnemyFormation.Formation == item || (isSiege && TeamAISiegeComponent.IsFormationInsideCastle(item, includeOnlyPositionedUnits: true) != isInsideCastle))
					{
						continue;
					}
					float num7 = item.CachedMedianPosition.AsVec2.Distance(cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2) / item.QuerySystem.MovementSpeedMaximum;
					if (num7 > num + 4f || (num <= 8f && item.CachedClosestEnemyFormation != base.Formation.QuerySystem))
					{
						continue;
					}
					bool flag = false;
					if (num <= 8f)
					{
						foreach (Team team2 in base.Formation.Team.Mission.Teams)
						{
							if (!team2.IsFriendOf(base.Formation.Team))
							{
								continue;
							}
							foreach (Formation item2 in team2.FormationsIncludingSpecialAndEmpty)
							{
								if (item2.CountOfUnits > 0 && item2 != base.Formation && item2.CachedClosestEnemyFormation == item.QuerySystem && item2.CachedMedianPosition.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition) / item2.QuerySystem.MovementSpeedMaximum < num7 + 4f)
								{
									flag = true;
									break;
								}
							}
							if (flag)
							{
								break;
							}
						}
					}
					if (!flag)
					{
						num6 += item.QuerySystem.FormationMeleeFightingPower * item.QuerySystem.GetClassWeightedFactor(1f, 1f, 1f, 1f);
					}
				}
			}
			float num8 = 0f;
			foreach (Team team3 in Mission.Current.Teams)
			{
				if (!team3.IsFriendOf(base.Formation.Team))
				{
					continue;
				}
				foreach (Formation item3 in team3.FormationsIncludingSpecialAndEmpty)
				{
					if (item3 != base.Formation && item3.CountOfUnits > 0 && cachedClosestEnemyFormation == item3.CachedClosestEnemyFormation && (!isSiege || TeamAISiegeComponent.IsFormationInsideCastle(item3, includeOnlyPositionedUnits: true) == isInsideCastle) && item3.CachedMedianPosition.AsVec2.Distance(item3.CachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2) / item3.QuerySystem.MovementSpeedMaximum < 4f)
					{
						num8 += item3.QuerySystem.FormationMeleeFightingPower * item3.QuerySystem.GetClassWeightedFactor(1f, 1f, 1f, 1f);
					}
				}
			}
			float num9 = (base.Formation.QuerySystem.FormationMeleeFightingPower * querySystem.GetClassWeightedFactor(1f, 1f, 1f, 1f) + num8 + 1f) / (1f + num6 + cachedClosestEnemyFormation.Formation.QuerySystem.FormationMeleeFightingPower * cachedClosestEnemyFormation.GetClassWeightedFactor(1f, 1f, 1f, 1f));
			num9 /= ((!isSiege) ? MBMath.ClampFloat(querySystem.Team.RemainingPowerRatio, 0.2f, 3f) : MBMath.ClampFloat(querySystem.Team.RemainingPowerRatio, 0.5f, 3f));
			if (num9 > 1f)
			{
				num9 = (num9 - 1f) / 3f;
				num9 += 1f;
			}
			num9 = MBMath.ClampFloat(num9, 0.1f, 1.25f);
			float num10 = 1f;
			if (num <= 4f)
			{
				float length = (base.Formation.CachedAveragePosition - cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2).Length;
				if (length > float.Epsilon)
				{
					WorldPosition cachedMedianPosition = base.Formation.CachedMedianPosition;
					cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
					float navMeshZ = cachedMedianPosition.GetNavMeshZ();
					if (!float.IsNaN(navMeshZ))
					{
						float value = (navMeshZ - cachedClosestEnemyFormation.Formation.CachedMedianPosition.GetNavMeshZ()) / length;
						num10 = MBMath.Lerp(0.9f, 1.1f, (MBMath.ClampFloat(value, -0.58f, 0.58f) + 0.58f) / 1.16f);
					}
				}
			}
			float num11 = 1f;
			if (num <= 4f && num >= 1.5f)
			{
				num11 = 1.2f;
			}
			float num12 = 1f;
			if (num <= 4f && cachedClosestEnemyFormation.Formation.CachedClosestEnemyFormation != querySystem)
			{
				num12 = 1.2f;
			}
			float num13 = ((!isSiege) ? (querySystem.GetClassWeightedFactor(1f, 1f, 1.5f, 1.5f) * cachedClosestEnemyFormation.GetClassWeightedFactor(1f, 1f, 0.5f, 0.5f)) : (querySystem.GetClassWeightedFactor(1f, 1f, 1.2f, 1.2f) * cachedClosestEnemyFormation.GetClassWeightedFactor(1f, 1f, 0.3f, 0.3f)));
			return num3 * num9 * num10 * num11 * num12 * num13;
		}

		protected override float GetAiWeight()
		{
			bool flag = base.Formation.Team.TeamAI is TeamAISiegeComponent;
			float result = 0f;
			FormationQuerySystem cachedClosestEnemyFormation = base.Formation.CachedClosestEnemyFormation;
			if (cachedClosestEnemyFormation == null)
			{
				if (base.Formation.Team.HasAnyEnemyTeamsWithAgents(ignoreMountedAgents: false))
				{
					result = 0.2f;
				}
			}
			else
			{
				bool flag2 = false;
				bool flag3;
				if (!flag)
				{
					flag3 = true;
				}
				else if ((base.Formation.Team.TeamAI as TeamAISiegeComponent).CalculateIsChargePastWallsApplicable(base.Formation.AI.Side))
				{
					flag3 = true;
				}
				else
				{
					flag2 = TeamAISiegeComponent.IsFormationInsideCastle(cachedClosestEnemyFormation.Formation, includeOnlyPositionedUnits: true, 0.51f);
					flag3 = flag2 == TeamAISiegeComponent.IsFormationInsideCastle(base.Formation, includeOnlyPositionedUnits: true, flag2 ? 0.9f : 0.1f);
				}
				if (flag3)
				{
					result = CalculateAIWeight(flag, flag2);
				}
			}
			return result;
		}
	}
	public abstract class BehaviorComponent
	{
		protected FormationAI.BehaviorSide _behaviorSide;

		protected const float FormArrangementDistanceToOrderPosition = 10f;

		private const float _playerInformCooldown = 60f;

		protected float _lastPlayerInformTime;

		private TaleWorlds.Core.Timer _navmeshlessTargetPenaltyTime;

		private float _navmeshlessTargetPositionPenalty = 1f;

		public bool IsCurrentOrderChanged;

		private MovementOrder _currentOrder;

		protected FacingOrder CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;

		public Formation Formation { get; private set; }

		public float BehaviorCoherence { get; set; }

		public virtual float NavmeshlessTargetPositionPenalty
		{
			get
			{
				if (_navmeshlessTargetPositionPenalty == 1f)
				{
					return 1f;
				}
				_navmeshlessTargetPenaltyTime.Check(Mission.Current.CurrentTime);
				float num = _navmeshlessTargetPenaltyTime.ElapsedTime();
				if (num >= 10f)
				{
					_navmeshlessTargetPositionPenalty = 1f;
					return 1f;
				}
				if (num <= 5f)
				{
					return _navmeshlessTargetPositionPenalty;
				}
				return MBMath.Lerp(_navmeshlessTargetPositionPenalty, 1f, (num - 5f) / 5f);
			}
			set
			{
				_navmeshlessTargetPenaltyTime.Reset(Mission.Current.CurrentTime);
				_navmeshlessTargetPositionPenalty = value;
			}
		}

		public MovementOrder CurrentOrder
		{
			get
			{
				return _currentOrder;
			}
			protected set
			{
				_currentOrder = value;
				IsCurrentOrderChanged = true;
			}
		}

		public float PreserveExpireTime { get; set; }

		public float WeightFactor { get; set; }

		protected BehaviorComponent(Formation formation)
		{
			Formation = formation;
			PreserveExpireTime = 0f;
			_navmeshlessTargetPenaltyTime = new TaleWorlds.Core.Timer(Mission.Current.CurrentTime, 50f);
		}

		protected BehaviorComponent()
		{
		}

		private void InformSergeantPlayer()
		{
			if (Mission.Current.MainAgent != null && Formation.Team.GeneralAgent != null && !Formation.Team.IsPlayerGeneral && Formation.Team.IsPlayerSergeant && Formation.PlayerOwner == Agent.Main)
			{
				TextObject behaviorString = GetBehaviorString();
				MBTextManager.SetTextVariable("BEHAVIOR", behaviorString);
				MBTextManager.SetTextVariable("PLAYER_NAME", Mission.Current.MainAgent.NameTextObject);
				MBTextManager.SetTextVariable("TEAM_LEADER", Formation.Team.GeneralAgent.NameTextObject);
				MBInformationManager.AddQuickInformation(new TextObject("{=L91XKoMD}{TEAM_LEADER}: {PLAYER_NAME}, {BEHAVIOR}"), 4000, Formation.Team.GeneralAgent.Character);
			}
		}

		protected virtual void OnBehaviorActivatedAux()
		{
		}

		internal void OnBehaviorActivated()
		{
			if (!Formation.Team.IsPlayerGeneral && !Formation.Team.IsPlayerSergeant && Formation.IsPlayerTroopInFormation && Mission.Current.MainAgent != null)
			{
				TextObject text = new TextObject(ToString().Replace("MBModule.Behavior", ""));
				MBTextManager.SetTextVariable("BEHAVIOUR_NAME_BEGIN", text);
				text = GameTexts.FindText("str_formation_ai_soldier_instruction_text");
				MBInformationManager.AddQuickInformation(text, 2000, Mission.Current.MainAgent.Character);
			}
			if (!GameNetwork.IsMultiplayer)
			{
				InformSergeantPlayer();
				_lastPlayerInformTime = Mission.Current.CurrentTime;
			}
			if (Formation.IsAIControlled)
			{
				OnBehaviorActivatedAux();
			}
		}

		public virtual void OnBehaviorCanceled()
		{
		}

		public virtual void OnLostAIControl()
		{
		}

		public virtual void OnAgentRemoved(Agent agent)
		{
		}

		public void RemindSergeantPlayer()
		{
			float currentTime = Mission.Current.CurrentTime;
			if (this == Formation.AI.ActiveBehavior && _lastPlayerInformTime + 60f < currentTime)
			{
				InformSergeantPlayer();
				_lastPlayerInformTime = currentTime;
			}
		}

		public virtual void TickOccasionally()
		{
		}

		public float GetAIWeight()
		{
			return GetAiWeight() * NavmeshlessTargetPositionPenalty;
		}

