	public class BehaviorDefendCastleKeyPosition : BehaviorComponent
	{
		private enum BehaviorState
		{
			UnSet,
			Waiting,
			Ready
		}

		private TeamAISiegeComponent _teamAISiegeDefender;

		private CastleGate _innerGate;

		private CastleGate _outerGate;

