				base.CurrentOrder = MovementOrder.MovementOrderMove(TacticalDefendPosition.Position);
			}
			else
			{
				WorldPosition cachedMedianPosition = base.Formation.CachedMedianPosition;
				cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
				base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
			}
			CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(direction);
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (base.Formation.CachedAveragePosition.Distance(base.CurrentOrder.GetPosition(base.Formation)) - base.Formation.Arrangement.Depth * 0.5f < 10f)
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderCircle);
				if (base.Formation.Team.FormationsIncludingEmpty.AnyQ((Formation f) => f.CountOfUnits > 0 && f.QuerySystem.IsRangedFormation))
				{
					Formation formation = base.Formation.Team.FormationsIncludingEmpty.WhereQ((Formation f) => f.CountOfUnits > 0 && f.QuerySystem.IsRangedFormation).MaxBy((Formation f) => f.CountOfUnits);
					int num = (int)TaleWorlds.Library.MathF.Sqrt(formation.CountOfUnits);
					float num2 = ((float)num * formation.UnitDiameter + (float)(num - 1) * formation.Interval) * 0.5f * 1.414213f;
					int num3 = base.Formation.Arrangement.UnitCount;
					int num4 = 0;
					while (num3 > 0)
					{
						double a = (double)(num2 + base.Formation.Distance * (float)num4 + base.Formation.UnitDiameter * (float)(num4 + 1)) * Math.PI * 2.0 / (double)(base.Formation.UnitDiameter + base.Formation.Interval);
						num3 -= (int)Math.Ceiling(a);
						num4++;
					}
					float num5 = num2 + (float)num4 * base.Formation.UnitDiameter + (float)(num4 - 1) * base.Formation.Distance;
					base.Formation.SetFormOrder(FormOrder.FormOrderCustom(num5 * 2f));
				}
			}
			else
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLoose);
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLoose);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderDeep);
		}

		public override void ResetBehavior()
		{
			base.ResetBehavior();
			TacticalDefendPosition = null;
		}

		protected override float GetAiWeight()
		{
			if (TacticalDefendPosition == null)
			{
				return 0f;
			}
			return 1f;
		}
	}
	public class BehaviorDestroySiegeWeapons : BehaviorComponent
	{
		private readonly List<SiegeWeapon> _allWeapons;

		private List<SiegeWeapon> _targetWeapons;

		public SiegeWeapon LastTargetWeapon;

		private bool _isTargetPrimaryWeapon;

		public override float NavmeshlessTargetPositionPenalty => 1f;

		private void DetermineTargetWeapons()
		{
			_targetWeapons = _allWeapons.Where((SiegeWeapon w) => w is IPrimarySiegeWeapon && (w as IPrimarySiegeWeapon).WeaponSide == _behaviorSide && w.IsDestructible && !w.IsDestroyed && !w.IsDisabled).ToList();
			if (_targetWeapons.IsEmpty())
			{
				_targetWeapons = _allWeapons.Where((SiegeWeapon w) => !(w is IPrimarySiegeWeapon) && w.IsDestructible && !w.IsDestroyed && !w.IsDisabled).ToList();
				_isTargetPrimaryWeapon = false;
			}
			else
			{
				_isTargetPrimaryWeapon = true;
			}
		}

		public BehaviorDestroySiegeWeapons(Formation formation)
			: base(formation)
		{
			base.BehaviorCoherence = 0.2f;
			_behaviorSide = formation.AI.Side;
			_allWeapons = (from sw in Mission.Current.ActiveMissionObjects.FindAllWithType<SiegeWeapon>()
				where sw.Side != formation.Team.Side
				select sw).ToList();
			DetermineTargetWeapons();
			base.CurrentOrder = MovementOrder.MovementOrderCharge;
		}

		public override TextObject GetBehaviorString()
		{
			TextObject behaviorString = base.GetBehaviorString();
			TextObject variable = GameTexts.FindText("str_formation_ai_side_strings", base.Formation.AI.Side.ToString());
			behaviorString.SetTextVariable("SIDE_STRING", variable);
			behaviorString.SetTextVariable("IS_GENERAL_SIDE", "0");
			return behaviorString;
		}

		public override void OnValidBehaviorSideChanged()
		{
			base.OnValidBehaviorSideChanged();
			DetermineTargetWeapons();
		}

		public override void TickOccasionally()
		{
			base.TickOccasionally();
			_targetWeapons.RemoveAll((SiegeWeapon tw) => tw.IsDestroyed);
			if (_targetWeapons.Count == 0)
			{
				DetermineTargetWeapons();
			}
			if (base.Formation.AI.ActiveBehavior != this)
			{
				return;
			}
			if (_targetWeapons.Count == 0)
			{
				MovementOrder m = base.CurrentOrder;
				if (m != MovementOrder.MovementOrderCharge)
				{
					base.CurrentOrder = MovementOrder.MovementOrderCharge;
				}
				_isTargetPrimaryWeapon = false;
			}
			else
			{
				SiegeWeapon siegeWeapon = _targetWeapons.MinBy((SiegeWeapon tw) => base.Formation.CachedAveragePosition.DistanceSquared(tw.GameEntity.GlobalPosition.AsVec2));
				if (base.CurrentOrder.OrderEnum != MovementOrder.MovementOrderEnum.AttackEntity || LastTargetWeapon != siegeWeapon)
				{
					LastTargetWeapon = siegeWeapon;
					base.CurrentOrder = MovementOrder.MovementOrderAttackEntity(GameEntity.CreateFromWeakEntity(LastTargetWeapon.GameEntity), surroundEntity: true);
				}
			}
			base.Formation.SetMovementOrder(base.CurrentOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
			DetermineTargetWeapons();
			base.Formation.SetArrangementOrder((base.Formation.QuerySystem.IsCavalryFormation || base.Formation.QuerySystem.IsRangedCavalryFormation) ? ArrangementOrder.ArrangementOrderSkein : ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtEnemy);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderDeep);
		}

		protected override float GetAiWeight()
		{
			if (!_targetWeapons.IsEmpty())
			{
				if (!_isTargetPrimaryWeapon)
				{
					return 0.7f;
				}
				return 1f;
			}
			return 0f;
		}
	}
	public class BehaviorEliminateEnemyInsideCastle : BehaviorComponent
	{
		private enum BehaviorState
		{
			UnSet,
			Gathering,
			Attacking
		}

		private BehaviorState _behaviorState;

		private MovementOrder _gatherOrder;

		private MovementOrder _attackOrder;

		private FacingOrder _gatheringFacingOrder;

		private FacingOrder _attackFacingOrder;

		private TacticalPosition _gatheringTacticalPos;

		private Formation _targetEnemyFormation;

		public override float NavmeshlessTargetPositionPenalty => 1f;

		public BehaviorEliminateEnemyInsideCastle(Formation formation)
			: base(formation)
		{
			_behaviorState = BehaviorState.UnSet;
			_behaviorSide = formation.AI.Side;
			ResetOrderPositions();
		}

		protected override void CalculateCurrentOrder()
		{
			base.CalculateCurrentOrder();
			base.CurrentOrder = ((_behaviorState == BehaviorState.Attacking) ? _attackOrder : _gatherOrder);
		}

		private void DetermineMostImportantInvadingEnemyFormation()
		{
			float num = float.MinValue;
			_targetEnemyFormation = null;
			foreach (Team team in base.Formation.Team.Mission.Teams)
			{
				if (!team.IsEnemyOf(base.Formation.Team))
				{
					continue;
				}
				for (int i = 0; i < Math.Min(team.FormationsIncludingSpecialAndEmpty.Count, 8); i++)
				{
					Formation formation = team.FormationsIncludingSpecialAndEmpty[i];
					if (formation.CountOfUnits > 0 && TeamAISiegeComponent.IsFormationInsideCastle(formation, includeOnlyPositionedUnits: true))
					{
						float formationPower = formation.QuerySystem.FormationPower;
						if (formationPower > num)
						{
							num = formationPower;
							_targetEnemyFormation = formation;
						}
					}
				}
			}
		}

		private void ConfirmGatheringSide()
		{
			SiegeLane siegeLane = TeamAISiegeComponent.SiegeLanes.FirstOrDefault((SiegeLane sl) => sl.LaneSide == _behaviorSide);
			if (siegeLane == null || siegeLane.LaneState >= SiegeLane.LaneStateEnum.Conceited)
			{
				ResetOrderPositions();
			}
		}

		private FormationAI.BehaviorSide DetermineGatheringSide()
		{
			DetermineMostImportantInvadingEnemyFormation();
			if (_targetEnemyFormation == null)
			{
				if (_behaviorState == BehaviorState.Attacking)
				{
					_behaviorState = BehaviorState.UnSet;
				}
				return _behaviorSide;
			}
			int connectedSides = TeamAISiegeComponent.QuerySystem.DeterminePositionAssociatedSide(_targetEnemyFormation.CachedMedianPosition.GetNavMeshVec3());
			IEnumerable<SiegeLane> source = TeamAISiegeComponent.SiegeLanes.Where((SiegeLane sl) => sl.LaneState != SiegeLane.LaneStateEnum.Conceited && !SiegeQuerySystem.AreSidesRelated(sl.LaneSide, connectedSides));
			FormationAI.BehaviorSide result = _behaviorSide;
			if (source.Any())
			{
				if (source.Count() > 1)
				{
					int leastDangerousLaneState = source.Min((SiegeLane pgl) => (int)pgl.LaneState);
					IEnumerable<SiegeLane> source2 = source.Where((SiegeLane pgl) => pgl.LaneState == (SiegeLane.LaneStateEnum)leastDangerousLaneState);
					result = ((source2.Count() > 1) ? source2.MinBy((SiegeLane ldl) => SiegeQuerySystem.SideDistance(1 << connectedSides, 1 << (int)ldl.LaneSide)).LaneSide : source2.First().LaneSide);
				}
				else
				{
					result = source.First().LaneSide;
				}
			}
			return result;
		}

		private void ResetOrderPositions()
		{
			_behaviorSide = DetermineGatheringSide();
			SiegeLane siegeLane = TeamAISiegeComponent.SiegeLanes.FirstOrDefault((SiegeLane sl) => sl.LaneSide == _behaviorSide);
			WorldFrame worldFrame = siegeLane?.DefensePoints?.FirstOrDefault((ICastleKeyPosition dp) => dp.AttackerSiegeWeapon is UsableMachine && !(dp.AttackerSiegeWeapon as UsableMachine).IsDisabled)?.DefenseWaitFrame ?? WorldFrame.Invalid;
			_gatheringTacticalPos = siegeLane?.DefensePoints?.FirstOrDefault((ICastleKeyPosition dp) => dp.AttackerSiegeWeapon is UsableMachine && !(dp.AttackerSiegeWeapon as UsableMachine).IsDisabled)?.WaitPosition ?? siegeLane?.DefensePoints?.FirstOrDefault().WaitPosition;
			if (_gatheringTacticalPos != null)
			{
				_gatherOrder = MovementOrder.MovementOrderMove(_gatheringTacticalPos.Position);
				_gatheringFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			}
			else if (worldFrame.Origin.IsValid)
			{
				worldFrame.Rotation.f.Normalize();
				_gatherOrder = MovementOrder.MovementOrderMove(worldFrame.Origin);
				_gatheringFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			}
			else
			{
				_gatherOrder = MovementOrder.MovementOrderMove(base.Formation.CachedMedianPosition);
				_gatheringFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			}
			_attackOrder = MovementOrder.MovementOrderChargeToTarget(_targetEnemyFormation);
			_attackFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			base.CurrentOrder = ((_behaviorState == BehaviorState.Attacking) ? _attackOrder : _gatherOrder);
			CurrentFacingOrder = ((_behaviorState == BehaviorState.Attacking) ? _attackFacingOrder : _gatheringFacingOrder);
		}

		public override void OnValidBehaviorSideChanged()
		{
			base.OnValidBehaviorSideChanged();
			ResetOrderPositions();
		}

		public override void TickOccasionally()
		{
			base.TickOccasionally();
			if (_behaviorState != BehaviorState.Attacking)
			{
				ConfirmGatheringSide();
			}
			bool flag = ((_behaviorState != BehaviorState.Attacking) ? (_targetEnemyFormation != null && (base.Formation.CachedMedianPosition.GetNavMeshVec3().DistanceSquared(_gatherOrder.CreateNewOrderWorldPositionMT(base.Formation, WorldPosition.WorldPositionEnforcedCache.NavMeshVec3).GetNavMeshVec3()) < 100f || base.Formation.CachedFormationIntegrityData.DeviationOfPositionsExcludeFarAgents / ((base.Formation.QuerySystem.IdealAverageDisplacement != 0f) ? base.Formation.QuerySystem.IdealAverageDisplacement : 1f) <= 3f)) : (_targetEnemyFormation != null));
			BehaviorState behaviorState = ((!flag) ? BehaviorState.Gathering : BehaviorState.Attacking);
			if (behaviorState != _behaviorState)
			{
				_behaviorState = behaviorState;
				base.CurrentOrder = ((_behaviorState == BehaviorState.Attacking) ? _attackOrder : _gatherOrder);
				CurrentFacingOrder = ((_behaviorState == BehaviorState.Attacking) ? _attackFacingOrder : _gatheringFacingOrder);
			}
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (_behaviorState == BehaviorState.Gathering && _gatheringTacticalPos != null)
			{
				base.Formation.SetFormOrder(FormOrder.FormOrderCustom(_gatheringTacticalPos.Width));
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			_behaviorState = BehaviorState.UnSet;
			_behaviorSide = base.Formation.AI.Side;
			ResetOrderPositions();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		protected override float GetAiWeight()
		{
			return 1f;
		}
	}
	public class BehaviorFireFromInfantryCover : BehaviorComponent
	{
		private Formation _mainFormation;

		private bool _isFireAtWill = true;

		public BehaviorFireFromInfantryCover(Formation formation)
			: base(formation)
		{
			_mainFormation = formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
			CalculateCurrentOrder();
		}

		protected override void CalculateCurrentOrder()
		{
			WorldPosition cachedMedianPosition = base.Formation.CachedMedianPosition;
			Vec2 vec = base.Formation.Direction;
			if (_mainFormation == null)
			{
				cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
			}
			else
			{
				Vec2 position = _mainFormation.GetReadonlyMovementOrderReference().GetPosition(_mainFormation);
				if (position.IsValid)
				{
					vec = (position - _mainFormation.CachedAveragePosition).Normalized();
					Vec2 vec2 = position - vec * _mainFormation.Depth * 0.33f;
					cachedMedianPosition.SetVec2(vec2);
				}
				else
				{
					cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
				}
			}
			base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
			CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(vec);
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (base.Formation.CachedAveragePosition.DistanceSquared(base.CurrentOrder.GetPosition(base.Formation)) < 100f)
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderSquare);
			}
			Vec2 position = base.CurrentOrder.GetPosition(base.Formation);
			bool flag = base.Formation.CachedClosestEnemyFormation == null || _mainFormation.CachedAveragePosition.DistanceSquared(base.Formation.CachedAveragePosition) <= base.Formation.Depth * base.Formation.Width || base.Formation.CachedAveragePosition.DistanceSquared(position) <= (_mainFormation.Depth + base.Formation.Depth) * (_mainFormation.Depth + base.Formation.Depth) * 0.25f;
			if (flag != _isFireAtWill)
			{
				_isFireAtWill = flag;
				base.Formation.SetFiringOrder(_isFireAtWill ? FiringOrder.FiringOrderFireAtWill : FiringOrder.FiringOrderHoldYourFire);
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			int num = (int)TaleWorlds.Library.MathF.Sqrt(base.Formation.CountOfUnits);
			float customWidth = (float)num * base.Formation.UnitDiameter + (float)(num - 1) * base.Formation.Interval;
			base.Formation.SetFormOrder(FormOrder.FormOrderCustom(customWidth));
		}

		protected override float GetAiWeight()
		{
			if (_mainFormation == null || !_mainFormation.AI.IsMainFormation)
			{
				_mainFormation = base.Formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
			}
			if (_mainFormation == null || base.Formation.AI.IsMainFormation || base.Formation.CachedClosestEnemyFormation == null || !base.Formation.QuerySystem.IsRangedFormation)
			{
				return 0f;
			}
			return 2f;
		}
	}
	public class BehaviorFlank : BehaviorComponent
	{
		public BehaviorFlank(Formation formation)
			: base(formation)
		{
			base.BehaviorCoherence = 0.5f;
			CalculateCurrentOrder();
		}

		protected override void CalculateCurrentOrder()
