	public class BehaviorHorseArcherSkirmish : BehaviorComponent
	{
		private bool _rushMode;

		private bool _isEnemyReachable = true;

		public BehaviorHorseArcherSkirmish(Formation formation)
			: base(formation)
		{
			CalculateCurrentOrder();
			base.BehaviorCoherence = 0.5f;
		}

		protected override float GetAiWeight()
		{
			if (!_isEnemyReachable)
			{
				return 0.09f;
			}
			return 0.9f;
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtEnemy);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderDeep);
		}

		protected override void CalculateCurrentOrder()
		{
			WorldPosition position = base.Formation.CachedMedianPosition;
			_isEnemyReachable = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation != null && (!(base.Formation.Team.TeamAI is TeamAISiegeComponent) || !TeamAISiegeComponent.IsFormationInsideCastle(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation, includeOnlyPositionedUnits: false));
			Vec2 cachedAveragePosition = base.Formation.CachedAveragePosition;
			if (!_isEnemyReachable)
			{
				position.SetVec2(cachedAveragePosition);
			}
			else
			{
				WorldPosition cachedMedianPosition = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition;
				int num = 0;
				Vec2 vec = Vec2.Zero;
				foreach (Formation item in base.Formation.Team.FormationsIncludingSpecialAndEmpty)
				{
					if (item != base.Formation && item.CountOfUnits > 0)
					{
						num++;
						vec += item.CachedMedianPosition.AsVec2;
					}
				}
				if (num > 0)
				{
					vec /= (float)num;
				}
				else
				{
					vec = cachedAveragePosition;
				}
				WorldPosition medianTargetFormationPosition = base.Formation.QuerySystem.Team.MedianTargetFormationPosition;
				Vec2 vec2 = (medianTargetFormationPosition.AsVec2 - vec).Normalized();
				float missileRangeAdjusted = base.Formation.QuerySystem.MissileRangeAdjusted;
				if (_rushMode)
				{
					float num2 = cachedAveragePosition.DistanceSquared(cachedMedianPosition.AsVec2);
					if (num2 > base.Formation.QuerySystem.MissileRangeAdjusted * base.Formation.QuerySystem.MissileRangeAdjusted)
					{
						position = medianTargetFormationPosition;
						position.SetVec2(position.AsVec2 - vec2 * (missileRangeAdjusted - (10f + base.Formation.Depth * 0.5f)));
					}
					else if (base.Formation.CachedClosestEnemyFormation.IsCavalryFormation || num2 <= 400f || base.Formation.QuerySystem.UnderRangedAttackRatio >= 0.4f)
					{
						position = base.Formation.QuerySystem.Team.MedianPosition;
						position.SetVec2(vec - (((num > 0) ? 30f : 80f) + base.Formation.Depth) * vec2);
						_rushMode = false;
					}
					else
					{
						position = base.Formation.QuerySystem.Team.MedianPosition;
						Vec2 vec3 = (cachedMedianPosition.AsVec2 - cachedAveragePosition).Normalized();
						position.SetVec2(cachedMedianPosition.AsVec2 - vec3 * (missileRangeAdjusted - (10f + base.Formation.Depth * 0.5f)));
					}
				}
				else
				{
					if (num > 0)
					{
						position = base.Formation.QuerySystem.Team.MedianPosition;
						position.SetVec2(vec - (30f + base.Formation.Depth) * vec2);
					}
					else
					{
						position = base.Formation.CachedClosestEnemyFormation.Formation.CachedMedianPosition;
						position.SetVec2(position.AsVec2 - 80f * vec2);
					}
					if (position.AsVec2.DistanceSquared(cachedAveragePosition) <= 400f)
					{
						position = medianTargetFormationPosition;
						position.SetVec2(position.AsVec2 - vec2 * (missileRangeAdjusted - (10f + base.Formation.Depth * 0.5f)));
						_rushMode = true;
					}
				}
			}
			base.CurrentOrder = MovementOrder.MovementOrderMove(position);
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
		}
	}
	public class BehaviorMountedSkirmish : BehaviorComponent
	{
		private struct Ellipse
		{
			private readonly Vec2 _center;

			private readonly float _radius;

			private readonly float _halfLength;

			private readonly Vec2 _direction;

			public Ellipse(Vec2 center, float radius, float halfLength, Vec2 direction)
			{
				_center = center;
				_radius = radius;
				_halfLength = halfLength;
				_direction = direction;
			}

			public Vec2 GetTargetPos(Vec2 position, float distance)
			{
				Vec2 vec = _direction.LeftVec();
				Vec2 vec2 = _center + vec * _halfLength;
				Vec2 vec3 = _center - vec * _halfLength;
				Vec2 vec4 = position - _center;
				bool flag = vec4.Normalized().DotProduct(_direction) > 0f;
				Vec2 vec5 = vec4.DotProduct(vec) * vec;
				bool flag2 = vec5.Length < _halfLength;
				bool flag3 = true;
				if (flag2)
				{
					position = _center + vec5 + _direction * (_radius * (float)(flag ? 1 : (-1)));
				}
				else
				{
					flag3 = vec5.DotProduct(vec) > 0f;
					Vec2 vec6 = (position - (flag3 ? vec2 : vec3)).Normalized();
					position = (flag3 ? vec2 : vec3) + vec6 * _radius;
				}
				Vec2 vec7 = _center + vec5;
				float num = System.MathF.PI * 2f * _radius;
				while (distance > 0f)
				{
					if (flag2 && flag)
					{
						float num2 = (((vec2 - vec7).Length < distance) ? (vec2 - vec7).Length : distance);
						position = vec7 + (vec2 - vec7).Normalized() * num2;
						position += _direction * _radius;
						distance -= num2;
						flag2 = false;
						flag3 = true;
					}
					else if (!flag2 && flag3)
					{
						Vec2 v = (position - vec2).Normalized();
						float num3 = TaleWorlds.Library.MathF.Acos(MBMath.ClampFloat(_direction.DotProduct(v), -1f, 1f));
						float num4 = System.MathF.PI * 2f * (distance / num);
						float num5 = ((num3 + num4 < System.MathF.PI) ? (num3 + num4) : System.MathF.PI);
						float num6 = (num5 - num3) / System.MathF.PI * (num / 2f);
						Vec2 direction = _direction;
						direction.RotateCCW(num5);
						position = vec2 + direction * _radius;
						distance -= num6;
						flag2 = true;
						flag = false;
					}
					else if (flag2)
					{
						float num7 = (((vec3 - vec7).Length < distance) ? (vec3 - vec7).Length : distance);
						position = vec7 + (vec3 - vec7).Normalized() * num7;
						position -= _direction * _radius;
						distance -= num7;
						flag2 = false;
						flag3 = false;
					}
					else
					{
						Vec2 vec8 = (position - vec3).Normalized();
						float num8 = TaleWorlds.Library.MathF.Acos(MBMath.ClampFloat(_direction.DotProduct(vec8), -1f, 1f));
						float num9 = System.MathF.PI * 2f * (distance / num);
						float num10 = ((num8 - num9 > 0f) ? (num8 - num9) : 0f);
						float num11 = num8 - num10;
						float num12 = num11 / System.MathF.PI * (num / 2f);
						Vec2 vec9 = vec8;
						vec9.RotateCCW(num11);
						position = vec3 + vec9 * _radius;
						distance -= num12;
						flag2 = true;
						flag = true;
					}
				}
				return position;
			}
		}

		private bool _engaging = true;

		private bool _isEnemyReachable = true;

		public BehaviorMountedSkirmish(Formation formation)
			: base(formation)
		{
			CalculateCurrentOrder();
			base.BehaviorCoherence = 0.5f;
		}

		protected override void CalculateCurrentOrder()
		{
			WorldPosition position = base.Formation.CachedMedianPosition;
			_isEnemyReachable = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation != null && (!(base.Formation.Team.TeamAI is TeamAISiegeComponent) || !TeamAISiegeComponent.IsFormationInsideCastle(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation, includeOnlyPositionedUnits: false));
			if (!_isEnemyReachable)
			{
				position.SetVec2(base.Formation.CachedAveragePosition);
			}
			else
			{
				bool engaging = (base.Formation.QuerySystem.AverageAllyPosition - base.Formation.Team.QuerySystem.AverageEnemyPosition).LengthSquared <= 3600f || ((!_engaging) ? ((base.Formation.CachedAveragePosition - base.Formation.QuerySystem.AverageAllyPosition).LengthSquared <= 3600f) : (!(base.Formation.QuerySystem.UnderRangedAttackRatio > base.Formation.QuerySystem.MakingRangedAttackRatio) && ((!base.Formation.QuerySystem.FastestSignificantlyLargeEnemyFormation.IsCavalryFormation && !base.Formation.QuerySystem.FastestSignificantlyLargeEnemyFormation.IsRangedCavalryFormation) || (base.Formation.CachedAveragePosition - base.Formation.QuerySystem.FastestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2).LengthSquared / (base.Formation.QuerySystem.FastestSignificantlyLargeEnemyFormation.Formation.CachedMovementSpeed * base.Formation.QuerySystem.FastestSignificantlyLargeEnemyFormation.Formation.CachedMovementSpeed) >= 16f)));
				_engaging = engaging;
				if (_engaging)
				{
					Vec2 vec = (base.Formation.CachedAveragePosition - base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedAveragePosition).Normalized().LeftVec();
					FormationQuerySystem closestSignificantlyLargeEnemyFormation = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation;
					float num = 50f + (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.Width + base.Formation.Depth) * 0.5f;
					float num2 = 0f;
					Formation formation = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation;
					foreach (Team team in Mission.Current.Teams)
					{
						if (!team.IsEnemyOf(base.Formation.Team))
						{
							continue;
						}
						foreach (Formation item in team.FormationsIncludingSpecialAndEmpty)
						{
							if (item.CountOfUnits > 0 && item.QuerySystem != closestSignificantlyLargeEnemyFormation)
							{
								Vec2 v = item.CachedAveragePosition - closestSignificantlyLargeEnemyFormation.Formation.CachedAveragePosition;
								float num3 = v.Normalize();
								if (vec.DotProduct(v) > 0.8f && num3 < num && num3 > num2)
								{
									num2 = num3;
									formation = item;
								}
							}
						}
					}
					if (!(base.Formation.Team.TeamAI is TeamAISiegeComponent) && base.Formation.QuerySystem.RangedCavalryUnitRatio > 0.95f && base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation == formation)
					{
						base.CurrentOrder = MovementOrder.MovementOrderCharge;
						return;
					}
					bool flag = formation.QuerySystem.IsCavalryFormation || formation.QuerySystem.IsRangedCavalryFormation;
					float num4 = (flag ? 35f : 20f);
					num4 += (formation.Depth + base.Formation.Width) * 0.5f;
					num4 = TaleWorlds.Library.MathF.Min(num4, base.Formation.QuerySystem.MissileRangeAdjusted - base.Formation.Width * 0.5f);
					Ellipse ellipse = new Ellipse(formation.CachedMedianPosition.AsVec2, num4, formation.Width * 0.5f * (flag ? 1.5f : 1f), formation.Direction);
					position.SetVec2(ellipse.GetTargetPos(base.Formation.CachedAveragePosition, 20f));
				}
				else
				{
					position = new WorldPosition(Mission.Current.Scene, new Vec3(base.Formation.QuerySystem.AverageAllyPosition, base.Formation.Team.QuerySystem.MedianPosition.GetNavMeshZ() + 100f));
				}
			}
			base.CurrentOrder = MovementOrder.MovementOrderMove(position);
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtEnemy);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderDeep);
		}

		protected override float GetAiWeight()
		{
			if (!_isEnemyReachable)
			{
				return 0.1f;
			}
			return 1f;
		}
	}
	public class BehaviorProtectFlank : BehaviorComponent
	{
		private enum BehaviorState
		{
			HoldingFlank,
			Charging,
			Returning
		}

		private Formation _mainFormation;

		public FormationAI.BehaviorSide FlankSide;

		private BehaviorState _protectFlankState;

		private MovementOrder _movementOrder;

		private MovementOrder _chargeToTargetOrder;

		public BehaviorProtectFlank(Formation formation)
			: base(formation)
		{
			_protectFlankState = BehaviorState.HoldingFlank;
			_behaviorSide = formation.AI.Side;
			_mainFormation = formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
			CalculateCurrentOrder();
			base.CurrentOrder = _movementOrder;
		}

		protected override void CalculateCurrentOrder()
		{
			if (_mainFormation == null || base.Formation.AI.IsMainFormation || base.Formation.CachedClosestEnemyFormation == null)
			{
				base.CurrentOrder = MovementOrder.MovementOrderStop;
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			}
			else if (_protectFlankState == BehaviorState.HoldingFlank || _protectFlankState == BehaviorState.Returning)
			{
				Vec2 direction = _mainFormation.Direction;
				Vec2 vec = (base.Formation.QuerySystem.Team.MedianTargetFormationPosition.AsVec2 - _mainFormation.CachedMedianPosition.AsVec2).Normalized();
				Vec2 vec2;
				if (_behaviorSide == FormationAI.BehaviorSide.Right || FlankSide == FormationAI.BehaviorSide.Right)
				{
					vec2 = _mainFormation.CurrentPosition + vec.RightVec().Normalized() * (_mainFormation.Width + base.Formation.Width + 10f);
					vec2 -= vec * (_mainFormation.Depth + base.Formation.Depth);
				}
				else if (_behaviorSide == FormationAI.BehaviorSide.Left || FlankSide == FormationAI.BehaviorSide.Left)
				{
					vec2 = _mainFormation.CurrentPosition + vec.LeftVec().Normalized() * (_mainFormation.Width + base.Formation.Width + 10f);
					vec2 -= vec * (_mainFormation.Depth + base.Formation.Depth);
				}
				else
				{
					vec2 = _mainFormation.CurrentPosition + vec * ((_mainFormation.Depth + base.Formation.Depth) * 0.5f + 10f);
				}
				WorldPosition cachedMedianPosition = _mainFormation.CachedMedianPosition;
				cachedMedianPosition.SetVec2(vec2);
				_movementOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
				base.CurrentOrder = _movementOrder;
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(direction);
			}
		}

		private void CheckAndChangeState()
		{
			Vec2 position = _movementOrder.GetPosition(base.Formation);
			switch (_protectFlankState)
			{
			case BehaviorState.HoldingFlank:
			{
				FormationQuerySystem cachedClosestEnemyFormation = base.Formation.CachedClosestEnemyFormation;
				if (cachedClosestEnemyFormation != null)
				{
					float num = 50f + (base.Formation.Depth + cachedClosestEnemyFormation.Formation.Depth) / 2f;
					if (cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2.DistanceSquared(position) < num * num)
					{
						_chargeToTargetOrder = MovementOrder.MovementOrderChargeToTarget(cachedClosestEnemyFormation.Formation);
						base.CurrentOrder = _chargeToTargetOrder;
						_protectFlankState = BehaviorState.Charging;
					}
				}
				break;
			}
			case BehaviorState.Charging:
			{
				FormationQuerySystem cachedClosestEnemyFormation2 = base.Formation.CachedClosestEnemyFormation;
				if (cachedClosestEnemyFormation2 == null)
				{
					base.CurrentOrder = _movementOrder;
					_protectFlankState = BehaviorState.Returning;
					break;
				}
				float num2 = 60f + (base.Formation.Depth + cachedClosestEnemyFormation2.Formation.Depth) / 2f;
				if (base.Formation.CachedAveragePosition.DistanceSquared(position) > num2 * num2)
				{
					base.CurrentOrder = _movementOrder;
					_protectFlankState = BehaviorState.Returning;
				}
				break;
			}
			case BehaviorState.Returning:
				if (base.Formation.CachedAveragePosition.DistanceSquared(position) < 400f)
				{
					_protectFlankState = BehaviorState.HoldingFlank;
				}
				break;
			}
		}

		public override void OnValidBehaviorSideChanged()
		{
			base.OnValidBehaviorSideChanged();
			_mainFormation = base.Formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
		}

		public override void TickOccasionally()
		{
			CheckAndChangeState();
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (_protectFlankState == BehaviorState.HoldingFlank && base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation != null && base.Formation.CachedAveragePosition.DistanceSquared(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2) > 1600f && base.Formation.QuerySystem.UnderRangedAttackRatio > 0.2f - ((base.Formation.ArrangementOrder.OrderEnum == ArrangementOrder.ArrangementOrderEnum.Loose) ? 0.1f : 0f))
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLoose);
			}
			else
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderDeep);
		}

		public override TextObject GetBehaviorString()
		{
			TextObject behaviorString = base.GetBehaviorString();
			TextObject variable = GameTexts.FindText("str_formation_ai_side_strings", base.Formation.AI.Side.ToString());
			behaviorString.SetTextVariable("IS_GENERAL_SIDE", "0");
			behaviorString.SetTextVariable("SIDE_STRING", variable);
			if (_mainFormation != null)
			{
				behaviorString.SetTextVariable("AI_SIDE", GameTexts.FindText("str_formation_ai_side_strings", _mainFormation.AI.Side.ToString()));
				behaviorString.SetTextVariable("CLASS", GameTexts.FindText("str_formation_class_string", _mainFormation.PhysicalClass.GetName()));
			}
			return behaviorString;
		}

		protected override float GetAiWeight()
		{
			if (_mainFormation == null || !_mainFormation.AI.IsMainFormation)
			{
				_mainFormation = base.Formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
			}
			if (_mainFormation == null || base.Formation.AI.IsMainFormation)
			{
				return 0f;
			}
			return 1.2f;
		}
	}
