	public class BehaviorPullBack : BehaviorComponent
	{
		public BehaviorPullBack(Formation formation)
			: base(formation)
		{
			CalculateCurrentOrder();
			base.BehaviorCoherence = 0.2f;
		}

		protected override void CalculateCurrentOrder()
		{
			WorldPosition cachedMedianPosition = base.Formation.CachedMedianPosition;
			FormationQuerySystem cachedClosestEnemyFormation = base.Formation.CachedClosestEnemyFormation;
			if (cachedClosestEnemyFormation == null)
			{
				cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
			}
			else
			{
				Vec2 vec = (base.Formation.CachedAveragePosition - cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2).Normalized();
				cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition + 50f * vec);
			}
			base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLoose);
			base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtEnemy);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		protected override float GetAiWeight()
		{
			if (base.Formation.Team.TeamAI is TeamAISiegeComponent && !(base.Formation.Team.TeamAI is TeamAISallyOutAttacker) && !(base.Formation.Team.TeamAI is TeamAISallyOutDefender))
			{
				return GetSiegeAIWeight();
			}
			FormationQuerySystem querySystem = base.Formation.QuerySystem;
			FormationQuerySystem formationQuerySystem = querySystem.ClosestSignificantlyLargeEnemyFormation;
			if (formationQuerySystem == null || formationQuerySystem.Formation.CachedClosestEnemyFormation != querySystem || formationQuerySystem.MovementSpeedMaximum - querySystem.MovementSpeedMaximum > 2f)
			{
				formationQuerySystem = base.Formation.CachedClosestEnemyFormation;
				if (formationQuerySystem == null || formationQuerySystem.Formation.CachedClosestEnemyFormation != querySystem || formationQuerySystem.MovementSpeedMaximum - querySystem.MovementSpeedMaximum > 2f)
				{
					return 0f;
				}
			}
			float num = base.Formation.CachedAveragePosition.Distance(formationQuerySystem.Formation.CachedMedianPosition.AsVec2) / formationQuerySystem.MovementSpeedMaximum;
			float num2 = MBMath.ClampFloat(num, 4f, 10f);
			float num3 = MBMath.Lerp(0.1f, 1f, 1f - (num2 - 4f) / 6f);
			float num4 = 0f;
			foreach (Team team in Mission.Current.Teams)
			{
				if (!team.IsEnemyOf(base.Formation.Team))
				{
					continue;
				}
				foreach (Formation item in team.FormationsIncludingSpecialAndEmpty)
				{
					if (item.CountOfUnits <= 0 || item == formationQuerySystem.Formation)
					{
						continue;
					}
					float num5 = item.CachedMedianPosition.AsVec2.Distance(formationQuerySystem.Formation.CachedMedianPosition.AsVec2) / item.QuerySystem.MovementSpeedMaximum;
					if (!(num5 <= num + 4f) || (!(num > 8f) && item.CachedClosestEnemyFormation != base.Formation.QuerySystem))
					{
						continue;
					}
					bool flag = false;
					if (num <= 8f)
					{
						foreach (Team team2 in base.Formation.Team.Mission.Teams)
						{
							if (!team2.IsFriendOf(base.Formation.Team))
							{
								continue;
							}
							foreach (Formation item2 in team2.FormationsIncludingSpecialAndEmpty)
							{
								if (item2.CountOfUnits > 0 && item2 != base.Formation && item2.CachedClosestEnemyFormation == item.QuerySystem && item2.CachedMedianPosition.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition) / item2.QuerySystem.MovementSpeedMaximum < num5 + 4f)
								{
									flag = true;
									break;
								}
							}
							if (flag)
							{
								break;
							}
						}
					}
					if (!flag)
					{
						num4 += item.QuerySystem.FormationMeleeFightingPower * item.QuerySystem.GetClassWeightedFactor(1f, 1f, 1f, 1f);
					}
				}
			}
			float num6 = 0f;
			foreach (Team team3 in Mission.Current.Teams)
			{
				if (!team3.IsFriendOf(base.Formation.Team))
				{
					continue;
				}
				foreach (Formation item3 in team3.FormationsIncludingSpecialAndEmpty)
				{
					if (item3.CountOfUnits > 0 && item3 != base.Formation && item3.CachedClosestEnemyFormation == formationQuerySystem && item3.CachedMedianPosition.AsVec2.Distance(item3.CachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2) / item3.QuerySystem.MovementSpeedMaximum < 4f)
					{
						num6 += item3.QuerySystem.FormationMeleeFightingPower * item3.QuerySystem.GetClassWeightedFactor(1f, 1f, 1f, 1f);
					}
				}
			}
			return MBMath.ClampFloat((1f + num4 + formationQuerySystem.Formation.QuerySystem.FormationMeleeFightingPower * formationQuerySystem.GetClassWeightedFactor(1f, 1f, 1f, 1f)) / (base.Formation.GetFormationMeleeFightingPower() * querySystem.GetClassWeightedFactor(1f, 1f, 1f, 1f) + num6 + 1f) * querySystem.Team.RemainingPowerRatio / 3f, 0.1f, 1.21f) * num3;
		}

		private float GetSiegeAIWeight()
		{
			return 0f;
		}
	}
	public class BehaviorRegroup : BehaviorComponent
	{
		public BehaviorRegroup(Formation formation)
			: base(formation)
		{
			base.BehaviorCoherence = 1f;
			CalculateCurrentOrder();
		}

		protected override void CalculateCurrentOrder()
		{
			Vec2 direction = ((base.Formation.CachedClosestEnemyFormation != null) ? (base.Formation.CachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized() : base.Formation.Direction);
			WorldPosition cachedMedianPosition = base.Formation.CachedMedianPosition;
			cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
			base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
			CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(direction);
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
		}

		protected override float GetAiWeight()
		{
			FormationQuerySystem querySystem = base.Formation.QuerySystem;
			if (base.Formation.AI.ActiveBehavior == null)
			{
				return 0f;
			}
			float behaviorCoherence = base.Formation.AI.ActiveBehavior.BehaviorCoherence;
			return MBMath.Lerp(0.1f, 1.2f, MBMath.ClampFloat(behaviorCoherence * (base.Formation.CachedFormationIntegrityData.DeviationOfPositionsExcludeFarAgents + 1f) / (querySystem.IdealAverageDisplacement + 1f), 0f, 3f) / 3f);
		}
	}
	public class BehaviorReserve : BehaviorComponent
	{
		public BehaviorReserve(Formation formation)
			: base(formation)
		{
			_behaviorSide = formation.AI.Side;
			CalculateCurrentOrder();
		}

		protected override void CalculateCurrentOrder()
		{
			Formation formation = base.Formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f != base.Formation && f.AI.IsMainFormation);
			WorldPosition position;
			if (formation != null)
			{
				position = formation.CachedMedianPosition;
				Vec2 vec = (base.Formation.QuerySystem.Team.AverageEnemyPosition - formation.CachedMedianPosition.AsVec2).Normalized();
				position.SetVec2(position.AsVec2 - vec * (40f + base.Formation.Depth));
			}
			else
			{
				Vec2 zero = Vec2.Zero;
				int num = 0;
				foreach (Formation item in base.Formation.Team.FormationsIncludingSpecialAndEmpty)
				{
					if (item.CountOfUnits > 0 && item != base.Formation)
					{
						zero += item.CachedMedianPosition.AsVec2;
						num++;
					}
				}
				if (num <= 0)
				{
					base.CurrentOrder = MovementOrder.MovementOrderStop;
					return;
				}
				WorldPosition worldPosition = WorldPosition.Invalid;
				float num2 = float.MaxValue;
				zero *= 1f / (float)num;
				foreach (Formation item2 in base.Formation.Team.FormationsIncludingSpecialAndEmpty)
				{
					if (item2.CountOfUnits > 0 && item2 != base.Formation)
					{
						float num3 = zero.DistanceSquared(item2.CachedMedianPosition.AsVec2);
						if (num3 < num2)
						{
							num2 = num3;
							worldPosition = item2.CachedMedianPosition;
						}
					}
				}
				Vec2 vec2 = (base.Formation.QuerySystem.Team.AverageEnemyPosition - worldPosition.AsVec2).Normalized();
				position = worldPosition;
				position.SetVec2(position.AsVec2 - vec2 * (20f + base.Formation.Depth));
			}
			base.CurrentOrder = MovementOrder.MovementOrderMove(position);
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtEnemy);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWider);
		}

		protected override float GetAiWeight()
		{
			if (!base.Formation.AI.IsMainFormation)
			{
				foreach (Formation item in base.Formation.Team.FormationsIncludingSpecialAndEmpty)
				{
					if (base.Formation == item || item.CountOfUnits <= 0)
					{
						continue;
					}
					foreach (Team team in Mission.Current.Teams)
					{
						if (!team.IsEnemyOf(base.Formation.Team))
						{
							continue;
						}
						foreach (Formation item2 in team.FormationsIncludingSpecialAndEmpty)
						{
							if (item2.CountOfUnits > 0)
							{
								return 0.04f;
							}
						}
					}
					break;
				}
			}
			return 0f;
		}
	}
	public class BehaviorRetakeCastleKeyPosition : BehaviorComponent
	{
		private enum BehaviorState
		{
			UnSet,
			Gathering,
			Attacking
		}

		private BehaviorState _behaviorState;

		private MovementOrder _gatherOrder;

		private MovementOrder _attackOrder;

		private FacingOrder _gatheringFacingOrder;

		private FacingOrder _attackFacingOrder;

		private TacticalPosition _gatheringTacticalPos;

		private FormationAI.BehaviorSide _gatheringSide;

		public override float NavmeshlessTargetPositionPenalty => 1f;

		public BehaviorRetakeCastleKeyPosition(Formation formation)
			: base(formation)
		{
			_behaviorState = BehaviorState.UnSet;
			_behaviorSide = formation.AI.Side;
			ResetOrderPositions();
		}

		protected override void CalculateCurrentOrder()
		{
			base.CalculateCurrentOrder();
			base.CurrentOrder = ((_behaviorState == BehaviorState.Attacking) ? _attackOrder : _gatherOrder);
		}

		private FormationAI.BehaviorSide DetermineGatheringSide()
		{
			IEnumerable<SiegeLane> source = TeamAISiegeComponent.SiegeLanes.Where((SiegeLane sl) => sl.LaneSide != _behaviorSide && sl.LaneState != SiegeLane.LaneStateEnum.Conceited && sl.DefenderOrigin.IsValid);
			if (source.Any())
			{
				int nearestSafeSideDistance = source.Min((SiegeLane pgl) => SiegeQuerySystem.SideDistance(1 << (int)_behaviorSide, 1 << (int)pgl.LaneSide));
				return source.Where((SiegeLane pgl) => SiegeQuerySystem.SideDistance(1 << (int)_behaviorSide, 1 << (int)pgl.LaneSide) == nearestSafeSideDistance).MinBy((SiegeLane pgl) => pgl.DefenderOrigin.GetGroundVec3().DistanceSquared(base.Formation.CachedMedianPosition.GetGroundVec3())).LaneSide;
			}
			return _behaviorSide;
		}

		private void ConfirmGatheringSide()
		{
			SiegeLane siegeLane = TeamAISiegeComponent.SiegeLanes.FirstOrDefault((SiegeLane sl) => sl.LaneSide == _gatheringSide);
			if (siegeLane == null || siegeLane.LaneState >= SiegeLane.LaneStateEnum.Conceited)
			{
				ResetOrderPositions();
			}
		}

		private void ResetOrderPositions()
		{
			_behaviorState = BehaviorState.UnSet;
			_gatheringSide = DetermineGatheringSide();
			SiegeLane siegeLane = TeamAISiegeComponent.SiegeLanes.FirstOrDefault((SiegeLane sl) => sl.LaneSide == _gatheringSide);
			WorldFrame worldFrame = siegeLane.DefensePoints.FirstOrDefault((ICastleKeyPosition dp) => dp.AttackerSiegeWeapon is UsableMachine && !(dp.AttackerSiegeWeapon as UsableMachine).IsDisabled)?.DefenseWaitFrame ?? siegeLane.DefensePoints.FirstOrDefault().DefenseWaitFrame;
			_gatheringTacticalPos = siegeLane.DefensePoints.FirstOrDefault((ICastleKeyPosition dp) => dp.AttackerSiegeWeapon is UsableMachine && !(dp.AttackerSiegeWeapon as UsableMachine).IsDisabled)?.WaitPosition;
			if (_gatheringTacticalPos != null)
			{
				_gatherOrder = MovementOrder.MovementOrderMove(_gatheringTacticalPos.Position);
				_gatheringFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			}
			else if (worldFrame.Origin.IsValid)
			{
				worldFrame.Rotation.f.Normalize();
				_gatherOrder = MovementOrder.MovementOrderMove(worldFrame.Origin);
				_gatheringFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			}
			else
			{
				_gatherOrder = MovementOrder.MovementOrderMove(base.Formation.CachedMedianPosition);
				_gatheringFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			}
			SiegeLane siegeLane2 = TeamAISiegeComponent.SiegeLanes.FirstOrDefault((SiegeLane sl) => sl.LaneSide == _behaviorSide);
			_attackOrder = MovementOrder.MovementOrderMove(siegeLane2.DefensePoints.FirstOrDefault((ICastleKeyPosition dp) => dp.AttackerSiegeWeapon is UsableMachine && !(dp.AttackerSiegeWeapon as UsableMachine).IsDisabled)?.MiddleFrame.Origin ?? siegeLane2.DefensePoints.FirstOrDefault().MiddleFrame.Origin);
			_attackFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			base.CurrentOrder = ((_behaviorState == BehaviorState.Attacking) ? _attackOrder : _gatherOrder);
			CurrentFacingOrder = ((_behaviorState == BehaviorState.Attacking) ? _attackFacingOrder : _gatheringFacingOrder);
		}

		public override void OnValidBehaviorSideChanged()
		{
			base.OnValidBehaviorSideChanged();
			ResetOrderPositions();
		}

		public override void TickOccasionally()
		{
			base.TickOccasionally();
			if (_behaviorState != BehaviorState.Attacking)
			{
				ConfirmGatheringSide();
			}
			bool flag = true;
			if (_behaviorState != BehaviorState.Attacking)
			{
				flag = base.Formation.CachedMedianPosition.GetNavMeshVec3().DistanceSquared(_gatherOrder.CreateNewOrderWorldPositionMT(base.Formation, WorldPosition.WorldPositionEnforcedCache.NavMeshVec3).GetNavMeshVec3()) < 100f || base.Formation.CachedFormationIntegrityData.DeviationOfPositionsExcludeFarAgents / ((base.Formation.QuerySystem.IdealAverageDisplacement != 0f) ? base.Formation.QuerySystem.IdealAverageDisplacement : 1f) <= 3f;
			}
			BehaviorState behaviorState = ((!flag) ? BehaviorState.Gathering : BehaviorState.Attacking);
			if (behaviorState != _behaviorState)
			{
				_behaviorState = behaviorState;
				base.CurrentOrder = ((_behaviorState == BehaviorState.Attacking) ? _attackOrder : _gatherOrder);
				CurrentFacingOrder = ((_behaviorState == BehaviorState.Attacking) ? _attackFacingOrder : _gatheringFacingOrder);
			}
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (_behaviorState == BehaviorState.Gathering && _gatheringTacticalPos != null)
			{
				base.Formation.SetFormOrder(FormOrder.FormOrderCustom(_gatheringTacticalPos.Width));
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			_behaviorState = BehaviorState.UnSet;
			_behaviorSide = base.Formation.AI.Side;
			ResetOrderPositions();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		protected override float GetAiWeight()
		{
			return 1f;
		}
	}
	public class BehaviorRetreat : BehaviorComponent
	{
		public override float NavmeshlessTargetPositionPenalty => 1f;

		public BehaviorRetreat(Formation formation)
			: base(formation)
		{
			base.CurrentOrder = MovementOrder.MovementOrderRetreat;
			base.BehaviorCoherence = 0f;
		}

		public override void TickOccasionally()
		{
			base.Formation.SetMovementOrder(base.CurrentOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
		}

		protected override float GetAiWeight()
		{
			float casualtyPowerLossOfFormation = Mission.Current.GetMissionBehavior<CasualtyHandler>().GetCasualtyPowerLossOfFormation(base.Formation);
			float num = TaleWorlds.Library.MathF.Sqrt(casualtyPowerLossOfFormation / (base.Formation.QuerySystem.FormationPower + casualtyPowerLossOfFormation));
			return MBMath.ClampFloat(base.Formation.Team.QuerySystem.TotalPowerRatio, 0.1f, 3f) / MBMath.ClampFloat(base.Formation.Team.QuerySystem.RemainingPowerRatio, 0.1f, 3f) * (0.05f + num);
		}
	}
