	public class BehaviorSallyOut : BehaviorComponent
	{
		private readonly TeamAISiegeDefender _teamAISiegeDefender;

		private MovementOrder _gatherOrder;

		private MovementOrder _attackOrder;

		private TacticalPosition _gatheringTacticalPos;

		private bool _calculateAreGatesOutsideOpen
		{
			get
			{
				if (_teamAISiegeDefender.OuterGate == null || _teamAISiegeDefender.OuterGate.IsGateOpen)
				{
					if (_teamAISiegeDefender.InnerGate != null)
					{
						return _teamAISiegeDefender.InnerGate.IsGateOpen;
					}
					return true;
				}
				return false;
			}
		}

		private bool _calculateShouldStartAttacking
		{
			get
			{
				if (!_calculateAreGatesOutsideOpen)
				{
					return !TeamAISiegeComponent.IsFormationInsideCastle(base.Formation, includeOnlyPositionedUnits: true);
				}
				return true;
			}
		}

		public override float NavmeshlessTargetPositionPenalty => 1f;

		public BehaviorSallyOut(Formation formation)
			: base(formation)
		{
			_teamAISiegeDefender = formation.Team.TeamAI as TeamAISiegeDefender;
			_behaviorSide = formation.AI.Side;
			ResetOrderPositions();
		}

		protected override void CalculateCurrentOrder()
		{
			base.CalculateCurrentOrder();
			base.CurrentOrder = (_calculateShouldStartAttacking ? _attackOrder : _gatherOrder);
		}

		private void ResetOrderPositions()
		{
			SiegeLane siegeLane = TeamAISiegeComponent.SiegeLanes.FirstOrDefault((SiegeLane sl) => sl.LaneSide == FormationAI.BehaviorSide.Middle);
			WorldFrame worldFrame = siegeLane?.DefensePoints.FirstOrDefault((ICastleKeyPosition dp) => dp.AttackerSiegeWeapon is UsableMachine && !(dp.AttackerSiegeWeapon as UsableMachine).IsDisabled)?.DefenseWaitFrame ?? WorldFrame.Invalid;
			_gatheringTacticalPos = siegeLane?.DefensePoints.FirstOrDefault((ICastleKeyPosition dp) => dp.AttackerSiegeWeapon is UsableMachine && !(dp.AttackerSiegeWeapon as UsableMachine).IsDisabled)?.WaitPosition;
			if (_gatheringTacticalPos != null)
			{
				_gatherOrder = MovementOrder.MovementOrderMove(_gatheringTacticalPos.Position);
			}
			else if (worldFrame.Origin.IsValid)
			{
				worldFrame.Rotation.f.Normalize();
				_gatherOrder = MovementOrder.MovementOrderMove(worldFrame.Origin);
			}
			else
			{
				_gatherOrder = MovementOrder.MovementOrderMove(base.Formation.CachedMedianPosition);
			}
			_attackOrder = MovementOrder.MovementOrderCharge;
			base.CurrentOrder = (_calculateShouldStartAttacking ? _attackOrder : _gatherOrder);
		}

		public override void TickOccasionally()
		{
			base.TickOccasionally();
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			if (!_calculateAreGatesOutsideOpen)
			{
				CastleGate castleGate = ((_teamAISiegeDefender.InnerGate != null && !_teamAISiegeDefender.InnerGate.IsGateOpen) ? _teamAISiegeDefender.InnerGate : _teamAISiegeDefender.OuterGate);
				if (!castleGate.IsUsedByFormation(base.Formation))
				{
					base.Formation.StartUsingMachine(castleGate);
				}
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			_behaviorSide = base.Formation.AI.Side;
			ResetOrderPositions();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtEnemy);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		protected override float GetAiWeight()
		{
			return 10f;
		}
	}
	public class BehaviorScreenedSkirmish : BehaviorComponent
	{
		private Formation _mainFormation;

		private bool _isFireAtWill = true;

		public BehaviorScreenedSkirmish(Formation formation)
			: base(formation)
		{
			_behaviorSide = formation.AI.Side;
			_mainFormation = formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
			CalculateCurrentOrder();
		}

		protected override void CalculateCurrentOrder()
		{
			Vec2 vec2;
			if (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation != null && _mainFormation != null)
			{
				Vec2 vec = (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized();
				Vec2 v = (_mainFormation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized();
				vec2 = ((vec.DotProduct(v) > 0.5f) ? _mainFormation.FacingOrder.GetDirection(_mainFormation) : vec);
			}
			else
			{
				vec2 = base.Formation.Direction;
			}
			WorldPosition cachedMedianPosition;
			if (_mainFormation == null)
			{
				cachedMedianPosition = base.Formation.CachedMedianPosition;
				cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
			}
			else
			{
				cachedMedianPosition = _mainFormation.CachedMedianPosition;
				cachedMedianPosition.SetVec2(cachedMedianPosition.AsVec2 - vec2 * ((_mainFormation.Depth + base.Formation.Depth) * 0.5f));
			}
			if (!base.CurrentOrder.CreateNewOrderWorldPositionMT(base.Formation, WorldPosition.WorldPositionEnforcedCache.None).IsValid || (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation != null && (!base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.IsRangedCavalryFormation || base.Formation.CachedAveragePosition.DistanceSquared(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.GetNavMeshVec3().AsVec2) >= base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.MissileRangeAdjusted * base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.MissileRangeAdjusted || base.CurrentOrder.CreateNewOrderWorldPositionMT(base.Formation, WorldPosition.WorldPositionEnforcedCache.NavMeshVec3).GetNavMeshVec3().DistanceSquared(cachedMedianPosition.GetNavMeshVec3()) >= base.Formation.Depth * base.Formation.Depth)))
			{
				base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
			}
			if (!CurrentFacingOrder.GetDirection(base.Formation).IsValid || CurrentFacingOrder.OrderEnum == FacingOrder.FacingOrderEnum.LookAtEnemy || base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation == null || base.Formation.CachedAveragePosition.DistanceSquared(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.GetNavMeshVec3().AsVec2) >= base.Formation.QuerySystem.MissileRangeAdjusted * base.Formation.QuerySystem.MissileRangeAdjusted || (!base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.IsRangedCavalryFormation && CurrentFacingOrder.GetDirection(base.Formation).DotProduct(vec2) <= MBMath.Lerp(0.5f, 1f, 1f - MBMath.ClampFloat(base.Formation.Width, 1f, 20f) * 0.05f)))
			{
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(vec2);
			}
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			FormationQuerySystem cachedClosestEnemyFormation = base.Formation.CachedClosestEnemyFormation;
			bool flag = cachedClosestEnemyFormation == null || _mainFormation.CachedMedianPosition.AsVec2.DistanceSquared(cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2) <= base.Formation.CachedAveragePosition.DistanceSquared(cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2) || base.Formation.CachedAveragePosition.DistanceSquared(base.CurrentOrder.GetPosition(base.Formation)) <= (_mainFormation.Depth + base.Formation.Depth) * (_mainFormation.Depth + base.Formation.Depth) * 0.25f;
			if (flag != _isFireAtWill)
			{
				_isFireAtWill = flag;
				base.Formation.SetFiringOrder(_isFireAtWill ? FiringOrder.FiringOrderFireAtWill : FiringOrder.FiringOrderHoldYourFire);
			}
			if (_mainFormation != null && TaleWorlds.Library.MathF.Abs(_mainFormation.Width - base.Formation.Width) > 10f)
			{
				base.Formation.SetFormOrder(FormOrder.FormOrderCustom(_mainFormation.Width));
			}
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderScatter);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		public override TextObject GetBehaviorString()
		{
			TextObject behaviorString = base.GetBehaviorString();
			if (_mainFormation != null)
			{
				behaviorString.SetTextVariable("AI_SIDE", GameTexts.FindText("str_formation_ai_side_strings", _mainFormation.AI.Side.ToString()));
				behaviorString.SetTextVariable("CLASS", GameTexts.FindText("str_formation_class_string", _mainFormation.PhysicalClass.GetName()));
			}
			return behaviorString;
		}

		protected override float GetAiWeight()
		{
			MovementOrder m = base.CurrentOrder;
			if (m == MovementOrder.MovementOrderStop)
			{
				CalculateCurrentOrder();
			}
			if (_mainFormation == null || !_mainFormation.AI.IsMainFormation)
			{
				_mainFormation = base.Formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
			}
			if (_behaviorSide != base.Formation.AI.Side)
			{
				_behaviorSide = base.Formation.AI.Side;
			}
			FormationQuerySystem cachedClosestEnemyFormation = base.Formation.CachedClosestEnemyFormation;
			if (_mainFormation == null || base.Formation.AI.IsMainFormation || cachedClosestEnemyFormation == null)
			{
				return 0f;
			}
			FormationQuerySystem querySystem = base.Formation.QuerySystem;
			float num = MBMath.Lerp(0.1f, 1f, MBMath.ClampFloat(querySystem.RangedUnitRatio + querySystem.RangedCavalryUnitRatio, 0f, 0.5f) * 2f);
			float num2 = _mainFormation.Direction.Normalized().DotProduct((cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2 - _mainFormation.CachedMedianPosition.AsVec2).Normalized());
			float num3 = MBMath.LinearExtrapolation(0.5f, 1.1f, (num2 + 1f) / 2f);
			float value = base.Formation.CachedAveragePosition.Distance(cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2) / cachedClosestEnemyFormation.MovementSpeedMaximum;
			float num4 = MBMath.Lerp(0.5f, 1.2f, (8f - MBMath.ClampFloat(value, 4f, 8f)) / 4f);
			return num * base.Formation.QuerySystem.MainFormationReliabilityFactor * num3 * num4;
		}
	}
	public class BehaviorSergeantMPInfantry : BehaviorComponent
	{
		private enum BehaviorState
		{
			GoingToFlag,
			Attacking,
			Unset
		}

		private BehaviorState _behaviorState;

		private List<FlagCapturePoint> _flagpositions;

		private MissionMultiplayerFlagDomination _flagDominationGameMode;

		public BehaviorSergeantMPInfantry(Formation formation)
			: base(formation)
		{
			_behaviorState = BehaviorState.Unset;
			_flagpositions = base.Formation.Team.Mission.ActiveMissionObjects.FindAllWithType<FlagCapturePoint>().ToList();
			_flagDominationGameMode = base.Formation.Team.Mission.GetMissionBehavior<MissionMultiplayerFlagDomination>();
			CalculateCurrentOrder();
		}

		protected override void CalculateCurrentOrder()
		{
			BehaviorState behaviorState = ((base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation != null && ((base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.IsRangedFormation && base.Formation.CachedAveragePosition.DistanceSquared(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2) <= ((_behaviorState == BehaviorState.Attacking) ? 3600f : 2500f)) || (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.IsInfantryFormation && base.Formation.CachedAveragePosition.DistanceSquared(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2) <= ((_behaviorState == BehaviorState.Attacking) ? 900f : 400f)))) ? BehaviorState.Attacking : BehaviorState.GoingToFlag);
			if (behaviorState == BehaviorState.Attacking && (_behaviorState != BehaviorState.Attacking || base.CurrentOrder.OrderEnum != MovementOrder.MovementOrderEnum.ChargeToTarget || base.CurrentOrder.TargetFormation.QuerySystem != base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation))
			{
				_behaviorState = BehaviorState.Attacking;
				base.CurrentOrder = MovementOrder.MovementOrderChargeToTarget(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation);
			}
			if (behaviorState != 0)
			{
				return;
			}
			_behaviorState = behaviorState;
			WorldPosition position;
			if (_flagpositions.Any((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) != base.Formation.Team))
			{
				position = new WorldPosition(base.Formation.Team.Mission.Scene, UIntPtr.Zero, _flagpositions.Where((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) != base.Formation.Team).MinBy((FlagCapturePoint fp) => fp.Position.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition)).Position, hasValidZ: false);
			}
			else if (_flagpositions.Any((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) == base.Formation.Team))
			{
				position = new WorldPosition(base.Formation.Team.Mission.Scene, UIntPtr.Zero, _flagpositions.Where((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) == base.Formation.Team).MinBy((FlagCapturePoint fp) => fp.Position.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition)).Position, hasValidZ: false);
			}
			else
			{
				position = base.Formation.CachedMedianPosition;
				position.SetVec2(base.Formation.CachedAveragePosition);
			}
			if (base.CurrentOrder.OrderEnum == MovementOrder.MovementOrderEnum.Invalid || base.CurrentOrder.GetPosition(base.Formation) != position.AsVec2)
			{
				Vec2 direction = ((base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation != null) ? (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized() : base.Formation.Direction);
				base.CurrentOrder = MovementOrder.MovementOrderMove(position);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(direction);
			}
		}

		public override void TickOccasionally()
		{
			_flagpositions.RemoveAll((FlagCapturePoint fp) => fp.IsDeactivated);
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (base.Formation.QuerySystem.HasShield && (_behaviorState == BehaviorState.Attacking || (_behaviorState == BehaviorState.GoingToFlag && base.CurrentOrder.GetPosition(base.Formation).IsValid && base.Formation.CachedAveragePosition.DistanceSquared(base.CurrentOrder.GetPosition(base.Formation)) <= 225f)))
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderShieldWall);
			}
			else
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderDeep);
		}

		protected override float GetAiWeight()
		{
			if (base.Formation.QuerySystem.IsInfantryFormation)
			{
				return 1.2f;
			}
			return 0f;
		}
	}
	public class BehaviorSergeantMPLastFlagLastStand : BehaviorComponent
	{
		private List<FlagCapturePoint> _flagpositions;

		private bool _lastEffort;

		private MissionMultiplayerFlagDomination _flagDominationGameMode;

		public BehaviorSergeantMPLastFlagLastStand(Formation formation)
			: base(formation)
		{
			_flagpositions = Mission.Current.ActiveMissionObjects.FindAllWithType<FlagCapturePoint>().ToList();
			_flagDominationGameMode = Mission.Current.GetMissionBehavior<MissionMultiplayerFlagDomination>();
			CalculateCurrentOrder();
		}

		protected override void CalculateCurrentOrder()
		{
			base.CurrentOrder = ((_flagpositions.Count > 0) ? MovementOrder.MovementOrderMove(new WorldPosition(Mission.Current.Scene, UIntPtr.Zero, _flagpositions[0].Position, hasValidZ: false)) : MovementOrder.MovementOrderStop);
		}

		public override void TickOccasionally()
		{
			_flagpositions.RemoveAll((FlagCapturePoint fp) => fp.IsDeactivated);
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderHoldYourFire);
		}

		protected override void OnBehaviorActivatedAux()
		{
			_flagpositions.RemoveAll((FlagCapturePoint fp) => fp.IsDeactivated);
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtEnemy);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderHoldYourFire);
			base.Formation.SetFormOrder(FormOrder.FormOrderDeep);
		}

		protected override float GetAiWeight()
		{
			if (_lastEffort)
			{
				return 10f;
			}
			_flagpositions.RemoveAll((FlagCapturePoint fp) => fp.IsDeactivated);
			FlagCapturePoint flagCapturePoint = _flagpositions.FirstOrDefault();
			if (_flagpositions.Count != 1 || _flagDominationGameMode.GetFlagOwnerTeam(flagCapturePoint) == null || !_flagDominationGameMode.GetFlagOwnerTeam(flagCapturePoint).IsEnemyOf(base.Formation.Team))
			{
				return 0f;
			}
			float timeUntilBattleSideVictory = _flagDominationGameMode.GetTimeUntilBattleSideVictory(_flagDominationGameMode.GetFlagOwnerTeam(flagCapturePoint).Side);
			if (timeUntilBattleSideVictory <= 60f)
			{
				return 10f;
			}
			float num = base.Formation.CachedAveragePosition.Distance(flagCapturePoint.Position.AsVec2);
			float movementSpeedMaximum = base.Formation.QuerySystem.MovementSpeedMaximum;
			if (num / movementSpeedMaximum * 8f > timeUntilBattleSideVictory)
			{
				_lastEffort = true;
				return 10f;
			}
			return 0f;
		}
	}
	public class BehaviorSergeantMPMounted : BehaviorComponent
	{
		private List<FlagCapturePoint> _flagpositions;

		private MissionMultiplayerFlagDomination _flagDominationGameMode;

		public BehaviorSergeantMPMounted(Formation formation)
			: base(formation)
		{
			_flagpositions = base.Formation.Team.Mission.ActiveMissionObjects.FindAllWithType<FlagCapturePoint>().ToList();
			_flagDominationGameMode = base.Formation.Team.Mission.GetMissionBehavior<MissionMultiplayerFlagDomination>();
			CalculateCurrentOrder();
		}

		private MovementOrder UncapturedFlagMoveOrder()
		{
			if (_flagpositions.Any((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) != base.Formation.Team))
			{
				FlagCapturePoint flagCapturePoint = _flagpositions.Where((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) != base.Formation.Team).MinBy((FlagCapturePoint fp) => base.Formation.Team.QuerySystem.GetLocalEnemyPower(fp.Position.AsVec2));
				return MovementOrder.MovementOrderMove(new WorldPosition(base.Formation.Team.Mission.Scene, UIntPtr.Zero, flagCapturePoint.Position, hasValidZ: false));
			}
			if (_flagpositions.Any((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) == base.Formation.Team))
			{
				Vec3 position = _flagpositions.Where((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) == base.Formation.Team).MinBy((FlagCapturePoint fp) => fp.Position.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition)).Position;
				return MovementOrder.MovementOrderMove(new WorldPosition(base.Formation.Team.Mission.Scene, UIntPtr.Zero, position, hasValidZ: false));
			}
			return MovementOrder.MovementOrderStop;
		}

		protected override void CalculateCurrentOrder()
		{
			if (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation == null || base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition) > 2500f)
			{
				base.CurrentOrder = UncapturedFlagMoveOrder();
				return;
			}
			FlagCapturePoint flagCapturePoint = null;
			if (_flagpositions.Any((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) != base.Formation.Team && !fp.IsContested))
			{
				flagCapturePoint = _flagpositions.Where((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) != base.Formation.Team && !fp.IsContested).MinBy((FlagCapturePoint fp) => base.Formation.CachedAveragePosition.DistanceSquared(fp.Position.AsVec2));
			}
			if ((!base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.IsRangedFormation || !(base.Formation.QuerySystem.FormationPower / base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.FormationPower / base.Formation.Team.QuerySystem.RemainingPowerRatio > 0.7f)) && flagCapturePoint != null)
			{
				base.CurrentOrder = MovementOrder.MovementOrderMove(new WorldPosition(base.Formation.Team.Mission.Scene, UIntPtr.Zero, flagCapturePoint.Position, hasValidZ: false));
			}
			else
			{
				base.CurrentOrder = MovementOrder.MovementOrderChargeToTarget(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation);
			}
		}

		public override void TickOccasionally()
		{
			_flagpositions.RemoveAll((FlagCapturePoint fp) => fp.IsDeactivated);
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtEnemy);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderDeep);
		}

		protected override float GetAiWeight()
		{
			if (base.Formation.QuerySystem.IsCavalryFormation)
			{
				return 1.2f;
			}
			return 0f;
		}
	}
	public class BehaviorSergeantMPMountedRanged : BehaviorComponent
	{
		private List<FlagCapturePoint> _flagpositions;

		private MissionMultiplayerFlagDomination _flagDominationGameMode;

		public BehaviorSergeantMPMountedRanged(Formation formation)
			: base(formation)
		{
			_flagpositions = base.Formation.Team.Mission.ActiveMissionObjects.FindAllWithType<FlagCapturePoint>().ToList();
			_flagDominationGameMode = base.Formation.Team.Mission.GetMissionBehavior<MissionMultiplayerFlagDomination>();
			CalculateCurrentOrder();
		}

		private MovementOrder UncapturedFlagMoveOrder()
		{
			if (_flagpositions.Any((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) != base.Formation.Team))
			{
				FlagCapturePoint flagCapturePoint = _flagpositions.Where((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) != base.Formation.Team).MinBy((FlagCapturePoint fp) => base.Formation.Team.QuerySystem.GetLocalEnemyPower(fp.Position.AsVec2));
				return MovementOrder.MovementOrderMove(new WorldPosition(base.Formation.Team.Mission.Scene, UIntPtr.Zero, flagCapturePoint.Position, hasValidZ: false));
			}
			if (_flagpositions.Any((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) == base.Formation.Team))
			{
				Vec3 position = _flagpositions.Where((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) == base.Formation.Team).MinBy((FlagCapturePoint fp) => fp.Position.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition)).Position;
				return MovementOrder.MovementOrderMove(new WorldPosition(base.Formation.Team.Mission.Scene, UIntPtr.Zero, position, hasValidZ: false));
			}
			return MovementOrder.MovementOrderStop;
		}

		protected override void CalculateCurrentOrder()
		{
			if (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation == null || base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition) > 2500f)
			{
				base.CurrentOrder = UncapturedFlagMoveOrder();
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
				return;
			}
			FlagCapturePoint flagCapturePoint = null;
			if (_flagpositions.Any((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) != base.Formation.Team && !fp.IsContested))
			{
				flagCapturePoint = _flagpositions.Where((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) != base.Formation.Team && !fp.IsContested).MinBy((FlagCapturePoint fp) => base.Formation.CachedAveragePosition.DistanceSquared(fp.Position.AsVec2));
			}
			if (!base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.IsInfantryFormation && flagCapturePoint != null)
			{
				WorldPosition position = new WorldPosition(base.Formation.Team.Mission.Scene, UIntPtr.Zero, flagCapturePoint.Position, hasValidZ: false);
				base.CurrentOrder = MovementOrder.MovementOrderMove(position);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
				return;
			}
			if (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.IsRangedFormation)
			{
				base.CurrentOrder = MovementOrder.MovementOrderChargeToTarget(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
				return;
			}
			Vec2 vec = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition;
			float num = vec.Normalize();
			WorldPosition cachedMedianPosition = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition;
			if (num > base.Formation.QuerySystem.MissileRangeAdjusted)
			{
				cachedMedianPosition.SetVec2(cachedMedianPosition.AsVec2 - vec * (base.Formation.QuerySystem.MissileRangeAdjusted - base.Formation.Depth * 0.5f));
			}
			else if (num < base.Formation.QuerySystem.MissileRangeAdjusted * 0.4f)
			{
				cachedMedianPosition.SetVec2(cachedMedianPosition.AsVec2 - vec * (base.Formation.QuerySystem.MissileRangeAdjusted * 0.7f));
			}
			else
			{
				vec = vec.RightVec();
				cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition + vec * 20f);
			}
			base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
			CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(vec);
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (base.CurrentOrder.OrderEnum == MovementOrder.MovementOrderEnum.ChargeToTarget && base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation != null && base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.IsRangedFormation)
			{
				base.Formation.SetFiringOrder(FiringOrder.FiringOrderHoldYourFire);
			}
			else
			{
				base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			_flagpositions.RemoveAll((FlagCapturePoint fp) => fp.IsDeactivated);
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderDeep);
		}

		protected override float GetAiWeight()
		{
			if (base.Formation.QuerySystem.IsRangedCavalryFormation)
			{
				return 1.2f;
			}
			return 0f;
		}
	}
	public class BehaviorSergeantMPRanged : BehaviorComponent
	{
		private List<FlagCapturePoint> _flagpositions;

		private Formation _attachedInfantry;

		private MissionMultiplayerFlagDomination _flagDominationGameMode;

		public BehaviorSergeantMPRanged(Formation formation)
			: base(formation)
		{
			_flagpositions = base.Formation.Team.Mission.ActiveMissionObjects.FindAllWithType<FlagCapturePoint>().ToList();
			_flagDominationGameMode = base.Formation.Team.Mission.GetMissionBehavior<MissionMultiplayerFlagDomination>();
			CalculateCurrentOrder();
		}

		protected override void CalculateCurrentOrder()
		{
			bool flag = false;
			Formation formation = null;
			float num = float.MaxValue;
			foreach (Team team in base.Formation.Team.Mission.Teams)
			{
				if (!team.IsEnemyOf(base.Formation.Team))
				{
					continue;
				}
				for (int i = 0; i < Math.Min(team.FormationsIncludingSpecialAndEmpty.Count, 8); i++)
				{
					Formation formation2 = team.FormationsIncludingSpecialAndEmpty[i];
					if (formation2.CountOfUnits <= 0)
					{
						continue;
					}
					flag = true;
					if (formation2.QuerySystem.IsCavalryFormation || formation2.QuerySystem.IsRangedCavalryFormation)
					{
						float num2 = formation2.CachedMedianPosition.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition);
						if (num2 < num)
						{
							num = num2;
							formation = formation2;
						}
					}
				}
			}
			if (base.Formation.Team.FormationsIncludingEmpty.AnyQ((Formation f) => f.CountOfUnits > 0 && f != base.Formation && f.QuerySystem.IsInfantryFormation))
			{
				_attachedInfantry = base.Formation.Team.FormationsIncludingEmpty.Where((Formation f) => f.CountOfUnits > 0 && f != base.Formation && f.QuerySystem.IsInfantryFormation).MinBy((Formation f) => f.CachedMedianPosition.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition));
				Formation formation3 = null;
				if (flag)
				{
					if (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition) <= 4900f)
					{
						formation3 = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation;
					}
					else if (formation != null)
					{
						formation3 = formation;
					}
				}
				Vec2 vec = ((formation3 == null) ? _attachedInfantry.Direction : (formation3.CachedMedianPosition.AsVec2 - _attachedInfantry.CachedMedianPosition.AsVec2).Normalized());
				WorldPosition cachedMedianPosition = _attachedInfantry.CachedMedianPosition;
				cachedMedianPosition.SetVec2(cachedMedianPosition.AsVec2 - vec * ((_attachedInfantry.Depth + base.Formation.Depth) / 2f));
				base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(vec);
			}
			else if (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation != null && base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition) <= 4900f)
			{
				Vec2 vec2 = (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized();
				float num3 = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2.Distance(base.Formation.CachedAveragePosition);
				WorldPosition cachedMedianPosition2 = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition;
				if (num3 > base.Formation.QuerySystem.MissileRangeAdjusted)
				{
					cachedMedianPosition2.SetVec2(cachedMedianPosition2.AsVec2 - vec2 * (base.Formation.QuerySystem.MissileRangeAdjusted - base.Formation.Depth * 0.5f));
				}
				else if (num3 < base.Formation.QuerySystem.MissileRangeAdjusted * 0.4f)
				{
					cachedMedianPosition2.SetVec2(cachedMedianPosition2.AsVec2 - vec2 * (base.Formation.QuerySystem.MissileRangeAdjusted * 0.4f));
				}
				else
				{
					cachedMedianPosition2.SetVec2(base.Formation.CachedAveragePosition);
				}
				base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition2);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(vec2);
			}
			else if (_flagpositions.Any((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) != base.Formation.Team))
			{
				Vec3 position = _flagpositions.Where((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) != base.Formation.Team).MinBy((FlagCapturePoint fp) => fp.Position.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition)).Position;
				if (base.CurrentOrder.OrderEnum == MovementOrder.MovementOrderEnum.Invalid || base.CurrentOrder.GetPosition(base.Formation) != position.AsVec2)
				{
					Vec2 direction = ((base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation != null) ? (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized() : base.Formation.Direction);
					WorldPosition position2 = new WorldPosition(base.Formation.Team.Mission.Scene, UIntPtr.Zero, position, hasValidZ: false);
					base.CurrentOrder = MovementOrder.MovementOrderMove(position2);
					CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(direction);
				}
			}
			else if (_flagpositions.Any((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) == base.Formation.Team))
			{
				Vec3 position3 = _flagpositions.Where((FlagCapturePoint fp) => _flagDominationGameMode.GetFlagOwnerTeam(fp) == base.Formation.Team).MinBy((FlagCapturePoint fp) => fp.Position.AsVec2.DistanceSquared(base.Formation.CachedAveragePosition)).Position;
				base.CurrentOrder = MovementOrder.MovementOrderMove(new WorldPosition(base.Formation.Team.Mission.Scene, UIntPtr.Zero, position3, hasValidZ: false));
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			}
			else
			{
				WorldPosition cachedMedianPosition3 = base.Formation.CachedMedianPosition;
				cachedMedianPosition3.SetVec2(base.Formation.CachedAveragePosition);
				base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition3);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			}
		}

		public override void TickOccasionally()
		{
			_flagpositions.RemoveAll((FlagCapturePoint fp) => fp.IsDeactivated);
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLoose);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		protected override float GetAiWeight()
		{
			if (base.Formation.QuerySystem.IsRangedFormation)
			{
				return 1.2f;
			}
			return 0f;
		}
	}
	public class BehaviorShootFromCastleWalls : BehaviorComponent
	{
		private GameEntity _archerPosition;

		private TacticalPosition _tacticalArcherPosition;

		private bool _areStrategicArcherAreasAbandoned;

		public GameEntity ArcherPosition
		{
			get
			{
				return _archerPosition;
			}
			set
			{
				if (_archerPosition != value)
				{
					OnArcherPositionSet(value);
				}
			}
		}

		public override float NavmeshlessTargetPositionPenalty => 1f;

		public BehaviorShootFromCastleWalls(Formation formation)
			: base(formation)
		{
			OnArcherPositionSet(_archerPosition);
			base.BehaviorCoherence = 0f;
		}

		private void OnArcherPositionSet(GameEntity value)
		{
			_archerPosition = value;
			if (_archerPosition != null)
			{
				_tacticalArcherPosition = _archerPosition.GetFirstScriptOfType<TacticalPosition>();
				if (_tacticalArcherPosition != null)
				{
					base.CurrentOrder = MovementOrder.MovementOrderMove(_tacticalArcherPosition.Position);
					CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(_tacticalArcherPosition.Direction);
				}
				else
				{
					base.CurrentOrder = MovementOrder.MovementOrderMove(_archerPosition.GlobalPosition.ToWorldPosition());
					CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(_archerPosition.GetGlobalFrame().rotation.f.AsVec2);
				}
			}
			else
			{
				_tacticalArcherPosition = null;
				WorldPosition cachedMedianPosition = base.Formation.CachedMedianPosition;
				cachedMedianPosition.SetVec2(base.Formation.CurrentPosition);
				base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			}
		}

		public override void TickOccasionally()
		{
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (_tacticalArcherPosition != null)
			{
				base.Formation.SetFormOrder(FormOrder.FormOrderCustom(_tacticalArcherPosition.Width));
			}
			foreach (Team team in base.Formation.Team.Mission.Teams)
			{
				if (!team.IsEnemyOf(base.Formation.Team))
				{
					continue;
				}
				if (!_areStrategicArcherAreasAbandoned)
				{
					if (team.QuerySystem.InsideWallsRatio > 0.6f)
					{
						base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
						_areStrategicArcherAreasAbandoned = true;
					}
				}
				else if (team.QuerySystem.InsideWallsRatio <= 0.4f)
				{
					base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderScatter);
					_areStrategicArcherAreasAbandoned = false;
				}
				break;
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderScatter);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		protected override float GetAiWeight()
		{
			return 10f * (base.Formation.QuerySystem.RangedCavalryUnitRatio + base.Formation.QuerySystem.RangedUnitRatio);
		}
	}
	public class BehaviorShootFromCliff : BehaviorComponent
	{
		private WorldPosition _defensePosition = WorldPosition.Invalid;

		private TacticalPosition _tacticalDefendPosition;

		public BehaviorShootFromCliff(Formation formation)
			: base(formation)
		{
			CalculateCurrentOrder();
		}

		public void SetTacticalDefendPosition(TacticalPosition tacticalPosition)
		{
			_tacticalDefendPosition = tacticalPosition;
		}

		protected override void CalculateCurrentOrder()
		{
			Vec2 vec = ((_tacticalDefendPosition != null) ? ((!_tacticalDefendPosition.IsInsurmountable) ? _tacticalDefendPosition.Direction : (base.Formation.Team.QuerySystem.AverageEnemyPosition - _tacticalDefendPosition.Position.AsVec2).Normalized()) : ((base.Formation.CachedClosestEnemyFormation != null) ? ((base.Formation.Direction.DotProduct((base.Formation.CachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized()) < 0.5f) ? (base.Formation.CachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition) : base.Formation.Direction).Normalized() : base.Formation.Direction));
			if (_tacticalDefendPosition != null)
			{
				if (!_tacticalDefendPosition.IsInsurmountable)
				{
					base.CurrentOrder = MovementOrder.MovementOrderMove(_tacticalDefendPosition.Position);
				}
				else
				{
					Vec2 vec2 = _tacticalDefendPosition.Position.AsVec2 + _tacticalDefendPosition.Width * 0.5f * vec;
					WorldPosition position = _tacticalDefendPosition.Position;
					position.SetVec2(vec2);
					base.CurrentOrder = MovementOrder.MovementOrderMove(position);
				}
				CurrentFacingOrder = ((!_tacticalDefendPosition.IsInsurmountable) ? FacingOrder.FacingOrderLookAtDirection(vec) : FacingOrder.FacingOrderLookAtEnemy);
			}
			else if (_defensePosition.IsValid)
			{
				base.CurrentOrder = MovementOrder.MovementOrderMove(_defensePosition);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(vec);
			}
			else
			{
				WorldPosition cachedMedianPosition = base.Formation.CachedMedianPosition;
				cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
				base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(vec);
			}
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (base.Formation.CachedAveragePosition.DistanceSquared(base.CurrentOrder.GetPosition(base.Formation)) < 100f)
			{
				if (base.Formation.QuerySystem.HasShield)
				{
					base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderShieldWall);
				}
				else if (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation != null && base.Formation.CachedAveragePosition.DistanceSquared(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2) > 100f && base.Formation.QuerySystem.UnderRangedAttackRatio > 0.2f - ((base.Formation.ArrangementOrder.OrderEnum == ArrangementOrder.ArrangementOrderEnum.Loose) ? 0.1f : 0f))
				{
					base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLoose);
				}
				if (_tacticalDefendPosition != null)
				{
					float customWidth;
					if (_tacticalDefendPosition.TacticalPositionType == TacticalPosition.TacticalPositionTypeEnum.ChokePoint)
					{
						customWidth = _tacticalDefendPosition.Width;
					}
					else
					{
						int countOfUnits = base.Formation.CountOfUnits;
						float num = base.Formation.Interval * (float)(countOfUnits - 1) + base.Formation.UnitDiameter * (float)countOfUnits;
						customWidth = TaleWorlds.Library.MathF.Min(_tacticalDefendPosition.Width, num / 3f);
					}
					base.Formation.SetFormOrder(FormOrder.FormOrderCustom(customWidth));
				}
			}
			else
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLoose);
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderScatter);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		public override void ResetBehavior()
		{
			base.ResetBehavior();
			_defensePosition = WorldPosition.Invalid;
			_tacticalDefendPosition = null;
		}

		protected override float GetAiWeight()
		{
			return 1f;
		}
	}
	public class BehaviorShootFromSiegeTower : BehaviorComponent
	{
		private SiegeTower _siegeTower;

		public BehaviorShootFromSiegeTower(Formation formation)
			: base(formation)
		{
			_behaviorSide = formation.AI.Side;
			_siegeTower = Mission.Current.ActiveMissionObjects.FindAllWithType<SiegeTower>().FirstOrDefault((SiegeTower st) => st.WeaponSide == _behaviorSide);
		}

		public override void TickOccasionally()
		{
			base.TickOccasionally();
			if (base.Formation.AI.Side != _behaviorSide)
			{
				_behaviorSide = base.Formation.AI.Side;
				_siegeTower = Mission.Current.ActiveMissionObjects.FindAllWithType<SiegeTower>().FirstOrDefault((SiegeTower st) => st.WeaponSide == _behaviorSide);
			}
			if (_siegeTower != null && !_siegeTower.IsDestroyed)
			{
				base.Formation.SetMovementOrder(base.CurrentOrder);
			}
		}

		protected override float GetAiWeight()
		{
			return 0f;
		}
	}
	public class BehaviorSkirmish : BehaviorComponent
	{
		private enum BehaviorState
		{
			Approaching,
			Shooting,
			PullingBack
		}

		private bool _cantShoot;

		private float _cantShootDistance = float.MaxValue;

		private bool _alternatePositionUsed;

		private WorldPosition _alternatePosition = WorldPosition.Invalid;

		private BehaviorState _behaviorState = BehaviorState.Shooting;

		private TaleWorlds.Core.Timer _cantShootTimer;

		private TaleWorlds.Core.Timer _pullBackTimer;

		public BehaviorSkirmish(Formation formation)
			: base(formation)
		{
			base.BehaviorCoherence = 0.5f;
			_cantShootTimer = new TaleWorlds.Core.Timer(0f, 0f);
			_pullBackTimer = new TaleWorlds.Core.Timer(0f, 0f);
			CalculateCurrentOrder();
		}

		protected override void CalculateCurrentOrder()
		{
			WorldPosition position = base.Formation.CachedMedianPosition;
			bool flag = false;
			Vec2 vec;
			if (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation == null)
			{
				vec = base.Formation.Direction;
				position.SetVec2(base.Formation.CachedAveragePosition);
			}
			else
			{
				vec = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition;
				float num = vec.Normalize();
				float num2 = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedCurrentVelocity.DotProduct(vec);
				float num3 = MBMath.Lerp(5f, 10f, (MBMath.ClampFloat(base.Formation.CountOfUnits, 10f, 60f) - 10f) * 0.02f) * num2;
				num += num3;
				float num4 = MBMath.Lerp(0.1f, 0.33f, 1f - MBMath.ClampFloat(base.Formation.CountOfUnits, 1f, 50f) * 0.02f) * base.Formation.QuerySystem.RangedUnitRatio;
				switch (_behaviorState)
				{
				case BehaviorState.Shooting:
					if (base.Formation.QuerySystem.MakingRangedAttackRatio <= num4)
					{
						if (num > base.Formation.QuerySystem.MaximumMissileRange)
						{
							_behaviorState = BehaviorState.Approaching;
							_cantShootDistance = TaleWorlds.Library.MathF.Min(_cantShootDistance, base.Formation.QuerySystem.MaximumMissileRange * 0.9f);
						}
						else if (!_cantShoot)
						{
							_cantShoot = true;
							_cantShootTimer.Reset(Mission.Current.CurrentTime, MBMath.Lerp(5f, 10f, (MBMath.ClampFloat(base.Formation.CountOfUnits, 10f, 60f) - 10f) * 0.02f));
						}
						else if (_cantShootTimer.Check(Mission.Current.CurrentTime))
						{
							_behaviorState = BehaviorState.Approaching;
							_cantShootDistance = TaleWorlds.Library.MathF.Min(_cantShootDistance, num);
						}
					}
					else
					{
						_cantShootDistance = TaleWorlds.Library.MathF.Max(_cantShootDistance, num);
						_cantShoot = false;
						if (_pullBackTimer.Check(Mission.Current.CurrentTime) && base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.IsInfantryFormation && num < TaleWorlds.Library.MathF.Min(base.Formation.QuerySystem.MissileRangeAdjusted * 0.4f, _cantShootDistance * 0.666f))
						{
							_behaviorState = BehaviorState.PullingBack;
							_pullBackTimer.Reset(Mission.Current.CurrentTime, 10f);
						}
					}
					break;
				case BehaviorState.Approaching:
					if (num < _cantShootDistance * 0.8f)
					{
						_behaviorState = BehaviorState.Shooting;
						_cantShoot = false;
						flag = true;
					}
					else if (base.Formation.QuerySystem.MakingRangedAttackRatio >= num4 * 1.2f)
					{
						_behaviorState = BehaviorState.Shooting;
						_cantShoot = false;
						flag = true;
					}
					break;
				case BehaviorState.PullingBack:
					if (num > TaleWorlds.Library.MathF.Min(_cantShootDistance, base.Formation.QuerySystem.MissileRangeAdjusted) * 0.8f)
					{
						_behaviorState = BehaviorState.Shooting;
						_cantShoot = false;
						flag = true;
					}
					else if (_pullBackTimer.Check(Mission.Current.CurrentTime) && base.Formation.QuerySystem.MakingRangedAttackRatio <= num4 * 0.5f)
					{
						_behaviorState = BehaviorState.Shooting;
						_cantShoot = false;
						flag = true;
						_pullBackTimer.Reset(Mission.Current.CurrentTime, 5f);
					}
					break;
				}
				switch (_behaviorState)
				{
				case BehaviorState.Shooting:
					position.SetVec2(base.Formation.CachedAveragePosition + base.Formation.CachedCurrentVelocity.Normalized() * (base.Formation.Depth * 0.5f));
					break;
				case BehaviorState.Approaching:
				{
					bool flag2 = false;
					if (_alternatePositionUsed)
					{
						float num5 = base.Formation.CachedAveragePosition.DistanceSquared(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedAveragePosition);
						Vec2 v = (base.Formation.CachedAveragePosition + base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedAveragePosition) * 0.5f;
						bool flag3 = (double)_alternatePosition.AsVec2.DistanceSquared(v) > (double)num5 * 0.0625;
						if (!flag3)
						{
							Scene scene = Mission.Current.Scene;
							Vec3 position2 = _alternatePosition.GetNavMeshVec3();
							scene.GetNavigationMeshForPosition(in position2, out var faceGroupId, 1.5f, excludeDynamicNavigationMeshes: false);
							Agent medianAgent = base.Formation.GetMedianAgent(excludeDetachedUnits: true, excludePlayer: true, base.Formation.CachedAveragePosition);
							flag3 = (medianAgent != null && medianAgent.GetCurrentNavigationFaceId() % 10 == 1) != (faceGroupId % 10 == 1);
						}
						if (flag3)
						{
							Agent medianAgent2 = base.Formation.GetMedianAgent(excludeDetachedUnits: true, excludePlayer: true, base.Formation.CachedAveragePosition);
							bool num6 = medianAgent2 != null && medianAgent2.GetCurrentNavigationFaceId() % 10 == 1;
							Agent medianAgent3 = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.GetMedianAgent(excludeDetachedUnits: true, excludePlayer: true, base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedAveragePosition);
							if (num6 == (medianAgent3 != null && medianAgent3.GetCurrentNavigationFaceId() % 10 == 1))
							{
								_alternatePositionUsed = false;
								_alternatePosition = WorldPosition.Invalid;
							}
							else
							{
								flag2 = true;
							}
						}
					}
					else if (Mission.Current.MissionTeamAIType == Mission.MissionTeamAITypeEnum.Siege || Mission.Current.MissionTeamAIType == Mission.MissionTeamAITypeEnum.SallyOut)
					{
						Agent medianAgent4 = base.Formation.GetMedianAgent(excludeDetachedUnits: true, excludePlayer: true, base.Formation.CachedAveragePosition);
						bool num7 = medianAgent4 != null && medianAgent4.GetCurrentNavigationFaceId() % 10 == 1;
						Agent medianAgent5 = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.GetMedianAgent(excludeDetachedUnits: true, excludePlayer: true, base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedAveragePosition);
						if (num7 != (medianAgent5 != null && medianAgent5.GetCurrentNavigationFaceId() % 10 == 1))
						{
							_alternatePositionUsed = true;
							flag2 = true;
						}
					}
					if (_alternatePositionUsed)
					{
						if (flag2)
						{
							_alternatePosition = new WorldPosition(Mission.Current.Scene, new Vec3((base.Formation.CachedAveragePosition + base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedAveragePosition) * 0.5f, base.Formation.CachedMedianPosition.GetNavMeshZ()));
						}
						position = _alternatePosition;
					}
					else
					{
						position = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition;
						position.SetVec2(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedAveragePosition);
					}
					break;
				}
				case BehaviorState.PullingBack:
					position = base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition;
					position.SetVec2(position.AsVec2 - vec * (base.Formation.QuerySystem.MissileRangeAdjusted - base.Formation.Depth * 0.5f - 10f));
					break;
				}
			}
			if (!base.CurrentOrder.GetPosition(base.Formation).IsValid || _behaviorState != BehaviorState.Shooting || flag)
			{
				base.CurrentOrder = MovementOrder.MovementOrderMove(position);
			}
			if (!CurrentFacingOrder.GetDirection(base.Formation).IsValid || _behaviorState != BehaviorState.Shooting || flag)
			{
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(vec);
			}
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
			_cantShoot = false;
			_cantShootDistance = float.MaxValue;
			_behaviorState = BehaviorState.Shooting;
			_cantShootTimer.Reset(Mission.Current.CurrentTime, MBMath.Lerp(5f, 10f, (MBMath.ClampFloat(base.Formation.CountOfUnits, 10f, 60f) - 10f) * 0.02f));
			_pullBackTimer.Reset(0f, 0f);
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderScatter);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
