	public class BehaviorTacticalCharge : BehaviorComponent
	{
		private enum ChargeState
		{
			Undetermined,
			Charging,
			ChargingPast,
			Reforming,
			Bracing
		}

		private ChargeState _chargeState;

		private FormationQuerySystem _lastTarget;

		private Vec2 _initialChargeDirection;

		private float _desiredChargeStopDistance;

		private WorldPosition _lastReformDestination;

		private TaleWorlds.Core.Timer _chargingPastTimer;

		private TaleWorlds.Core.Timer _reformTimer;

		private Vec2 _bracePosition = Vec2.Invalid;

		public override float NavmeshlessTargetPositionPenalty => 1f;

		public BehaviorTacticalCharge(Formation formation)
			: base(formation)
		{
			_lastTarget = null;
			base.CurrentOrder = MovementOrder.MovementOrderCharge;
			CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			_chargeState = ChargeState.Undetermined;
			base.BehaviorCoherence = 0.5f;
			_desiredChargeStopDistance = 20f;
		}

		public override void TickOccasionally()
		{
			base.TickOccasionally();
			if (base.Formation.AI.ActiveBehavior == this)
			{
				CalculateCurrentOrder();
				base.Formation.SetMovementOrder(base.CurrentOrder);
				base.Formation.SetFacingOrder(CurrentFacingOrder);
			}
		}

		private ChargeState CheckAndChangeState()
		{
			ChargeState result = _chargeState;
			FormationQuerySystem cachedClosestEnemyFormation = base.Formation.CachedClosestEnemyFormation;
			if (cachedClosestEnemyFormation == null)
			{
				result = ChargeState.Undetermined;
			}
			else
			{
				switch (_chargeState)
				{
				case ChargeState.Undetermined:
					if ((!base.Formation.QuerySystem.IsCavalryFormation && !base.Formation.QuerySystem.IsRangedCavalryFormation) || base.Formation.CachedAveragePosition.Distance(cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2) / base.Formation.QuerySystem.MovementSpeedMaximum <= 5f)
					{
						result = ChargeState.Charging;
					}
					break;
				case ChargeState.Charging:
					if (_lastTarget == null || _lastTarget.Formation.CountOfUnits == 0)
					{
						result = ChargeState.Undetermined;
					}
					else if (!base.Formation.QuerySystem.IsCavalryFormation && !base.Formation.QuerySystem.IsRangedCavalryFormation)
					{
						if (!base.Formation.QuerySystem.IsInfantryFormation || !cachedClosestEnemyFormation.IsCavalryFormation)
						{
							result = ChargeState.Charging;
							break;
						}
						Vec2 vec2 = base.Formation.CachedAveragePosition - cachedClosestEnemyFormation.Formation.CachedAveragePosition;
						float num3 = vec2.Normalize();
						Vec2 cachedCurrentVelocity2 = cachedClosestEnemyFormation.Formation.CachedCurrentVelocity;
						float num4 = cachedCurrentVelocity2.Normalize();
						if (num3 / num4 <= 6f && vec2.DotProduct(cachedCurrentVelocity2) > 0.5f)
						{
							_chargeState = ChargeState.Bracing;
						}
					}
					else if (_initialChargeDirection.DotProduct(cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition) <= 0f)
					{
						result = ChargeState.ChargingPast;
					}
					break;
				case ChargeState.ChargingPast:
					if (_chargingPastTimer.Check(Mission.Current.CurrentTime) || base.Formation.CachedAveragePosition.Distance(cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2) >= _desiredChargeStopDistance)
					{
						result = ChargeState.Reforming;
					}
					break;
				case ChargeState.Reforming:
					if (_reformTimer.Check(Mission.Current.CurrentTime) || base.Formation.CachedAveragePosition.Distance(cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2) <= 30f)
					{
						result = ChargeState.Charging;
					}
					break;
				case ChargeState.Bracing:
				{
					bool flag = false;
					if (base.Formation.QuerySystem.IsInfantryFormation && cachedClosestEnemyFormation.IsCavalryFormation)
					{
						Vec2 vec = base.Formation.CachedAveragePosition - cachedClosestEnemyFormation.Formation.CachedAveragePosition;
						float num = vec.Normalize();
						Vec2 cachedCurrentVelocity = cachedClosestEnemyFormation.Formation.CachedCurrentVelocity;
						float num2 = cachedCurrentVelocity.Normalize();
						if (num / num2 <= 8f && vec.DotProduct(cachedCurrentVelocity) > 0.33f)
						{
							flag = true;
						}
					}
					if (!flag)
					{
						_bracePosition = Vec2.Invalid;
						_chargeState = ChargeState.Charging;
					}
					break;
				}
				}
			}
			return result;
		}

		protected override void CalculateCurrentOrder()
		{
			FormationQuerySystem cachedClosestEnemyFormation = base.Formation.CachedClosestEnemyFormation;
			if (cachedClosestEnemyFormation == null)
			{
				base.CurrentOrder = MovementOrder.MovementOrderCharge;
				return;
			}
			if (base.Formation.QuerySystem.IsCavalryFormation || base.Formation.QuerySystem.IsRangedCavalryFormation)
			{
				base.CurrentOrder = MovementOrder.MovementOrderChargeToTarget(cachedClosestEnemyFormation.Formation);
				return;
			}
			ChargeState chargeState = CheckAndChangeState();
			if (chargeState != _chargeState)
			{
				_chargeState = chargeState;
				switch (_chargeState)
				{
				case ChargeState.Undetermined:
					base.CurrentOrder = MovementOrder.MovementOrderCharge;
					break;
				case ChargeState.Charging:
					_lastTarget = cachedClosestEnemyFormation;
					if (base.Formation.QuerySystem.IsCavalryFormation || base.Formation.QuerySystem.IsRangedCavalryFormation)
					{
						_initialChargeDirection = _lastTarget.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition;
						float value = _initialChargeDirection.Normalize();
						_desiredChargeStopDistance = MBMath.ClampFloat(value, 20f, 50f);
					}
					break;
				case ChargeState.ChargingPast:
					_chargingPastTimer = new TaleWorlds.Core.Timer(Mission.Current.CurrentTime, 5f);
					break;
				case ChargeState.Reforming:
					_reformTimer = new TaleWorlds.Core.Timer(Mission.Current.CurrentTime, 2f);
					break;
				case ChargeState.Bracing:
				{
					Vec2 vec = (base.Formation.QuerySystem.Team.MedianTargetFormationPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized();
					_bracePosition = base.Formation.CachedAveragePosition + vec * 5f;
					break;
				}
				}
			}
			switch (_chargeState)
			{
			case ChargeState.Undetermined:
				if (cachedClosestEnemyFormation != null && (base.Formation.QuerySystem.IsCavalryFormation || base.Formation.QuerySystem.IsRangedCavalryFormation))
				{
					base.CurrentOrder = MovementOrder.MovementOrderMove(cachedClosestEnemyFormation.Formation.CachedMedianPosition);
				}
				else
				{
					base.CurrentOrder = MovementOrder.MovementOrderCharge;
				}
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
				break;
			case ChargeState.Charging:
				if (!base.Formation.QuerySystem.IsCavalryFormation && !base.Formation.QuerySystem.IsRangedCavalryFormation)
				{
					if (base.Formation.Width >= cachedClosestEnemyFormation.Formation.Width * (1f + ((base.Formation.GetReadonlyMovementOrderReference().OrderEnum != MovementOrder.MovementOrderEnum.Charge) ? 0.1f : 0f)))
					{
						base.CurrentOrder = MovementOrder.MovementOrderCharge;
						CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
					}
					else
					{
						WorldPosition cachedMedianPosition2 = cachedClosestEnemyFormation.Formation.CachedMedianPosition;
						base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition2);
						CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
					}
				}
				else
				{
					Vec2 vec4 = (_lastTarget.Formation.CachedMedianPosition.AsVec2 - base.Formation.CachedAveragePosition).Normalized();
					WorldPosition cachedMedianPosition3 = _lastTarget.Formation.CachedMedianPosition;
					Vec2 vec5 = cachedMedianPosition3.AsVec2 + vec4 * _desiredChargeStopDistance;
					cachedMedianPosition3.SetVec2(vec5);
					base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition3);
					CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(vec4);
				}
				break;
			case ChargeState.ChargingPast:
			{
				Vec2 vec2 = (base.Formation.CachedAveragePosition - _lastTarget.Formation.CachedMedianPosition.AsVec2).Normalized();
				_lastReformDestination = _lastTarget.Formation.CachedMedianPosition;
				Vec2 vec3 = _lastTarget.Formation.CachedMedianPosition.AsVec2 + vec2 * _desiredChargeStopDistance;
				_lastReformDestination.SetVec2(vec3);
				base.CurrentOrder = MovementOrder.MovementOrderMove(_lastReformDestination);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(vec2);
				break;
			}
			case ChargeState.Reforming:
				base.CurrentOrder = MovementOrder.MovementOrderMove(_lastReformDestination);
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
				break;
			case ChargeState.Bracing:
			{
				WorldPosition cachedMedianPosition = base.Formation.CachedMedianPosition;
				cachedMedianPosition.SetVec2(_bracePosition);
				base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
				break;
			}
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (base.Formation.QuerySystem.IsCavalryFormation || base.Formation.QuerySystem.IsRangedCavalryFormation)
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderSkein);
			}
			else
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			}
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		public override TextObject GetBehaviorString()
		{
			TextObject behaviorString = base.GetBehaviorString();
			if (base.Formation.CachedClosestEnemyFormation != null)
			{
				behaviorString.SetTextVariable("AI_SIDE", GameTexts.FindText("str_formation_ai_side_strings", base.Formation.CachedClosestEnemyFormation.Formation.AI.Side.ToString()));
				behaviorString.SetTextVariable("CLASS", GameTexts.FindText("str_formation_class_string", base.Formation.CachedClosestEnemyFormation.Formation.PhysicalClass.GetName()));
			}
			return behaviorString;
		}

		private float CalculateAIWeight()
		{
			FormationQuerySystem querySystem = base.Formation.QuerySystem;
			FormationQuerySystem cachedClosestEnemyFormation = base.Formation.CachedClosestEnemyFormation;
			if (cachedClosestEnemyFormation == null)
			{
				return 0f;
			}
			float num = base.Formation.CachedAveragePosition.Distance(cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2) / querySystem.MovementSpeedMaximum;
			float num3;
			if (!querySystem.IsCavalryFormation && !querySystem.IsRangedCavalryFormation)
			{
				float num2 = MBMath.ClampFloat(num, 4f, 10f);
				num3 = MBMath.Lerp(0.8f, 1f, 1f - (num2 - 4f) / 6f);
			}
			else if (num <= 4f)
			{
				float num4 = MBMath.ClampFloat(num, 0f, 4f);
				num3 = MBMath.Lerp(0.8f, 1.2f, num4 / 4f);
			}
			else
			{
				float num5 = MBMath.ClampFloat(num, 4f, 10f);
				num3 = MBMath.Lerp(0.8f, 1.2f, 1f - (num5 - 4f) / 6f);
			}
			float num6 = 1f;
			if (num <= 4f)
			{
				float length = (base.Formation.CachedAveragePosition - cachedClosestEnemyFormation.Formation.CachedMedianPosition.AsVec2).Length;
				if (length > float.Epsilon)
				{
					WorldPosition cachedMedianPosition = base.Formation.CachedMedianPosition;
					cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
					float navMeshZ = cachedMedianPosition.GetNavMeshZ();
					if (!float.IsNaN(navMeshZ))
					{
						float value = (navMeshZ - cachedClosestEnemyFormation.Formation.CachedMedianPosition.GetNavMeshZ()) / length;
						num6 = MBMath.Lerp(0.9f, 1.1f, (MBMath.ClampFloat(value, -0.58f, 0.58f) + 0.58f) / 1.16f);
					}
				}
			}
			float num7 = 1f;
			if (num <= 4f && num >= 1.5f)
			{
				num7 = 1.2f;
			}
			float num8 = 1f;
			if (num <= 4f && cachedClosestEnemyFormation.Formation.CachedClosestEnemyFormation != querySystem)
			{
				num8 = 1.2f;
			}
			float num9 = querySystem.GetClassWeightedFactor(1f, 1f, 1.5f, 1.5f) * cachedClosestEnemyFormation.GetClassWeightedFactor(1f, 1f, 0.5f, 0.5f);
			return num3 * num6 * num7 * num8 * num9;
		}

		protected override float GetAiWeight()
		{
			float result = 0f;
			FormationQuerySystem cachedClosestEnemyFormation = base.Formation.CachedClosestEnemyFormation;
			if (cachedClosestEnemyFormation != null)
			{
				bool flag;
				if (!(base.Formation.Team.TeamAI is TeamAISiegeComponent))
				{
					flag = true;
				}
				else if ((base.Formation.Team.TeamAI as TeamAISiegeComponent).CalculateIsChargePastWallsApplicable(base.Formation.AI.Side))
				{
					flag = true;
				}
				else
				{
					bool flag2 = TeamAISiegeComponent.IsFormationInsideCastle(cachedClosestEnemyFormation.Formation, includeOnlyPositionedUnits: true, 0.51f);
					flag = flag2 == TeamAISiegeComponent.IsFormationInsideCastle(base.Formation, includeOnlyPositionedUnits: true, flag2 ? 0.9f : 0.1f);
				}
				if (flag)
				{
					result = CalculateAIWeight();
				}
			}
			return result;
		}
	}
	public class BehaviorUseMurderHole : BehaviorComponent
	{
		private readonly CastleGate _outerGate;

		private readonly CastleGate _innerGate;

		private readonly BatteringRam _batteringRam;

		public BehaviorUseMurderHole(Formation formation)
			: base(formation)
		{
			_behaviorSide = formation.AI.Side;
			WorldPosition position = new WorldPosition(base.Formation.Team.Mission.Scene, UIntPtr.Zero, (formation.Team.TeamAI as TeamAISiegeDefender).MurderHolePosition, hasValidZ: false);
			_outerGate = (formation.Team.TeamAI as TeamAISiegeDefender).OuterGate;
			_innerGate = (formation.Team.TeamAI as TeamAISiegeDefender).InnerGate;
			_batteringRam = base.Formation.Team.Mission.ActiveMissionObjects.FindAllWithType<BatteringRam>().FirstOrDefault();
			base.CurrentOrder = MovementOrder.MovementOrderMove(position);
			base.BehaviorCoherence = 0f;
		}

		public override void TickOccasionally()
		{
			base.Formation.SetMovementOrder(base.CurrentOrder);
		}

		public bool IsMurderHoleActive()
		{
			if (_batteringRam == null || !_batteringRam.HasArrivedAtTarget || _innerGate.IsDestroyed)
			{
				if (_outerGate.IsDestroyed)
				{
					return !_innerGate.IsDestroyed;
				}
				return false;
			}
			return true;
		}

		protected override float GetAiWeight()
		{
			return 10f * (IsMurderHoleActive() ? 1f : 0f);
		}
	}
	public class BehaviorUseSiegeMachines : BehaviorComponent
	{
		private enum BehaviorState
		{
			Unset,
			Follow,
			ClimbSiegeTower,
			Stop
		}

		private List<SiegeWeapon> _primarySiegeWeapons;

		private TeamAISiegeComponent _teamAISiegeComponent;

		private MovementOrder _followEntityOrder;

		private GameEntity _followedEntity;

		private MovementOrder _stopOrder;

		private BehaviorState _behaviorState;

		public override float NavmeshlessTargetPositionPenalty => 1f;

		public BehaviorUseSiegeMachines(Formation formation)
			: base(formation)
		{
			_behaviorSide = formation.AI.Side;
			_primarySiegeWeapons = new List<SiegeWeapon>();
			foreach (MissionObject activeMissionObject in Mission.Current.ActiveMissionObjects)
			{
				if (activeMissionObject is IPrimarySiegeWeapon primarySiegeWeapon && primarySiegeWeapon.WeaponSide == _behaviorSide)
				{
					_primarySiegeWeapons.Add(activeMissionObject as SiegeWeapon);
				}
			}
			_teamAISiegeComponent = (TeamAISiegeComponent)formation.Team.TeamAI;
			base.BehaviorCoherence = 0f;
			_stopOrder = MovementOrder.MovementOrderStop;
			RecreateFollowEntityOrder();
			if (_followEntityOrder.OrderEnum != 0)
			{
				_behaviorState = BehaviorState.Follow;
				base.CurrentOrder = _followEntityOrder;
			}
			else
			{
				_behaviorState = BehaviorState.Stop;
				base.CurrentOrder = _stopOrder;
			}
		}

		public override TextObject GetBehaviorString()
		{
			TextObject behaviorString = base.GetBehaviorString();
			TextObject variable = GameTexts.FindText("str_formation_ai_side_strings", base.Formation.AI.Side.ToString());
			behaviorString.SetTextVariable("SIDE_STRING", variable);
			behaviorString.SetTextVariable("IS_GENERAL_SIDE", "0");
			return behaviorString;
		}

		private void RecreateFollowEntityOrder()
		{
			_followEntityOrder = MovementOrder.MovementOrderStop;
			_followedEntity = _primarySiegeWeapons.FirstOrDefault((SiegeWeapon psw) => !psw.IsDeactivated && psw is IPrimarySiegeWeapon primarySiegeWeapon && !primarySiegeWeapon.HasCompletedAction())?.WaitEntity;
			if (_followedEntity != null)
			{
				_followEntityOrder = MovementOrder.MovementOrderFollowEntity(_followedEntity);
			}
		}

		public override void OnValidBehaviorSideChanged()
		{
			base.OnValidBehaviorSideChanged();
			_primarySiegeWeapons.Clear();
			foreach (MissionObject activeMissionObject in Mission.Current.ActiveMissionObjects)
			{
				if (activeMissionObject is IPrimarySiegeWeapon primarySiegeWeapon && primarySiegeWeapon.WeaponSide == _behaviorSide && !((SiegeWeapon)activeMissionObject).IsDeactivated)
				{
					_primarySiegeWeapons.Add(activeMissionObject as SiegeWeapon);
				}
			}
			RecreateFollowEntityOrder();
			_behaviorState = BehaviorState.Unset;
		}

		public override void TickOccasionally()
		{
			base.TickOccasionally();
			bool flag = false;
			for (int num = _primarySiegeWeapons.Count - 1; num >= 0; num--)
			{
				SiegeWeapon siegeWeapon = _primarySiegeWeapons[num];
				if (siegeWeapon.IsDestroyed || siegeWeapon.IsDeactivated)
				{
					_primarySiegeWeapons.RemoveAt(num);
					flag = true;
				}
			}
			if (flag)
			{
				RecreateFollowEntityOrder();
			}
			int num2 = 0;
			SiegeTower siegeTower = null;
			foreach (SiegeWeapon primarySiegeWeapon in _primarySiegeWeapons)
			{
				if (!((IPrimarySiegeWeapon)primarySiegeWeapon).HasCompletedAction())
				{
					num2++;
					if (primarySiegeWeapon is SiegeTower siegeTower2)
					{
						siegeTower = siegeTower2;
					}
				}
			}
			if (num2 == 0)
			{
				base.CurrentOrder = _stopOrder;
				return;
			}
			if (_behaviorState == BehaviorState.Follow)
			{
				if (_followEntityOrder.OrderEnum == MovementOrder.MovementOrderEnum.Stop)
				{
					RecreateFollowEntityOrder();
				}
				base.CurrentOrder = _followEntityOrder;
			}
			BehaviorState behaviorState = ((siegeTower != null && siegeTower.HasArrivedAtTarget) ? BehaviorState.ClimbSiegeTower : ((_followEntityOrder.OrderEnum != 0) ? BehaviorState.Follow : BehaviorState.Stop));
			if (behaviorState != _behaviorState)
			{
				switch (behaviorState)
				{
				case BehaviorState.Follow:
					base.CurrentOrder = _followEntityOrder;
					break;
				case BehaviorState.ClimbSiegeTower:
					RecreateFollowEntityOrder();
					base.CurrentOrder = _followEntityOrder;
					break;
				default:
					base.CurrentOrder = _stopOrder;
					break;
				}
				_behaviorState = behaviorState;
				bool flag2 = _behaviorState == BehaviorState.ClimbSiegeTower;
				if (!flag2)
				{
					foreach (SiegeWeapon primarySiegeWeapon2 in _primarySiegeWeapons)
					{
						if (primarySiegeWeapon2 is SiegeLadder { IsDisabled: false })
						{
							flag2 = true;
							break;
						}
					}
				}
				if (flag2)
				{
					base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
				}
				else if (base.Formation.QuerySystem.IsRangedFormation)
				{
					base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderScatter);
				}
				else
				{
					base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderShieldWall);
				}
			}
			if (_followedEntity != null && (_behaviorState == BehaviorState.Follow || _behaviorState == BehaviorState.ClimbSiegeTower))
			{
				base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtDirection(_followedEntity.GetGlobalFrame().rotation.f.AsVec2.Normalized()));
			}
			else
			{
				base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtEnemy);
			}
			if (base.Formation.AI.ActiveBehavior == this)
			{
				foreach (SiegeWeapon primarySiegeWeapon3 in _primarySiegeWeapons)
				{
					if (((IPrimarySiegeWeapon)primarySiegeWeapon3).HasCompletedAction())
					{
						continue;
					}
					if (!primarySiegeWeapon3.IsUsedByFormation(base.Formation))
					{
						base.Formation.StartUsingMachine(primarySiegeWeapon3);
					}
					for (int num3 = primarySiegeWeapon3.UserFormations.Count - 1; num3 >= 0; num3--)
					{
						Formation formation = primarySiegeWeapon3.UserFormations[num3];
						if (formation != base.Formation && formation.IsAIControlled && (formation.AI.Side != _behaviorSide || !(formation.AI.ActiveBehavior is BehaviorUseSiegeMachines)) && formation.Team == base.Formation.Team)
						{
							formation.StopUsingMachine(primarySiegeWeapon3);
						}
					}
				}
			}
			base.Formation.SetMovementOrder(base.CurrentOrder);
		}

		protected override void OnBehaviorActivatedAux()
		{
			base.Formation.SetArrangementOrder(base.Formation.QuerySystem.IsRangedFormation ? ArrangementOrder.ArrangementOrderScatter : ArrangementOrder.ArrangementOrderShieldWall);
			base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtEnemy);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderDeep);
		}

		protected override float GetAiWeight()
		{
			float result = 0f;
			if (_teamAISiegeComponent != null && _primarySiegeWeapons.Count > 0 && _primarySiegeWeapons.All((SiegeWeapon psw) => !(psw as IPrimarySiegeWeapon).HasCompletedAction()))
			{
				result = ((!_teamAISiegeComponent.IsCastleBreached()) ? 0.75f : 0.25f);
			}
			return result;
		}
	}
	public class BehaviorVanguard : BehaviorComponent
	{
		private Formation _mainFormation;

		public BehaviorVanguard(Formation formation)
			: base(formation)
		{
			_behaviorSide = formation.AI.Side;
			_mainFormation = formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
			CalculateCurrentOrder();
		}

		protected override void CalculateCurrentOrder()
		{
			if (_mainFormation != null && _mainFormation.CountOfUnits == 0)
			{
				_mainFormation = base.Formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
			}
			Vec2 direction;
			WorldPosition cachedMedianPosition;
			if (_mainFormation != null)
			{
				direction = _mainFormation.Direction;
				Vec2 vec = (base.Formation.QuerySystem.Team.MedianTargetFormationPosition.AsVec2 - _mainFormation.CachedMedianPosition.AsVec2).Normalized();
				cachedMedianPosition = _mainFormation.CachedMedianPosition;
				cachedMedianPosition.SetVec2(_mainFormation.CurrentPosition + vec * ((_mainFormation.Depth + base.Formation.Depth) * 0.5f + 10f));
			}
			else
			{
				direction = base.Formation.Direction;
				cachedMedianPosition = base.Formation.CachedMedianPosition;
				cachedMedianPosition.SetVec2(base.Formation.CachedAveragePosition);
			}
			base.CurrentOrder = MovementOrder.MovementOrderMove(cachedMedianPosition);
			CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(direction);
		}

		public override void OnValidBehaviorSideChanged()
		{
			base.OnValidBehaviorSideChanged();
			_mainFormation = base.Formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
		}

		public override void TickOccasionally()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation != null && base.Formation.CachedAveragePosition.DistanceSquared(base.Formation.QuerySystem.ClosestSignificantlyLargeEnemyFormation.Formation.CachedMedianPosition.AsVec2) > 1600f && base.Formation.QuerySystem.UnderRangedAttackRatio > 0.2f - ((base.Formation.ArrangementOrder.OrderEnum == ArrangementOrder.ArrangementOrderEnum.Loose) ? 0.1f : 0f))
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLoose);
			}
			else
			{
				base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			CalculateCurrentOrder();
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			base.Formation.SetArrangementOrder(ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		public override TextObject GetBehaviorString()
		{
			TextObject behaviorString = base.GetBehaviorString();
			TextObject variable = GameTexts.FindText("str_formation_ai_side_strings", base.Formation.AI.Side.ToString());
			behaviorString.SetTextVariable("SIDE_STRING", variable);
			if (_mainFormation != null)
			{
				behaviorString.SetTextVariable("AI_SIDE", GameTexts.FindText("str_formation_ai_side_strings", _mainFormation.AI.Side.ToString()));
				behaviorString.SetTextVariable("CLASS", GameTexts.FindText("str_formation_class_string", _mainFormation.PhysicalClass.GetName()));
			}
			return behaviorString;
		}

		protected override float GetAiWeight()
		{
			if (_mainFormation == null || !_mainFormation.AI.IsMainFormation)
			{
				_mainFormation = base.Formation.Team.FormationsIncludingEmpty.FirstOrDefaultQ((Formation f) => f.CountOfUnits > 0 && f.AI.IsMainFormation);
			}
			if (_mainFormation == null || base.Formation.AI.IsMainFormation)
			{
				return 0f;
			}
			return 1.2f;
		}
	}
	public class BehaviorWaitForLadders : BehaviorComponent
	{
		private enum BehaviorState
		{
			Unset,
			Stop,
			Follow
		}

		private const string WallWaitPositionTag = "attacker_wait_pos";

		private List<SiegeLadder> _ladders;

		private WallSegment _breachedWallSegment;

		private TeamAISiegeComponent _teamAISiegeComponent;

		private MovementOrder _stopOrder;

		private MovementOrder _followOrder;

		private BehaviorState _behaviorState;

		private GameEntity _followedEntity;

		private TacticalPosition _followTacticalPosition;

		public override float NavmeshlessTargetPositionPenalty => 1f;

		public BehaviorWaitForLadders(Formation formation)
			: base(formation)
		{
			_behaviorSide = formation.AI.Side;
			_ladders = Mission.Current.ActiveMissionObjects.OfType<SiegeLadder>().ToList();
			_ladders.RemoveAll((SiegeLadder l) => l.IsDeactivated || l.WeaponSide != _behaviorSide);
			_teamAISiegeComponent = (TeamAISiegeComponent)formation.Team.TeamAI;
			_breachedWallSegment = TeamAISiegeComponent.SiegeLanes.FirstOrDefault((SiegeLane sl) => sl.LaneSide == _behaviorSide)?.DefensePoints.FirstOrDefault((ICastleKeyPosition dp) => dp is WallSegment && (dp as WallSegment).IsBreachedWall) as WallSegment;
			ResetFollowOrder();
			_stopOrder = MovementOrder.MovementOrderStop;
			if (_followOrder.OrderEnum != 0)
			{
				base.CurrentOrder = _followOrder;
				_behaviorState = BehaviorState.Follow;
			}
			else
			{
				base.CurrentOrder = _stopOrder;
				_behaviorState = BehaviorState.Stop;
			}
		}

		private void ResetFollowOrder()
		{
			_followedEntity = null;
			_followTacticalPosition = null;
			if (_ladders.Count > 0)
			{
				_followedEntity = (_ladders.FirstOrDefault((SiegeLadder l) => !l.IsDeactivated && l.InitialWaitPosition.HasScriptOfType<TacticalPosition>()) ?? _ladders.FirstOrDefault((SiegeLadder l) => !l.IsDeactivated)).InitialWaitPosition;
				if (_followedEntity == null)
				{
					_followedEntity = _ladders.FirstOrDefault((SiegeLadder l) => !l.IsDeactivated).InitialWaitPosition;
				}
				_followOrder = MovementOrder.MovementOrderFollowEntity(_followedEntity);
			}
			else if (_breachedWallSegment != null)
			{
				WeakGameEntity firstChildEntityWithTagRecursive = _breachedWallSegment.GameEntity.GetFirstChildEntityWithTagRecursive("attacker_wait_pos");
				_followedEntity = GameEntity.CreateFromWeakEntity(firstChildEntityWithTagRecursive);
				_followOrder = MovementOrder.MovementOrderFollowEntity(_followedEntity);
			}
			else
			{
				_followOrder = MovementOrder.MovementOrderNull;
			}
			if (_followedEntity != null)
			{
				_followTacticalPosition = _followedEntity.GetFirstScriptOfType<TacticalPosition>();
			}
		}

		public override void OnValidBehaviorSideChanged()
		{
			base.OnValidBehaviorSideChanged();
			_ladders = Mission.Current.ActiveMissionObjects.OfType<SiegeLadder>().ToList();
			_ladders.RemoveAll((SiegeLadder l) => l.IsDeactivated || l.WeaponSide != _behaviorSide);
			_breachedWallSegment = TeamAISiegeComponent.SiegeLanes.FirstOrDefault((SiegeLane sl) => sl.LaneSide == _behaviorSide)?.DefensePoints.FirstOrDefault((ICastleKeyPosition dp) => dp is WallSegment && (dp as WallSegment).IsBreachedWall) as WallSegment;
			ResetFollowOrder();
			_behaviorState = BehaviorState.Unset;
		}

		protected override void CalculateCurrentOrder()
		{
			BehaviorState behaviorState = ((_followOrder.OrderEnum == MovementOrder.MovementOrderEnum.Invalid) ? BehaviorState.Stop : BehaviorState.Follow);
			if (behaviorState == _behaviorState)
			{
				return;
			}
			if (behaviorState == BehaviorState.Follow)
			{
				base.CurrentOrder = _followOrder;
				if (_followTacticalPosition != null)
				{
					CurrentFacingOrder = FacingOrder.FacingOrderLookAtDirection(_followTacticalPosition.Direction);
				}
				else
				{
					CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
				}
			}
			else
			{
				base.CurrentOrder = _stopOrder;
				CurrentFacingOrder = FacingOrder.FacingOrderLookAtEnemy;
			}
			_behaviorState = behaviorState;
		}

		public override void TickOccasionally()
		{
			base.TickOccasionally();
			if (_ladders.RemoveAll((SiegeLadder l) => l.IsDeactivated) > 0)
			{
				ResetFollowOrder();
				CalculateCurrentOrder();
			}
			base.Formation.SetMovementOrder(base.CurrentOrder);
			base.Formation.SetFacingOrder(CurrentFacingOrder);
			if (_behaviorState == BehaviorState.Follow && _followTacticalPosition != null)
			{
				base.Formation.SetFormOrder(FormOrder.FormOrderCustom(_followTacticalPosition.Width));
			}
			foreach (SiegeLadder ladder in _ladders)
			{
				if (ladder.IsUsedByFormation(base.Formation))
				{
					base.Formation.StopUsingMachine(ladder);
				}
			}
		}

		protected override void OnBehaviorActivatedAux()
		{
			base.Formation.SetArrangementOrder(base.Formation.QuerySystem.HasShield ? ArrangementOrder.ArrangementOrderShieldWall : ArrangementOrder.ArrangementOrderLine);
			base.Formation.SetFacingOrder(FacingOrder.FacingOrderLookAtEnemy);
			base.Formation.SetFiringOrder(FiringOrder.FiringOrderFireAtWill);
			base.Formation.SetFormOrder(FormOrder.FormOrderWide);
		}

		protected override float GetAiWeight()
		{
			float result = 0f;
			if (_followOrder.OrderEnum != 0 && !_teamAISiegeComponent.AreLaddersReady)
			{
				result = ((!_teamAISiegeComponent.IsCastleBreached()) ? 1f : 0.5f);
			}
			return result;
		}
	}
	public class DividableTask
	{
		private bool _isTaskCompletelyFinished;

		private bool _isMainTaskFinished;

		private bool _lastActionCalled;

		private DividableTask _continueToTask;

		private Action _lastAction;

		public DividableTask(DividableTask continueToTask = null)
		{
			_continueToTask = continueToTask;
			ResetTaskStatus();
		}

		public void ResetTaskStatus()
		{
			_isMainTaskFinished = false;
			_isTaskCompletelyFinished = false;
			_lastActionCalled = false;
		}

		public void SetTaskFinished(bool callLastAction = false)
		{
			if (callLastAction)
			{
				_lastAction?.Invoke();
				_lastActionCalled = true;
			}
			_isTaskCompletelyFinished = true;
			_isMainTaskFinished = true;
		}

		public bool Update()
		{
			if (!_isTaskCompletelyFinished)
			{
				if (!_isMainTaskFinished && UpdateExtra())
				{
					_isMainTaskFinished = true;
				}
				if (_isMainTaskFinished)
				{
					_isTaskCompletelyFinished = _continueToTask?.Update() ?? true;
				}
			}
			if (_isTaskCompletelyFinished && !_lastActionCalled)
			{
				_lastAction?.Invoke();
				_lastActionCalled = true;
			}
			return _isTaskCompletelyFinished;
		}

		public void SetLastAction(Action action)
		{
			_lastAction = action;
		}

		protected virtual bool UpdateExtra()
		{
			return true;
		}
	}
	public class FormationAI
	{
		public class BehaviorData
		{
			public BehaviorComponent Behavior;

			public float Preference = 1f;

			public float Weight;

			public bool IsRemovedOnCancel;

			public bool IsPreprocessed;
		}

		public enum BehaviorSide
		{
			Left = 0,
			Middle = 1,
			Right = 2,
			BehaviorSideNotSet = 3,
			ValidBehaviorSideCount = 3
		}

		private const float BehaviorPreserveTime = 5f;

		private readonly Formation _formation;

		private readonly List<BehaviorData> _specialBehaviorData;

		private readonly List<BehaviorComponent> _behaviors = new List<BehaviorComponent>();

		private BehaviorComponent _activeBehavior;

		private BehaviorSide _side = BehaviorSide.Middle;

		private readonly TaleWorlds.Core.Timer _tickTimer;

		public BehaviorComponent ActiveBehavior
		{
			get
			{
				return _activeBehavior;
			}
			private set
			{
				if (_activeBehavior != value)
				{
					_activeBehavior?.OnBehaviorCanceled();
					BehaviorComponent activeBehavior = _activeBehavior;
					_activeBehavior = value;
					_activeBehavior.OnBehaviorActivated();
					ActiveBehavior.PreserveExpireTime = Mission.Current.CurrentTime + 10f;
					if (this.OnActiveBehaviorChanged != null && (activeBehavior == null || !activeBehavior.Equals(value)))
					{
						this.OnActiveBehaviorChanged(_formation);
					}
				}
			}
		}

		public BehaviorSide Side
		{
			get
			{
				return _side;
			}
			set
			{
				if (_side == value)
				{
					return;
				}
				_side = value;
				if (_side == BehaviorSide.BehaviorSideNotSet)
				{
					return;
				}
				foreach (BehaviorComponent behavior in _behaviors)
				{
					behavior.OnValidBehaviorSideChanged();
				}
			}
		}

		public bool IsMainFormation { get; set; }

		public int BehaviorCount => _behaviors.Count;

		public event Action<Formation> OnActiveBehaviorChanged;

		public FormationAI(Formation formation)
		{
			_formation = formation;
			float num = 0f;
			if (formation.Team != null)
			{
				float num2 = 0.1f * (float)formation.FormationIndex;
				float num3 = 0f;
				if (formation.Team.TeamIndex >= 0)
				{
					num3 = (float)formation.Team.TeamIndex * 0.5f * 0.1f;
				}
				num = num2 + num3;
			}
			_tickTimer = new TaleWorlds.Core.Timer(Mission.Current.CurrentTime + 0.5f * num, 0.5f);
			_specialBehaviorData = new List<BehaviorData>();
		}

		public T SetBehaviorWeight<T>(float w) where T : BehaviorComponent
		{
			foreach (BehaviorComponent behavior in _behaviors)
			{
				if (behavior is T val)
				{
					val.WeightFactor = w;
					return val;
				}
			}
			throw new MBException("Behavior weight could not be set.");
		}

		public void AddAiBehavior(BehaviorComponent behaviorComponent)
		{
			_behaviors.Add(behaviorComponent);
		}

		public T GetBehavior<T>() where T : BehaviorComponent
		{
			foreach (BehaviorComponent behavior in _behaviors)
			{
				if (behavior is T result)
				{
					return result;
				}
			}
			foreach (BehaviorData specialBehaviorDatum in _specialBehaviorData)
			{
				if (specialBehaviorDatum.Behavior is T result2)
				{
					return result2;
				}
			}
			return null;
		}

		public void AddSpecialBehavior(BehaviorComponent behavior, bool purgePreviousSpecialBehaviors = false)
		{
			if (purgePreviousSpecialBehaviors)
			{
				_specialBehaviorData.Clear();
			}
			_specialBehaviorData.Add(new BehaviorData
			{
				Behavior = behavior
			});
		}

		private bool FindBestBehavior()
		{
			BehaviorComponent behaviorComponent = null;
			float num = float.MinValue;
			foreach (BehaviorComponent behavior in _behaviors)
			{
				if (!(behavior.WeightFactor > 1E-07f))
				{
					continue;
				}
				float num2 = behavior.GetAIWeight() * behavior.WeightFactor;
				if (behavior == ActiveBehavior)
				{
					num2 *= MBMath.Lerp(1.2f, 2f, MBMath.ClampFloat((behavior.PreserveExpireTime - Mission.Current.CurrentTime) / 5f, 0f, 1f), float.MinValue);
				}
				if (num2 > num)
				{
					if (behavior.NavmeshlessTargetPositionPenalty > 0f)
					{
						num2 /= behavior.NavmeshlessTargetPositionPenalty;
					}
					behavior.PrecalculateMovementOrder();
					num2 *= behavior.NavmeshlessTargetPositionPenalty;
					if (num2 > num)
					{
						behaviorComponent = behavior;
						num = num2;
					}
				}
			}
			if (behaviorComponent != null)
			{
				ActiveBehavior = behaviorComponent;
				if (behaviorComponent != _behaviors[0])
				{
					_behaviors.Remove(behaviorComponent);
					_behaviors.Insert(0, behaviorComponent);
				}
				return true;
			}
			return false;
		}

		private void PreprocessBehaviors()
		{
			if (!_formation.HasAnyEnemyFormationsThatIsNotEmpty())
			{
				return;
			}
			BehaviorData behaviorData = _specialBehaviorData.FirstOrDefault((BehaviorData sd) => !sd.IsPreprocessed);
			if (behaviorData != null)
			{
				behaviorData.Behavior.TickOccasionally();
				float num = behaviorData.Behavior.GetAIWeight();
				if (behaviorData.Behavior == ActiveBehavior)
				{
					num *= MBMath.Lerp(1.01f, 1.5f, MBMath.ClampFloat((behaviorData.Behavior.PreserveExpireTime - Mission.Current.CurrentTime) / 5f, 0f, 1f), float.MinValue);
				}
				behaviorData.Weight = num * behaviorData.Preference;
				behaviorData.IsPreprocessed = true;
			}
		}

		public void Tick()
		{
			if (Mission.Current.AllowAiTicking && (Mission.Current.ForceTickOccasionally || _tickTimer.Check(Mission.Current.CurrentTime)))
			{
				TickOccasionally(_tickTimer.PreviousDeltaTime);
			}
		}

		private void TickOccasionally(float dt)
		{
			_formation.IsAITickedAfterSplit = true;
			if (FindBestBehavior())
			{
				if (!_formation.IsAIControlled)
				{
					if (GameNetwork.IsMultiplayer && Mission.Current.MainAgent != null && !_formation.Team.IsPlayerGeneral && _formation.Team.IsPlayerSergeant && _formation.PlayerOwner == Agent.Main)
					{
						ActiveBehavior.RemindSergeantPlayer();
					}
				}
				else
				{
					ActiveBehavior.TickOccasionally();
				}
				return;
			}
			BehaviorComponent behaviorComponent = ActiveBehavior;
			if (!_formation.HasAnyEnemyFormationsThatIsNotEmpty())
			{
				return;
			}
			PreprocessBehaviors();
			foreach (BehaviorData specialBehaviorDatum in _specialBehaviorData)
			{
				specialBehaviorDatum.IsPreprocessed = false;
			}
			if (behaviorComponent is BehaviorStop && _specialBehaviorData.Count > 0)
			{
				IEnumerable<BehaviorData> source = _specialBehaviorData.Where((BehaviorData sbd) => sbd.Weight > 0f);
				if (source.Any())
				{
					behaviorComponent = source.MaxBy((BehaviorData abd) => abd.Weight).Behavior;
				}
			}
			_ = _formation.IsAIControlled;
			bool flag = false;
			if (ActiveBehavior != behaviorComponent)
			{
				_ = ActiveBehavior;
				ActiveBehavior = behaviorComponent;
				flag = true;
			}
			if (flag || (behaviorComponent != null && behaviorComponent.IsCurrentOrderChanged))
			{
				if (_formation.IsAIControlled)
				{
					_formation.SetMovementOrder(behaviorComponent.CurrentOrder);
				}
				behaviorComponent.IsCurrentOrderChanged = false;
			}
		}

		public void OnDeploymentFinished()
		{
			foreach (BehaviorComponent behavior in _behaviors)
			{
				behavior.OnDeploymentFinished();
			}
		}

		public void OnAgentRemoved(Agent agent)
		{
			foreach (BehaviorComponent behavior in _behaviors)
			{
				behavior.OnAgentRemoved(agent);
			}
		}

		public BehaviorComponent GetBehaviorAtIndex(int index)
		{
			if (index >= 0 && index < _behaviors.Count)
			{
				return _behaviors[index];
			}
			return null;
		}

		[Conditional("DEBUG")]
		public void DebugMore()
		{
			if (!MBDebug.IsDisplayingHighLevelAI)
			{
				return;
			}
			foreach (BehaviorData item in _specialBehaviorData.OrderBy((BehaviorData d) => d.Behavior.GetType().ToString()))
			{
				item.Behavior.GetType().ToString().Replace("MBModule.Behavior", "");
				item.Weight.ToString("0.00");
				item.Preference.ToString("0.00");
			}
		}

		[Conditional("DEBUG")]
		public void DebugScores()
		{
			if (_formation.PhysicalClass.IsRanged())
			{
				MBDebug.Print("Ranged");
			}
			else if (_formation.PhysicalClass.IsMeleeCavalry())
			{
				MBDebug.Print("Cavalry");
			}
			else
			{
				MBDebug.Print("Infantry");
			}
			foreach (BehaviorData item in _specialBehaviorData.OrderBy((BehaviorData d) => d.Behavior.GetType().ToString()))
			{
				string text = item.Behavior.GetType().ToString().Replace("MBModule.Behavior", "");
				string text2 = item.Weight.ToString("0.00");
				string text3 = item.Preference.ToString("0.00");
				MBDebug.Print(text + " \t\t w:" + text2 + "\t p:" + text3);
			}
		}

		public void ResetBehaviorWeights()
		{
			foreach (BehaviorComponent behavior in _behaviors)
			{
				behavior.ResetBehavior();
			}
		}
	}
	public class CircularFormation : LineFormation
	{
		public override float Width
		{
			get
			{
				return Diameter;
			}
			set
			{
				float circumference = System.MathF.PI * value;
				FormFromCircumference(circumference);
			}
		}

		public override float Depth => Diameter;

		private float Diameter => 2f * Radius;

		private float Radius => (base.FlankWidth + base.Interval) / (System.MathF.PI * 2f);

		public override float MinimumWidth
		{
			get
			{
				int unitCountWithOverride = GetUnitCountWithOverride();
				int currentMaximumRankCount = GetCurrentMaximumRankCount(unitCountWithOverride);
				float radialInterval = owner.MinimumInterval + base.UnitDiameter;
				float distanceInterval = owner.MinimumDistance + base.UnitDiameter;
				return GetCircumferenceAux(unitCountWithOverride, currentMaximumRankCount, radialInterval, distanceInterval) / System.MathF.PI;
			}
		}

		public override float MaximumWidth
		{
			get
			{
				int unitCountWithOverride = GetUnitCountWithOverride();
				float num = owner.MaximumInterval + base.UnitDiameter;
				return TaleWorlds.Library.MathF.Max(0f, (float)unitCountWithOverride * num) / System.MathF.PI;
			}
		}

		private int MaxRank => TaleWorlds.Library.MathF.Floor(Radius / (base.Distance + base.UnitDiameter));

		public CircularFormation(IFormation owner)
			: base(owner, isDeformingOnWidthChange: true, isStaggered: true)
		{
		}

		public override IFormationArrangement Clone(IFormation formation)
		{
			return new CircularFormation(formation);
		}

		private float GetDistanceFromCenterOfRank(int rankIndex)
		{
			float num = Radius - (float)rankIndex * (base.Distance + base.UnitDiameter);
			if (num >= 0f)
			{
				return num;
			}
			return 0f;
		}

		protected override bool IsDeepenApplicable()
		{
			return Radius - (float)base.RankCount * (base.Distance + base.UnitDiameter) >= 0f;
		}

		protected override bool IsNarrowApplicable(int amount)
		{
			return ((float)(base.FileCount - 1 - amount) * (base.Interval + base.UnitDiameter) + base.UnitDiameter) / (System.MathF.PI * 2f) - (float)base.RankCount * (base.Distance + base.UnitDiameter) >= 0f;
		}

		private int GetUnitCountOfRank(int rankIndex)
		{
			if (rankIndex == 0)
			{
				return base.FileCount;
			}
			float distanceFromCenterOfRank = GetDistanceFromCenterOfRank(rankIndex);
			int b = TaleWorlds.Library.MathF.Floor(System.MathF.PI * 2f * distanceFromCenterOfRank / (base.Interval + base.UnitDiameter));
			return TaleWorlds.Library.MathF.Max(1, b);
		}

		protected override bool IsUnitPositionRestrained(int fileIndex, int rankIndex)
		{
			if (base.IsUnitPositionRestrained(fileIndex, rankIndex))
			{
				return true;
			}
			if (rankIndex > MaxRank)
			{
				return true;
			}
			int unitCountOfRank = GetUnitCountOfRank(rankIndex);
			int num = (base.FileCount - unitCountOfRank) / 2;
			if (fileIndex < num || fileIndex >= num + unitCountOfRank)
			{
				return true;
			}
			return false;
		}

		protected override void MakeRestrainedPositionsUnavailable()
		{
			for (int i = 0; i < base.FileCount; i++)
			{
				for (int j = 0; j < base.RankCount; j++)
				{
					if (IsUnitPositionRestrained(i, j))
					{
						UnitPositionAvailabilities[i, j] = 1;
					}
				}
			}
		}

		protected override Vec2 GetLocalDirectionOfUnit(int fileIndex, int rankIndex)
		{
			int unitCountOfRank = GetUnitCountOfRank(rankIndex);
			int num = (base.FileCount - unitCountOfRank) / 2;
			Vec2 result = Vec2.FromRotation((float)((fileIndex - num) * 2) * System.MathF.PI / (float)unitCountOfRank + System.MathF.PI);
			result.x *= -1f;
			return result;
		}

		public override Vec2? GetLocalDirectionOfUnitOrDefault(IFormationUnit unit)
		{
			if (unit.FormationFileIndex < 0 || unit.FormationRankIndex < 0)
			{
				return null;
			}
			return GetLocalDirectionOfUnit(unit.FormationFileIndex, unit.FormationRankIndex);
		}

		protected override Vec2 GetLocalPositionOfUnit(int fileIndex, int rankIndex)
		{
			Vec2 vec = new Vec2(0f, 0f - Radius);
			Vec2 localDirectionOfUnit = GetLocalDirectionOfUnit(fileIndex, rankIndex);
			float distanceFromCenterOfRank = GetDistanceFromCenterOfRank(rankIndex);
			return vec + localDirectionOfUnit * distanceFromCenterOfRank;
		}

		protected override Vec2 GetLocalPositionOfUnitWithAdjustment(int fileIndex, int rankIndex, float distanceBetweenAgentsAdjustment)
		{
			return GetLocalPositionOfUnit(fileIndex, rankIndex);
		}

		protected override bool TryGetUnitPositionIndexFromLocalPosition(Vec2 localPosition, out int fileIndex, out int rankIndex)
		{
			Vec2 vec = new Vec2(0f, 0f - Radius);
			Vec2 vec2 = localPosition - vec;
			float length = vec2.Length;
			rankIndex = TaleWorlds.Library.MathF.Round((length - Radius) / (base.Distance + base.UnitDiameter) * -1f);
			if (rankIndex < 0 || rankIndex >= base.RankCount)
			{
				fileIndex = -1;
				return false;
			}
			if (Radius - (float)rankIndex * (base.Distance + base.UnitDiameter) < 0f)
			{
				fileIndex = -1;
				return false;
			}
			int unitCountOfRank = GetUnitCountOfRank(rankIndex);
			int num = (base.FileCount - unitCountOfRank) / 2;
			vec2.x *= -1f;
			float rotationInRadians = vec2.RotationInRadians;
			rotationInRadians -= System.MathF.PI;
			if (rotationInRadians < 0f)
			{
				rotationInRadians += System.MathF.PI * 2f;
			}
			int num2 = TaleWorlds.Library.MathF.Round(rotationInRadians / 2f / System.MathF.PI * (float)unitCountOfRank);
			fileIndex = num2 + num;
			if (fileIndex < 0 || fileIndex >= base.FileCount)
			{
				return false;
			}
			return true;
		}

		protected int GetCurrentMaximumRankCount(int unitCount)
		{
			int num = 0;
			int num2 = 0;
			float num3 = base.Interval + base.UnitDiameter;
			float num4 = base.Distance + base.UnitDiameter;
			while (num2 < unitCount)
			{
				float num5 = (float)num * num4;
				int b = (int)(System.MathF.PI * 2f * num5 / num3);
				num2 += TaleWorlds.Library.MathF.Max(1, b);
				num++;
			}
			return TaleWorlds.Library.MathF.Max(num, 1);
		}

		public float GetCircumferenceFromRankCount(int rankCount)
		{
			int unitCountWithOverride = GetUnitCountWithOverride();
			rankCount = TaleWorlds.Library.MathF.Min(GetCurrentMaximumRankCount(unitCountWithOverride), rankCount);
			float radialInterval = base.Interval + base.UnitDiameter;
			float distanceInterval = base.Distance + base.UnitDiameter;
			return GetCircumferenceAux(unitCountWithOverride, rankCount, radialInterval, distanceInterval);
		}

		public void FormFromCircumference(float circumference)
		{
			int unitCountWithOverride = GetUnitCountWithOverride();
			int currentMaximumRankCount = GetCurrentMaximumRankCount(unitCountWithOverride);
			float num = base.Interval + base.UnitDiameter;
			float distanceInterval = base.Distance + base.UnitDiameter;
			float circumferenceAux = GetCircumferenceAux(unitCountWithOverride, currentMaximumRankCount, num, distanceInterval);
			float maxValue = TaleWorlds.Library.MathF.Max(0f, (float)unitCountWithOverride * num);
			circumference = MBMath.ClampFloat(circumference, circumferenceAux, maxValue);
			base.FlankWidth = Math.Max(circumference - base.Interval, base.UnitDiameter);
		}

		protected float GetCircumferenceAux(int unitCount, int rankCount, float radialInterval, float distanceInterval)
		{
			float num = (float)(Math.PI * 2.0 * (double)distanceInterval);
			float num2 = TaleWorlds.Library.MathF.Max(0f, (float)unitCount * radialInterval);
			float num3;
			int unitCountAux;
			do
			{
				num3 = num2;
				num2 = TaleWorlds.Library.MathF.Max(0f, num3 - num);
				unitCountAux = GetUnitCountAux(num2, rankCount, radialInterval, distanceInterval);
			}
			while (unitCountAux > unitCount && num3 > 0f);
			return num3;
		}

		private static int GetUnitCountAux(float circumference, int rankCount, float radialInterval, float distanceInterval)
		{
			int num = 0;
			double num2 = Math.PI * 2.0 * (double)distanceInterval;
			for (int i = 1; i <= rankCount; i++)
			{
				num += (int)(Math.Max(0.0, (double)circumference - (double)(rankCount - i) * num2) / (double)radialInterval);
			}
			return num;
		}

		protected override void UpdateFrontUnitTypeDelegate()
		{
		}
	}
	public class CircularSchiltronFormation : CircularFormation
	{
		public override float MaximumWidth
		{
			get
			{
				int unitCountWithOverride = GetUnitCountWithOverride();
				int currentMaximumRankCount = GetCurrentMaximumRankCount(unitCountWithOverride);
				float radialInterval = owner.MaximumInterval + base.UnitDiameter;
				float distanceInterval = owner.MaximumDistance + base.UnitDiameter;
				return GetCircumferenceAux(unitCountWithOverride, currentMaximumRankCount, radialInterval, distanceInterval) / System.MathF.PI;
			}
		}

		public CircularSchiltronFormation(IFormation owner)
			: base(owner)
		{
		}

		public override IFormationArrangement Clone(IFormation formation)
		{
			return new CircularSchiltronFormation(formation);
		}

		public void Form()
		{
			int unitCountWithOverride = GetUnitCountWithOverride();
			int currentMaximumRankCount = GetCurrentMaximumRankCount(unitCountWithOverride);
			float circumferenceFromRankCount = GetCircumferenceFromRankCount(currentMaximumRankCount);
			FormFromCircumference(circumferenceFromRankCount);
		}
	}
	public class ColumnFormation : IFormationArrangement
