				int a = TaleWorlds.Library.MathF.Max(0, (int)((value - owner.UnitDiameter) / (owner.Interval + owner.UnitDiameter) + 1E-05f)) + 1;
				a = TaleWorlds.Library.MathF.Max(a, 1);
				SetColumnCount(a);
