		public Vec2? CreateNewPosition(int unitIndex)
		{
			Vec2? result = null;
			int num = 100;
			while (!result.HasValue && num > 0 && !AreLastRanksCompletelyUnavailable() && IsDeepenApplicable())
			{
				Deepen();
				result = GetLocalPositionOfUnitOrDefault(unitIndex);
				num--;
			}
			return result;
		}

