		protected override void ManageFormationCounts()
		{
			List<SiegeLane> list = DetermineCurrentLanes();
			if (_indicators == null && base.Team.QuerySystem.EnemyUnitCount > 0)
			{
				_indicators = new BreachWallsProgressIndicators(base.Team, list);
			}
			if (_tacticState == TacticState.Retreating)
			{
				return;
			}
			int count = list.Count;
			if (_tacticState == TacticState.AssaultUnderRangedCover)
			{
				int rangedCount = TaleWorlds.Library.MathF.Min(DetermineCurrentArcherPositions(list).Count, 8 - count);
				ManageFormationCounts(count, rangedCount, 0, 0);
				_meleeFormations = base.FormationsIncludingEmpty.Where((Formation f) => f.QuerySystem.IsInfantryFormation && f.CountOfUnitsWithoutDetachedOnes > 0).ToList();
				_rangedFormations = base.FormationsIncludingEmpty.Where((Formation f) => f.QuerySystem.IsRangedFormation && f.CountOfUnitsWithoutDetachedOnes > 0).ToList();
			}
			else if (_tacticState == TacticState.TotalAttack)
			{
				SplitFormationClassIntoGivenNumber((Formation f) => true, count);
			}
		}

		private void CheckAndChangeState()
		{
			if (_tacticState == TacticState.Retreating)
			{
				return;
			}
			bool isShockAssault = _isShockAssault;
			List<SiegeLane> currentLanes = DetermineCurrentLanes();
			int num = 0;
			foreach (Formation item in base.Team.FormationsIncludingEmpty)
			{
				if (item.CountOfUnits > 0 && TeamAISiegeComponent.IsFormationInsideCastle(item, includeOnlyPositionedUnits: true))
				{
					num++;
				}
			}
			if (ShouldRetreat(currentLanes, num))
			{
				_tacticState = TacticState.Retreating;
				StartTacticalRetreat();
				IsTacticReapplyNeeded = false;
				return;
			}
			TacticState tacticState = TacticState.TotalAttack;
			List<ArcherPosition> archerPositions = null;
			if (_tacticState != TacticState.TotalAttack)
			{
				archerPositions = DetermineCurrentArcherPositions(currentLanes);
				if (archerPositions.Count > 0)
				{
					int num2 = TaleWorlds.Library.MathF.Max(_meleeFormations.Sum((Formation mf) => mf.CountOfUnits), 1);
					int num3 = TaleWorlds.Library.MathF.Max(_rangedFormations.Sum((Formation rf) => rf.CountOfUnits), 1);
					int num4 = num2 + num3;
					int num5 = num4 - base.Team.FormationsIncludingEmpty.Sum((Formation f) => f.CountOfUnitsWithoutDetachedOnes);
					tacticState = (((float)num2 / (float)num3 > 0.5f && (float)num5 / (float)num4 < 0.2f) ? TacticState.AssaultUnderRangedCover : TacticState.TotalAttack);
				}
			}
			if (tacticState != _tacticState || isShockAssault != _isShockAssault)
			{
				switch (tacticState)
				{
				case TacticState.AssaultUnderRangedCover:
					_tacticState = TacticState.AssaultUnderRangedCover;
					ManageFormationCounts();
					WellRoundedAssault(ref currentLanes, ref archerPositions);
					IsTacticReapplyNeeded = false;
					break;
				case TacticState.TotalAttack:
					_tacticState = TacticState.TotalAttack;
					ManageFormationCounts();
					AllInAssault();
					IsTacticReapplyNeeded = false;
					break;
				}
			}
		}

		private List<SiegeLane> DetermineCurrentLanes()
		{
			List<SiegeLane> list = TeamAISiegeComponent.SiegeLanes.Where((SiegeLane sl) => sl.IsBreach).ToList();
			if (list.Count >= 2)
			{
				if (_indicators == null || _indicators.InitialUnitCount > 100)
				{
					return list;
				}
				if (!_isShockAssault)
				{
					StopUsingAllMachines();
					_isShockAssault = true;
				}
				return list.Take(1).ToList();
			}
			List<SiegeLane> list2 = TeamAISiegeComponent.SiegeLanes.Where((SiegeLane sl) => !sl.CalculateIsLaneUnusable()).ToList();
			if (list2.Count > 0)
			{
				if (_indicators == null || _indicators.InitialUnitCount > 100)
				{
					if (list.Count >= 1)
					{
						return list2.Where((SiegeLane l) => l.IsBreach || l.PrimarySiegeWeapons.Any((IPrimarySiegeWeapon psw) => !(psw is SiegeLadder))).ToList();
					}
					return list2;
				}
				List<SiegeLane> result = new List<SiegeLane> { list2.MaxBy((SiegeLane ul) => ul.CalculateLaneCapacity()) };
				if (!_isShockAssault)
				{
					StopUsingAllMachines();
					_isShockAssault = true;
				}
				return result;
			}
			return TeamAISiegeComponent.SiegeLanes.Where((SiegeLane sl) => sl.HasGate).ToList();
		}

		private List<ArcherPosition> DetermineCurrentArcherPositions(List<SiegeLane> currentLanes)
		{
			return _teamAISiegeAttacker.ArcherPositions.Where((ArcherPosition ap) => currentLanes.Any((SiegeLane cl) => ap.IsArcherPositionRelatedToSide(cl.LaneSide))).ToList();
		}

		public override void TickOccasionally()
		{
			if (!base.AreFormationsCreated)
			{
				return;
			}
			_meleeFormations.RemoveAll((Formation mf) => mf.CountOfUnitsWithoutDetachedOnes == 0);
			_rangedFormations.RemoveAll((Formation rf) => rf.CountOfUnitsWithoutDetachedOnes == 0);
			List<SiegeLane> currentLanes = DetermineCurrentLanes();
			MergeFormationsIfLanesBecameUnavailable(ref currentLanes);
			bool flag = CheckAndSetAvailableFormationsChanged();
			if (_indicators == null && base.Team.QuerySystem.EnemyUnitCount > 0)
			{
				_indicators = new BreachWallsProgressIndicators(base.Team, currentLanes);
				_indicators.StartingPowerRatio = base.Team.QuerySystem.TotalPowerRatio;
				_indicators.InitialLaneCount = currentLanes.Count;
				_indicators.InitialUnitCount = base.Team.QuerySystem.AllyUnitCount;
			}
			int num = 0;
			foreach (SiegeLane item in currentLanes)
			{
				num |= TaleWorlds.Library.MathF.PowTwo32((int)item.LaneSide);
			}
			IsTacticReapplyNeeded = num != _lanesInUse;
			_lanesInUse = num;
			if (flag)
			{
				ManageFormationCounts();
			}
			CheckAndChangeState();
			switch (_tacticState)
			{
			case TacticState.AssaultUnderRangedCover:
			{
				List<ArcherPosition> currentArcherPositions = DetermineCurrentArcherPositions(currentLanes);
				if (flag || IsTacticReapplyNeeded)
				{
					_cachedUsedArcherPositions = currentArcherPositions;
					WellRoundedAssault(ref currentLanes, ref currentArcherPositions);
					IsTacticReapplyNeeded = false;
				}
				else if (_cachedUsedArcherPositions.Count != currentArcherPositions.Count)
				{
					MergeFormationsIfArcherPositionsBecameUnavailable(ref currentArcherPositions);
				}
				BalanceAssaultLanes(_meleeFormations.Where((Formation mf) => mf.IsAIControlled && mf.IsAITickedAfterSplit && (mf.AI.ActiveBehavior is BehaviorUseSiegeMachines || mf.AI.ActiveBehavior is BehaviorWaitForLadders)).ToList());
				break;
			}
			case TacticState.TotalAttack:
				if (flag || IsTacticReapplyNeeded)
				{
					AllInAssault();
					IsTacticReapplyNeeded = false;
				}
				BalanceAssaultLanes(base.FormationsIncludingEmpty.Where((Formation f) => f.CountOfUnits > 0 && f.IsAIControlled && f.IsAITickedAfterSplit && (f.AI.ActiveBehavior is BehaviorUseSiegeMachines || f.AI.ActiveBehavior is BehaviorWaitForLadders)).ToList());
				break;
			case TacticState.Retreating:
				if (flag || IsTacticReapplyNeeded)
				{
					StartTacticalRetreat();
					IsTacticReapplyNeeded = false;
				}
				break;
			}
			_teamAISiegeAttacker.SetAreLaddersReady(currentLanes.Count((SiegeLane l) => l.IsBreach) > 1 || !currentLanes.Any((SiegeLane l) => l.PrimarySiegeWeapons.Any((IPrimarySiegeWeapon psw) => psw.HoldLadders)) || currentLanes.Any((SiegeLane l) => l.PrimarySiegeWeapons.Any((IPrimarySiegeWeapon psw) => psw.SendLadders)));
			CheckAndSetAvailableFormationsChanged();
			base.TickOccasionally();
		}

		protected internal override float GetTacticWeight()
		{
			return 10f;
		}
	}
	public class TacticCharge : TacticComponent
	{
		public TacticCharge(Team team)
			: base(team)
		{
		}

		public override void TickOccasionally()
		{
			foreach (Formation item in base.FormationsIncludingEmpty)
			{
				if (item.CountOfUnits > 0)
				{
					item.AI.ResetBehaviorWeights();
					TacticComponent.SetDefaultBehaviorWeights(item);
					item.AI.SetBehaviorWeight<BehaviorCharge>(10000f);
				}
			}
			base.TickOccasionally();
		}

		protected internal override void OnApply()
		{
			base.OnApply();
			if (!base.Team.IsPlayerTeam || base.Team.IsPlayerGeneral || !base.Team.IsPlayerSergeant)
			{
				return;
			}
			foreach (Formation item in base.Team.FormationsIncludingSpecialAndEmpty)
			{
				if (item.CountOfUnits <= 0)
				{
					continue;
				}
				foreach (Team team in base.Team.Mission.Teams)
				{
					if (!team.IsEnemyOf(base.Team))
					{
						continue;
					}
					foreach (Formation item2 in team.FormationsIncludingSpecialAndEmpty)
					{
						if (item2.CountOfUnits > 0)
						{
							SoundTacticalHorn(TacticComponent.AttackHornSoundIndex);
							return;
						}
					}
				}
			}
		}

		protected internal override float GetTacticWeight()
		{
			float num = base.Team.QuerySystem.RemainingPowerRatio / base.Team.QuerySystem.TotalPowerRatio;
			float num2 = TaleWorlds.Library.MathF.Max(base.Team.QuerySystem.InfantryRatio, TaleWorlds.Library.MathF.Max(base.Team.QuerySystem.RangedRatio, base.Team.QuerySystem.CavalryRatio)) + ((base.Team.Side == BattleSideEnum.Defender) ? 0.33f : 0f);
			float num3 = ((base.Team.Side == BattleSideEnum.Defender) ? 0.33f : 0.5f);
			float num4 = 0f;
			float num5 = 0f;
			CasualtyHandler missionBehavior = Mission.Current.GetMissionBehavior<CasualtyHandler>();
			foreach (Team team in base.Team.Mission.Teams)
			{
				if (team != base.Team && !team.IsEnemyOf(base.Team))
				{
					continue;
				}
				for (int i = 0; i < Math.Min(team.FormationsIncludingSpecialAndEmpty.Count, 8); i++)
				{
					Formation formation = team.FormationsIncludingSpecialAndEmpty[i];
					if (formation.CountOfUnits > 0)
					{
						num4 += formation.QuerySystem.FormationPower;
						num5 += missionBehavior.GetCasualtyPowerLossOfFormation(formation);
					}
				}
			}
			float num6 = num4 + num5;
			float num7 = num4 / num6;
			num7 = ((base.Team.Side == BattleSideEnum.Attacker && num < 0.5f) ? 0f : MBMath.LinearExtrapolation(0f, 1.6f * num2, (1f - num7) / (1f - num3)));
			float b = MBMath.LinearExtrapolation(0f, 1.6f * num2, base.Team.QuerySystem.RemainingPowerRatio * num3 * 0.5f);
			return TaleWorlds.Library.MathF.Max(num7, b);
		}
	}
	public abstract class TacticComponent
	{
		public static readonly int MoveHornSoundIndex;

		public static readonly int AttackHornSoundIndex;

		public static readonly int RetreatHornSoundIndex;

		protected int _AIControlledFormationCount;

		protected bool IsTacticReapplyNeeded;

		private bool _areFormationsCreated;

		protected Formation _mainInfantry;

		protected Formation _archers;

		protected Formation _leftCavalry;

		protected Formation _rightCavalry;

		protected Formation _rangedCavalry;

		private float _hornCooldownExpireTime;

		private const float HornCooldownTime = 10f;

		public Team Team { get; protected set; }

		protected MBList<Formation> FormationsIncludingSpecialAndEmpty => Team.FormationsIncludingSpecialAndEmpty;

		protected MBList<Formation> FormationsIncludingEmpty => Team.FormationsIncludingEmpty;

		protected bool AreFormationsCreated
		{
			get
			{
				if (_areFormationsCreated)
				{
					return true;
				}
				if (FormationsIncludingEmpty.AnyQ((Formation f) => f.CountOfUnits > 0))
				{
					_areFormationsCreated = true;
					ManageFormationCounts();
					CheckAndSetAvailableFormationsChanged();
					IsTacticReapplyNeeded = true;
					return true;
				}
				return false;
			}
		}

		protected TacticComponent(Team team)
		{
			Team = team;
		}

		static TacticComponent()
		{
			MoveHornSoundIndex = SoundEvent.GetEventIdFromString("event:/ui/mission/horns/move");
			AttackHornSoundIndex = SoundEvent.GetEventIdFromString("event:/ui/mission/horns/attack");
			RetreatHornSoundIndex = SoundEvent.GetEventIdFromString("event:/ui/mission/horns/retreat");
		}

		protected internal virtual void OnCancel()
		{
		}

		protected internal virtual void OnApply()
		{
			IsTacticReapplyNeeded = true;
		}

		public virtual void TickOccasionally()
		{
			TeamAIComponent teamAI = Team.TeamAI;
			if (teamAI.GetIsFirstTacticChosen)
			{
				teamAI.OnTacticAppliedForFirstTime();
			}
			if (Mission.Current.IsMissionEnding)
			{
				StopUsingAllMachines();
				if (teamAI.HasStrategicAreas)
				{
					teamAI.RemoveAllStrategicAreas();
				}
			}
		}

		private static void GetUnitCountByAttackType(Formation formation, out int unitCount, out int rangedCount, out int semiRangedCount, out int nonRangedCount)
		{
			FormationQuerySystem querySystem = formation.QuerySystem;
			unitCount = formation.CountOfUnits;
			rangedCount = (int)(querySystem.RangedUnitRatio * (float)unitCount);
			semiRangedCount = 0;
			nonRangedCount = unitCount - rangedCount;
		}

		protected static float GetFormationGroupEffectivenessOverOrder(IEnumerable<Formation> formationGroup, OrderType orderType, IOrderable targetObject = null)
		{
			GetUnitCountByAttackType(formationGroup.FirstOrDefault(), out var unitCount, out var rangedCount, out var semiRangedCount, out var nonRangedCount);
			switch (orderType)
			{
			case OrderType.PointDefence:
			{
				float num3 = ((float)nonRangedCount * 0.1f + (float)semiRangedCount * 0.3f + (float)rangedCount * 1f) / (float)unitCount;
				int num4 = (targetObject as IPointDefendable).DefencePoints.Count() * 3;
				float num5 = TaleWorlds.Library.MathF.Min((float)unitCount * 1f / (float)num4, 1f);
				return num3 * num5;
			}
			case OrderType.Use:
			{
				float num = ((float)nonRangedCount * 1f + (float)semiRangedCount * 0.9f + (float)rangedCount * 0.3f) / (float)unitCount;
				int maxUserCount = (targetObject as UsableMachine).MaxUserCount;
				float num2 = TaleWorlds.Library.MathF.Min((float)unitCount * 1f / (float)maxUserCount, 1f);
				return num * num2;
			}
			case OrderType.Charge:
				return ((float)nonRangedCount * 1f + (float)semiRangedCount * 0.9f + (float)rangedCount * 0.3f) / (float)unitCount;
			default:
				return 1f;
			}
		}

		protected static float GetFormationEffectivenessOverOrder(Formation formation, OrderType orderType, IOrderable targetObject = null)
		{
			GetUnitCountByAttackType(formation, out var unitCount, out var rangedCount, out var semiRangedCount, out var nonRangedCount);
			switch (orderType)
			{
			case OrderType.PointDefence:
			{
				float num = ((float)nonRangedCount * 0.1f + (float)semiRangedCount * 0.3f + (float)rangedCount * 1f) / (float)unitCount;
				int num2 = (targetObject as IPointDefendable).DefencePoints.Count() * 3;
				float num3 = TaleWorlds.Library.MathF.Min((float)unitCount * 1f / (float)num2, 1f);
				return num * num3;
			}
			case OrderType.Use:
			{
				float minDistanceSquared = float.MaxValue;
				formation.ApplyActionOnEachUnit(delegate(Agent agent)
				{
					minDistanceSquared = TaleWorlds.Library.MathF.Min(agent.Position.DistanceSquared((targetObject as UsableMachine).GameEntity.GlobalPosition), minDistanceSquared);
				});
				return 1f / MBMath.ClampFloat(minDistanceSquared, 1f, float.MaxValue);
			}
			case OrderType.Charge:
				return ((float)nonRangedCount * 1f + (float)semiRangedCount * 0.9f + (float)rangedCount * 0.3f) / (float)unitCount;
			default:
				return 1f;
			}
		}

