				if (_hasBattleBeenJoined)
				{
					Attack();
				}
				else
				{
					Advance();
				}
				IsTacticReapplyNeeded = false;
			}
			bool flag = HasBattleBeenJoined();
			if (flag != _hasBattleBeenJoined || IsTacticReapplyNeeded)
			{
				_hasBattleBeenJoined = flag;
				if (_hasBattleBeenJoined)
				{
					Attack();
