		{
			float num = base.Team.QuerySystem.RangedCavalryRatio * (float)base.Team.QuerySystem.MemberCount;
			return base.Team.QuerySystem.CavalryRatio * (float)base.Team.QuerySystem.MemberCount / ((float)base.Team.QuerySystem.MemberCount - num) * TaleWorlds.Library.MathF.Sqrt(base.Team.QuerySystem.RemainingPowerRatio);
		}
