		protected TacticComponent CurrentTactic
		{
			get
			{
				return _currentTactic;
			}
			private set
			{
				_currentTactic?.OnCancel();
				_currentTactic = value;
				if (_currentTactic != null)
				{
					_currentTactic.OnApply();
					_currentTactic.TickOccasionally();
				}
