		public Vec3 GetGlobalVelocity()
		{
			if (TargetableObject != null)
			{
				return TargetableObject.GetTargetGlobalVelocity();
			}
			if (Agent != null)
			{
				return new Vec3(Agent.GetAverageRealGlobalVelocity().AsVec2);
			}
			return Vec3.Zero;
		}

