	}
	[EngineStruct("Blow_weapon_record", false, null)]
	public struct BlowWeaponRecord
	{
		public Vec3 StartingPosition;

		public Vec3 CurrentPosition;

		public Vec3 Velocity;

		public ItemFlags ItemFlags;

		public WeaponFlags WeaponFlags;

		public WeaponClass WeaponClass;

		public sbyte BoneNoToAttach;

		public int AffectorWeaponSlotOrMissileIndex;

		public float Weight;

		[MarshalAs(UnmanagedType.U1)]
		[CustomEngineStructMemberData(true)]
		private bool _isMissile;

		[MarshalAs(UnmanagedType.U1)]
		private bool _isMaterialMetal;

		public bool IsMissile => _isMissile;

		public bool IsShield
		{
			get
			{
				if (!WeaponFlags.HasAnyFlag(WeaponFlags.WeaponMask))
				{
					return WeaponFlags.HasAllFlags(WeaponFlags.HasHitPoints | WeaponFlags.CanBlockRanged);
				}
				return false;
			}
		}

		public bool IsRanged => WeaponFlags.HasAnyFlag(WeaponFlags.RangedWeapon);

		public bool IsAmmo
		{
			get
			{
				if (!WeaponFlags.HasAnyFlag(WeaponFlags.WeaponMask))
				{
					return WeaponFlags.HasAnyFlag(WeaponFlags.Consumable);
				}
				return false;
			}
		}

		public void FillAsMeleeBlow(ItemObject item, WeaponComponentData weaponComponentData, int affectorWeaponSlot, sbyte weaponAttachBoneIndex)
		{
			_isMissile = false;
			if (weaponComponentData != null)
			{
				ItemFlags = item.ItemFlags;
				WeaponFlags = weaponComponentData.WeaponFlags;
				WeaponClass = weaponComponentData.WeaponClass;
				BoneNoToAttach = weaponAttachBoneIndex;
				AffectorWeaponSlotOrMissileIndex = affectorWeaponSlot;
				Weight = item.Weight;
				_isMaterialMetal = weaponComponentData.PhysicsMaterial.Contains("metal");
			}
			else
			{
				_isMaterialMetal = false;
				AffectorWeaponSlotOrMissileIndex = -1;
			}
		}

		public void FillAsMissileBlow(ItemObject item, WeaponComponentData weaponComponentData, int missileIndex, sbyte weaponAttachBoneIndex, Vec3 startingPosition, Vec3 currentPosition, Vec3 velocity)
		{
			_isMissile = true;
			StartingPosition = startingPosition;
			CurrentPosition = currentPosition;
			Velocity = velocity;
			ItemFlags = item.ItemFlags;
			WeaponFlags = weaponComponentData.WeaponFlags;
			WeaponClass = weaponComponentData.WeaponClass;
			BoneNoToAttach = weaponAttachBoneIndex;
			AffectorWeaponSlotOrMissileIndex = missileIndex;
			Weight = item.Weight;
			_isMaterialMetal = weaponComponentData.PhysicsMaterial.Contains("metal");
		}

		public bool HasWeapon()
		{
			return AffectorWeaponSlotOrMissileIndex >= 0;
		}

		public int GetHitSound(bool isOwnerHumanoid, bool isCriticalBlow, bool isLowBlow, bool isNonTipThrust, AgentAttackType attackType, DamageTypes damageType)
		{
			int result;
			if (!HasWeapon())
			{
				result = ((!isOwnerHumanoid) ? CombatSoundContainer.SoundCodeMissionCombatChargeDamage : ((attackType == AgentAttackType.Kick) ? CombatSoundContainer.SoundCodeMissionCombatKick : (isCriticalBlow ? CombatSoundContainer.SoundCodeMissionCombatPunchHigh : ((!isLowBlow) ? CombatSoundContainer.SoundCodeMissionCombatPunchMed : CombatSoundContainer.SoundCodeMissionCombatPunchLow))));
			}
			else if (IsRanged || IsAmmo)
			{
				switch (WeaponClass)
				{
				case WeaponClass.ThrowingAxe:
					result = ((!isCriticalBlow) ? ((!isLowBlow) ? CombatSoundContainer.SoundCodeMissionCombatThrowingAxeMed : CombatSoundContainer.SoundCodeMissionCombatThrowingAxeLow) : CombatSoundContainer.SoundCodeMissionCombatThrowingAxeHigh);
					break;
				case WeaponClass.ThrowingKnife:
					result = ((!isCriticalBlow) ? ((!isLowBlow) ? CombatSoundContainer.SoundCodeMissionCombatThrowingDaggerMed : CombatSoundContainer.SoundCodeMissionCombatThrowingDaggerLow) : CombatSoundContainer.SoundCodeMissionCombatThrowingDaggerHigh);
					break;
				case WeaponClass.Javelin:
					result = ((!isCriticalBlow) ? ((!isLowBlow) ? CombatSoundContainer.SoundCodeMissionCombatMissileMed : CombatSoundContainer.SoundCodeMissionCombatMissileLow) : CombatSoundContainer.SoundCodeMissionCombatMissileHigh);
					break;
				case WeaponClass.Sling:
				case WeaponClass.Stone:
				case WeaponClass.BallistaStone:
					result = ((!isCriticalBlow) ? ((!isLowBlow) ? CombatSoundContainer.SoundCodeMissionCombatThrowingStoneMed : CombatSoundContainer.SoundCodeMissionCombatThrowingStoneLow) : CombatSoundContainer.SoundCodeMissionCombatThrowingStoneHigh);
					break;
				case WeaponClass.Boulder:
				case WeaponClass.BallistaBoulder:
					result = ((!isCriticalBlow) ? ((!isLowBlow) ? CombatSoundContainer.SoundCodeMissionCombatBoulderMed : CombatSoundContainer.SoundCodeMissionCombatBoulderLow) : CombatSoundContainer.SoundCodeMissionCombatBoulderHigh);
					break;
				default:
					result = ((!isCriticalBlow) ? ((!isLowBlow) ? CombatSoundContainer.SoundCodeMissionCombatMissileMed : CombatSoundContainer.SoundCodeMissionCombatMissileLow) : CombatSoundContainer.SoundCodeMissionCombatMissileHigh);
					break;
				}
			}
			else if (IsShield)
			{
				result = ((!_isMaterialMetal) ? CombatSoundContainer.SoundCodeMissionCombatWoodShieldBash : CombatSoundContainer.SoundCodeMissionCombatMetalShieldBash);
			}
			else if (attackType == AgentAttackType.Bash)
			{
				result = CombatSoundContainer.SoundCodeMissionCombatBluntLow;
			}
			else
			{
				if (isNonTipThrust)
				{
					damageType = DamageTypes.Blunt;
				}
				switch (damageType)
				{
				case DamageTypes.Cut:
					result = ((!isCriticalBlow) ? ((!isLowBlow) ? CombatSoundContainer.SoundCodeMissionCombatCutMed : CombatSoundContainer.SoundCodeMissionCombatCutLow) : CombatSoundContainer.SoundCodeMissionCombatCutHigh);
					break;
				case DamageTypes.Pierce:
					result = ((!isCriticalBlow) ? ((!isLowBlow) ? CombatSoundContainer.SoundCodeMissionCombatPierceMed : CombatSoundContainer.SoundCodeMissionCombatPierceLow) : CombatSoundContainer.SoundCodeMissionCombatPierceHigh);
					break;
				case DamageTypes.Blunt:
					result = ((!isCriticalBlow) ? ((!isLowBlow) ? CombatSoundContainer.SoundCodeMissionCombatBluntMed : CombatSoundContainer.SoundCodeMissionCombatBluntLow) : CombatSoundContainer.SoundCodeMissionCombatBluntHigh);
					break;
				default:
					result = CombatSoundContainer.SoundCodeMissionCombatBluntMed;
					TaleWorlds.Library.Debug.FailedAssert("false", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\BlowWeaponRecord.cs", "GetHitSound", 250);
					break;
				}
			}
			return result;
		}
	}
	public class BodyGenerator
	{
		public const string FaceGenTeethAnimationName = "facegen_teeth";

		public BodyProperties CurrentBodyProperties;

		public BodyProperties BodyPropertiesMin;

		public BodyProperties BodyPropertiesMax;

		public int Race;

		public bool IsFemale;

		public BasicCharacterObject Character { get; private set; }

		public BodyGenerator(BasicCharacterObject troop)
		{
			Character = troop;
			MBDebug.Print("FaceGen set character> character face key: " + troop.GetBodyProperties(troop.Equipment));
			Race = Character.Race;
			IsFemale = Character.IsFemale;
		}

		public FaceGenerationParams InitBodyGenerator(bool isDressed)
		{
			CurrentBodyProperties = Character.GetBodyProperties(Character.Equipment);
			FaceGenerationParams faceGenerationParams = FaceGenerationParams.Create();
			faceGenerationParams.CurrentRace = Character.Race;
			faceGenerationParams.CurrentGender = (Character.IsFemale ? 1 : 0);
			faceGenerationParams.CurrentAge = Character.Age;
			MBBodyProperties.GetParamsFromKey(ref faceGenerationParams, CurrentBodyProperties, isDressed && Character.Equipment.EarsAreHidden, isDressed && Character.Equipment.MouthIsHidden);
			faceGenerationParams.SetRaceGenderAndAdjustParams(faceGenerationParams.CurrentRace, faceGenerationParams.CurrentGender, (int)faceGenerationParams.CurrentAge);
			return faceGenerationParams;
		}

		public void RefreshFace(FaceGenerationParams faceGenerationParams, bool hasEquipment)
		{
			MBBodyProperties.ProduceNumericKeyWithParams(faceGenerationParams, hasEquipment && Character.Equipment.EarsAreHidden, hasEquipment && Character.Equipment.MouthIsHidden, ref CurrentBodyProperties);
			Race = faceGenerationParams.CurrentRace;
			IsFemale = faceGenerationParams.CurrentGender == 1;
		}

		public void SaveCurrentCharacter()
		{
			Character.UpdatePlayerCharacterBodyProperties(CurrentBodyProperties, Race, IsFemale);
		}
	}
	public class ClanFriendListService : IFriendListService
	{
		public const string CodeName = "ClanFriends";

		private readonly Dictionary<PlayerId, ClanPlayerInfo> _clanPlayerInfos;

		bool IFriendListService.InGameStatusFetchable => false;

		bool IFriendListService.AllowsFriendOperations => false;

		bool IFriendListService.CanInvitePlayersToPlatformSession => false;

		bool IFriendListService.IncludeInAllFriends => false;

		public event Action<PlayerId> OnUserStatusChanged;

		public event Action<PlayerId> OnFriendRemoved;

		public event Action OnFriendListChanged;

		public ClanFriendListService()
		{
			_clanPlayerInfos = new Dictionary<PlayerId, ClanPlayerInfo>();
		}

		string IFriendListService.GetServiceCodeName()
		{
			return "ClanFriends";
		}

		TextObject IFriendListService.GetServiceLocalizedName()
		{
			return new TextObject("{=j4F7tTzy}Clan");
		}

		FriendListServiceType IFriendListService.GetFriendListServiceType()
		{
			return FriendListServiceType.Clan;
		}

		IEnumerable<PlayerId> IFriendListService.GetAllFriends()
		{
			return _clanPlayerInfos.Keys;
		}

		async Task<bool> IFriendListService.GetUserOnlineStatus(PlayerId providedId)
		{
			bool result = false;
			_clanPlayerInfos.TryGetValue(providedId, out var value);
			if (value != null)
			{
				result = value.State == AnotherPlayerState.InMultiplayerGame || value.State == AnotherPlayerState.AtLobby || value.State == AnotherPlayerState.InParty;
			}
			return await Task.FromResult(result);
		}

		async Task<bool> IFriendListService.IsPlayingThisGame(PlayerId providedId)
		{
			return await ((IFriendListService)this).GetUserOnlineStatus(providedId);
		}

		async Task<string> IFriendListService.GetUserName(PlayerId providedId)
		{
			_clanPlayerInfos.TryGetValue(providedId, out var value);
			return await Task.FromResult(value?.PlayerName);
		}

		public async Task<PlayerId> GetUserWithName(string name)
		{
			return await Task.FromResult(_clanPlayerInfos.Values.FirstOrDefaultQ((ClanPlayerInfo playerInfo) => playerInfo.PlayerName == name)?.PlayerId ?? PlayerId.Empty);
		}

		public IEnumerable<PlayerId> GetPendingRequests()
		{
			return null;
		}

		public IEnumerable<PlayerId> GetReceivedRequests()
		{
			return null;
		}

		private void Dummy()
		{
			if (this.OnUserStatusChanged != null)
			{
				this.OnUserStatusChanged(default(PlayerId));
			}
			if (this.OnFriendRemoved != null)
			{
				this.OnFriendRemoved(default(PlayerId));
			}
		}

		public void OnClanInfoChanged(List<ClanPlayerInfo> playerInfosInClan)
		{
			_clanPlayerInfos.Clear();
			if (playerInfosInClan != null)
			{
				foreach (ClanPlayerInfo item in playerInfosInClan)
				{
					_clanPlayerInfos.Add(item.PlayerId, item);
				}
			}
			this.OnFriendListChanged?.Invoke();
		}
	}
