		private static bool SearchOccupiedInLineFormation(LineFormation lineFormation, int fileIndex, int rankIndex, int fileCount, bool searchLeftToRight, out ArrangementPosition foundPosition)
		{
			if (lineFormation.GetUnit(fileIndex, rankIndex) != null)
			{
				foundPosition = new ArrangementPosition(fileIndex, rankIndex);
				return true;
			}
			int fileIndex2 = TaleWorlds.Library.MathF.Min(fileIndex + 1, fileCount - 1);
			int fileIndex3 = TaleWorlds.Library.MathF.Max(fileIndex - 1, 0);
			foundPosition = ArrangementPosition.Invalid;
			if (searchLeftToRight)
			{
				if (SearchOccupiedFileLeftToRight(lineFormation, fileIndex2, rankIndex, fileCount, ref foundPosition))
				{
					return true;
				}
				if (SearchOccupiedFileRightToLeft(lineFormation, fileIndex3, rankIndex, ref foundPosition))
				{
					return true;
				}
			}
			else
			{
				if (SearchOccupiedFileRightToLeft(lineFormation, fileIndex3, rankIndex, ref foundPosition))
				{
					return true;
				}
				if (SearchOccupiedFileLeftToRight(lineFormation, fileIndex2, rankIndex, fileCount, ref foundPosition))
				{
					return true;
				}
			}
			return false;
		}

		private static bool SearchOccupiedFileRightToLeft(LineFormation lineFormation, int fileIndex, int rankIndex, ref ArrangementPosition foundPosition)
		{
			for (int num = fileIndex; num >= 0; num--)
			{
				if (lineFormation.GetUnit(num, rankIndex) != null)
				{
					foundPosition = new ArrangementPosition(num, rankIndex);
					return true;
				}
			}
			return false;
		}

		private static bool SearchOccupiedFileLeftToRight(LineFormation lineFormation, int fileIndex, int rankIndex, int fileCount, ref ArrangementPosition foundPosition)
		{
			for (int i = fileIndex; i < fileCount; i++)
			{
				if (lineFormation.GetUnit(i, rankIndex) != null)
				{
					foundPosition = new ArrangementPosition(i, rankIndex);
					return true;
				}
			}
			return false;
		}
	}
	public class DefaultItemPickupModel : ItemPickupModel
	{
		public override float GetItemScoreForAgent(SpawnedItemEntity item, Agent agent)
		{
			if (!item.WeaponCopy.Item.ItemFlags.HasAnyFlag(ItemFlags.CannotBePickedUp))
			{
				WeaponClass weaponClass = item.WeaponCopy.Item.PrimaryWeapon.WeaponClass;
				if (MissionGameModels.Current.BattleBannerBearersModel.IsFormationBanner(agent.Formation, item))
				{
					return 120f;
				}
				if (agent.HadSameTypeOfConsumableOrShieldOnSpawn(weaponClass))
				{
					switch (weaponClass)
					{
					case WeaponClass.SmallShield:
					case WeaponClass.LargeShield:
						return 100f;
					case WeaponClass.Arrow:
					case WeaponClass.Bolt:
					case WeaponClass.SlingStone:
						return 80f;
					case WeaponClass.Javelin:
						return 70f;
					case WeaponClass.ThrowingAxe:
						return 60f;
					case WeaponClass.ThrowingKnife:
						return 50f;
					case WeaponClass.Stone:
					case WeaponClass.BallistaStone:
						return 20f;
					case WeaponClass.Boulder:
					case WeaponClass.BallistaBoulder:
						return -1f;
					default:
						throw new MBException("This pickable item not scored: " + weaponClass);
					}
				}
			}
			return 0f;
		}

		public override bool IsItemAvailableForAgent(SpawnedItemEntity item, Agent agent, EquipmentIndex slotToPickUp)
		{
			if (!agent.CanReachAndUseObject(item, 0f) || !agent.ObjectHasVacantPosition(item) || item.HasAIMovingTo)
			{
				return false;
			}
			WeaponClass weaponClass = item.WeaponCopy.Item.PrimaryWeapon.WeaponClass;
			switch (weaponClass)
			{
			case WeaponClass.Arrow:
			case WeaponClass.Bolt:
			case WeaponClass.SlingStone:
			case WeaponClass.ThrowingAxe:
			case WeaponClass.ThrowingKnife:
			case WeaponClass.Javelin:
				if (item.WeaponCopy.Amount > 0 && !agent.Equipment[slotToPickUp].IsEmpty && agent.Equipment[slotToPickUp].Item.PrimaryWeapon.WeaponClass == weaponClass && agent.Equipment[slotToPickUp].Amount <= agent.Equipment[slotToPickUp].ModifiedMaxAmount >> 1)
				{
					return true;
				}
				break;
			case WeaponClass.SmallShield:
			case WeaponClass.LargeShield:
				if (agent.Equipment[slotToPickUp].IsEmpty)
				{
					return agent.HasLostShield();
				}
				return false;
			case WeaponClass.Banner:
				return agent.Equipment[slotToPickUp].IsEmpty;
			}
			return false;
		}

		public override bool IsAgentEquipmentSuitableForPickUpAvailability(Agent agent)
		{
			if (agent.HasLostShield())
			{
				return true;
			}
			for (EquipmentIndex equipmentIndex = EquipmentIndex.WeaponItemBeginSlot; equipmentIndex < EquipmentIndex.ExtraWeaponSlot; equipmentIndex++)
			{
				MissionWeapon missionWeapon = agent.Equipment[equipmentIndex];
				if (!missionWeapon.IsEmpty && missionWeapon.IsAnyConsumable() && missionWeapon.Amount <= missionWeapon.ModifiedMaxAmount >> 1)
				{
					return true;
				}
			}
			BattleBannerBearersModel battleBannerBearersModel = MissionGameModels.Current.BattleBannerBearersModel;
			if (battleBannerBearersModel != null && battleBannerBearersModel.IsBannerSearchingAgent(agent))
			{
				return true;
			}
			return false;
		}
	}
	public class DefaultMissionDifficultyModel : MissionDifficultyModel
	{
		public override float GetDamageMultiplierOfCombatDifficulty(Agent victimAgent, Agent attackerAgent = null)
		{
			float result = 1f;
			victimAgent = (victimAgent.IsMount ? victimAgent.RiderAgent : victimAgent);
			if (victimAgent != null)
			{
				if (victimAgent.IsMainAgent)
				{
					result = Mission.Current.DamageToPlayerMultiplier;
				}
				else
				{
					Agent agent = Mission.Current?.MainAgent;
					if (agent != null && victimAgent.IsFriendOf(agent))
					{
						result = ((attackerAgent == null || attackerAgent != agent) ? Mission.Current.DamageToFriendsMultiplier : Mission.Current.DamageFromPlayerToFriendsMultiplier);
					}
				}
			}
			return result;
		}
	}
	public class DefaultStrikeMagnitudeModel : StrikeMagnitudeCalculationModel
	{
		public override float CalculateStrikeMagnitudeForMissile(in AttackInformation attackInformation, in AttackCollisionData collisionData, in MissionWeapon weapon, float missileSpeed)
		{
			float missileTotalDamage = collisionData.MissileTotalDamage;
			float missileStartingBaseSpeed = collisionData.MissileStartingBaseSpeed;
			float num = missileSpeed / missileStartingBaseSpeed;
			return num * num * missileTotalDamage;
		}

		public override float CalculateStrikeMagnitudeForSwing(in AttackInformation attackInformation, in AttackCollisionData collisionData, in MissionWeapon weapon, float swingSpeed, float impactPointAsPercent, float extraLinearSpeed)
		{
			WeaponComponentData currentUsageItem = weapon.CurrentUsageItem;
			return CombatStatCalculator.CalculateStrikeMagnitudeForSwing(swingSpeed, impactPointAsPercent, weapon.Item.Weight, currentUsageItem.GetRealWeaponLength(), currentUsageItem.TotalInertia, currentUsageItem.CenterOfMass, extraLinearSpeed);
		}

		public override float CalculateStrikeMagnitudeForUnarmedAttack(in AttackInformation attackInformation, in AttackCollisionData collisionData, float progressEffect, float momentumRemaining)
		{
			return momentumRemaining * progressEffect * ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.FistFightDamageMultiplier);
		}

		public override float CalculateStrikeMagnitudeForThrust(in AttackInformation attackInformation, in AttackCollisionData collisionData, in MissionWeapon weapon, float thrustWeaponSpeed, float extraLinearSpeed, bool isThrown = false)
		{
			return CombatStatCalculator.CalculateStrikeMagnitudeForThrust(thrustWeaponSpeed, weapon.Item.Weight, extraLinearSpeed, isThrown);
		}

		public override float ComputeRawDamage(DamageTypes damageType, float magnitude, float armorEffectiveness, float absorbedDamageRatio)
		{
			float bluntDamageFactorByDamageType = GetBluntDamageFactorByDamageType(damageType);
			float num = 50f / (50f + armorEffectiveness);
			float num2 = magnitude * num;
			float num3 = bluntDamageFactorByDamageType * num2;
			float num4;
			switch (damageType)
			{
			case DamageTypes.Cut:
				num4 = TaleWorlds.Library.MathF.Max(0f, num2 - armorEffectiveness * 0.5f);
				break;
			case DamageTypes.Pierce:
				num4 = TaleWorlds.Library.MathF.Max(0f, num2 - armorEffectiveness * 0.33f);
				break;
			case DamageTypes.Blunt:
				num4 = TaleWorlds.Library.MathF.Max(0f, num2 - armorEffectiveness * 0.2f);
				break;
			default:
				TaleWorlds.Library.Debug.FailedAssert("Given damage type is invalid.", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\ComponentInterfaces\\DefaultStrikeMagnitudeModel.cs", "ComputeRawDamage", 70);
				return 0f;
			}
			num3 += (1f - bluntDamageFactorByDamageType) * num4;
			return num3 * absorbedDamageRatio;
		}

		public override float GetBluntDamageFactorByDamageType(DamageTypes damageType)
		{
			float result = 0f;
			switch (damageType)
			{
			case DamageTypes.Blunt:
				result = 0.6f;
				break;
			case DamageTypes.Cut:
				result = 0.1f;
				break;
			case DamageTypes.Pierce:
				result = 0.25f;
				break;
			}
			return result;
		}

		public override float CalculateHorseArcheryFactor(BasicCharacterObject characterObject)
		{
			return 100f;
		}

		public override float CalculateBaseBlowMagnitudeForPassiveUsage(in AttackInformation attackInformation, in AttackCollisionData collisionData, float extraLinearSpeed)
		{
			return CombatStatCalculator.CalculateBaseBlowMagnitudeForPassiveUsage(attackInformation.AttackerWeapon.Item.Weight, extraLinearSpeed);
		}
	}
	public class MultiplayerAgentApplyDamageModel : AgentApplyDamageModel
	{
		public override bool IsDamageIgnored(in AttackInformation attackInformation, in AttackCollisionData collisionData)
