	public class CustomBattleBannerBearersModel : BattleBannerBearersModel
	{
		private static readonly int[] BannerBearerPriorityPerTier = new int[7] { 0, 1, 3, 5, 6, 4, 2 };

		private static List<ItemObject> ReplacementWeapons = null;

		private static DefaultBattleMissionAgentSpawnLogic _missionSpawnLogic;

		public override int GetMinimumFormationTroopCountToBearBanners()
		{
			return 2;
		}

		public override float GetBannerInteractionDistance(Agent interactingAgent)
		{
			if (!interactingAgent.HasMount)
			{
				return 1.5f;
			}
			return 3f;
		}

		public override bool CanBannerBearerProvideEffectToFormation(Agent agent, Formation formation)
		{
			if (agent.Formation != formation)
			{
				if (agent.IsPlayerControlled)
				{
					return agent.Team == formation.Team;
				}
				return false;
			}
			return true;
		}

		public override bool CanAgentPickUpAnyBanner(Agent agent)
		{
			if (agent.IsHuman && agent.Banner == null && agent.CanBeAssignedForScriptedMovement() && (agent.CommonAIComponent == null || !agent.CommonAIComponent.IsPanicked))
			{
				if (agent.HumanAIComponent != null)
				{
					return !agent.HumanAIComponent.IsInImportantCombatAction();
				}
				return true;
			}
			return false;
		}

		public override bool CanAgentBecomeBannerBearer(Agent agent)
		{
			if (_missionSpawnLogic == null)
			{
				_missionSpawnLogic = Mission.Current.GetMissionBehavior<DefaultBattleMissionAgentSpawnLogic>();
			}
			if (_missionSpawnLogic != null)
			{
				Team team = agent.Formation?.Team;
				if (team != null)
				{
					BasicCharacterObject generalCharacterOfSide = _missionSpawnLogic.GetGeneralCharacterOfSide(team.Side);
					if (agent.IsHuman && !agent.IsMainAgent && !agent.IsHero && agent.IsAIControlled)
					{
						return agent.Character != generalCharacterOfSide;
					}
					return false;
				}
			}
			return false;
		}

		public override int GetAgentBannerBearingPriority(Agent agent)
		{
			if (!CanAgentBecomeBannerBearer(agent))
			{
				return 0;
			}
			if (agent.Formation != null)
			{
				bool calculateHasSignificantNumberOfMounted = agent.Formation.CalculateHasSignificantNumberOfMounted;
				if ((calculateHasSignificantNumberOfMounted && !agent.HasMount) || (!calculateHasSignificantNumberOfMounted && agent.HasMount))
				{
					return 0;
				}
			}
			if (agent.Banner != null)
			{
				return int.MaxValue;
			}
			int num = Math.Min(agent.Character.Level / 4 + 1, BannerBearerPriorityPerTier.Length - 1);
			return BannerBearerPriorityPerTier[num];
		}

		public override bool CanFormationDeployBannerBearers(Formation formation)
		{
			BannerBearerLogic bannerBearerLogic = base.BannerBearerLogic;
			if (bannerBearerLogic == null || formation.CountOfUnits < GetMinimumFormationTroopCountToBearBanners() || bannerBearerLogic.GetFormationBanner(formation) == null)
			{
				return false;
			}
			return formation.UnitsWithoutLooseDetachedOnes.Count((IFormationUnit unit) => unit is Agent agent && CanAgentBecomeBannerBearer(agent)) > 0;
		}

		public override int GetDesiredNumberOfBannerBearersForFormation(Formation formation)
		{
			if (!CanFormationDeployBannerBearers(formation))
			{
				return 0;
			}
			return 1;
		}

		public override ItemObject GetBannerBearerReplacementWeapon(BasicCharacterObject agentCharacter)
		{
			if (ReplacementWeapons == null)
			{
				ReplacementWeapons = MBObjectManager.Instance.GetObjectTypeList<ItemObject>().Where(delegate(ItemObject item)
				{
					if (item.PrimaryWeapon != null)
					{
						WeaponComponentData primaryWeapon = item.PrimaryWeapon;
						return primaryWeapon.WeaponClass == WeaponClass.OneHandedSword;
					}
					return false;
				}).ToList();
			}
			if (ReplacementWeapons.IsEmpty())
			{
				return null;
			}
			IEnumerable<ItemObject> enumerable = ReplacementWeapons.Where((ItemObject item) => item.Culture != null && item.Culture == agentCharacter.Culture);
			List<(int, ItemObject)> list = new List<(int, ItemObject)>();
			int minTierDifference = int.MaxValue;
			foreach (ItemObject item in enumerable)
			{
				int a = TaleWorlds.Library.MathF.Ceiling(((float)agentCharacter.Level - 5f) / 5f);
				a = TaleWorlds.Library.MathF.Min(TaleWorlds.Library.MathF.Max(a, 0), 7);
				int num = TaleWorlds.Library.MathF.Abs((int)(item.Tier - a));
				if (num < minTierDifference)
				{
					minTierDifference = num;
				}
				list.Add((num, item));
			}
			return list.Where<(int, ItemObject)>(((int TierDifference, ItemObject Weapon) tuple) => tuple.TierDifference == minTierDifference).GetRandomElementInefficiently().Item2;
		}
	}
	public class CustomBattleCombatant : IBattleCombatant
	{
		private List<BasicCharacterObject> _characters;

		private BasicCharacterObject _general;

		public TextObject Name { get; private set; }

		public BattleSideEnum Side { get; set; }

		public BasicCharacterObject General => _general;

		public BasicCultureObject BasicCulture { get; private set; }

		public Tuple<uint, uint> PrimaryColorPair => new Tuple<uint, uint>(Banner.GetPrimaryColor(), Banner.GetFirstIconColor());

		public Tuple<uint, uint> AlternativeColorPair => new Tuple<uint, uint>(Banner.GetFirstIconColor(), Banner.GetPrimaryColor());

		public Banner Banner { get; private set; }

		public IEnumerable<BasicCharacterObject> Characters => _characters.AsReadOnly();

		public int CountOfCharacters => _characters.Count();

		public int NumberOfAllMembers { get; private set; }

		public int NumberOfHealthyMembers => _characters.Count;

		public CustomBattleCombatant(TextObject name, BasicCultureObject culture, Banner banner)
		{
			Name = name;
			BasicCulture = culture;
			Banner = banner;
			_characters = new List<BasicCharacterObject>();
			_general = null;
		}

		public void AddCharacter(BasicCharacterObject characterObject, int number)
		{
			for (int i = 0; i < number; i++)
			{
				_characters.Add(characterObject);
			}
			NumberOfAllMembers += number;
		}

		public void SetGeneral(BasicCharacterObject generalCharacter)
		{
			_general = generalCharacter;
		}

		public int GetTacticsSkillAmount()
		{
			if (_characters.Count > 0)
			{
				return _characters.Max((BasicCharacterObject h) => h.GetSkillValue(DefaultSkills.Tactics));
			}
			return 0;
		}

		public int GetNumberOfMissionReadyTroops()
		{
			return NumberOfHealthyMembers;
		}

		public bool IsUnderPlayersCommand(BattleSideEnum playerSide)
		{
			if (Side != playerSide)
			{
				return false;
			}
			return General.IsPlayerCharacter;
		}
	}
	public class CustomBattleTroopSupplier : IMissionTroopSupplier
	{
		private readonly CustomBattleCombatant _customBattleCombatant;

		private PriorityQueue<float, BasicCharacterObject> _characters;

		private int _numAllocated;

		private int _numWounded;

		private int _numKilled;

		private int _numRouted;

		private Func<BasicCharacterObject, bool> _customAllocationConditions;

		private bool _anyTroopRemainsToBeSupplied = true;

		private readonly bool _isPlayerSide;

		private readonly bool _isPlayerGeneral;

		private readonly bool _isSallyOut;

		private int _nextTroopRank;

		public int NumRemovedTroops => _numWounded + _numKilled + _numRouted;

		public int NumTroopsNotSupplied => _characters.Count - _numAllocated;

		public bool AnyTroopRemainsToBeSupplied => _anyTroopRemainsToBeSupplied;

		public CustomBattleTroopSupplier(CustomBattleCombatant customBattleCombatant, bool isPlayerSide, bool isPlayerGeneral, bool isSallyOut, Func<BasicCharacterObject, bool> customAllocationConditions = null)
		{
			_customBattleCombatant = customBattleCombatant;
			_customAllocationConditions = customAllocationConditions;
			_isPlayerSide = isPlayerSide;
			_isPlayerGeneral = isPlayerSide && isPlayerGeneral;
			_isSallyOut = isSallyOut;
			ArrangePriorities();
			_nextTroopRank = 0;
		}

		private void ArrangePriorities()
		{
			_characters = new PriorityQueue<float, BasicCharacterObject>(new TaleWorlds.Library.GenericComparer<float>());
			int[] troopCountByFormationType = new int[8];
			int[] enqueuedTroopCountByFormationType = new int[8];
			int i;
			for (i = 0; i < 8; i++)
			{
				troopCountByFormationType[i] = _customBattleCombatant.Characters.Count((BasicCharacterObject character) => character.DefaultFormationClass == (FormationClass)i);
			}
			UnitSpawnPrioritizations unitSpawnPrioritization = ((!_isPlayerSide) ? UnitSpawnPrioritizations.HighLevel : Game.Current.UnitSpawnPrioritization);
			int troopCountTotal = troopCountByFormationType.Sum();
			float heroProbability = 1000f;
			foreach (BasicCharacterObject character in _customBattleCombatant.Characters)
			{
				FormationClass formationClass = character.GetFormationClass();
				float num = 0f;
				num = ((!_isSallyOut) ? GetDefaultProbabilityOfTroop(character, troopCountTotal, unitSpawnPrioritization, ref heroProbability, ref troopCountByFormationType, ref enqueuedTroopCountByFormationType) : GetSallyOutAmbushProbabilityOfTroop(character, troopCountTotal, ref heroProbability));
				troopCountByFormationType[(int)formationClass]--;
				enqueuedTroopCountByFormationType[(int)formationClass]++;
				_characters.Enqueue(num, character);
			}
		}

		private float GetSallyOutAmbushProbabilityOfTroop(BasicCharacterObject character, int troopCountTotal, ref float heroProbability)
		{
			float num = 0f;
			if (character.IsHero)
			{
				num = heroProbability--;
			}
			else
			{
				num += (float)character.Level;
				if (character.HasMount())
				{
					num += 100f;
				}
			}
			return num;
		}

		private float GetDefaultProbabilityOfTroop(BasicCharacterObject character, int troopCountTotal, UnitSpawnPrioritizations unitSpawnPrioritization, ref float heroProbability, ref int[] troopCountByFormationType, ref int[] enqueuedTroopCountByFormationType)
		{
			FormationClass formationClass = character.GetFormationClass();
			float num = (float)troopCountByFormationType[(int)formationClass] / (float)((unitSpawnPrioritization == UnitSpawnPrioritizations.Homogeneous) ? (enqueuedTroopCountByFormationType[(int)formationClass] + 1) : troopCountTotal);
			float num2 = (character.IsHero ? heroProbability-- : num);
			if (!character.IsHero && (unitSpawnPrioritization == UnitSpawnPrioritizations.HighLevel || unitSpawnPrioritization == UnitSpawnPrioritizations.LowLevel))
			{
				num2 += (float)character.Level;
				if (unitSpawnPrioritization == UnitSpawnPrioritizations.LowLevel)
				{
					num2 *= -1f;
				}
			}
			return num2;
		}

		public IEnumerable<IAgentOriginBase> SupplyTroops(int numberToAllocate)
		{
			List<BasicCharacterObject> list = AllocateTroops(numberToAllocate);
			CustomBattleAgentOrigin[] array = new CustomBattleAgentOrigin[list.Count];
			_numAllocated += list.Count;
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = new CustomBattleAgentOrigin(uniqueNo: new UniqueTroopDescriptor(Game.Current.NextUniqueTroopSeed), customBattleCombatant: _customBattleCombatant, characterObject: list[i], troopSupplier: this, isPlayerSide: _isPlayerSide, rank: _nextTroopRank++);
			}
			if (array.Length < numberToAllocate)
			{
				_anyTroopRemainsToBeSupplied = false;
			}
			return array;
		}

		public IAgentOriginBase SupplyOneTroop()
		{
			BasicCharacterObject basicCharacterObject = AllocateTroop();
			if (basicCharacterObject != null)
			{
				return new CustomBattleAgentOrigin(uniqueNo: new UniqueTroopDescriptor(Game.Current.NextUniqueTroopSeed), customBattleCombatant: _customBattleCombatant, characterObject: basicCharacterObject, troopSupplier: this, isPlayerSide: _isPlayerSide, rank: _nextTroopRank++);
			}
			_anyTroopRemainsToBeSupplied = false;
			return null;
		}

		public IEnumerable<IAgentOriginBase> GetAllTroops()
		{
			CustomBattleAgentOrigin[] array = new CustomBattleAgentOrigin[_customBattleCombatant.Characters.Count()];
			int num = 0;
			foreach (BasicCharacterObject character in _customBattleCombatant.Characters)
			{
				array[num] = new CustomBattleAgentOrigin(_customBattleCombatant, character, this, _isPlayerSide);
				num++;
			}
			return array;
		}

		public BasicCharacterObject GetGeneralCharacter()
		{
			return _customBattleCombatant.General;
		}

		private List<BasicCharacterObject> AllocateTroops(int numberToAllocate)
		{
			if (numberToAllocate > _characters.Count)
			{
				numberToAllocate = _characters.Count;
			}
			List<BasicCharacterObject> list = new List<BasicCharacterObject>();
			while (numberToAllocate > 0 && _characters.Count > 0)
			{
				BasicCharacterObject basicCharacterObject = _characters.DequeueValue();
				if (_customAllocationConditions == null || _customAllocationConditions(basicCharacterObject))
				{
					list.Add(basicCharacterObject);
					numberToAllocate--;
				}
			}
			return list;
		}

		private BasicCharacterObject AllocateTroop()
		{
			BasicCharacterObject result = null;
			while (_characters.Count > 0)
			{
				BasicCharacterObject basicCharacterObject = _characters.DequeueValue();
				if (_customAllocationConditions == null || _customAllocationConditions(basicCharacterObject))
				{
					result = basicCharacterObject;
					break;
				}
			}
			return result;
		}

		public void OnTroopWounded()
		{
			_numWounded++;
		}

		public void OnTroopKilled()
		{
			_numKilled++;
		}

		public void OnTroopRouted()
		{
			_numRouted++;
		}

		public int GetNumberOfPlayerControllableTroops()
		{
			return _customBattleCombatant.CountOfCharacters;
		}
	}
	public class BattleSideSpawnPathSelector
	{
		public const float MaxNeighborCount = 2f;

		private readonly Mission _mission;

		private readonly SpawnPathData _initialSpawnPath;

		private readonly MBList<SpawnPathData> _reinforcementSpawnPaths;

		public SpawnPathData InitialSpawnPath => _initialSpawnPath;

		public MBReadOnlyList<SpawnPathData> ReinforcementPaths => _reinforcementSpawnPaths;

		public BattleSideSpawnPathSelector(Mission mission, TaleWorlds.Engine.Path initialPath, float initialPivotOffset, bool initialPathIsInverted)
		{
			_mission = mission;
			SpawnPathData.SnapMethod snapType = (mission.IsNavalBattle ? SpawnPathData.SnapMethod.SnapToWaterLevel : (mission.IsFieldBattle ? SpawnPathData.SnapMethod.SnapToTerrain : SpawnPathData.SnapMethod.DontSnap));
			_initialSpawnPath = SpawnPathData.Create(_mission.Scene, initialPath, initialPivotOffset, initialPathIsInverted, snapType);
			_reinforcementSpawnPaths = new MBList<SpawnPathData>();
			FindReinforcementPaths();
		}

		public bool HasReinforcementPath(TaleWorlds.Engine.Path path)
		{
			if (path != null)
			{
				return _reinforcementSpawnPaths.Exists((SpawnPathData pathData) => pathData.Path.Pointer == path.Pointer);
			}
			return false;
		}

		private void FindReinforcementPaths()
		{
			_reinforcementSpawnPaths.Clear();
			float pivotOffset = _initialSpawnPath.PathLength / 2f;
			SpawnPathData spawnPathData = SpawnPathData.Create(_initialSpawnPath.Scene, _initialSpawnPath.Path, pivotOffset, _initialSpawnPath.IsInverted);
			_reinforcementSpawnPaths.Add(spawnPathData);
			MBList<TaleWorlds.Engine.Path> allSpawnPaths = MBSceneUtilities.GetAllSpawnPaths(_mission.Scene);
			if (allSpawnPaths.Count == 0)
			{
				return;
			}
			bool flag = false;
			if (allSpawnPaths.Count > 1)
			{
				MatrixFrame[] array = new MatrixFrame[100];
				spawnPathData.Path.GetPoints(array);
				MatrixFrame matrixFrame = (spawnPathData.IsInverted ? array[spawnPathData.Path.NumberOfPoints - 1] : array[0]);
				SortedList<float, SpawnPathData> sortedList = new SortedList<float, SpawnPathData>();
				foreach (TaleWorlds.Engine.Path item in allSpawnPaths)
				{
					if (item.NumberOfPoints > 1 && item.Pointer != spawnPathData.Path.Pointer)
					{
						item.GetPoints(array);
						MatrixFrame matrixFrame2 = array[0];
						MatrixFrame matrixFrame3 = array[item.NumberOfPoints - 1];
						float key = matrixFrame2.origin.DistanceSquared(matrixFrame.origin);
						float key2 = matrixFrame3.origin.DistanceSquared(matrixFrame.origin);
						float pivotOffset2 = item.GetTotalLength() / 2f;
						sortedList.Add(key, SpawnPathData.Create(_initialSpawnPath.Scene, item, pivotOffset2));
						sortedList.Add(key2, SpawnPathData.Create(_initialSpawnPath.Scene, item, pivotOffset2, isInverted: true));
					}
					else
					{
						flag = flag || spawnPathData.Path.Pointer == item.Pointer;
					}
				}
				int num = 0;
				{
					foreach (KeyValuePair<float, SpawnPathData> item2 in sortedList)
					{
						_reinforcementSpawnPaths.Add(item2.Value);
						num++;
						if ((float)num >= 2f)
						{
							break;
						}
					}
					return;
				}
			}
			flag = spawnPathData.Path.Pointer == allSpawnPaths[0].Pointer;
		}
	}
	public class BattleSpawnPathSelector
	{
		private readonly Mission _mission;

		private TaleWorlds.Engine.Path _initialPath;

		private BattleSideSpawnPathSelector[] _battleSideSelectors;

		public bool IsInitialized { get; private set; }

		public TaleWorlds.Engine.Path InitialPath => _initialPath;

		public BattleSpawnPathSelector(Mission mission)
		{
			IsInitialized = false;
			_initialPath = null;
			_mission = mission;
		}

		public void Initialize()
		{
			float pathPivotOffset;
			float pathLength;
			bool isPathInverted;
			TaleWorlds.Engine.Path path = FindBestInitialPath(_mission, out pathPivotOffset, out pathLength, out isPathInverted);
			if (path != null)
			{
				_initialPath = path;
				_battleSideSelectors = new BattleSideSpawnPathSelector[2];
				_battleSideSelectors[0] = new BattleSideSpawnPathSelector(_mission, path, pathPivotOffset, isPathInverted);
				float initialPivotOffset = TaleWorlds.Library.MathF.Clamp(pathLength - pathPivotOffset, 1f, pathLength - 1f);
				_battleSideSelectors[1] = new BattleSideSpawnPathSelector(_mission, path, initialPivotOffset, !isPathInverted);
				IsInitialized = true;
			}
			else
			{
				_initialPath = null;
				IsInitialized = false;
			}
		}

		public bool HasPath(TaleWorlds.Engine.Path path)
		{
			if (!IsInitialized)
			{
				TaleWorlds.Library.Debug.FailedAssert("BattleSpawnPathSelector must be initialized.", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Deployment\\BattleSpawnPathSelector.cs", "HasPath", 68);
				return false;
			}
			BattleSideSpawnPathSelector battleSideSpawnPathSelector = _battleSideSelectors[1];
			BattleSideSpawnPathSelector battleSideSpawnPathSelector2 = _battleSideSelectors[0];
			if (path != null)
			{
				if (!(_initialPath.Pointer == path.Pointer) && !battleSideSpawnPathSelector.HasReinforcementPath(path))
				{
					return battleSideSpawnPathSelector2.HasReinforcementPath(path);
				}
				return true;
			}
			return false;
		}

		public bool GetInitialPathDataOfSide(BattleSideEnum side, out SpawnPathData pathPathData)
		{
			if (!IsInitialized)
			{
				TaleWorlds.Library.Debug.FailedAssert("BattleSpawnPathSelector must be initialized.", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Deployment\\BattleSpawnPathSelector.cs", "GetInitialPathDataOfSide", 82);
				pathPathData = null;
				return false;
			}
			pathPathData = _battleSideSelectors[(int)side].InitialSpawnPath;
			return pathPathData.IsValid;
		}

		public MBReadOnlyList<SpawnPathData> GetReinforcementPathsDataOfSide(BattleSideEnum side)
		{
			if (!IsInitialized)
			{
				TaleWorlds.Library.Debug.FailedAssert("BattleSpawnPathSelector must be initialized.", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Deployment\\BattleSpawnPathSelector.cs", "GetReinforcementPathsDataOfSide", 96);
				return null;
			}
			return _battleSideSelectors[(int)side].ReinforcementPaths;
		}

		public static TaleWorlds.Engine.Path FindBestInitialPath(Mission mission, out float pathPivotOffset, out float pathLength, out bool isPathInverted)
		{
			pathPivotOffset = 0f;
			isPathInverted = false;
			pathLength = 0f;
			MBList<TaleWorlds.Engine.Path> allSpawnPaths = MBSceneUtilities.GetAllSpawnPaths(mission.Scene);
			if (allSpawnPaths.IsEmpty())
			{
				return null;
			}
			int num = 2;
			foreach (TaleWorlds.Engine.Path item in allSpawnPaths)
			{
				num = TaleWorlds.Library.MathF.Max(item.NumberOfPoints, num);
			}
			TaleWorlds.Engine.Path path = null;
			if (mission.HasSceneMapPatch())
			{
				TaleWorlds.Engine.Path path2 = null;
				bool flag = false;
				float num2 = float.MinValue;
				MatrixFrame[] array = new MatrixFrame[num];
				mission.GetPatchSceneEncounterPosition(out var position);
				Vec2 asVec = position.AsVec2;
				mission.GetPatchSceneEncounterDirection(out var direction);
				foreach (TaleWorlds.Engine.Path item2 in allSpawnPaths)
				{
					if (item2.NumberOfPoints > 1)
					{
						item2.GetPoints(array);
						float num3 = 0f;
						for (int i = 1; i < item2.NumberOfPoints; i++)
						{
							Vec2 asVec2 = array[i - 1].origin.AsVec2;
							Vec2 v = (array[i].origin.AsVec2 - asVec2).Normalized();
							float num4 = direction.DotProduct(v);
							float num5 = 1000f / (1f + asVec2.Distance(asVec));
							num3 += num5 * num4;
						}
						num3 /= (float)(item2.NumberOfPoints - 1);
						bool flag2 = false;
						if (num3 < 0f)
						{
							num3 = 0f - num3;
							flag2 = true;
						}
						if (num3 >= num2)
						{
							path2 = item2;
							num2 = num3;
							flag = flag2;
						}
					}
				}
				if (path2 != null)
				{
					path2.GetPoints(array);
					float num6 = array[0].origin.AsVec2.DistanceSquared(asVec);
					float value = 0f;
					float num7 = 0f;
					for (int j = 1; j < path2.NumberOfPoints; j++)
					{
						float num8 = array[j].origin.AsVec2.DistanceSquared(asVec);
						num7 += path2.GetArcLength(j - 1);
						if (num8 < num6)
						{
							num6 = num8;
							value = num7;
						}
					}
					path = path2;
					pathLength = path.GetTotalLength();
					pathPivotOffset = TaleWorlds.Library.MathF.Clamp(value, 1f, pathLength - 1f);
					isPathInverted = flag;
				}
			}
			else
			{
				TaleWorlds.Engine.Path randomElement = allSpawnPaths.GetRandomElement();
				if (randomElement.NumberOfPoints > 1)
				{
					path = randomElement;
					float num9 = 0.37f + MBRandom.RandomFloat * 0.26f;
					pathLength = path.GetTotalLength();
					pathPivotOffset = TaleWorlds.Library.MathF.Clamp(pathLength * num9, 1f, pathLength - 1f);
					isPathInverted = false;
				}
			}
			return path;
		}
	}
	public class DefaultDeploymentPlan
	{
		public const float VerticalFormationGap = 3f;

		public const float HorizontalFormationGap = 2f;

		public const float MaxSafetyScore = 100f;

		public readonly Team Team;

		public readonly bool IsReinforcement;

		public readonly SpawnPathData SpawnPathData;

		private readonly Mission _mission;

		private int _planCount;

		private bool _spawnWithHorses;

		private readonly int[] _formationMountedTroopCounts;

		private readonly int[] _formationFootTroopCounts;

		private Vec3 _meanPosition;

		private readonly DefaultFormationDeploymentPlan[] _formationPlans;

		private readonly SortedList<FormationDeploymentOrder, DefaultFormationDeploymentPlan>[] _deploymentFlanks = new SortedList<FormationDeploymentOrder, DefaultFormationDeploymentPlan>[4];

		public bool SpawnWithHorses => _spawnWithHorses;

		public int PlanCount => _planCount;

		public bool IsPlanMade { get; private set; }

		public float SpawnPathOffset { get; private set; }

		public float TargetOffset { get; private set; }

		public bool IsSafeToDeploy => SafetyScore >= 50f;

		public float SafetyScore { get; private set; }

		public int FootTroopCount
		{
			get
			{
				int num = 0;
				for (int i = 0; i < 11; i++)
				{
					num += _formationFootTroopCounts[i];
				}
				return num;
			}
		}

		public int MountedTroopCount
		{
			get
			{
				int num = 0;
				for (int i = 0; i < 11; i++)
				{
					num += _formationMountedTroopCounts[i];
				}
				return num;
			}
		}

		public int TroopCount
		{
			get
			{
				int num = 0;
				for (int i = 0; i < 11; i++)
				{
					num += _formationFootTroopCounts[i] + _formationMountedTroopCounts[i];
				}
				return num;
			}
		}

		public Vec3 MeanPosition => _meanPosition;

		public static DefaultDeploymentPlan CreateInitialPlan(Mission mission, Team team)
		{
			return new DefaultDeploymentPlan(mission, team, isReinforcement: false, null);
		}

		public static DefaultDeploymentPlan CreateReinforcementPlan(Mission mission, Team team)
		{
			return new DefaultDeploymentPlan(mission, team, isReinforcement: true, null);
		}

		public static DefaultDeploymentPlan CreateReinforcementPlanWithSpawnPath(Mission mission, Team team, SpawnPathData spawnPathData)
		{
			return new DefaultDeploymentPlan(mission, team, isReinforcement: true, spawnPathData);
		}

		private DefaultDeploymentPlan(Mission mission, Team team, bool isReinforcement, SpawnPathData spawnPathData)
		{
			_mission = mission;
			_planCount = 0;
			Team = team;
			IsReinforcement = isReinforcement;
			SpawnPathData = spawnPathData;
			int num = 11;
			_formationPlans = new DefaultFormationDeploymentPlan[num];
			_formationFootTroopCounts = new int[num];
			_formationMountedTroopCounts = new int[num];
			_meanPosition = Vec3.Zero;
			IsPlanMade = false;
			SpawnPathOffset = 0f;
			TargetOffset = 0f;
			SafetyScore = 100f;
			for (int i = 0; i < _formationPlans.Length; i++)
			{
				FormationClass fClass = (FormationClass)i;
				_formationPlans[i] = new DefaultFormationDeploymentPlan(fClass);
			}
			for (int j = 0; j < 4; j++)
			{
				_deploymentFlanks[j] = new SortedList<FormationDeploymentOrder, DefaultFormationDeploymentPlan>(FormationDeploymentOrder.GetComparer());
			}
			ClearAddedTroops();
			ClearPlan();
		}

		public void SetSpawnWithHorses(bool value)
		{
			_spawnWithHorses = value;
		}

		public void MakeDeploymentPlan(float spawnPathOffset = 0f, float targetOffset = 0f, FormationSceneSpawnEntry[,] formationSceneSpawnEntries = null)
		{
			SpawnPathOffset = spawnPathOffset;
			TargetOffset = targetOffset;
			PlanFormationDimensions();
			if (_mission.HasSpawnPath)
			{
				PlanFieldBattleDeploymentFromSpawnPath(spawnPathOffset, targetOffset);
			}
			else if (_mission.IsFieldBattle)
			{
				PlanFieldBattleDeploymentFromSceneData(formationSceneSpawnEntries);
			}
			else
			{
				PlanBattleDeploymentFromSceneData(formationSceneSpawnEntries);
			}
			ComputeMeanPosition();
		}

		public void ClearPlan()
		{
			DefaultFormationDeploymentPlan[] formationPlans = _formationPlans;
			for (int i = 0; i < formationPlans.Length; i++)
			{
				formationPlans[i].Clear();
			}
			SortedList<FormationDeploymentOrder, DefaultFormationDeploymentPlan>[] deploymentFlanks = _deploymentFlanks;
			for (int i = 0; i < deploymentFlanks.Length; i++)
			{
				deploymentFlanks[i].Clear();
			}
			IsPlanMade = false;
		}

		public void ClearAddedTroops()
		{
			for (int i = 0; i < 11; i++)
			{
				_formationFootTroopCounts[i] = 0;
				_formationMountedTroopCounts[i] = 0;
			}
		}

		public void AddTroops(FormationClass formationClass, int footTroopCount, int mountedTroopCount)
		{
			if (footTroopCount + mountedTroopCount > 0 && formationClass < FormationClass.NumberOfAllFormationsWithUnset)
			{
				_formationFootTroopCounts[(int)formationClass] += footTroopCount;
				_formationMountedTroopCounts[(int)formationClass] += mountedTroopCount;
			}
		}

		public DefaultFormationDeploymentPlan GetFormationPlan(FormationClass fClass)
		{
			return _formationPlans[(int)fClass];
		}

		public bool GetFormationDeploymentFrame(FormationClass fClass, out MatrixFrame frame)
		{
			DefaultFormationDeploymentPlan formationPlan = GetFormationPlan(fClass);
			if (formationPlan.HasFrame())
			{
				frame = formationPlan.GetFrame();
				return true;
			}
			frame = MatrixFrame.Identity;
			return false;
		}

		public bool GetFirstValidFormationDeploymentFrame(out MatrixFrame frame)
		{
			DefaultFormationDeploymentPlan[] formationPlans = _formationPlans;
			foreach (DefaultFormationDeploymentPlan defaultFormationDeploymentPlan in formationPlans)
			{
				if (defaultFormationDeploymentPlan.HasFrame())
				{
					frame = defaultFormationDeploymentPlan.GetFrame();
					return true;
				}
			}
			frame = MatrixFrame.Identity;
			return false;
		}

		public bool IsPlanSuitableForFormations((int, int)[] troopDataPerFormationClass)
		{
			if (troopDataPerFormationClass.Length == 11)
			{
				for (int i = 0; i < 11; i++)
				{
					FormationClass fClass = (FormationClass)i;
					DefaultFormationDeploymentPlan formationPlan = GetFormationPlan(fClass);
					(int, int) tuple = troopDataPerFormationClass[i];
					if (formationPlan.PlannedFootTroopCount != tuple.Item1 || formationPlan.PlannedMountedTroopCount != tuple.Item2)
					{
						return false;
					}
				}
				return true;
			}
			return false;
		}

		public void UpdateSafetyScore()
		{
			if (_mission.Teams == null)
			{
				return;
			}
			float num = 100f;
			Team team = ((Team.Side == BattleSideEnum.Attacker) ? _mission.Teams.Defender : ((Team.Side == BattleSideEnum.Defender) ? _mission.Teams.Attacker : null));
			if (team != null)
			{
				foreach (Formation item in team.FormationsIncludingEmpty)
				{
					if (item.CountOfUnits > 0)
					{
						float num2 = _meanPosition.AsVec2.Distance(item.CachedAveragePosition);
						if (num >= num2)
						{
							num = num2;
						}
					}
				}
			}
			team = ((Team.Side == BattleSideEnum.Attacker) ? _mission.Teams.DefenderAlly : ((Team.Side == BattleSideEnum.Defender) ? _mission.Teams.AttackerAlly : null));
			if (team != null)
			{
				foreach (Formation item2 in team.FormationsIncludingEmpty)
				{
					if (item2.CountOfUnits > 0)
					{
						float num3 = _meanPosition.AsVec2.Distance(item2.CachedAveragePosition);
						if (num >= num3)
						{
							num = num3;
						}
					}
				}
			}
			SafetyScore = num;
		}

		public WorldFrame GetFrameFromFormationSpawnEntity(GameEntity formationSpawnEntity, float depthOffset = 0f)
		{
			MatrixFrame globalFrame = formationSpawnEntity.GetGlobalFrame();
			globalFrame.rotation.OrthonormalizeAccordingToForwardAndKeepUpAsZAxis();
			WorldPosition worldPosition = new WorldPosition(_mission.Scene, UIntPtr.Zero, globalFrame.origin, hasValidZ: false);
			WorldPosition origin = worldPosition;
			if (depthOffset != 0f)
			{
				origin.SetVec2(origin.AsVec2 - depthOffset * globalFrame.rotation.f.AsVec2);
				if (!origin.IsValid || origin.GetNavMesh() == UIntPtr.Zero)
				{
					origin = worldPosition;
				}
			}
			return new WorldFrame(globalFrame.rotation, origin);
		}

		private void PlanFieldBattleDeploymentFromSpawnPath(float pathOffset, float targetOffset)
		{
			bool teamPlanHasAnyFootTroops = FootTroopCount > 0;
			for (int i = 0; i < _formationPlans.Length; i++)
			{
				FormationClass formationClass = (FormationClass)i;
				int num = _formationFootTroopCounts[i] + _formationMountedTroopCounts[i];
				if (num > 0 || (!IsReinforcement && (formationClass == FormationClass.NumberOfRegularFormations || formationClass == FormationClass.Bodyguard)))
				{
					DefaultFormationDeploymentPlan defaultFormationDeploymentPlan = _formationPlans[i];
					FormationDeploymentFlank defaultFlank = defaultFormationDeploymentPlan.GetDefaultFlank(num, teamPlanHasAnyFootTroops, _spawnWithHorses);
					int offset = ((num <= 0 && formationClass != FormationClass.NumberOfRegularFormations) ? 1 : 0);
					FormationDeploymentOrder flankDeploymentOrder = defaultFormationDeploymentPlan.GetFlankDeploymentOrder(offset);
					_deploymentFlanks[(int)defaultFlank].Add(flankDeploymentOrder, defaultFormationDeploymentPlan);
				}
			}
			float horizontalCenterOffset = ComputeHorizontalCenterOffset();
			SpawnPathData initialSpawnPathData = _mission.GetInitialSpawnPathData(Team.Side);
			Vec2 spawnPathPosition;
			Vec2 spawnPathDirection;
			if (IsReinforcement)
			{
				spawnPathPosition = SpawnPathData.GetSpawnFrame(SpawnPathData.GetBaseOffset(), searchNearestValidFrame: true, SpawnPathData.SearchDirection.Forward).origin.AsVec2;
				spawnPathDirection = (initialSpawnPathData.GetSpawnFrame(0f).origin.AsVec2 - spawnPathPosition).Normalized();
			}
			else
			{
				initialSpawnPathData.GetSpawnPathFrameFacingTarget(pathOffset, targetOffset, useTangentDirection: false, out spawnPathPosition, out spawnPathDirection, decideDirectionDynamically: true);
			}
			DeployFlanks(spawnPathPosition, spawnPathDirection, horizontalCenterOffset);
			SortedList<FormationDeploymentOrder, DefaultFormationDeploymentPlan>[] deploymentFlanks = _deploymentFlanks;
			for (int j = 0; j < deploymentFlanks.Length; j++)
			{
				deploymentFlanks[j].Clear();
			}
			IsPlanMade = true;
			_planCount++;
		}

		private void PlanFieldBattleDeploymentFromSceneData(FormationSceneSpawnEntry[,] formationSceneSpawnEntries)
		{
			if (formationSceneSpawnEntries == null || formationSceneSpawnEntries.GetLength(0) != 2 || formationSceneSpawnEntries.GetLength(1) != _formationPlans.Length)
			{
				return;
			}
			int side = (int)Team.Side;
			int num = ((Team.Side != BattleSideEnum.Attacker) ? 1 : 0);
			Dictionary<GameEntity, float> spawnDepths = new Dictionary<GameEntity, float>();
			bool flag = !IsReinforcement;
			for (int i = 0; i < _formationPlans.Length; i++)
			{
				DefaultFormationDeploymentPlan defaultFormationDeploymentPlan = _formationPlans[i];
				FormationSceneSpawnEntry formationSceneSpawnEntry = formationSceneSpawnEntries[side, i];
				FormationSceneSpawnEntry formationSceneSpawnEntry2 = formationSceneSpawnEntries[num, i];
				GameEntity gameEntity = (flag ? formationSceneSpawnEntry.SpawnEntity : formationSceneSpawnEntry.ReinforcementSpawnEntity);
				GameEntity gameEntity2 = (flag ? formationSceneSpawnEntry2.SpawnEntity : formationSceneSpawnEntry2.ReinforcementSpawnEntity);
				if (gameEntity != null && gameEntity2 != null)
				{
					WorldFrame frame = ComputeFieldBattleDeploymentFrameForFormation(defaultFormationDeploymentPlan, gameEntity, gameEntity2, ref spawnDepths);
					defaultFormationDeploymentPlan.SetFrame(in frame);
				}
				else
				{
					defaultFormationDeploymentPlan.SetFrame(in WorldFrame.Invalid);
				}
				defaultFormationDeploymentPlan.SetSpawnClass(formationSceneSpawnEntry.FormationClass);
			}
			IsPlanMade = true;
			_planCount++;
		}

		private void PlanBattleDeploymentFromSceneData(FormationSceneSpawnEntry[,] formationSceneSpawnEntries)
		{
			if (formationSceneSpawnEntries == null || formationSceneSpawnEntries.GetLength(0) != 2 || formationSceneSpawnEntries.GetLength(1) != _formationPlans.Length)
			{
				return;
			}
			int side = (int)Team.Side;
			Dictionary<GameEntity, float> spawnDepths = new Dictionary<GameEntity, float>();
			bool flag = !IsReinforcement;
			for (int i = 0; i < _formationPlans.Length; i++)
			{
				DefaultFormationDeploymentPlan defaultFormationDeploymentPlan = _formationPlans[i];
				FormationSceneSpawnEntry formationSceneSpawnEntry = formationSceneSpawnEntries[side, i];
				GameEntity gameEntity = (flag ? formationSceneSpawnEntry.SpawnEntity : formationSceneSpawnEntry.ReinforcementSpawnEntity);
				if (gameEntity != null)
				{
					float andUpdateSpawnDepth = GetAndUpdateSpawnDepth(ref spawnDepths, gameEntity, defaultFormationDeploymentPlan);
					WorldFrame frame = GetFrameFromFormationSpawnEntity(gameEntity, andUpdateSpawnDepth);
					defaultFormationDeploymentPlan.SetFrame(in frame);
				}
				else
				{
					defaultFormationDeploymentPlan.SetFrame(in WorldFrame.Invalid);
				}
				defaultFormationDeploymentPlan.SetSpawnClass(formationSceneSpawnEntry.FormationClass);
			}
			IsPlanMade = true;
			_planCount++;
		}

		private void PlanFormationDimensions()
		{
			for (int i = 0; i < _formationPlans.Length; i++)
			{
				int num = _formationFootTroopCounts[i];
				int num2 = _formationMountedTroopCounts[i];
				int num3 = num + num2;
				DefaultFormationDeploymentPlan defaultFormationDeploymentPlan = _formationPlans[i];
				if (num3 > 0)
				{
					bool hasMountedTroops = DefaultMissionDeploymentPlan.HasSignificantMountedTroops(num, num2);
					var (width, depth) = GetFormationSpawnWidthAndDepth(defaultFormationDeploymentPlan.Class, num3, hasMountedTroops, !_spawnWithHorses);
					defaultFormationDeploymentPlan.SetPlannedDimensions(width, depth);
					defaultFormationDeploymentPlan.SetPlannedTroopCount(num, num2);
				}
			}
		}

		private void DeployFlanks(Vec2 deployPosition, Vec2 deployDirection, float horizontalCenterOffset)
		{
			(float flankWidth, float flankDepth) tuple = PlanFlankDeployment(FormationDeploymentFlank.Front, deployPosition, deployDirection, 0f, horizontalCenterOffset);
			float item = tuple.flankWidth;
			float item2 = tuple.flankDepth;
			item2 += 3f;
			float item3 = PlanFlankDeployment(FormationDeploymentFlank.Rear, deployPosition, deployDirection, item2, horizontalCenterOffset).flankWidth;
			float num = TaleWorlds.Library.MathF.Max(item, item3);
			float num2 = ComputeFlankDepth(FormationDeploymentFlank.Front, countPositiveNumTroops: true);
			num2 += 3f;
			float num3 = ComputeFlankWidth(FormationDeploymentFlank.Left);
			float horizontalOffset = horizontalCenterOffset + 2f + 0.5f * (num + num3);
			PlanFlankDeployment(FormationDeploymentFlank.Left, deployPosition, deployDirection, num2, horizontalOffset);
			float num4 = ComputeFlankWidth(FormationDeploymentFlank.Right);
			float horizontalOffset2 = horizontalCenterOffset - (2f + 0.5f * (num + num4));
			PlanFlankDeployment(FormationDeploymentFlank.Right, deployPosition, deployDirection, num2, horizontalOffset2);
		}

		private void ComputeMeanPosition()
		{
			_meanPosition = Vec3.Zero;
			Vec2 zero = Vec2.Zero;
			int num = 0;
			DefaultFormationDeploymentPlan[] formationPlans = _formationPlans;
			foreach (DefaultFormationDeploymentPlan defaultFormationDeploymentPlan in formationPlans)
			{
				if (defaultFormationDeploymentPlan.HasFrame())
				{
					zero += defaultFormationDeploymentPlan.GetPosition().AsVec2;
					num++;
				}
			}
			if (num > 0)
			{
				zero = new Vec2(zero.X / (float)num, zero.Y / (float)num);
				float height = 0f;
				Mission.Current.Scene.GetHeightAtPoint(zero, BodyFlags.None, ref height);
				_meanPosition = new Vec3(zero, height);
			}
		}

		private (float flankWidth, float flankDepth) PlanFlankDeployment(FormationDeploymentFlank flankFlank, Vec2 deployPosition, Vec2 deployDirection, float verticalOffset = 0f, float horizontalOffset = 0f)
		{
			Mat3 identity = Mat3.Identity;
			identity.RotateAboutUp(deployDirection.RotationInRadians);
			float num = 0f;
			float num2 = 0f;
			Vec2 vec = deployDirection.LeftVec();
			WorldPosition position = new WorldPosition(_mission.Scene, UIntPtr.Zero, deployPosition.ToVec3(), hasValidZ: false);
			foreach (KeyValuePair<FormationDeploymentOrder, DefaultFormationDeploymentPlan> item in _deploymentFlanks[(int)flankFlank])
			{
				DefaultFormationDeploymentPlan value = item.Value;
				Vec2 destination = position.AsVec2 - (num2 + verticalOffset) * deployDirection + horizontalOffset * vec;
				Vec3 lastPointOnNavigationMeshFromWorldPositionToDestination = _mission.Scene.GetLastPointOnNavigationMeshFromWorldPositionToDestination(ref position, destination);
				WorldFrame frame = new WorldFrame(origin: new WorldPosition(_mission.Scene, UIntPtr.Zero, lastPointOnNavigationMeshFromWorldPositionToDestination, hasValidZ: false), rotation: identity);
				value.SetFrame(in frame);
				float num3 = value.PlannedDepth + 3f;
				num2 += num3;
				num = TaleWorlds.Library.MathF.Max(num, value.PlannedWidth);
			}
			num2 = TaleWorlds.Library.MathF.Max(num2 - 3f, 0f);
			return (flankWidth: num, flankDepth: num2);
		}

		private WorldFrame ComputeFieldBattleDeploymentFrameForFormation(DefaultFormationDeploymentPlan formationPlan, GameEntity formationSceneEntity, GameEntity counterSideFormationSceneEntity, ref Dictionary<GameEntity, float> spawnDepths)
		{
			Vec3 globalPosition = formationSceneEntity.GlobalPosition;
			Vec2 asVec = (counterSideFormationSceneEntity.GlobalPosition - globalPosition).AsVec2;
			asVec.Normalize();
			float andUpdateSpawnDepth = GetAndUpdateSpawnDepth(ref spawnDepths, formationSceneEntity, formationPlan);
			WorldPosition origin = new WorldPosition(_mission.Scene, UIntPtr.Zero, globalPosition, hasValidZ: false);
			origin.SetVec2(origin.AsVec2 - andUpdateSpawnDepth * asVec);
			Mat3 identity = Mat3.Identity;
			identity.RotateAboutUp(asVec.RotationInRadians);
			return new WorldFrame(identity, origin);
		}

		private float ComputeFlankWidth(FormationDeploymentFlank flank)
		{
			float num = 0f;
			foreach (KeyValuePair<FormationDeploymentOrder, DefaultFormationDeploymentPlan> item in _deploymentFlanks[(int)flank])
			{
				num = TaleWorlds.Library.MathF.Max(num, item.Value.PlannedWidth);
			}
			return num;
		}

		private float ComputeFlankDepth(FormationDeploymentFlank flank, bool countPositiveNumTroops = false)
		{
			float num = 0f;
			foreach (KeyValuePair<FormationDeploymentOrder, DefaultFormationDeploymentPlan> item in _deploymentFlanks[(int)flank])
			{
				if (!countPositiveNumTroops)
				{
					num += item.Value.PlannedDepth + 3f;
				}
				else if (item.Value.PlannedTroopCount > 0)
				{
					num += item.Value.PlannedDepth + 3f;
				}
			}
			return num - 3f;
		}

		private float ComputeHorizontalCenterOffset()
		{
			float num = TaleWorlds.Library.MathF.Max(ComputeFlankWidth(FormationDeploymentFlank.Front), ComputeFlankWidth(FormationDeploymentFlank.Rear));
			float num2 = ComputeFlankWidth(FormationDeploymentFlank.Left);
			float num3 = ComputeFlankWidth(FormationDeploymentFlank.Right);
			float num4 = num / 2f + num2 + 2f;
			return (num / 2f + num3 + 2f - num4) / 2f;
		}

		private float GetAndUpdateSpawnDepth(ref Dictionary<GameEntity, float> spawnDepths, GameEntity spawnEntity, DefaultFormationDeploymentPlan formationPlan)
		{
			float value;
			bool num = spawnDepths.TryGetValue(spawnEntity, out value);
			float num2 = (formationPlan.HasDimensions ? (formationPlan.PlannedDepth + 3f) : 0f);
			if (!num)
			{
				value = 0f;
				spawnDepths[spawnEntity] = num2;
			}
			else if (formationPlan.HasDimensions)
			{
				spawnDepths[spawnEntity] = value + num2;
			}
			return value;
		}

		public static (float, float) GetFormationSpawnWidthAndDepth(FormationClass formationNo, int troopCount, bool hasMountedTroops, bool considerCavalryAsInfantry = false)
		{
			bool flag = !considerCavalryAsInfantry && hasMountedTroops;
			float defaultUnitDiameter = Formation.GetDefaultUnitDiameter(flag);
			int unitSpacingOf = ArrangementOrder.GetUnitSpacingOf(ArrangementOrder.ArrangementOrderEnum.Line);
			float num = (flag ? Formation.CavalryInterval(unitSpacingOf) : Formation.InfantryInterval(unitSpacingOf));
			float num2 = (flag ? Formation.CavalryDistance(unitSpacingOf) : Formation.InfantryDistance(unitSpacingOf));
			float num3 = (float)TaleWorlds.Library.MathF.Max(0, troopCount - 1) * (num + defaultUnitDiameter) + defaultUnitDiameter;
			float num4 = (flag ? 18f : 9f);
			int b = (int)(num3 / TaleWorlds.Library.MathF.Sqrt(num4 * (float)troopCount + 1f));
			b = TaleWorlds.Library.MathF.Max(1, b);
			float num5 = (float)troopCount / (float)b;
			float item = TaleWorlds.Library.MathF.Max(0f, num5 - 1f) * (num + defaultUnitDiameter) + defaultUnitDiameter;
			float item2 = (float)(b - 1) * (num2 + defaultUnitDiameter) + defaultUnitDiameter;
			return (item, item2);
		}
	}
	public class DefaultFormationDeploymentPlan : IFormationDeploymentPlan
	{
		private WorldFrame _spawnFrame;

		private FormationClass _spawnClass;

		private readonly FormationClass _class;

		private float _plannedWidth;

		private float _plannedDepth;

		private int _plannedFootTroopCount;

		private int _plannedMountedTroopCount;

		public FormationClass Class => _class;

		public FormationClass SpawnClass => _spawnClass;

		public float PlannedWidth => _plannedWidth;

		public float PlannedDepth => _plannedDepth;

		public int PlannedTroopCount => _plannedFootTroopCount + _plannedMountedTroopCount;

		public int PlannedFootTroopCount => _plannedFootTroopCount;

		public int PlannedMountedTroopCount => _plannedMountedTroopCount;

		public bool HasDimensions
		{
			get
			{
				if (_plannedWidth >= 1E-05f)
				{
					return _plannedDepth >= 1E-05f;
				}
				return false;
			}
		}

		public bool HasSignificantMountedTroops => DefaultMissionDeploymentPlan.HasSignificantMountedTroops(_plannedFootTroopCount, _plannedMountedTroopCount);

		public DefaultFormationDeploymentPlan(FormationClass fClass)
		{
			_class = fClass;
			_spawnClass = fClass;
			Clear();
		}

		public bool HasFrame()
		{
			return _spawnFrame.IsValid;
		}

		public FormationDeploymentFlank GetDefaultFlank(int formationTroopCount, bool teamPlanHasAnyFootTroops, bool spawnWithHorses = false)
		{
			return GetFormationDefaultFlankAux(_class, formationTroopCount, teamPlanHasAnyFootTroops, HasSignificantMountedTroops, spawnWithHorses);
		}

		public FormationDeploymentOrder GetFlankDeploymentOrder(int offset = 0)
		{
			return FormationDeploymentOrder.GetDeploymentOrder(_class, offset);
		}

		public MatrixFrame GetFrame()
		{
			return _spawnFrame.ToGroundMatrixFrame();
		}

		public Vec3 GetPosition()
		{
			return _spawnFrame.Origin.GetGroundVec3();
		}

		public Vec2 GetDirection()
		{
			return _spawnFrame.Rotation.f.AsVec2.Normalized();
		}

		public WorldPosition CreateNewDeploymentWorldPosition(WorldPosition.WorldPositionEnforcedCache worldPositionEnforcedCache)
		{
			return worldPositionEnforcedCache switch
			{
				WorldPosition.WorldPositionEnforcedCache.NavMeshVec3 => new WorldPosition(Mission.Current.Scene, UIntPtr.Zero, _spawnFrame.Origin.GetNavMeshVec3(), hasValidZ: false), 
				WorldPosition.WorldPositionEnforcedCache.GroundVec3 => new WorldPosition(Mission.Current.Scene, UIntPtr.Zero, _spawnFrame.Origin.GetGroundVec3(), hasValidZ: false), 
				_ => _spawnFrame.Origin, 
			};
		}

		public void Clear()
		{
			_plannedWidth = 0f;
			_plannedDepth = 0f;
			_plannedFootTroopCount = 0;
			_plannedMountedTroopCount = 0;
			_spawnFrame = WorldFrame.Invalid;
		}

		public void SetPlannedTroopCount(int footTroopCount, int mountedTroopCount)
		{
			_plannedFootTroopCount = footTroopCount;
			_plannedMountedTroopCount = mountedTroopCount;
		}

		public void SetPlannedDimensions(float width, float depth)
		{
			_plannedWidth = TaleWorlds.Library.MathF.Max(0f, width);
			_plannedDepth = TaleWorlds.Library.MathF.Max(0f, depth);
		}

		public void SetFrame(in WorldFrame frame)
		{
			_spawnFrame = frame;
		}

		public void SetSpawnClass(FormationClass spawnClass)
		{
			_spawnClass = spawnClass;
		}

		public static FormationDeploymentFlank GetFormationDefaultFlankAux(FormationClass formationClass, int formationTroopCount, bool teamPlanHasAnyFootTroops, bool hasSignificantMountedTroops, bool canSpawnWithHorses)
		{
			FormationDeploymentFlank formationDeploymentFlank = FormationDeploymentFlank.Count;
			if (!formationClass.IsMounted() && formationTroopCount == 0)
			{
				return FormationDeploymentFlank.Rear;
			}
			if (hasSignificantMountedTroops && (!canSpawnWithHorses || !teamPlanHasAnyFootTroops))
			{
				if (formationTroopCount == 0 || formationClass == FormationClass.LightCavalry || formationClass == FormationClass.HorseArcher)
				{
					return FormationDeploymentFlank.Rear;
				}
				return FormationDeploymentFlank.Front;
			}
			switch (formationClass)
			{
			case FormationClass.Cavalry:
			case FormationClass.HeavyCavalry:
				return FormationDeploymentFlank.Left;
			case FormationClass.HorseArcher:
			case FormationClass.LightCavalry:
				return FormationDeploymentFlank.Right;
			case FormationClass.Ranged:
			case FormationClass.NumberOfRegularFormations:
			case FormationClass.Bodyguard:
			case FormationClass.NumberOfAllFormations:
				return FormationDeploymentFlank.Rear;
			default:
				return FormationDeploymentFlank.Front;
			}
		}
	}
	public class DefaultMissionDeploymentPlan : IMissionDeploymentPlan
	{
		private readonly Mission _mission;

		private readonly MBList<(Team team, DefaultTeamDeploymentPlan plan)> _teamDeploymentPlans = new MBList<(Team, DefaultTeamDeploymentPlan)>();

		private readonly WorldFrame?[] _playerSpawnFrames = new WorldFrame?[2];

		private FormationSceneSpawnEntry[,] _formationSceneSpawnEntries;

		public DefaultMissionDeploymentPlan(Mission mission)
		{
			_mission = mission;
		}

		public void Initialize()
		{
			foreach (Team team in _mission.Teams)
			{
				if (team.Side != BattleSideEnum.None)
				{
					DefaultTeamDeploymentPlan item = new DefaultTeamDeploymentPlan(_mission, team);
					_teamDeploymentPlans.Add((team, item));
				}
			}
			for (int i = 0; i < 2; i++)
			{
				_playerSpawnFrames[i] = null;
			}
		}

		public void ClearDeploymentPlan(Team team)
		{
			GetTeamPlan(team).ClearPlan();
		}

		public void ClearReinforcementPlan(Team team)
		{
			GetTeamPlan(team).ClearPlan(isReinforcement: true);
		}

		public bool HasPlayerSpawnFrame(BattleSideEnum battleSide)
		{
			return _playerSpawnFrames[(int)battleSide].HasValue;
		}

		public bool GetPlayerSpawnFrame(BattleSideEnum battleSide, out WorldPosition position, out Vec2 direction)
		{
			WorldFrame? worldFrame = _playerSpawnFrames[(int)battleSide];
			if (worldFrame.HasValue)
			{
				position = new WorldPosition(Mission.Current.Scene, UIntPtr.Zero, worldFrame.Value.Origin.GetGroundVec3(), hasValidZ: false);
				direction = worldFrame.Value.Rotation.f.AsVec2.Normalized();
				return true;
			}
			position = WorldPosition.Invalid;
			direction = Vec2.Invalid;
			return false;
		}

		public static bool HasSignificantMountedTroops(int footTroopCount, int mountedTroopCount)
		{
			return (float)mountedTroopCount / Math.Max(mountedTroopCount + footTroopCount, 1f) >= 0.1f;
		}

		public void ClearAddedTroops(Team team, bool isReinforcement = false)
		{
			GetTeamPlan(team).ClearAddedTroops(isReinforcement);
		}

		public void ClearAll()
		{
			foreach (var teamDeploymentPlan in _teamDeploymentPlans)
			{
				DefaultTeamDeploymentPlan item = teamDeploymentPlan.plan;
				item.ClearAddedTroops();
				item.ClearPlan();
				item.ClearAddedTroops(isReinforcement: true);
				item.ClearPlan(isReinforcement: true);
			}
		}

		public void AddTroops(Team team, FormationClass formationClass, int footTroopCount, int mountedTroopCount = 0, bool isReinforcement = false)
		{
			_ = team.Side;
			GetTeamPlan(team).AddTroops(formationClass, footTroopCount, mountedTroopCount, isReinforcement);
		}

		public void SetSpawnWithHorses(Team team, bool spawnWithHorses)
		{
			GetTeamPlan(team).SetSpawnWithHorses(spawnWithHorses);
		}

		public void MakeDefaultDeploymentPlans()
		{
			foreach (var teamDeploymentPlan in _teamDeploymentPlans)
			{
				Team item = teamDeploymentPlan.team;
				MakeDeploymentPlan(item);
				MakeReinforcementDeploymentPlan(item);
			}
		}

		public void MakeDeploymentPlan(Team team, float spawnPathOffset = 0f, float targetOffset = 0f)
		{
			if (!IsPlanMade(team))
			{
				MakeDeploymentPlanAux(team, isReinforcement: false, spawnPathOffset, targetOffset);
				if (IsPlanMade(team, out var isFirstPlan))
				{
					_mission.OnDeploymentPlanMade(team, isFirstPlan);
				}
			}
		}

		public void MakeReinforcementDeploymentPlan(Team team)
		{
			if (!IsReinforcementPlanMade(team))
			{
				MakeDeploymentPlanAux(team, isReinforcement: true);
			}
		}

		public bool RemakeDeploymentPlan(Team team)
		{
			IsPlanMade(team);
			float spawnPathOffset = GetSpawnPathOffset(team);
			float targetOffset = GetTargetOffset(team);
			(int, int)[] array = new(int, int)[11];
			foreach (Agent item in _mission.AllAgents.Where((Agent agent) => agent.IsHuman && agent.Team != null && agent.Team == team && agent.Formation != null))
			{
				int formationIndex = (int)item.Formation.FormationIndex;
				(int, int) tuple = array[formationIndex];
				array[formationIndex] = (item.HasMount ? (tuple.Item1, tuple.Item2 + 1) : (tuple.Item1 + 1, tuple.Item2));
			}
			if (!IsInitialPlanSuitableForFormations(team, array))
			{
				ClearAddedTroops(team);
				ClearDeploymentPlan(team);
				for (int i = 0; i < 11; i++)
				{
					var (num, num2) = array[i];
					if (num + num2 > 0)
					{
						AddTroops(team, (FormationClass)i, num, num2);
					}
				}
				MakeDeploymentPlan(team, spawnPathOffset, targetOffset);
				return IsPlanMade(team);
			}
			return false;
		}

