			List<IFormationUnit> list = ((num == 0) ? new List<IFormationUnit>() : Arrangement.GetUnitsToPop(num, targetPosition));
			int num2 = count - list.Count;
			if (num2 > 0)
			{
				List<Agent> list2 = _looseDetachedUnits.Take(num2).ToList();
				num2 -= list2.Count;
				list.AddRange(list2);
