		public Vec3 RagdollImpulseLocalPoint;

		public Vec3 RagdollImpulseAmount;

		public int DeathAction;

		public DamageTypes DamageType;

		public AgentAttackType AttackType;

		public int OwnerId;

		public BoneBodyPartType VictimBodyPart;

		public int WeaponClass;

		public Agent.KillInfo OverrideKillInfo;

		public Vec3 BlowPosition;

		public WeaponFlags WeaponRecordWeaponFlags;

		public int WeaponItemKind;

		public int InflictedDamage;

		[MarshalAs(UnmanagedType.U1)]
		public bool IsMissile;

		[MarshalAs(UnmanagedType.U1)]
		public bool IsValid;

		public KillingBlow(Blow b, Vec3 ragdollImpulsePoint, Vec3 ragdollImpulseAmount, int deathAction, int weaponItemKind, Agent.KillInfo overrideKillInfo = Agent.KillInfo.Invalid)
		{
			RagdollImpulseLocalPoint = ragdollImpulsePoint;
			RagdollImpulseAmount = ragdollImpulseAmount;
			DeathAction = deathAction;
			OverrideKillInfo = overrideKillInfo;
			DamageType = b.DamageType;
			AttackType = b.AttackType;
			OwnerId = b.OwnerId;
			VictimBodyPart = b.VictimBodyPart;
			WeaponClass = (int)b.WeaponRecord.WeaponClass;
			BlowPosition = b.GlobalPosition;
			WeaponRecordWeaponFlags = b.WeaponRecord.WeaponFlags;
			WeaponItemKind = weaponItemKind;
			InflictedDamage = b.InflictedDamage;
			IsMissile = b.IsMissile;
			IsValid = true;
		}

		public bool IsHeadShot()
		{
			return VictimBodyPart == BoneBodyPartType.Head;
		}
	}
	public class CoreManaged : IManagedComponent
	{
		private static CoreManaged _instance;

		private static ICallbackManager _callbackManager;

		private static readonly Dictionary<int, IntPtr> _engineApiPointers = new Dictionary<int, IntPtr>();

		private static Delegate _passManagedCoreCallbackMethodPointersMono = null;

		public string ManagedCallbacksDll => ManagedDllFolder.Name + "TaleWorlds.MountAndBlade.AutoGenerated.dll";

		public CoreManaged()
		{
			_instance = this;
		}

		[MBCallback(null, false)]
		public static void Start()
		{
			Managed.Start(new IManagedComponent[0]);
		}

		void IManagedComponent.OnStart()
		{
			TaleWorlds.Library.Debug.DebugManager = new MBDebugManager();
			Dictionary<string, Type> dictionary = new Dictionary<string, Type>();
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly moduleAssembly in assemblies)
			{
				Dictionary<string, Type> second = CollectModuleAssemblyTypes(moduleAssembly);
				dictionary = dictionary.Union(second).ToDictionary((KeyValuePair<string, Type> k) => k.Key, (KeyValuePair<string, Type> v) => v.Value);
			}
			Managed.InitializeTypes(dictionary);
		}

		private Dictionary<string, Type> CollectModuleAssemblyTypes(Assembly moduleAssembly)
		{
			Dictionary<string, Type> dictionary = new Dictionary<string, Type>();
			try
			{
				Type[] types = moduleAssembly.GetTypes();
				foreach (Type type in types)
				{
					if (typeof(ManagedObject).IsAssignableFrom(type) || typeof(DotNetObject).IsAssignableFrom(type))
					{
						dictionary.Add(type.Name, type);
					}
				}
			}
			catch (Exception)
			{
				dictionary.Clear();
			}
			return dictionary;
		}

		[MBCallback(null, false)]
		internal static void OnLoadCommonFinished()
		{
			FaceGen.CreateInstance();
		}

		private void OnInitialize()
		{
			List<Type> typesSafe = AssemblyLoader.LoadFrom(ManagedCallbacksDll).GetTypesSafe();
			Type type = null;
			foreach (Type item in typesSafe)
			{
				if (item.GetInterfaces().Contains<Type>(typeof(ICallbackManager)))
				{
					type = item;
					break;
				}
			}
			_callbackManager = type.GetConstructor(new Type[0]).Invoke(new object[0]) as ICallbackManager;
			_callbackManager.Initialize();
			Delegate[] delegates = _callbackManager.GetDelegates();
			for (int i = 0; i < delegates.Length; i++)
			{
				try
				{
					PassManagedCoreCallbackMethodPointers(delegates[i]);
				}
				catch (Exception ex)
				{
					PassManagedCoreCallbackMethodPointers(null);
					Console.WriteLine(string.Concat(ex, " ", i));
				}
			}
			MBAPI.SetObjects(_callbackManager.GetScriptingInterfaceObjects());
			Module.CreateModule();
		}

		void IManagedComponent.OnCustomCallbackMethodPassed(string name, Delegate method)
		{
			if (name == "MBCore")
			{
				_passManagedCoreCallbackMethodPointersMono = method;
				OnInitialize();
			}
		}

		[MBCallback(null, false)]
		internal static void Finalize()
		{
			Module.FinalizeCurrentModule();
			Common.MemoryCleanupGC();
		}

		void IManagedComponent.OnApplicationTick(float dt)
		{
			Module.CurrentModule.OnApplicationTick(dt);
		}

		[MBCallback(null, false)]
		internal static void CheckSharedStructureSizes()
		{
			_callbackManager.CheckSharedStructureSizes();
		}

		[MBCallback(null, false)]
		internal static void EngineApiMethodInterfaceInitializer(int id, IntPtr pointer)
		{
			_engineApiPointers.Add(id, pointer);
		}

		[MBCallback(null, false)]
		internal static void FillEngineApiPointers()
		{
			foreach (KeyValuePair<int, IntPtr> engineApiPointer in _engineApiPointers)
			{
				try
				{
					_callbackManager.SetFunctionPointer(engineApiPointer.Key, engineApiPointer.Value);
				}
				catch (Exception ex)
				{
					Console.WriteLine("error: " + engineApiPointer.Key + " " + ex);
				}
			}
		}

		private static void PassManagedCoreCallbackMethodPointers(Delegate methodDelegate)
		{
			_passManagedCoreCallbackMethodPointersMono?.DynamicInvoke(methodDelegate);
		}
	}
	public static class MBSceneUtilities
	{
		public const int MaxNumberOfSpawnPaths = 32;

		public const string SpawnPathPrefix = "spawn_path_";

		public const string SoftBorderVertexTag = "walk_area_vertex";

		public const string HardBorderVertexTag = "walk_area_vertex_hard";

		public const string SoftBoundaryName = "walk_area";

		public const string SceneBoundaryName = "scene_boundary";

		public const float SceneToHardBoundaryMargin = 100f;

		public const string DefenderDeploymentReferencePositionTag = "defender_infantry";

		public const string AttackerDeploymentReferencePositionTag = "attacker_infantry";

		private const string DeploymentBoundaryTag = "deployment_castle_boundary";

		private const string DeploymentBoundaryTagExpression = "deployment_castle_boundary(_\\d+)*";

		public static MBList<TaleWorlds.Engine.Path> GetAllSpawnPaths(Scene scene)
		{
			MBList<TaleWorlds.Engine.Path> mBList = new MBList<TaleWorlds.Engine.Path>();
			for (int i = 0; i < 32; i++)
			{
				string name = "spawn_path_" + i.ToString("D2");
				TaleWorlds.Engine.Path pathWithName = scene.GetPathWithName(name);
				if (pathWithName != null && pathWithName.NumberOfPoints > 1)
				{
					mBList.Add(pathWithName);
				}
			}
			return mBList;
		}

		public static MBList<Vec2> GetSoftBoundaryPoints(Scene scene)
		{
			MBList<Vec2> mBList = new MBList<Vec2>();
			int softBoundaryVertexCount = scene.GetSoftBoundaryVertexCount();
			if (softBoundaryVertexCount > 2)
			{
				for (int i = 0; i < softBoundaryVertexCount; i++)
				{
					Vec2 softBoundaryVertex = scene.GetSoftBoundaryVertex(i);
					mBList.Add(softBoundaryVertex);
				}
			}
			return mBList;
		}

		public static MBList<Vec2> GetHardBoundaryPoints(Scene scene)
		{
			MBList<Vec2> mBList = new MBList<Vec2>();
			int hardBoundaryVertexCount = scene.GetHardBoundaryVertexCount();
			for (int i = 0; i < hardBoundaryVertexCount; i++)
			{
				Vec2 hardBoundaryVertex = scene.GetHardBoundaryVertex(i);
				mBList.Add(hardBoundaryVertex);
			}
			return mBList;
		}

		public static MBList<Vec2> GetSceneLimitPoints(Scene scene, out Vec2 sceneLimitMin, out Vec2 sceneLimitMax)
		{
			MBList<Vec2> mBList = new MBList<Vec2>();
			scene.GetSceneLimits(out var min, out var max);
			mBList.Add(new Vec2(min.x, min.y));
			mBList.Add(new Vec2(max.x, min.y));
			mBList.Add(new Vec2(max.x, max.y));
			mBList.Add(new Vec2(min.x, max.y));
			sceneLimitMin = min.AsVec2;
			sceneLimitMax = max.AsVec2;
			return mBList;
		}

		public static MBList<(string tag, MBList<Vec2> boundaryPoints, bool insideAllowance)> GetDeploymentBoundaries(BattleSideEnum battleSide)
		{
			IEnumerable<GameEntity> enumerable = Mission.Current.Scene.FindEntitiesWithTagExpression("deployment_castle_boundary(_\\d+)*");
			List<(string, List<GameEntity>)> list = new List<(string, List<GameEntity>)>();
			foreach (GameEntity item4 in enumerable)
			{
				if (!item4.HasTag(battleSide.ToString()))
				{
					continue;
				}
				string[] tags = item4.Tags;
				foreach (string tag in tags)
				{
					if (tag.Contains("deployment_castle_boundary"))
					{
						(string, List<GameEntity>) item = list.FirstOrDefault<(string, List<GameEntity>)>(((string tag, List<GameEntity> boundaryEntities) tuple) => tuple.tag.Equals(tag));
						if (item.Item1 == null)
						{
							item = (tag, new List<GameEntity>());
							list.Add(item);
						}
						item.Item2.Add(item4);
						break;
					}
				}
			}
			MBList<(string, MBList<Vec2>, bool)> mBList = new MBList<(string, MBList<Vec2>, bool)>();
			foreach (var item5 in list)
			{
				string item2 = item5.Item1;
				bool item3 = !item5.Item2.Any((GameEntity e) => e.HasTag("out"));
				MBList<Vec2> boundary = item5.Item2.Select((GameEntity bp) => bp.GlobalPosition.AsVec2).ToMBList();
				RadialSortBoundary(ref boundary);
				mBList.Add((item2, boundary, item3));
			}
			return mBList;
		}

		public static void GetAxisAlignedBoundaryRectangle(List<Vec2> boundaryPoints, out Vec2 boundsMin, out Vec2 boundsMax)
		{
			boundsMin = new Vec2(float.MaxValue, float.MaxValue);
			boundsMax = new Vec2(float.MinValue, float.MinValue);
			for (int i = 0; i < boundaryPoints.Count; i++)
			{
				Vec2 vec = boundaryPoints[i];
				if (vec.x < boundsMin.X)
				{
					boundsMin.x = vec.x;
				}
				if (vec.y < boundsMin.Y)
				{
					boundsMin.y = vec.y;
				}
				if (vec.x > boundsMax.X)
				{
					boundsMax.x = vec.x;
				}
				if (vec.y > boundsMax.Y)
				{
					boundsMax.y = vec.y;
				}
			}
		}

		public static void FindConvexHull(ref MBList<Vec2> boundary)
		{
			Vec2[] array = boundary.ToArray();
			int convexPointCount = 0;
			MBAPI.IMBMission.FindConvexHull(array, boundary.Count, ref convexPointCount);
			boundary = array.ToMBList();
			boundary.RemoveRange(convexPointCount, boundary.Count - convexPointCount);
		}

		public static void RadialSortBoundary(ref MBList<Vec2> boundary)
		{
			if (boundary.Count == 0)
			{
				return;
			}
			Vec2 boundaryCenter = Vec2.Zero;
			foreach (Vec2 item in boundary)
			{
				boundaryCenter += item;
			}
			boundaryCenter.x /= boundary.Count;
			boundaryCenter.y /= boundary.Count;
			boundary = boundary.OrderBy((Vec2 b) => (b - boundaryCenter).RotationInRadians).ToMBList();
		}

		public static void RadialSortBoundary(ref MBList<Vec3> boundary)
		{
			if (boundary.Count == 0)
			{
				return;
			}
			Vec2 boundaryCenter = Vec2.Zero;
			foreach (Vec3 item in boundary)
			{
				boundaryCenter += item.AsVec2;
			}
			boundaryCenter.x /= boundary.Count;
			boundaryCenter.y /= boundary.Count;
			boundary = boundary.OrderBy((Vec3 b) => (b.AsVec2 - boundaryCenter).RotationInRadians).ToMBList();
		}

		public static bool IsConvexAndRadiallySorted(MBList<Vec2> boundary)
		{
			int count = boundary.Count;
			if (count < 3)
			{
				return false;
			}
			Vec2 vec = new Vec2(0f, 0f);
			foreach (Vec2 item in boundary)
			{
				vec += item;
			}
			vec /= (float)count;
			Vec2 vec2 = (boundary[0] - vec).Normalized();
			vec2.RotateCCW(-0.001f);
			Vec2 vec3 = vec2;
			for (int i = 0; i < count; i++)
			{
				Vec2 vec4 = boundary[i];
				vec2 = (vec4 - vec).Normalized();
				if (vec3.AngleBetween(vec2) <= 0f)
				{
					return false;
				}
				vec3 = vec2;
				Vec2 vec5 = boundary[(i + 1) % count];
				Vec2 vec6 = boundary[(i + 2) % count];
				Vec2 vec7 = vec5 - vec4;
				Vec2 vec8 = vec6 - vec4;
				if (Vec2.Determinant(in vec7, in vec8) < 0f)
				{
					return false;
				}
			}
			return true;
		}

		public static bool IsPointInsideBoundaries(in Vec2 point, MBList<Vec2> boundaries, float acceptanceThreshold = 0.05f)
		{
			if (boundaries.Count <= 2)
			{
				return false;
			}
			acceptanceThreshold = TaleWorlds.Library.MathF.Max(0f, acceptanceThreshold);
			bool result = true;
			for (int i = 0; i < boundaries.Count; i++)
			{
				Vec2 vec = boundaries[i];
				Vec2 vec2 = boundaries[(i + 1) % boundaries.Count] - vec;
				Vec2 vec3 = point - vec;
				if (vec2.x * vec3.y - vec2.y * vec3.x < 0f)
				{
					vec2.Normalize();
					Vec2 vec4 = vec3.DotProduct(vec2) * vec2;
					if ((vec3 - vec4).LengthSquared > acceptanceThreshold * acceptanceThreshold)
					{
						result = false;
						break;
					}
				}
			}
			return result;
		}

		public static float FindClosestPointToBoundaries(in Vec2 position, MBList<Vec2> boundaries, out Vec2 closestPoint)
		{
			closestPoint = position;
			float num = float.MaxValue;
			for (int i = 0; i < boundaries.Count; i++)
			{
				Vec2 lineSegmentBegin = boundaries[i];
				Vec2 lineSegmentEnd = boundaries[(i + 1) % boundaries.Count];
				Vec2 closestPointOnLineSegmentToPoint = MBMath.GetClosestPointOnLineSegmentToPoint(in lineSegmentBegin, in lineSegmentEnd, in position);
				float num2 = position.DistanceSquared(closestPointOnLineSegmentToPoint);
				if (num2 <= num)
				{
					num = num2;
					closestPoint = closestPointOnLineSegmentToPoint;
				}
			}
			return TaleWorlds.Library.MathF.Sqrt(num);
		}

		public static float FindClosestPointToBoundariesReturnDistanceSquared(in Vec2 position, MBList<Vec2> boundaries, out Vec2 closestPoint, out bool isPositionInsideBoundaries)
		{
			closestPoint = position;
			float num = float.MaxValue;
			for (int i = 0; i < boundaries.Count; i++)
			{
				Vec2 lineSegmentBegin = boundaries[i];
				Vec2 lineSegmentEnd = boundaries[(i + 1) % boundaries.Count];
				Vec2 closestPointOnLineSegmentToPoint = MBMath.GetClosestPointOnLineSegmentToPoint(in lineSegmentBegin, in lineSegmentEnd, in position);
				float num2 = position.DistanceSquared(closestPointOnLineSegmentToPoint);
				if (num2 <= num)
				{
					num = num2;
					closestPoint = closestPointOnLineSegmentToPoint;
				}
			}
			isPositionInsideBoundaries = IsPointInsideBoundaries(in position, boundaries);
			return TaleWorlds.Library.MathF.Sqrt(num);
		}
	}
