	public static class MissionCombatMechanicsHelper
	{
		private const float SpeedBonusFactorForSwing = 0.7f;

		private const float SpeedBonusFactorForThrust = 0.5f;

		public static bool DecideAgentShrugOffBlow(Agent victimAgent, in AttackCollisionData collisionData, in Blow blow)
		{
			bool result = false;
			if (victimAgent.Health - (float)collisionData.InflictedDamage >= 1f)
			{
				float num = MissionGameModels.Current.AgentApplyDamageModel.CalculateStaggerThresholdDamage(victimAgent, in blow);
				result = (float)collisionData.InflictedDamage <= num;
			}
			return result;
		}

		public static bool DecideAgentDismountedByBlow(Agent attackerAgent, Agent victimAgent, in AttackCollisionData collisionData, WeaponComponentData attackerWeapon, in Blow blow)
		{
			bool flag = false;
			int inflictedDamage = collisionData.InflictedDamage;
			bool flag2 = victimAgent.Health - (float)inflictedDamage >= 1f;
			bool flag3 = (blow.BlowFlag & BlowFlags.ShrugOff) != 0;
			if (attackerWeapon != null && flag2 && !flag3)
			{
				int num = (int)victimAgent.HealthLimit;
				if (MissionGameModels.Current.AgentApplyDamageModel.CanWeaponDismount(attackerAgent, attackerWeapon, in blow, in collisionData))
				{
					float dismountPenetration = MissionGameModels.Current.AgentApplyDamageModel.GetDismountPenetration(attackerAgent, attackerWeapon, in blow, in collisionData);
					float dismountResistance = MissionGameModels.Current.AgentStatCalculateModel.GetDismountResistance(victimAgent);
					flag = DecideCombatEffect(inflictedDamage, num, dismountResistance, dismountPenetration);
				}
				if (!flag)
				{
					flag = DecideWeaponKnockDown(attackerAgent, victimAgent, attackerWeapon, in collisionData, in blow);
				}
			}
			return flag;
		}

		public static bool DecideAgentKnockedBackByBlow(Agent attackerAgent, Agent victimAgent, in AttackCollisionData collisionData, WeaponComponentData attackerWeapon, in Blow blow)
		{
			bool result = false;
			int num = (int)victimAgent.HealthLimit;
			int inflictedDamage = collisionData.InflictedDamage;
			bool flag = (blow.BlowFlag & BlowFlags.ShrugOff) != 0;
			if (collisionData.IsHorseCharge)
			{
				Vec3 victimPosition = victimAgent.Position;
				Vec2 chargerMovementDirection = attackerAgent.GetMovementDirection();
				Vec3 collisionPoint = collisionData.CollisionGlobalPosition;
				if (ChargeDamageDotProduct(in victimPosition, in chargerMovementDirection, in collisionPoint) >= 0.7f)
				{
					result = true;
				}
			}
			else if (collisionData.IsAlternativeAttack)
			{
				result = true;
			}
			else if (attackerWeapon != null && !flag && MissionGameModels.Current.AgentApplyDamageModel.CanWeaponKnockback(attackerAgent, attackerWeapon, in blow, in collisionData))
			{
				float knockBackPenetration = MissionGameModels.Current.AgentApplyDamageModel.GetKnockBackPenetration(attackerAgent, attackerWeapon, in blow, in collisionData);
				float knockBackResistance = MissionGameModels.Current.AgentStatCalculateModel.GetKnockBackResistance(victimAgent);
				result = DecideCombatEffect(inflictedDamage, num, knockBackResistance, knockBackPenetration);
			}
			return result;
		}

		public static bool DecideAgentKnockedDownByBlow(Agent attackerAgent, Agent victimAgent, in AttackCollisionData collisionData, WeaponComponentData attackerWeapon, in Blow blow)
		{
			bool result = false;
			if ((blow.BlowFlag & BlowFlags.ShrugOff) == 0)
			{
				int num = (int)victimAgent.HealthLimit;
				float inflictedDamage = collisionData.InflictedDamage;
				bool flag = (blow.BlowFlag & BlowFlags.KnockBack) != 0;
				if (collisionData.IsHorseCharge && flag)
				{
					float horseChargePenetration = MissionGameModels.Current.AgentApplyDamageModel.GetHorseChargePenetration();
					float knockDownResistance = MissionGameModels.Current.AgentStatCalculateModel.GetKnockDownResistance(victimAgent);
					result = DecideCombatEffect(inflictedDamage, num, knockDownResistance, horseChargePenetration);
				}
				else if (attackerWeapon != null)
				{
					result = DecideWeaponKnockDown(attackerAgent, victimAgent, attackerWeapon, in collisionData, in blow);
				}
			}
			return result;
		}

		public static bool DecideMountRearedByBlow(Agent attackerAgent, Agent victimAgent, in AttackCollisionData collisionData, WeaponComponentData attackerWeapon, in Blow blow)
		{
			float damageMultiplierOfCombatDifficulty = Mission.Current.GetDamageMultiplierOfCombatDifficulty(victimAgent, attackerAgent);
			if (attackerWeapon != null && attackerWeapon.WeaponFlags.HasAnyFlag(WeaponFlags.WideGrip) && attackerWeapon.WeaponLength > 120 && blow.StrikeType == StrikeType.Thrust && collisionData.ThrustTipHit && attackerAgent != null && !attackerAgent.HasMount && victimAgent.GetAgentFlags().HasAnyFlag(AgentFlag.CanRear) && victimAgent.MovementVelocity.y > 5f && Vec3.DotProduct(blow.Direction, victimAgent.Frame.rotation.f) < -0.35f && Vec2.DotProduct(blow.GlobalPosition.AsVec2 - victimAgent.Position.AsVec2, victimAgent.GetMovementDirection()) > 0f)
			{
				return (float)collisionData.InflictedDamage >= ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.MakesRearAttackDamageThreshold) * damageMultiplierOfCombatDifficulty;
			}
			return false;
		}

		public static void DecideWeaponCollisionReaction(in Blow registeredBlow, in AttackCollisionData collisionData, Agent attacker, Agent defender, in MissionWeapon attackerWeapon, bool isFatalHit, bool isShruggedOff, float momentumRemaining, out MeleeCollisionReaction colReaction)
		{
			if (collisionData.IsColliderAgent && collisionData.StrikeType == 1 && collisionData.CollisionHitResultFlags.HasAnyFlag(CombatHitResultFlags.HitWithStartOfTheAnimation))
			{
				colReaction = MeleeCollisionReaction.Staggered;
				return;
			}
			if (!collisionData.IsColliderAgent && collisionData.PhysicsMaterialIndex != -1 && PhysicsMaterial.GetFromIndex(collisionData.PhysicsMaterialIndex).GetFlags().HasAnyFlag(PhysicsMaterialFlags.AttacksCanPassThrough))
			{
				colReaction = MeleeCollisionReaction.SlicedThrough;
				return;
			}
			if (!collisionData.IsColliderAgent || registeredBlow.InflictedDamage <= 0)
			{
				colReaction = MeleeCollisionReaction.Bounced;
				return;
			}
			if (collisionData.StrikeType == 1 && attacker.IsDoingPassiveAttack)
			{
				colReaction = MissionGameModels.Current.AgentApplyDamageModel.DecidePassiveAttackCollisionReaction(attacker, defender, isFatalHit);
				return;
			}
			if (collisionData.IsAlternativeAttack && momentumRemaining > 0f)
			{
				colReaction = MeleeCollisionReaction.ContinueChecking;
				return;
			}
			if (HitWithAnotherBone(in collisionData, attacker, in attackerWeapon))
			{
				colReaction = MeleeCollisionReaction.Bounced;
				return;
			}
			WeaponClass weaponClass = ((!attackerWeapon.IsEmpty) ? attackerWeapon.CurrentUsageItem.WeaponClass : WeaponClass.Undefined);
			if ((!attackerWeapon.IsEmpty && !isFatalHit && isShruggedOff) || (attackerWeapon.IsEmpty && defender != null && defender.IsHuman && !collisionData.IsAlternativeAttack && (collisionData.VictimHitBodyPart == BoneBodyPartType.Chest || collisionData.VictimHitBodyPart == BoneBodyPartType.ShoulderLeft || collisionData.VictimHitBodyPart == BoneBodyPartType.ShoulderRight || collisionData.VictimHitBodyPart == BoneBodyPartType.Abdomen || collisionData.VictimHitBodyPart == BoneBodyPartType.Legs)))
			{
				colReaction = MeleeCollisionReaction.Bounced;
			}
			else if (((weaponClass == WeaponClass.OneHandedAxe || weaponClass == WeaponClass.TwoHandedAxe) && !isFatalHit && (float)collisionData.InflictedDamage < defender.HealthLimit * 0.5f) || (attackerWeapon.IsEmpty && !collisionData.IsAlternativeAttack && collisionData.AttackDirection == Agent.UsageDirection.AttackUp) || (collisionData.ThrustTipHit && collisionData.DamageType == 1 && !attackerWeapon.IsEmpty && defender.CanThrustAttackStickToBone(collisionData.VictimHitBodyPart)))
			{
				colReaction = MeleeCollisionReaction.Stuck;
			}
			else
			{
				colReaction = MeleeCollisionReaction.SlicedThrough;
			}
			if ((collisionData.AttackBlockedWithShield || collisionData.CollidedWithShieldOnBack) && colReaction == MeleeCollisionReaction.SlicedThrough)
			{
				colReaction = MeleeCollisionReaction.Bounced;
			}
		}

		public static bool IsCollisionBoneDifferentThanWeaponAttachBone(in AttackCollisionData collisionData, int weaponAttachBoneIndex)
		{
			if (collisionData.AttackBoneIndex != -1 && weaponAttachBoneIndex != -1)
			{
				return weaponAttachBoneIndex != collisionData.AttackBoneIndex;
			}
			return false;
		}

		public static bool DecideSweetSpotCollision(in AttackCollisionData collisionData)
		{
			if (collisionData.AttackProgress >= 0.22f)
			{
				return collisionData.AttackProgress <= 0.55f;
			}
			return false;
		}

		public static void GetAttackCollisionResults(in AttackInformation attackInformation, bool crushedThrough, float momentumRemaining, bool cancelDamage, ref AttackCollisionData attackCollisionData, out CombatLogData combatLog, out int speedBonus)
		{
			float distance = 0f;
			if (attackCollisionData.IsMissile)
			{
				distance = (attackCollisionData.MissileStartingPosition - attackCollisionData.CollisionGlobalPosition).Length;
			}
			combatLog = new CombatLogData(attackInformation.IsVictimAgentSameWithAttackerAgent, attackInformation.IsAttackerAgentHuman, attackInformation.IsAttackerAgentMine, attackInformation.DoesAttackerHaveRiderAgent, attackInformation.IsAttackerAgentRiderAgentMine, attackInformation.IsAttackerAgentMount, attackInformation.IsVictimAgentHuman, attackInformation.IsVictimAgentMine, isVictimAgentDead: false, attackInformation.DoesVictimHaveRiderAgent, attackInformation.IsVictimAgentRiderAgentMine, attackInformation.IsVictimAgentMount, null, attackInformation.IsVictimRiderAgentSameAsAttackerAgent, crushedThrough: false, chamber: false, distance);
			bool flag = IsCollisionBoneDifferentThanWeaponAttachBone(in attackCollisionData, attackInformation.WeaponAttachBoneIndex);
			Vec2 agentVelocityContribution = GetAgentVelocityContribution(attackInformation.DoesAttackerHaveMountAgent, attackInformation.AttackerAgentMovementVelocity, attackInformation.AttackerAgentMountMovementDirection, attackInformation.AttackerMovementDirectionAsAngle);
			Vec2 agentVelocityContribution2 = GetAgentVelocityContribution(attackInformation.DoesVictimHaveMountAgent, attackInformation.VictimAgentMovementVelocity, attackInformation.VictimAgentMountMovementDirection, attackInformation.VictimMovementDirectionAsAngle);
			if (attackCollisionData.IsColliderAgent)
			{
				combatLog.IsRangedAttack = attackCollisionData.IsMissile;
				combatLog.HitSpeed = (attackCollisionData.IsMissile ? (agentVelocityContribution2.ToVec3() - attackCollisionData.MissileVelocity).Length : (agentVelocityContribution - agentVelocityContribution2).Length);
			}
			ComputeBlowMagnitude(in attackCollisionData, in attackInformation, momentumRemaining, cancelDamage, flag, agentVelocityContribution, agentVelocityContribution2, out attackCollisionData.BaseMagnitude, out var specialMagnitude, out attackCollisionData.MovementSpeedDamageModifier, out speedBonus);
			DamageTypes damageType = (combatLog.DamageType = ((attackInformation.AttackerWeapon.IsEmpty || flag || attackCollisionData.IsAlternativeAttack || attackCollisionData.IsFallDamage || attackCollisionData.IsHorseCharge) ? DamageTypes.Blunt : ((DamageTypes)attackCollisionData.DamageType)));
			if (!attackCollisionData.IsColliderAgent && attackCollisionData.EntityExists)
			{
				bool isFlammable = PhysicsMaterial.GetFromIndex(attackCollisionData.PhysicsMaterialIndex).GetFlags().HasAnyFlag(PhysicsMaterialFlags.Flammable);
				attackCollisionData.BaseMagnitude *= GetEntityDamageMultiplier(attackInformation.IsAttackerAgentDoingPassiveAttack, attackInformation.AttackerWeapon.CurrentUsageItem, damageType, isFlammable);
				attackCollisionData.InflictedDamage = MBMath.ClampInt((int)attackCollisionData.BaseMagnitude, 0, 2000);
				combatLog.InflictedDamage = attackCollisionData.InflictedDamage;
			}
			if (attackCollisionData.IsColliderAgent && !attackInformation.IsVictimAgentNull)
			{
				if (attackCollisionData.IsAlternativeAttack)
				{
					specialMagnitude = attackCollisionData.BaseMagnitude;
				}
				if (attackCollisionData.AttackBlockedWithShield)
				{
					ComputeBlowDamageOnShield(in attackInformation, in attackCollisionData, attackInformation.AttackerWeapon.CurrentUsageItem, attackCollisionData.BaseMagnitude, out attackCollisionData.InflictedDamage);
					attackCollisionData.AbsorbedByArmor = attackCollisionData.InflictedDamage;
				}
				else if (attackCollisionData.MissileBlockedWithWeapon)
				{
					attackCollisionData.InflictedDamage = 0;
					attackCollisionData.AbsorbedByArmor = 0;
				}
				else
				{
					ComputeBlowDamage(in attackInformation, in attackCollisionData, attackInformation.AttackerWeapon.CurrentUsageItem, damageType, specialMagnitude, speedBonus, cancelDamage, out attackCollisionData.InflictedDamage, out attackCollisionData.AbsorbedByArmor, out var isSneakAttack);
					attackCollisionData.IsSneakAttack = isSneakAttack;
					combatLog.IsSneakAttack = isSneakAttack;
				}
				combatLog.InflictedDamage = attackCollisionData.InflictedDamage;
				combatLog.AbsorbedDamage = attackCollisionData.AbsorbedByArmor;
				combatLog.AttackProgress = attackCollisionData.AttackProgress;
			}
		}

		internal static void GetDefendCollisionResults(Agent attackerAgent, Agent defenderAgent, CombatCollisionResult collisionResult, int attackerWeaponSlotIndex, bool isAlternativeAttack, StrikeType strikeType, Agent.UsageDirection attackDirection, float collisionDistanceOnWeapon, float attackProgress, bool attackIsParried, bool isPassiveUsageHit, bool isHeavyAttack, ref float defenderStunPeriod, ref float attackerStunPeriod, ref bool crushedThrough, ref bool chamber)
		{
			MissionWeapon missionWeapon = ((attackerWeaponSlotIndex >= 0) ? attackerAgent.Equipment[attackerWeaponSlotIndex] : MissionWeapon.Invalid);
			WeaponComponentData weaponComponentData = (missionWeapon.IsEmpty ? null : missionWeapon.CurrentUsageItem);
			EquipmentIndex equipmentIndex = defenderAgent.GetOffhandWieldedItemIndex();
			if (equipmentIndex == EquipmentIndex.None)
			{
				equipmentIndex = defenderAgent.GetPrimaryWieldedItemIndex();
			}
			ItemObject itemObject = ((equipmentIndex != EquipmentIndex.None) ? defenderAgent.Equipment[equipmentIndex].Item : null);
			WeaponComponentData weaponComponentData2 = ((equipmentIndex != EquipmentIndex.None) ? defenderAgent.Equipment[equipmentIndex].CurrentUsageItem : null);
			float num = 10f;
			attackerStunPeriod = ((strikeType == StrikeType.Thrust) ? ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.StunPeriodAttackerThrust) : ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.StunPeriodAttackerSwing));
			chamber = false;
			float num2 = 0f;
			if (!missionWeapon.IsEmpty)
			{
				float z = attackerAgent.GetCurWeaponOffset().z;
				float realWeaponLength = weaponComponentData.GetRealWeaponLength();
				float num3 = realWeaponLength + z;
				num2 = MBMath.ClampFloat((0.2f + collisionDistanceOnWeapon) / num3, 0.1f, 0.98f);
				float exraLinearSpeed = ComputeRelativeSpeedDiffOfAgents(attackerAgent, defenderAgent);
				float num4 = ((strikeType != StrikeType.Thrust) ? CombatStatCalculator.CalculateBaseBlowMagnitudeForSwing((float)missionWeapon.GetModifiedSwingSpeedForCurrentUsage() / 4.5454545f * SpeedGraphFunction(attackProgress, strikeType, attackDirection), realWeaponLength, missionWeapon.Item.Weight, weaponComponentData.TotalInertia, weaponComponentData.CenterOfMass, num2, exraLinearSpeed) : CombatStatCalculator.CalculateBaseBlowMagnitudeForThrust((float)missionWeapon.GetModifiedThrustSpeedForCurrentUsage() / 11.764706f * SpeedGraphFunction(attackProgress, strikeType, attackDirection), missionWeapon.Item.Weight, exraLinearSpeed));
				if (strikeType == StrikeType.Thrust)
				{
					num4 *= 0.8f;
				}
				else if (attackDirection == Agent.UsageDirection.AttackUp)
				{
					num4 *= 1.25f;
				}
				else if (isHeavyAttack)
				{
					num4 *= ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.HeavyAttackMomentumMultiplier);
				}
				num += num4;
			}
			float num5 = 1f;
			defenderStunPeriod = num * ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.StunMomentumTransferFactor);
			if (weaponComponentData2 != null)
			{
				if (weaponComponentData2.IsShield)
				{
					float managedParameter = ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.StunDefendWeaponWeightOffsetShield);
					num5 += managedParameter * itemObject.Weight;
				}
				else
				{
					num5 = 0.9f;
					float managedParameter2 = ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.StunDefendWeaponWeightMultiplierWeaponWeight);
					num5 += managedParameter2 * itemObject.Weight;
					switch (itemObject.ItemType)
					{
					case ItemObject.ItemTypeEnum.TwoHandedWeapon:
						num5 += ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.StunDefendWeaponWeightBonusTwoHanded);
						break;
					case ItemObject.ItemTypeEnum.Polearm:
						num5 += ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.StunDefendWeaponWeightBonusPolearm);
						break;
					}
				}
				switch (collisionResult)
				{
				case CombatCollisionResult.Parried:
					attackerStunPeriod += TaleWorlds.Library.MathF.Min(0.15f, 0.12f * num5);
					num5 += ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.StunDefendWeaponWeightBonusActiveBlocked);
					break;
				case CombatCollisionResult.ChamberBlocked:
					attackerStunPeriod += TaleWorlds.Library.MathF.Min(0.25f, 0.25f * num5);
					num5 += ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.StunDefendWeaponWeightBonusChamberBlocked);
					chamber = true;
					break;
				}
			}
			if (!defenderAgent.GetIsLeftStance())
			{
				num5 += ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.StunDefendWeaponWeightBonusRightStance);
			}
			defenderStunPeriod /= num5;
			MissionGameModels.Current.AgentApplyDamageModel.CalculateDefendedBlowStunMultipliers(attackerAgent, defenderAgent, collisionResult, weaponComponentData, weaponComponentData2, ref attackerStunPeriod, ref defenderStunPeriod);
			float managedParameter3 = ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.StunPeriodMax);
			attackerStunPeriod = TaleWorlds.Library.MathF.Min(attackerStunPeriod, managedParameter3);
			defenderStunPeriod = TaleWorlds.Library.MathF.Min(defenderStunPeriod, managedParameter3);
			crushedThrough = !chamber && MissionGameModels.Current.AgentApplyDamageModel.DecideCrushedThrough(attackerAgent, defenderAgent, num, attackDirection, strikeType, weaponComponentData2, isPassiveUsageHit);
		}

		public static void UpdateMomentumRemaining(ref float momentumRemaining, in Blow b, in AttackCollisionData collisionData, Agent attacker, Agent victim, in MissionWeapon attackerWeapon, bool isCrushThrough)
		{
			momentumRemaining = MissionGameModels.Current.AgentApplyDamageModel.CalculateRemainingMomentum(momentumRemaining, in b, in collisionData, attacker, victim, in attackerWeapon, isCrushThrough);
		}

		public static bool HitWithAnotherBone(in AttackCollisionData collisionData, Agent attacker, in MissionWeapon attackerWeapon)
		{
			int weaponAttachBoneIndex = ((!attackerWeapon.IsEmpty && attacker != null && attacker.IsHuman) ? attacker.Monster.GetBoneToAttachForItemFlags(attackerWeapon.Item.ItemFlags) : (-1));
			return IsCollisionBoneDifferentThanWeaponAttachBone(in collisionData, weaponAttachBoneIndex);
		}

		private static bool DecideWeaponKnockDown(Agent attackerAgent, Agent victimAgent, WeaponComponentData attackerWeapon, in AttackCollisionData collisionData, in Blow blow)
		{
			if (MissionGameModels.Current.AgentApplyDamageModel.CanWeaponKnockDown(attackerAgent, victimAgent, attackerWeapon, in blow, in collisionData))
			{
				float knockDownPenetration = MissionGameModels.Current.AgentApplyDamageModel.GetKnockDownPenetration(attackerAgent, attackerWeapon, in blow, in collisionData);
				float knockDownResistance = MissionGameModels.Current.AgentStatCalculateModel.GetKnockDownResistance(victimAgent, blow.StrikeType);
				return DecideCombatEffect(collisionData.InflictedDamage, victimAgent.HealthLimit, knockDownResistance, knockDownPenetration);
			}
			return false;
		}

		private static bool DecideCombatEffect(float inflictedDamage, float victimMaxHealth, float victimResistance, float attackPenetration)
		{
			float num = victimMaxHealth * Math.Max(0f, victimResistance - attackPenetration);
			return inflictedDamage >= num;
		}

		private static float ChargeDamageDotProduct(in Vec3 victimPosition, in Vec2 chargerMovementDirection, in Vec3 collisionPoint)
		{
			float b = Vec2.DotProduct((victimPosition.AsVec2 - collisionPoint.AsVec2).Normalized(), chargerMovementDirection);
			return TaleWorlds.Library.MathF.Max(0f, b);
		}

		private static float SpeedGraphFunction(float progress, StrikeType strikeType, Agent.UsageDirection attackDir)
		{
			bool num = strikeType == StrikeType.Thrust;
			bool flag = attackDir == Agent.UsageDirection.AttackUp;
			ManagedParametersEnum managedParameterEnum;
			ManagedParametersEnum managedParameterEnum2;
			ManagedParametersEnum managedParameterEnum3;
			ManagedParametersEnum managedParameterEnum4;
			if (num)
			{
				managedParameterEnum = ManagedParametersEnum.ThrustCombatSpeedGraphZeroProgressValue;
				managedParameterEnum2 = ManagedParametersEnum.ThrustCombatSpeedGraphFirstMaximumPoint;
				managedParameterEnum3 = ManagedParametersEnum.ThrustCombatSpeedGraphSecondMaximumPoint;
				managedParameterEnum4 = ManagedParametersEnum.ThrustCombatSpeedGraphOneProgressValue;
			}
			else if (flag)
			{
				managedParameterEnum = ManagedParametersEnum.OverSwingCombatSpeedGraphZeroProgressValue;
				managedParameterEnum2 = ManagedParametersEnum.OverSwingCombatSpeedGraphFirstMaximumPoint;
				managedParameterEnum3 = ManagedParametersEnum.OverSwingCombatSpeedGraphSecondMaximumPoint;
				managedParameterEnum4 = ManagedParametersEnum.OverSwingCombatSpeedGraphOneProgressValue;
			}
			else
			{
				managedParameterEnum = ManagedParametersEnum.SwingCombatSpeedGraphZeroProgressValue;
				managedParameterEnum2 = ManagedParametersEnum.SwingCombatSpeedGraphFirstMaximumPoint;
				managedParameterEnum3 = ManagedParametersEnum.SwingCombatSpeedGraphSecondMaximumPoint;
				managedParameterEnum4 = ManagedParametersEnum.SwingCombatSpeedGraphOneProgressValue;
			}
			float managedParameter = ManagedParameters.Instance.GetManagedParameter(managedParameterEnum);
			float managedParameter2 = ManagedParameters.Instance.GetManagedParameter(managedParameterEnum2);
			float managedParameter3 = ManagedParameters.Instance.GetManagedParameter(managedParameterEnum3);
			float managedParameter4 = ManagedParameters.Instance.GetManagedParameter(managedParameterEnum4);
			if (progress < managedParameter2)
			{
				return (1f - managedParameter) / managedParameter2 * progress + managedParameter;
			}
			if (managedParameter3 < progress)
			{
				return (managedParameter4 - 1f) / (1f - managedParameter3) * (progress - managedParameter3) + 1f;
			}
			return 1f;
		}

		private static float ConvertBaseAttackMagnitude(WeaponComponentData weapon, StrikeType strikeType, float baseMagnitude)
		{
			return baseMagnitude * ((strikeType == StrikeType.Thrust) ? weapon.ThrustDamageFactor : weapon.SwingDamageFactor);
		}

		private static Vec2 GetAgentVelocityContribution(bool hasAgentMountAgent, Vec2 agentMovementVelocity, Vec2 agentMountMovementDirection, float agentMovementDirectionAsAngle)
		{
			Vec2 zero = Vec2.Zero;
			if (hasAgentMountAgent)
			{
				zero = agentMovementVelocity.y * agentMountMovementDirection;
			}
			else
			{
				zero = agentMovementVelocity;
				zero.RotateCCW(agentMovementDirectionAsAngle);
			}
			return zero;
		}

		private static float GetEntityDamageMultiplier(bool isAttackerAgentDoingPassiveAttack, WeaponComponentData weapon, DamageTypes damageType, bool isFlammable)
		{
			float num = 1f;
			if (isAttackerAgentDoingPassiveAttack)
			{
				num *= 0.2f;
			}
			if (weapon != null)
			{
				if (weapon.WeaponFlags.HasAnyFlag(WeaponFlags.BonusAgainstShield))
				{
					num *= 1.2f;
				}
				switch (damageType)
				{
				case DamageTypes.Cut:
					num *= 0.8f;
					break;
				case DamageTypes.Pierce:
					num *= 0.1f;
					break;
				}
				if (isFlammable && weapon.WeaponFlags.HasAnyFlag(WeaponFlags.Burning))
				{
					num *= 1.5f;
				}
			}
			return num;
		}

		private static float ComputeSpeedBonus(float baseMagnitude, float baseMagnitudeWithoutSpeedBonus)
		{
			return baseMagnitude / baseMagnitudeWithoutSpeedBonus - 1f;
		}

		private static float ComputeRelativeSpeedDiffOfAgents(Agent agentA, Agent agentB)
		{
			Vec2 zero = Vec2.Zero;
			if (agentA.MountAgent != null)
			{
				zero = agentA.MountAgent.MovementVelocity.y * agentA.MountAgent.GetMovementDirection();
			}
			else
			{
				zero = agentA.MovementVelocity;
				zero.RotateCCW(agentA.MovementDirectionAsAngle);
			}
			Vec2 zero2 = Vec2.Zero;
			if (agentB.MountAgent != null)
			{
				zero2 = agentB.MountAgent.MovementVelocity.y * agentB.MountAgent.GetMovementDirection();
			}
			else
			{
				zero2 = agentB.MovementVelocity;
				zero2.RotateCCW(agentB.MovementDirectionAsAngle);
			}
			return (zero - zero2).Length;
		}

		private static void ComputeBlowDamage(in AttackInformation attackInformation, in AttackCollisionData attackCollisionData, WeaponComponentData attackerWeapon, DamageTypes damageType, float magnitude, int speedBonus, bool cancelDamage, out int inflictedDamage, out int absorbedByArmor, out bool isSneakAttack)
		{
			isSneakAttack = false;
			float armorAmountFloat = attackInformation.ArmorAmountFloat;
			WeaponComponentData shieldOnBack = attackInformation.ShieldOnBack;
			AgentFlag victimAgentFlags = attackInformation.VictimAgentFlags;
			float victimAgentAbsorbedDamageRatio = attackInformation.VictimAgentAbsorbedDamageRatio;
			float damageMultiplierOfBone = attackInformation.DamageMultiplierOfBone;
			float combatDifficultyMultiplier = attackInformation.CombatDifficultyMultiplier;
			bool attackBlockedWithShield = attackCollisionData.AttackBlockedWithShield;
			bool collidedWithShieldOnBack = attackCollisionData.CollidedWithShieldOnBack;
			bool isFallDamage = attackCollisionData.IsFallDamage;
			BasicCharacterObject attackerAgentCharacter = attackInformation.AttackerAgentCharacter;
			BasicCharacterObject attackerCaptainCharacter = attackInformation.AttackerCaptainCharacter;
			BasicCharacterObject victimAgentCharacter = attackInformation.VictimAgentCharacter;
			BasicCharacterObject victimCaptainCharacter = attackInformation.VictimCaptainCharacter;
			float num = 0f;
			if (!isFallDamage)
			{
				num = MissionGameModels.Current.StrikeMagnitudeModel.CalculateAdjustedArmorForBlow(in attackInformation, in attackCollisionData, armorAmountFloat, attackerAgentCharacter, attackerCaptainCharacter, victimAgentCharacter, victimCaptainCharacter, attackerWeapon);
			}
			if (collidedWithShieldOnBack && shieldOnBack != null)
			{
				num += 10f;
			}
			float absorbedDamageRatio = victimAgentAbsorbedDamageRatio;
			float num2 = MissionGameModels.Current.StrikeMagnitudeModel.ComputeRawDamage(damageType, magnitude, num, absorbedDamageRatio);
			float num3 = 1f;
			if (!attackBlockedWithShield && !isFallDamage)
			{
				num3 *= damageMultiplierOfBone;
				if (MissionGameModels.Current.AgentApplyDamageModel.CanWeaponDealSneakAttack(in attackInformation, attackerWeapon))
				{
					float sneakAttackMultiplier = MissionGameModels.Current.AgentStatCalculateModel.GetSneakAttackMultiplier(attackInformation.AttackerAgent, attackerWeapon);
					num3 *= sneakAttackMultiplier;
					isSneakAttack = true;
				}
				num3 *= combatDifficultyMultiplier;
			}
			num2 *= num3;
			inflictedDamage = MBMath.ClampInt(TaleWorlds.Library.MathF.Ceiling(num2), 0, 2000);
			int num4 = MBMath.ClampInt(TaleWorlds.Library.MathF.Ceiling(MissionGameModels.Current.StrikeMagnitudeModel.ComputeRawDamage(damageType, magnitude, 0f, absorbedDamageRatio) * num3), 0, 2000);
			absorbedByArmor = num4 - inflictedDamage;
		}

		private static void ComputeBlowDamageOnShield(in AttackInformation attackInformation, in AttackCollisionData attackCollisionData, WeaponComponentData attackerWeapon, float blowMagnitude, out int inflictedDamage)
		{
			inflictedDamage = 0;
			MissionWeapon victimShield = attackInformation.VictimShield;
			if (!victimShield.CurrentUsageItem.WeaponFlags.HasAnyFlag(WeaponFlags.CanBlockRanged) || !attackInformation.CanGiveDamageToAgentShield)
			{
				return;
			}
			DamageTypes damageType = (DamageTypes)attackCollisionData.DamageType;
			int getModifiedArmorForCurrentUsage = victimShield.GetGetModifiedArmorForCurrentUsage();
			float absorbedDamageRatio = 1f;
			float num = MissionGameModels.Current.StrikeMagnitudeModel.ComputeRawDamage(damageType, blowMagnitude, getModifiedArmorForCurrentUsage, absorbedDamageRatio);
			if (attackCollisionData.IsMissile)
			{
				num = ((attackerWeapon.WeaponClass == WeaponClass.ThrowingAxe) ? (num * 0.3f) : ((attackerWeapon.WeaponClass == WeaponClass.Javelin) ? (num * 0.5f) : ((!attackerWeapon.WeaponFlags.HasAnyFlag(WeaponFlags.CanPenetrateShield) || !attackerWeapon.WeaponFlags.HasAnyFlag(WeaponFlags.MultiplePenetration)) ? (num * 0.15f) : (num * 0.5f))));
			}
			else
			{
				switch (attackCollisionData.DamageType)
				{
				case 1:
					num *= 0.5f;
					break;
				case 0:
				case 2:
					num *= 0.7f;
					break;
				}
			}
			if (attackerWeapon != null && attackerWeapon.WeaponFlags.HasAnyFlag(WeaponFlags.BonusAgainstShield))
			{
				num *= 2f;
			}
			if (num > 0f)
			{
				if (!attackInformation.IsVictimAgentLeftStance)
				{
					num *= ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.ShieldRightStanceBlockDamageMultiplier);
				}
				if (attackCollisionData.CorrectSideShieldBlock)
				{
					num *= ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.ShieldCorrectSideBlockDamageMultiplier);
				}
				num = MissionGameModels.Current.AgentApplyDamageModel.CalculateShieldDamage(in attackInformation, num);
				inflictedDamage = (int)num;
			}
		}

		public static float CalculateBaseMeleeBlowMagnitude(in AttackInformation attackInformation, in AttackCollisionData collisionData, StrikeType strikeType, float progressEffect, float impactPointAsPercent, float exraLinearSpeed)
		{
			WeaponComponentData currentUsageItem = attackInformation.AttackerWeapon.CurrentUsageItem;
			float num = TaleWorlds.Library.MathF.Sqrt(progressEffect);
			if (strikeType == StrikeType.Thrust)
			{
				exraLinearSpeed *= 0.5f;
				float thrustSpeed = (float)attackInformation.AttackerWeapon.GetModifiedThrustSpeedForCurrentUsage() / 11.764706f * num;
				return MissionGameModels.Current.StrikeMagnitudeModel.CalculateStrikeMagnitudeForThrust(in attackInformation, in collisionData, in attackInformation.AttackerWeapon, thrustSpeed, exraLinearSpeed);
			}
			exraLinearSpeed *= 0.7f;
			float swingSpeed = (float)attackInformation.AttackerWeapon.GetModifiedSwingSpeedForCurrentUsage() / 4.5454545f * num;
			float num2 = MBMath.ClampFloat(0.4f / currentUsageItem.GetRealWeaponLength(), 0f, 1f);
			float num3 = TaleWorlds.Library.MathF.Min(0.93f, impactPointAsPercent);
			float num4 = TaleWorlds.Library.MathF.Min(0.93f, impactPointAsPercent + num2);
			float num5 = 0f;
			for (int i = 0; i < 5; i++)
			{
				float impactPointAsPercent2 = num3 + (float)i / 4f * (num4 - num3);
				float num6 = MissionGameModels.Current.StrikeMagnitudeModel.CalculateStrikeMagnitudeForSwing(in attackInformation, in collisionData, in attackInformation.AttackerWeapon, swingSpeed, impactPointAsPercent2, exraLinearSpeed);
				if (num5 < num6)
				{
					num5 = num6;
				}
			}
			return num5;
		}

		private static void ComputeBlowMagnitude(in AttackCollisionData acd, in AttackInformation attackInformation, float momentumRemaining, bool cancelDamage, bool hitWithAnotherBone, Vec2 attackerVelocity, Vec2 victimVelocity, out float baseMagnitude, out float specialMagnitude, out float movementSpeedDamageModifier, out int speedBonusInt)
		{
			StrikeType strikeType = (StrikeType)acd.StrikeType;
			Agent.UsageDirection attackDirection = acd.AttackDirection;
			bool attackerIsDoingPassiveAttack = !attackInformation.IsAttackerAgentNull && attackInformation.IsAttackerAgentHuman && attackInformation.IsAttackerAgentActive && attackInformation.IsAttackerAgentDoingPassiveAttack;
			movementSpeedDamageModifier = 0f;
			speedBonusInt = 0;
			if (acd.IsMissile)
			{
				ComputeBlowMagnitudeMissile(in attackInformation, in acd, momentumRemaining, in victimVelocity, out baseMagnitude, out specialMagnitude);
			}
			else if (acd.IsFallDamage)
			{
				ComputeBlowMagnitudeFromFall(in attackInformation, in acd, out baseMagnitude, out specialMagnitude);
			}
			else if (acd.IsHorseCharge)
			{
				ComputeBlowMagnitudeFromHorseCharge(in attackInformation, in acd, attackerVelocity, victimVelocity, out baseMagnitude, out specialMagnitude);
			}
			else
			{
				ComputeBlowMagnitudeMelee(in attackInformation, in acd, momentumRemaining, cancelDamage, hitWithAnotherBone, strikeType, attackDirection, attackerIsDoingPassiveAttack, attackerVelocity, victimVelocity, out baseMagnitude, out specialMagnitude, out movementSpeedDamageModifier, out speedBonusInt);
			}
			specialMagnitude = MBMath.ClampFloat(specialMagnitude, 0f, 500f);
		}

		private static void ComputeBlowMagnitudeMelee(in AttackInformation attackInformation, in AttackCollisionData collisionData, float momentumRemaining, bool cancelDamage, bool hitWithAnotherBone, StrikeType strikeType, Agent.UsageDirection attackDirection, bool attackerIsDoingPassiveAttack, Vec2 attackerVelocity, Vec2 victimVelocity, out float baseMagnitude, out float specialMagnitude, out float movementSpeedDamageModifier, out int speedBonusInt)
		{
			Vec3 attackerAgentCurrentWeaponOffset = attackInformation.AttackerAgentCurrentWeaponOffset;
			movementSpeedDamageModifier = 0f;
			speedBonusInt = 0;
			BasicCharacterObject attackerAgentCharacter = attackInformation.AttackerAgentCharacter;
			if (collisionData.IsAlternativeAttack)
			{
				WeaponComponentData currentUsageItem = attackInformation.AttackerWeapon.CurrentUsageItem;
				baseMagnitude = MissionGameModels.Current.AgentApplyDamageModel.CalculateAlternativeAttackDamage(in attackInformation, in collisionData, currentUsageItem);
				baseMagnitude *= momentumRemaining;
				specialMagnitude = baseMagnitude;
				return;
			}
			Vec3 weaponBlowDir = collisionData.WeaponBlowDir;
			Vec2 vb = attackerVelocity - victimVelocity;
			float num = vb.Normalize();
			float num2 = Vec2.DotProduct(weaponBlowDir.AsVec2, vb);
			if (num2 > 0f)
			{
				num2 += 0.2f;
				num2 = TaleWorlds.Library.MathF.Min(num2, 1f);
			}
			float num3 = num * num2;
			if (attackInformation.AttackerWeapon.IsEmpty)
			{
				float progressEffect = SpeedGraphFunction(collisionData.AttackProgress, strikeType, attackDirection);
				baseMagnitude = MissionGameModels.Current.StrikeMagnitudeModel.CalculateStrikeMagnitudeForUnarmedAttack(in attackInformation, in collisionData, progressEffect, momentumRemaining);
				specialMagnitude = baseMagnitude;
				return;
			}
			float z = attackerAgentCurrentWeaponOffset.z;
			WeaponComponentData currentUsageItem2 = attackInformation.AttackerWeapon.CurrentUsageItem;
			float num4 = currentUsageItem2.GetRealWeaponLength() + z;
			float impactPointAsPercent = MBMath.ClampFloat(collisionData.CollisionDistanceOnWeapon, -0.2f, num4) / num4;
			if (attackerIsDoingPassiveAttack)
			{
				if (!attackInformation.DoesAttackerHaveMountAgent && !attackInformation.DoesVictimHaveMountAgent && !attackInformation.IsVictimAgentMount)
				{
					baseMagnitude = 0f;
				}
				else
				{
					baseMagnitude = MissionGameModels.Current.StrikeMagnitudeModel.CalculateBaseBlowMagnitudeForPassiveUsage(in attackInformation, in collisionData, num3);
				}
				baseMagnitude = MissionGameModels.Current.AgentApplyDamageModel.CalculatePassiveAttackDamage(attackerAgentCharacter, in collisionData, baseMagnitude);
			}
			else
			{
				float num5 = SpeedGraphFunction(collisionData.AttackProgress, strikeType, attackDirection);
				baseMagnitude = CalculateBaseMeleeBlowMagnitude(in attackInformation, in collisionData, strikeType, num5, impactPointAsPercent, num3);
				if (baseMagnitude >= 0f && num5 > 0.7f)
				{
					float baseMagnitudeWithoutSpeedBonus = CalculateBaseMeleeBlowMagnitude(in attackInformation, in collisionData, strikeType, num5, impactPointAsPercent, 0f);
					movementSpeedDamageModifier = ComputeSpeedBonus(baseMagnitude, baseMagnitudeWithoutSpeedBonus);
					speedBonusInt = TaleWorlds.Library.MathF.Round(100f * movementSpeedDamageModifier);
					speedBonusInt = MBMath.ClampInt(speedBonusInt, -1000, 1000);
				}
			}
			baseMagnitude *= momentumRemaining;
			float num6 = 1f;
			if (hitWithAnotherBone)
			{
				num6 = ((strikeType != StrikeType.Thrust) ? ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.SwingHitWithArmDamageMultiplier) : ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.ThrustHitWithArmDamageMultiplier));
			}
			else if (strikeType == StrikeType.Thrust && !collisionData.ThrustTipHit && !collisionData.AttackBlockedWithShield)
			{
				num6 = ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.NonTipThrustHitDamageMultiplier);
			}
			baseMagnitude *= num6;
			if (attackInformation.AttackerAgent != null)
			{
				float weaponDamageMultiplier = MissionGameModels.Current.AgentStatCalculateModel.GetWeaponDamageMultiplier(attackInformation.AttackerAgent, currentUsageItem2);
				baseMagnitude *= weaponDamageMultiplier;
			}
			specialMagnitude = ConvertBaseAttackMagnitude(currentUsageItem2, strikeType, baseMagnitude);
		}

		private static void ComputeBlowMagnitudeFromHorseCharge(in AttackInformation attackInformation, in AttackCollisionData acd, Vec2 attackerAgentVelocity, Vec2 victimAgentVelocity, out float baseMagnitude, out float specialMagnitude)
		{
			Vec2 chargerMovementDirection = attackInformation.AttackerAgentMovementDirection;
			Vec2 vec = chargerMovementDirection * Vec2.DotProduct(victimAgentVelocity, chargerMovementDirection);
			Vec2 vec2 = attackerAgentVelocity - vec;
			ref readonly Vec3 victimAgentPosition = ref attackInformation.VictimAgentPosition;
			Vec3 collisionPoint = acd.CollisionGlobalPosition;
			float num = ChargeDamageDotProduct(in victimAgentPosition, in chargerMovementDirection, in collisionPoint);
			float num2 = vec2.Length * num;
			baseMagnitude = num2 * num2 * num * attackInformation.AttackerAgentMountChargeDamageProperty;
			specialMagnitude = baseMagnitude;
		}

		private static void ComputeBlowMagnitudeMissile(in AttackInformation attackInformation, in AttackCollisionData collisionData, float momentumRemaining, in Vec2 victimVelocity, out float baseMagnitude, out float specialMagnitude)
		{
			float missileSpeed = (attackInformation.IsVictimAgentNull ? collisionData.MissileVelocity.Length : (victimVelocity.ToVec3() - collisionData.MissileVelocity).Length);
			baseMagnitude = MissionGameModels.Current.StrikeMagnitudeModel.CalculateStrikeMagnitudeForMissile(in attackInformation, in collisionData, in attackInformation.AttackerWeapon, missileSpeed);
			baseMagnitude *= momentumRemaining;
			if (attackInformation.AttackerAgent != null)
			{
				float weaponDamageMultiplier = MissionGameModels.Current.AgentStatCalculateModel.GetWeaponDamageMultiplier(attackInformation.AttackerAgent, attackInformation.AttackerWeapon.CurrentUsageItem);
				baseMagnitude *= weaponDamageMultiplier;
			}
			specialMagnitude = baseMagnitude;
		}

		private static void ComputeBlowMagnitudeFromFall(in AttackInformation attackInformation, in AttackCollisionData acd, out float baseMagnitude, out float specialMagnitude)
		{
			float victimAgentScale = attackInformation.VictimAgentScale;
			float num = attackInformation.VictimAgentWeight * victimAgentScale * victimAgentScale;
			float num2 = TaleWorlds.Library.MathF.Sqrt(1f + attackInformation.VictimAgentTotalEncumbrance / num);
			float num3 = 0f - acd.VictimAgentCurVelocity.z;
			if (attackInformation.DoesVictimHaveMountAgent)
			{
				float managedParameter = ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.FallSpeedReductionMultiplierForRiderDamage);
				num3 *= managedParameter;
			}
			float num4 = ((!attackInformation.IsVictimAgentHuman) ? 1.41f : 1f);
			float managedParameter2 = ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.FallDamageMultiplier);
			float managedParameter3 = ManagedParameters.Instance.GetManagedParameter(ManagedParametersEnum.FallDamageAbsorption);
			baseMagnitude = (num3 * num3 * managedParameter2 - managedParameter3) * num2 * num4;
			if (baseMagnitude < 3f)
			{
				baseMagnitude = 0f;
			}
			else if (baseMagnitude > 499.9f)
			{
				baseMagnitude = 499.9f;
			}
			specialMagnitude = baseMagnitude;
		}
	}
	public delegate void GetFocusableObjectInteractionTextsDelegate(Agent requesterAgent, IFocusable focusableObject, bool isInteractable, out FocusableObjectInformation focusableObjectInformation);
	public class MissionFocusableObjectInformationProvider
	{
		private List<GetFocusableObjectInteractionTextsDelegate> _getFocusableObjectTextsCallbacks;

		private List<GetFocusableObjectInteractionTextsDelegate> _getDefaultFocusableObjectTextsCallbacks;

		public MissionFocusableObjectInformationProvider()
		{
			_getFocusableObjectTextsCallbacks = new List<GetFocusableObjectInteractionTextsDelegate>();
			_getDefaultFocusableObjectTextsCallbacks = new List<GetFocusableObjectInteractionTextsDelegate>();
			AddDefaultInteractionTexts();
		}

		private void AddDefaultInteractionTexts()
		{
			_getDefaultFocusableObjectTextsCallbacks.Add(GetSpawnedItemEntityTexts);
			_getDefaultFocusableObjectTextsCallbacks.Add(GetUsableMissionObjectTexts);
			_getDefaultFocusableObjectTextsCallbacks.Add(GetDestructibleComponentTexts);
			_getDefaultFocusableObjectTextsCallbacks.Add(GetUsableMachineTexts);
			_getDefaultFocusableObjectTextsCallbacks.Add(GetHumanAgentTexts);
			_getDefaultFocusableObjectTextsCallbacks.Add(GetMountTexts);
			_getDefaultFocusableObjectTextsCallbacks.Add(GetGenericAgentTexts);
		}

		public void OnFinalize()
		{
			_getFocusableObjectTextsCallbacks.Clear();
			_getDefaultFocusableObjectTextsCallbacks.Clear();
			_getFocusableObjectTextsCallbacks = null;
			_getDefaultFocusableObjectTextsCallbacks = null;
		}

		public void AddInfoCallback(GetFocusableObjectInteractionTextsDelegate callback)
		{
			_getFocusableObjectTextsCallbacks.Add(callback);
		}

		public void RemoveInfoCallback(GetFocusableObjectInteractionTextsDelegate callback)
		{
			_getFocusableObjectTextsCallbacks.Remove(callback);
		}

		public void GetInteractionTexts(Agent requesterAgent, IFocusable focusable, bool isInteractable, out FocusableObjectInformation focusableObjectInformation)
		{
			focusableObjectInformation = default(FocusableObjectInformation);
			for (int num = _getFocusableObjectTextsCallbacks.Count - 1; num >= 0; num--)
			{
				_getFocusableObjectTextsCallbacks[num](requesterAgent, focusable, isInteractable, out focusableObjectInformation);
				if (focusableObjectInformation.IsActive)
				{
					return;
				}
			}
			for (int i = 0; i < _getDefaultFocusableObjectTextsCallbacks.Count; i++)
			{
				_getDefaultFocusableObjectTextsCallbacks[i](requesterAgent, focusable, isInteractable, out focusableObjectInformation);
				if (focusableObjectInformation.IsActive)
				{
					return;
				}
			}
			focusableObjectInformation.IsActive = false;
			focusableObjectInformation.PrimaryInteractionText = TextObject.GetEmpty();
			focusableObjectInformation.SecondaryInteractionText = TextObject.GetEmpty();
		}

		private void GetSpawnedItemEntityTexts(Agent requesterAgent, IFocusable focusableObject, bool isInteractable, out FocusableObjectInformation focusableObjectInformation)
		{
			focusableObjectInformation = default(FocusableObjectInformation);
			if (focusableObject is SpawnedItemEntity { IsDeactivated: false, IsDisabled: false } spawnedItemEntity)
			{
				EquipmentIndex possibleSlotIndex;
				ItemObject weaponToReplaceOnQuickAction = Agent.Main.GetWeaponToReplaceOnQuickAction(spawnedItemEntity, out possibleSlotIndex);
				bool flag = Agent.Main.CanQuickPickUp(spawnedItemEntity);
				bool fillUp = possibleSlotIndex != EquipmentIndex.None && !Agent.Main.Equipment[possibleSlotIndex].IsEmpty && Agent.Main.Equipment[possibleSlotIndex].IsAnyConsumable() && Agent.Main.Equipment[possibleSlotIndex].Amount < Agent.Main.Equipment[possibleSlotIndex].ModifiedMaxAmount;
				TextObject actionMessage = spawnedItemEntity.GetActionMessage(weaponToReplaceOnQuickAction, fillUp);
				TextObject descriptionMessage = spawnedItemEntity.GetDescriptionMessage(fillUp);
				if (!TextObject.IsNullOrEmpty(actionMessage) && !TextObject.IsNullOrEmpty(descriptionMessage))
				{
					if (isInteractable)
					{
						MBTextManager.SetTextVariable("USE_KEY", HyperlinkTexts.GetKeyHyperlinkText(HotKeyManager.GetHotKeyId("CombatHotKeyCategory", 13)));
						if (flag)
						{
							Agent main = Agent.Main;
							if (main != null && main.CanInteractableWeaponBePickedUp(spawnedItemEntity))
							{
								TextObject textObject = GameTexts.FindText("str_key_action");
								textObject.SetTextVariable("KEY", GameTexts.FindText("str_ui_agent_interaction_use").ToString());
								textObject.SetTextVariable("ACTION", actionMessage.ToString());
								TextObject textObject2 = GameTexts.FindText("str_hold_key_action");
								textObject2.SetTextVariable("KEY", GameTexts.FindText("str_ui_agent_interaction_use").ToString());
								textObject2.SetTextVariable("ACTION", GameTexts.FindText("str_select_item_to_replace").ToString());
								focusableObjectInformation.PrimaryInteractionText = GameTexts.FindText("str_string_newline_string");
								focusableObjectInformation.PrimaryInteractionText.SetTextVariable("STR1", textObject.ToString());
								focusableObjectInformation.PrimaryInteractionText.SetTextVariable("STR2", textObject2.ToString());
								focusableObjectInformation.SecondaryInteractionText = GetItemNameText(descriptionMessage, GetWeaponSpecificText(spawnedItemEntity));
								focusableObjectInformation.IsActive = true;
							}
							else
							{
								focusableObjectInformation.PrimaryInteractionText = GameTexts.FindText("str_key_action");
								focusableObjectInformation.PrimaryInteractionText.SetTextVariable("KEY", GameTexts.FindText("str_ui_agent_interaction_use").ToString());
								focusableObjectInformation.PrimaryInteractionText.SetTextVariable("ACTION", actionMessage.ToString());
								focusableObjectInformation.SecondaryInteractionText = GetItemNameText(descriptionMessage, GetWeaponSpecificText(spawnedItemEntity));
								focusableObjectInformation.IsActive = true;
							}
						}
						else
						{
							focusableObjectInformation.PrimaryInteractionText = GameTexts.FindText("str_hold_key_action");
							focusableObjectInformation.PrimaryInteractionText.SetTextVariable("KEY", GameTexts.FindText("str_ui_agent_interaction_use").ToString());
							focusableObjectInformation.PrimaryInteractionText.SetTextVariable("ACTION", GameTexts.FindText("str_select_item_to_replace").ToString());
							focusableObjectInformation.SecondaryInteractionText = GetItemNameText(descriptionMessage, GetWeaponSpecificText(spawnedItemEntity));
							focusableObjectInformation.IsActive = true;
						}
					}
					else
					{
						focusableObjectInformation.PrimaryInteractionText = spawnedItemEntity.GetInfoTextForBeingNotInteractable(Agent.Main);
						focusableObjectInformation.SecondaryInteractionText = GetItemNameText(descriptionMessage, GetWeaponSpecificText(spawnedItemEntity));
						focusableObjectInformation.IsActive = true;
					}
				}
				else
				{
					focusableObjectInformation.IsActive = false;
				}
			}
			else
			{
				focusableObjectInformation.IsActive = false;
			}
		}

		private TextObject GetItemNameText(TextObject descriptionMessage, TextObject weaponSpecificText)
		{
			TextObject textObject;
			if (!TextObject.IsNullOrEmpty(weaponSpecificText))
			{
				textObject = GameTexts.FindText("str_STR1_space_STR2");
				textObject.SetTextVariable("STR1", descriptionMessage.ToString());
				textObject.SetTextVariable("STR2", weaponSpecificText.ToString());
			}
			else
			{
				textObject = descriptionMessage;
			}
			return textObject;
		}

		private TextObject GetWeaponSpecificText(SpawnedItemEntity spawnedItem)
		{
			MissionWeapon weaponCopy = spawnedItem.WeaponCopy;
			WeaponComponentData currentUsageItem = weaponCopy.CurrentUsageItem;
			if (currentUsageItem != null && currentUsageItem.IsShield)
			{
				TextObject textObject = GameTexts.FindText("str_LEFT_over_RIGHT_in_paranthesis");
				textObject.SetTextVariable("LEFT", weaponCopy.HitPoints);
				textObject.SetTextVariable("RIGHT", weaponCopy.ModifiedMaxHitPoints);
				return textObject;
			}
			WeaponComponentData currentUsageItem2 = weaponCopy.CurrentUsageItem;
			if (currentUsageItem2 != null && currentUsageItem2.IsAmmo && weaponCopy.ModifiedMaxAmount > 1 && !spawnedItem.IsStuckMissile())
			{
				TextObject textObject2 = GameTexts.FindText("str_LEFT_over_RIGHT_in_paranthesis");
				textObject2.SetTextVariable("LEFT", weaponCopy.Amount);
				textObject2.SetTextVariable("RIGHT", weaponCopy.ModifiedMaxAmount);
				return textObject2;
			}
			return TextObject.GetEmpty();
		}

		private void GetUsableMissionObjectTexts(Agent requesterAgent, IFocusable focusableObject, bool isInteractable, out FocusableObjectInformation focusableObjectInformation)
		{
			focusableObjectInformation = default(FocusableObjectInformation);
			if (!(focusableObject is UsableMissionObject usableMissionObject))
			{
				focusableObjectInformation.IsActive = false;
				return;
			}
			if (!TextObject.IsNullOrEmpty(usableMissionObject.ActionMessage) || !TextObject.IsNullOrEmpty(usableMissionObject.DescriptionMessage))
			{
				focusableObjectInformation.PrimaryInteractionText = usableMissionObject.DescriptionMessage;
				focusableObjectInformation.SecondaryInteractionText = (isInteractable ? usableMissionObject.ActionMessage : TextObject.GetEmpty());
				focusableObjectInformation.IsActive = true;
				return;
			}
			UsableMachine usableMachineFromPoint = GetUsableMachineFromPoint(usableMissionObject);
			if (usableMachineFromPoint != null)
			{
				focusableObjectInformation.PrimaryInteractionText = usableMachineFromPoint.GetDescriptionText(usableMissionObject.GameEntity);
				focusableObjectInformation.SecondaryInteractionText = (isInteractable ? (usableMachineFromPoint.GetActionTextForStandingPoint(usableMissionObject) ?? TextObject.GetEmpty()) : TextObject.GetEmpty());
				focusableObjectInformation.IsActive = true;
			}
			else
			{
				focusableObjectInformation.IsActive = false;
			}
		}

		private UsableMachine GetUsableMachineFromPoint(UsableMissionObject standingPoint)
		{
			WeakGameEntity weakGameEntity = standingPoint.GameEntity;
			while (weakGameEntity.IsValid && !weakGameEntity.HasScriptOfType<UsableMachine>())
			{
				weakGameEntity = weakGameEntity.Parent;
			}
			UsableMachine result = null;
			if (weakGameEntity.IsValid)
			{
				result = weakGameEntity.GetFirstScriptOfType<UsableMachine>();
			}
			return result;
		}

		private void GetDestructibleComponentTexts(Agent requesterAgent, IFocusable focusableObject, bool isInteractable, out FocusableObjectInformation focusableObjectInformation)
		{
			focusableObjectInformation = default(FocusableObjectInformation);
			if (!(focusableObject is DestructableComponent destructableComponent))
			{
				focusableObjectInformation.IsActive = false;
				return;
			}
			TextObject descriptionText = destructableComponent.GetDescriptionText(destructableComponent.GameEntity);
			bool flag = !TextObject.IsNullOrEmpty(descriptionText);
			focusableObjectInformation.PrimaryInteractionText = (flag ? descriptionText : TextObject.GetEmpty());
			focusableObjectInformation.SecondaryInteractionText = TextObject.GetEmpty();
			focusableObjectInformation.IsActive = flag;
		}

		private void GetUsableMachineTexts(Agent requesterAgent, IFocusable focusableObject, bool isInteractable, out FocusableObjectInformation focusableObjectInformation)
		{
			focusableObjectInformation = default(FocusableObjectInformation);
			if (!(focusableObject is UsableMachine usableMachine))
			{
				focusableObjectInformation.IsActive = false;
				return;
			}
			focusableObjectInformation.PrimaryInteractionText = usableMachine.GetDescriptionText(usableMachine.GameEntity) ?? TextObject.GetEmpty();
			focusableObjectInformation.SecondaryInteractionText = TextObject.GetEmpty();
			focusableObjectInformation.IsActive = true;
		}

		private void GetHumanAgentTexts(Agent requesterAgent, IFocusable focusableObject, bool isInteractable, out FocusableObjectInformation focusableObjectInformation)
		{
			focusableObjectInformation = default(FocusableObjectInformation);
			if (focusableObject is Agent { IsHuman: not false } agent)
			{
				Mission current = Mission.Current;
				if (isInteractable && (current.Mode == MissionMode.StartUp || current.Mode == MissionMode.Duel || current.Mode == MissionMode.Battle || current.Mode == MissionMode.Stealth) && agent.IsHuman)
				{
					MBTextManager.SetTextVariable("USE_KEY", HyperlinkTexts.GetKeyHyperlinkText(HotKeyManager.GetHotKeyId("CombatHotKeyCategory", 13)));
					if (agent.IsActive())
					{
						if (current.Mode == MissionMode.Duel || current.Mode == MissionMode.Battle)
						{
							focusableObjectInformation.PrimaryInteractionText = agent.NameTextObject;
							focusableObjectInformation.IsActive = true;
							return;
						}
						if (agent.IsEnemyOf(requesterAgent))
						{
							focusableObjectInformation.PrimaryInteractionText = agent.NameTextObject;
							focusableObjectInformation.IsActive = true;
							return;
						}
						if (!Mission.Current.IsAgentInteractionAllowed())
						{
							focusableObjectInformation.IsActive = false;
							return;
						}
						focusableObjectInformation.PrimaryInteractionText = agent.NameTextObject;
						if (CanInteractWithAgent(requesterAgent, agent))
						{
							focusableObjectInformation.SecondaryInteractionText = GameTexts.FindText("str_key_action");
							focusableObjectInformation.SecondaryInteractionText.SetTextVariable("KEY", GameTexts.FindText("str_ui_agent_interaction_use"));
							focusableObjectInformation.SecondaryInteractionText.SetTextVariable("ACTION", GameTexts.FindText("str_ui_talk"));
						}
						focusableObjectInformation.IsActive = true;
						return;
					}
					if (current.Mode != MissionMode.Battle && current.Mode != MissionMode.Duel)
					{
						focusableObjectInformation.PrimaryInteractionText = agent.NameTextObject;
						focusableObjectInformation.SecondaryInteractionText = GameTexts.FindText("str_key_action");
						focusableObjectInformation.SecondaryInteractionText.SetTextVariable("KEY", GameTexts.FindText("str_ui_agent_interaction_use"));
						focusableObjectInformation.SecondaryInteractionText.SetTextVariable("ACTION", GameTexts.FindText("str_ui_search"));
						focusableObjectInformation.IsActive = true;
						return;
					}
				}
				focusableObjectInformation.IsActive = false;
			}
			else
			{
				focusableObjectInformation.IsActive = false;
			}
		}

		private bool CanInteractWithAgent(Agent requesterAgent, Agent focusedAgent)
		{
			if (!requesterAgent.CanInteractWithAgent(focusedAgent, -1000f))
			{
				return requesterAgent.IsEnemyOf(focusedAgent);
			}
			return true;
		}

		private void GetMountTexts(Agent requesterAgent, IFocusable focusableObject, bool isInteractable, out FocusableObjectInformation focusableObjectInformation)
		{
			focusableObjectInformation = default(FocusableObjectInformation);
			if (focusableObject is Agent { IsMount: not false } agent)
			{
				if (agent.IsActive() && agent.IsMount)
				{
					string keyHyperlinkText = HyperlinkTexts.GetKeyHyperlinkText(HotKeyManager.GetHotKeyId("CombatHotKeyCategory", 13));
					focusableObjectInformation.PrimaryInteractionText = agent.NameTextObject;
					if (agent.RiderAgent == null)
					{
						if ((float)requesterAgent.Character.GetSkillValue(DefaultSkills.Riding) < agent.GetAgentDrivenPropertyValue(DrivenProperty.MountDifficulty))
						{
							focusableObjectInformation.SecondaryInteractionText = GameTexts.FindText("str_ui_riding_skill_not_adequate_to_mount");
						}
						else if ((requesterAgent.GetAgentFlags() & AgentFlag.CanRide) != 0)
						{
							focusableObjectInformation.SecondaryInteractionText = GameTexts.FindText("str_key_action");
							focusableObjectInformation.SecondaryInteractionText.SetTextVariable("KEY", keyHyperlinkText);
							focusableObjectInformation.SecondaryInteractionText.SetTextVariable("ACTION", GameTexts.FindText("str_ui_mount"));
						}
					}
					else if (agent.RiderAgent == requesterAgent)
					{
						focusableObjectInformation.SecondaryInteractionText = GameTexts.FindText("str_key_action");
						focusableObjectInformation.SecondaryInteractionText.SetTextVariable("KEY", keyHyperlinkText);
						focusableObjectInformation.SecondaryInteractionText.SetTextVariable("ACTION", GameTexts.FindText("str_ui_dismount"));
					}
					focusableObjectInformation.IsActive = true;
				}
				else
				{
					focusableObjectInformation.IsActive = false;
				}
			}
			else
			{
				focusableObjectInformation.IsActive = false;
			}
		}

		private void GetGenericAgentTexts(Agent requesterAgent, IFocusable focusableObject, bool isInteractable, out FocusableObjectInformation focusableObjectInformation)
		{
			focusableObjectInformation = default(FocusableObjectInformation);
			if (focusableObject is Agent { IsHuman: false, IsMount: false } agent)
			{
				if (agent.IsActive() && !agent.IsMount && !agent.IsHuman)
				{
					AgentComponent agentComponent = null;
					foreach (AgentComponent component in agent.Components)
					{
						if (component is IFocusable)
						{
							agentComponent = component;
							break;
						}
					}
					if (agentComponent != null)
					{
						focusableObjectInformation.PrimaryInteractionText = agent.NameTextObject;
						if (isInteractable)
						{
							focusableObjectInformation.SecondaryInteractionText = ((IFocusable)agentComponent).GetDescriptionText(WeakGameEntity.Invalid);
						}
						else
						{
							focusableObjectInformation.SecondaryInteractionText = ((IFocusable)agentComponent).GetInfoTextForBeingNotInteractable(requesterAgent);
						}
						focusableObjectInformation.IsActive = true;
						return;
					}
				}
				focusableObjectInformation.IsActive = false;
			}
			else
			{
				focusableObjectInformation.IsActive = false;
			}
		}
	}
	public struct FocusableObjectInformation
	{
		public bool IsActive;

		public TextObject PrimaryInteractionText;

		public TextObject SecondaryInteractionText;
	}
	public class AgentCommonAILogic : MissionLogic
	{
		public override void OnAgentCreated(Agent agent)
		{
			base.OnAgentCreated(agent);
			if (agent.IsAIControlled)
			{
				agent.AddComponent(new CommonAIComponent(agent));
			}
		}

		protected internal override void OnAgentControllerChanged(Agent agent, AgentControllerType oldController)
		{
			base.OnAgentControllerChanged(agent, oldController);
			if (agent.IsActive())
			{
				if (agent.Controller == AgentControllerType.AI)
				{
					agent.AddComponent(new CommonAIComponent(agent));
				}
				else if (oldController == AgentControllerType.AI && agent.CommonAIComponent != null)
				{
					agent.RemoveComponent(agent.CommonAIComponent);
				}
			}
		}
	}
	public class AgentHumanAILogic : MissionLogic
	{
		public override void OnAgentCreated(Agent agent)
		{
			base.OnAgentCreated(agent);
			if (agent.IsAIControlled && agent.IsHuman)
			{
				agent.AddComponent(new HumanAIComponent(agent));
			}
		}

		protected internal override void OnAgentControllerChanged(Agent agent, AgentControllerType oldController)
		{
			base.OnAgentControllerChanged(agent, oldController);
			if (agent.IsHuman)
			{
				if (agent.Controller == AgentControllerType.AI)
				{
					agent.AddComponent(new HumanAIComponent(agent));
				}
				else if (oldController == AgentControllerType.AI && agent.HumanAIComponent != null)
				{
					agent.RemoveComponent(agent.HumanAIComponent);
				}
			}
		}

		public override void OnAgentMount(Agent agent)
		{
			base.OnAgentMount(agent);
			Mission.Current.UpdateMountReservationsAfterRiderMounts(agent, agent.MountAgent);
		}
	}
	public class AgentVictoryLogic : MissionLogic
	{
		public enum CheerActionGroupEnum
		{
			None,
			LowCheerActions,
			MidCheerActions,
			HighCheerActions
		}

		public struct CheerReactionTimeSettings
		{
			public readonly float MinDuration;

			public readonly float MaxDuration;

			public CheerReactionTimeSettings(float minDuration, float maxDuration)
			{
				MinDuration = minDuration;
				MaxDuration = maxDuration;
			}
		}

		private class CheeringAgent
		{
			public readonly Agent Agent;

			public readonly bool IsCheeringOnRetreat;

			public bool GotOrderRecently { get; private set; }

			public bool IsCheeringPaused { get; private set; }

			public CheeringAgent(Agent agent, bool isCheeringOnRetreat)
			{
				Agent = agent;
				IsCheeringOnRetreat = isCheeringOnRetreat;
			}

			public void OrderReceived()
			{
				GotOrderRecently = true;
			}

			internal void UpdatePauseState(bool shouldCheeringBePaused)
			{
				IsCheeringPaused = shouldCheeringBePaused;
			}
		}

		private const float HighCheerThreshold = 0.25f;

		private const float MidCheerThreshold = 0.75f;

		private const float YellIfOrderedInRetreatProbability = 0.25f;

		private CheerActionGroupEnum _cheerActionGroup;

		private CheerReactionTimeSettings _cheerReactionTimerData;

		private readonly ActionIndexCache[] _lowCheerActions = new ActionIndexCache[10]
		{
			ActionIndexCache.act_cheering_low_01,
			ActionIndexCache.act_cheering_low_02,
			ActionIndexCache.act_cheering_low_03,
			ActionIndexCache.act_cheering_low_04,
			ActionIndexCache.act_cheering_low_05,
			ActionIndexCache.act_cheering_low_06,
			ActionIndexCache.act_cheering_low_07,
			ActionIndexCache.act_cheering_low_08,
			ActionIndexCache.act_cheering_low_09,
			ActionIndexCache.act_cheering_low_10
		};

		private readonly ActionIndexCache[] _midCheerActions = new ActionIndexCache[4]
		{
			ActionIndexCache.act_cheer_1,
			ActionIndexCache.act_cheer_2,
			ActionIndexCache.act_cheer_3,
			ActionIndexCache.act_cheer_4
		};

		private readonly ActionIndexCache[] _highCheerActions = new ActionIndexCache[8]
		{
			ActionIndexCache.act_cheering_high_01,
			ActionIndexCache.act_cheering_high_02,
			ActionIndexCache.act_cheering_high_03,
			ActionIndexCache.act_cheering_high_04,
			ActionIndexCache.act_cheering_high_05,
			ActionIndexCache.act_cheering_high_06,
			ActionIndexCache.act_cheering_high_07,
			ActionIndexCache.act_cheering_high_08
		};

		private ActionIndexCache[] _selectedCheerActions;

		private List<CheeringAgent> _cheeringAgents;

		private bool _isInRetreat;

		public CheerActionGroupEnum CheerActionGroup => _cheerActionGroup;

		public CheerReactionTimeSettings CheerReactionTimerData => _cheerReactionTimerData;

		public override void AfterStart()
		{
			base.Mission.MissionCloseTimeAfterFinish = 60f;
			_cheeringAgents = new List<CheeringAgent>();
			SetCheerReactionTimerSettings();
			if (base.Mission.PlayerTeam != null)
			{
				base.Mission.PlayerTeam.PlayerOrderController.OnOrderIssued += MasterOrderControllerOnOrderIssued;
			}
			Mission.Current.IsBattleInRetreatEvent += CheckIfIsInRetreat;
		}

		private void MasterOrderControllerOnOrderIssued(OrderType orderType, IEnumerable<Formation> appliedFormations, OrderController orderController, object[] delegateparams)
		{
			MBList<Formation> mBList = appliedFormations.ToMBList();
			for (int num = _cheeringAgents.Count - 1; num >= 0; num--)
			{
				Agent agent = _cheeringAgents[num].Agent;
				if (mBList.Contains(agent.Formation))
				{
					_cheeringAgents[num].OrderReceived();
				}
			}
		}

		public void SetCheerActionGroup(CheerActionGroupEnum cheerActionGroup = CheerActionGroupEnum.None)
		{
			_cheerActionGroup = cheerActionGroup;
			switch (_cheerActionGroup)
			{
			case CheerActionGroupEnum.LowCheerActions:
				_selectedCheerActions = _lowCheerActions;
				break;
			case CheerActionGroupEnum.MidCheerActions:
				_selectedCheerActions = _midCheerActions;
				break;
			case CheerActionGroupEnum.HighCheerActions:
				_selectedCheerActions = _highCheerActions;
				break;
			default:
				_selectedCheerActions = null;
				break;
			}
		}

		public void SetCheerReactionTimerSettings(float minDuration = 1f, float maxDuration = 8f)
		{
			_cheerReactionTimerData = new CheerReactionTimeSettings(minDuration, maxDuration);
		}

		public override void OnClearScene()
		{
			_cheeringAgents.Clear();
		}

		public override void OnAgentRemoved(Agent affectedAgent, Agent affectorAgent, AgentState agentState, KillingBlow killingBlow)
		{
			VictoryComponent component = affectedAgent.GetComponent<VictoryComponent>();
			if (component != null)
			{
				affectedAgent.RemoveComponent(component);
			}
			for (int i = 0; i < _cheeringAgents.Count; i++)
			{
				if (_cheeringAgents[i].Agent == affectedAgent)
				{
					_cheeringAgents.RemoveAt(i);
					break;
				}
			}
		}

		protected override void OnEndMission()
		{
			Mission.Current.IsBattleInRetreatEvent -= CheckIfIsInRetreat;
		}

		public override void OnMissionTick(float dt)
		{
			if (_cheeringAgents.Count > 0)
			{
				CheckAnimationAndVoice();
			}
		}

		private void CheckAnimationAndVoice()
		{
			for (int num = _cheeringAgents.Count - 1; num >= 0; num--)
			{
				Agent agent = _cheeringAgents[num].Agent;
				bool gotOrderRecently = _cheeringAgents[num].GotOrderRecently;
				bool isCheeringOnRetreat = _cheeringAgents[num].IsCheeringOnRetreat;
				bool isCheeringPaused = _cheeringAgents[num].IsCheeringPaused;
				VictoryComponent component = agent.GetComponent<VictoryComponent>();
				if (component != null)
				{
					bool flag = agent.GetComponent<HumanAIComponent>()?.GetCurrentlyMovingGameObject() != null;
					bool flag2 = agent.GetCurrentAnimationFlag(0).HasAnyFlag(AnimFlags.anf_synch_with_ladder_movement) || agent.GetCurrentAnimationFlag(1).HasAnyFlag(AnimFlags.anf_synch_with_ladder_movement);
					bool flag3 = agent.IsInWater() || agent.IsUsingGameObject || flag || flag2;
					if (CheckIfIsInRetreat() && gotOrderRecently)
					{
						agent.RemoveComponent(component);
						agent.SetActionChannel(1, in ActionIndexCache.act_none, ignorePriority: false, (AnimFlags)Math.Min(agent.GetCurrentActionPriority(1), 73));
						if (MBRandom.RandomFloat > 0.25f)
						{
							agent.MakeVoice(SkinVoiceManager.VoiceType.Yell, SkinVoiceManager.CombatVoiceNetworkPredictionType.NoPrediction);
						}
						if (isCheeringOnRetreat)
						{
							agent.ClearTargetFrame();
						}
						_cheeringAgents.RemoveAt(num);
					}
					else if (isCheeringPaused != flag3)
					{
						_cheeringAgents[num].UpdatePauseState(flag3);
						isCheeringPaused = _cheeringAgents[num].IsCheeringPaused;
					}
					if (!(CheckIfIsInRetreat() && gotOrderRecently) && !isCheeringPaused && component.CheckTimer())
					{
						if (!agent.IsActive())
						{
							TaleWorlds.Library.Debug.FailedAssert("Agent trying to cheer without being active", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\MissionLogics\\AgentVictoryLogic.cs", "CheckAnimationAndVoice", 250);
							TaleWorlds.Library.Debug.Print("Agent trying to cheer without being active");
						}
						ChooseWeaponToCheerWithCheerAndUpdateTimer(agent, out var resetTimer);
						if (resetTimer)
						{
							component.ChangeTimerDuration(6f, 12f);
						}
					}
				}
			}
		}

		private void SelectVictoryCondition(BattleSideEnum side)
		{
			if (_cheerActionGroup != 0)
			{
				return;
			}
			BattleObserverMissionLogic missionBehavior = Mission.Current.GetMissionBehavior<BattleObserverMissionLogic>();
			if (missionBehavior != null)
			{
				float deathToBuiltAgentRatioForSide = missionBehavior.GetDeathToBuiltAgentRatioForSide(side);
				if (deathToBuiltAgentRatioForSide < 0.25f)
				{
					SetCheerActionGroup(CheerActionGroupEnum.HighCheerActions);
				}
				else if (deathToBuiltAgentRatioForSide < 0.75f)
				{
					SetCheerActionGroup(CheerActionGroupEnum.MidCheerActions);
				}
				else
				{
					SetCheerActionGroup(CheerActionGroupEnum.LowCheerActions);
				}
			}
			else
			{
				SetCheerActionGroup(CheerActionGroupEnum.MidCheerActions);
			}
		}

		public void SetTimersOfVictoryReactionsOnBattleEnd(BattleSideEnum side)
		{
			_isInRetreat = false;
			SelectVictoryCondition(side);
			foreach (Team team in base.Mission.Teams)
			{
				if (team.Side != side)
				{
					continue;
				}
				foreach (Formation item in team.FormationsIncludingSpecialAndEmpty)
				{
					if (item.CountOfUnits > 0)
					{
						item.SetMovementOrder(MovementOrder.MovementOrderStop);
					}
				}
			}
			foreach (Agent agent in base.Mission.Agents)
			{
				if (agent.IsHuman && agent.IsAIControlled && agent.Team != null && side == agent.Team.Side && agent.CurrentWatchState == Agent.WatchState.Alarmed && agent.GetComponent<VictoryComponent>() == null)
				{
					RegisterAgentForCheerCheck(agent, isCheeringOnRetreat: false, _cheerReactionTimerData.MinDuration, _cheerReactionTimerData.MaxDuration);
				}
			}
		}

		private void RegisterAgentForCheerCheck(Agent agent, bool isCheeringOnRetreat, float minReactionTime, float maxReactionTime)
		{
			agent.AddComponent(new VictoryComponent(agent, new RandomTimer(base.Mission.CurrentTime, minReactionTime, maxReactionTime)));
			_cheeringAgents.Add(new CheeringAgent(agent, isCheeringOnRetreat));
		}

		public void SetTimersOfVictoryReactionsOnRetreat(BattleSideEnum side)
		{
			_isInRetreat = true;
			SelectVictoryCondition(side);
			List<Agent> list = base.Mission.Agents.Where((Agent agent) => agent.IsHuman && agent.IsAIControlled && agent.Team.Side == side).ToList();
			int num = (int)((float)list.Count * 0.5f);
			List<Agent> list2 = new List<Agent>();
			for (int i = 0; i < list.Count; i++)
			{
				if (list2.Count == num)
				{
					break;
				}
				Agent agent2 = list[i];
				EquipmentIndex primaryWieldedItemIndex = agent2.GetPrimaryWieldedItemIndex();
				bool flag = primaryWieldedItemIndex != EquipmentIndex.None && agent2.Equipment[primaryWieldedItemIndex].Item.ItemFlags.HasAnyFlag(ItemFlags.DropOnAnyAction);
				EquipmentIndex offhandWieldedItemIndex = agent2.GetOffhandWieldedItemIndex();
				bool flag2 = offhandWieldedItemIndex != EquipmentIndex.None && agent2.Equipment[offhandWieldedItemIndex].Item.ItemFlags.HasAnyFlag(ItemFlags.DropOnAnyAction);
				bool flag3 = agent2.GetComponent<HumanAIComponent>()?.GetCurrentlyMovingGameObject() != null;
				bool flag4 = agent2.GetCurrentAnimationFlag(0).HasAnyFlag(AnimFlags.anf_synch_with_ladder_movement) || agent2.GetCurrentAnimationFlag(1).HasAnyFlag(AnimFlags.anf_synch_with_ladder_movement);
				if (agent2.IsInWater() || flag || flag2 || agent2.IsUsingGameObject || flag3 || flag4)
				{
					continue;
				}
				int num2 = list.Count - i;
				int num3 = num - list2.Count;
				int num4 = num2 - num3;
				float num5 = MBMath.ClampFloat((float)(num - num4) / (float)num, 0f, 1f);
				if (num5 < 1f && agent2.TryGetImmediateEnemyAgentMovementData(out var maximumForwardUnlimitedSpeed, out var position))
				{
					float maximumForwardUnlimitedSpeed2 = agent2.GetMaximumForwardUnlimitedSpeed();
					float num6 = maximumForwardUnlimitedSpeed;
					if (maximumForwardUnlimitedSpeed2 > num6)
					{
						float num7 = (agent2.Position - position).LengthSquared / (maximumForwardUnlimitedSpeed2 - num6);
						if (num7 < 900f)
						{
							float num8 = num5 - -1f;
							float num9 = num7 / 900f;
							num5 = -1f + num8 * num9;
						}
					}
				}
				if (MBRandom.RandomFloat <= 0.5f + 0.5f * num5)
				{
					list2.Add(agent2);
				}
			}
			foreach (Agent item in list2)
			{
				MatrixFrame frame = item.Frame;
				Vec2 targetPosition = frame.origin.AsVec2;
				Vec3 targetDirection = frame.rotation.f;
				item.SetTargetPositionAndDirectionSynched(ref targetPosition, ref targetDirection);
				SetTimersOfVictoryReactionsForSingleAgent(item, _cheerReactionTimerData.MinDuration, _cheerReactionTimerData.MaxDuration, isCheeringOnRetreat: true);
			}
		}

		public void SetTimersOfVictoryReactionsOnTournamentVictoryForAgent(Agent agent, float minStartTime, float maxStartTime)
		{
			_selectedCheerActions = _midCheerActions;
			SetTimersOfVictoryReactionsForSingleAgent(agent, minStartTime, maxStartTime, isCheeringOnRetreat: false);
		}

		private void SetTimersOfVictoryReactionsForSingleAgent(Agent agent, float minStartTime, float maxStartTime, bool isCheeringOnRetreat)
		{
			if (agent.IsActive() && agent.IsHuman && agent.IsAIControlled)
			{
				RegisterAgentForCheerCheck(agent, isCheeringOnRetreat, minStartTime, maxStartTime);
			}
		}

		private void ChooseWeaponToCheerWithCheerAndUpdateTimer(Agent cheerAgent, out bool resetTimer)
		{
			resetTimer = false;
			if (cheerAgent.GetCurrentActionType(1) == Agent.ActionCodeType.EquipUnequip)
			{
				return;
			}
			EquipmentIndex primaryWieldedItemIndex = cheerAgent.GetPrimaryWieldedItemIndex();
			bool flag = primaryWieldedItemIndex != EquipmentIndex.None && !cheerAgent.Equipment[primaryWieldedItemIndex].Item.ItemFlags.HasAnyFlag(ItemFlags.DropOnAnyAction);
			if (!flag)
			{
				EquipmentIndex equipmentIndex = EquipmentIndex.None;
				for (EquipmentIndex equipmentIndex2 = EquipmentIndex.WeaponItemBeginSlot; equipmentIndex2 < EquipmentIndex.ExtraWeaponSlot; equipmentIndex2++)
				{
					if (!cheerAgent.Equipment[equipmentIndex2].IsEmpty && !cheerAgent.Equipment[equipmentIndex2].Item.ItemFlags.HasAnyFlag(ItemFlags.DropOnAnyAction))
					{
						equipmentIndex = equipmentIndex2;
						break;
					}
				}
				if (equipmentIndex == EquipmentIndex.None)
				{
					if (primaryWieldedItemIndex != EquipmentIndex.None)
					{
						cheerAgent.TryToSheathWeaponInHand(Agent.HandIndex.MainHand, Agent.WeaponWieldActionType.WithAnimation);
					}
					else
					{
						flag = true;
					}
				}
				else
				{
					cheerAgent.TryToWieldWeaponInSlot(equipmentIndex, Agent.WeaponWieldActionType.WithAnimation, isWieldedOnSpawn: false);
				}
			}
			if (flag)
			{
				ActionIndexCache[] array = _selectedCheerActions;
				if (cheerAgent.HasMount)
				{
					array = _midCheerActions;
				}
				cheerAgent.SetActionChannel(1, in array[MBRandom.RandomInt(array.Length)], ignorePriority: false, (AnimFlags)0uL);
				cheerAgent.MakeVoice(SkinVoiceManager.VoiceType.Victory, SkinVoiceManager.CombatVoiceNetworkPredictionType.NoPrediction);
				resetTimer = true;
			}
		}

		private bool CheckIfIsInRetreat()
		{
			return _isInRetreat;
		}
	}
	public delegate void PlayerTurnToChooseFormationToLeadEvent(Dictionary<int, Agent> lockedFormationIndicesAndSergeants, List<int> remainingFormationIndices);
	public delegate void AllFormationsAssignedSergeantsEvent(Dictionary<int, Agent> looselyMatchedFormationIndicesAndSergeants);
	public class AssignPlayerRoleInTeamMissionController : MissionLogic
	{
		protected readonly List<string> CharactersInPlayerSideByPriority;

		protected Queue<string> CharacterNamesInPlayerSideByPriorityQueue;

		protected List<Formation> RemainingFormationsToAssignSergeantsTo;

		protected Dictionary<int, Agent> FormationsLockedWithSergeants;

		protected Dictionary<int, Agent> FormationsWithLooselyChosenSergeants;

		public bool IsPlayerInArmy { get; }

		public bool IsPlayerGeneral { get; }

		public bool IsPlayerSergeant { get; }

		public int PlayerChosenIndex { get; protected set; }

		public event PlayerTurnToChooseFormationToLeadEvent OnPlayerTurnToChooseFormationToLead;

		public event AllFormationsAssignedSergeantsEvent OnAllFormationsAssignedSergeants;

		public AssignPlayerRoleInTeamMissionController(bool isPlayerGeneral, bool isPlayerSergeant, bool isPlayerInArmy, List<string> charactersInPlayerSideByPriority = null)
		{
			IsPlayerGeneral = isPlayerGeneral;
			IsPlayerSergeant = isPlayerSergeant;
			IsPlayerInArmy = isPlayerInArmy;
			PlayerChosenIndex = -1;
			CharactersInPlayerSideByPriority = charactersInPlayerSideByPriority;
		}

		public override void AfterStart()
		{
			Mission.Current.PlayerTeam.SetPlayerRole(IsPlayerGeneral, IsPlayerSergeant);
		}

		public override void OnTeamDeployed(Team team)
		{
			base.OnTeamDeployed(team);
			if (team != base.Mission.PlayerTeam)
			{
				return;
			}
			team.PlayerOrderController.Owner = base.Mission.InitialPlayerAgent;
			if (team.IsPlayerGeneral)
			{
				foreach (Formation item in team.FormationsIncludingEmpty)
				{
					item.PlayerOwner = base.Mission.InitialPlayerAgent;
				}
			}
			team.PlayerOrderController.SelectAllFormations();
		}

		public virtual void OnPlayerTeamDeployed()
		{
			if (!MissionGameModels.Current.BattleInitializationModel.CanPlayerSideDeployWithOrderOfBattle())
			{
				return;
			}
			Team playerTeam = Mission.Current.PlayerTeam;
			FormationsLockedWithSergeants = new Dictionary<int, Agent>();
			FormationsWithLooselyChosenSergeants = new Dictionary<int, Agent>();
			if (playerTeam.IsPlayerGeneral)
			{
				CharacterNamesInPlayerSideByPriorityQueue = new Queue<string>();
				RemainingFormationsToAssignSergeantsTo = new List<Formation>();
			}
			else
			{
				CharacterNamesInPlayerSideByPriorityQueue = ((CharactersInPlayerSideByPriority != null) ? new Queue<string>(CharactersInPlayerSideByPriority) : new Queue<string>());
				RemainingFormationsToAssignSergeantsTo = playerTeam.FormationsIncludingSpecialAndEmpty.WhereQ((Formation f) => f.CountOfUnits > 0).ToList();
				while (RemainingFormationsToAssignSergeantsTo.Count > 0 && CharacterNamesInPlayerSideByPriorityQueue.Count > 0)
				{
					string nextAgentNameToProcess = CharacterNamesInPlayerSideByPriorityQueue.Dequeue();
					Agent agent = playerTeam.ActiveAgents.FirstOrDefault((Agent aa) => aa.Character.StringId.Equals(nextAgentNameToProcess));
					if (agent != null)
					{
						if (agent == base.Mission.InitialPlayerAgent)
						{
							break;
						}
						Formation formation = ChooseFormationToLead(RemainingFormationsToAssignSergeantsTo, agent);
						if (formation != null)
						{
							FormationsLockedWithSergeants.Add(formation.Index, agent);
							RemainingFormationsToAssignSergeantsTo.Remove(formation);
						}
					}
				}
			}
			this.OnPlayerTurnToChooseFormationToLead?.Invoke(FormationsLockedWithSergeants, RemainingFormationsToAssignSergeantsTo.Select((Formation ftcsf) => ftcsf.Index).ToList());
		}

		public virtual void OnPlayerChoiceMade(int chosenIndex)
		{
			if (PlayerChosenIndex == chosenIndex)
			{
				return;
			}
			PlayerChosenIndex = chosenIndex;
			FormationsWithLooselyChosenSergeants.Clear();
			List<Formation> list = base.Mission.PlayerTeam.FormationsIncludingEmpty.WhereQ((Formation f) => f.CountOfUnits > 0 && !FormationsLockedWithSergeants.ContainsKey(f.Index)).ToList();
			if (chosenIndex != -1)
			{
				Formation item = list.FirstOrDefault((Formation fr) => fr.Index == chosenIndex);
				FormationsWithLooselyChosenSergeants.Add(chosenIndex, base.Mission.PlayerTeam.PlayerOrderController.Owner);
				list.Remove(item);
			}
			Queue<string> queue = new Queue<string>(CharacterNamesInPlayerSideByPriorityQueue);
			while (list.Count > 0 && queue.Count > 0)
			{
				string nextAgentNameToProcess = queue.Dequeue();
				Agent agent = base.Mission.PlayerTeam.ActiveAgents.FirstOrDefault((Agent aa) => aa.Character.StringId.Equals(nextAgentNameToProcess));
				if (agent != null)
				{
					Formation formation = ChooseFormationToLead(list, agent);
					if (formation != null)
					{
						FormationsWithLooselyChosenSergeants.Add(formation.Index, agent);
						list.Remove(formation);
					}
				}
			}
			if (this.OnAllFormationsAssignedSergeants != null)
			{
				this.OnAllFormationsAssignedSergeants(FormationsWithLooselyChosenSergeants);
			}
		}

		public void OnPlayerChoiceFinalized()
		{
			foreach (KeyValuePair<int, Agent> formationsLockedWithSergeant in FormationsLockedWithSergeants)
			{
				AssignSergeant(formationsLockedWithSergeant.Value.Team.GetFormation((FormationClass)formationsLockedWithSergeant.Key), formationsLockedWithSergeant.Value);
			}
			foreach (KeyValuePair<int, Agent> formationsWithLooselyChosenSergeant in FormationsWithLooselyChosenSergeants)
			{
				AssignSergeant(formationsWithLooselyChosenSergeant.Value.Team.GetFormation((FormationClass)formationsWithLooselyChosenSergeant.Key), formationsWithLooselyChosenSergeant.Value);
			}
		}

		protected virtual void AssignSergeant(Formation formationToLead, Agent sergeant)
		{
			sergeant.Formation = formationToLead;
			if (!sergeant.IsAIControlled || sergeant == base.Mission.InitialPlayerAgent)
			{
				formationToLead.PlayerOwner = sergeant;
			}
			formationToLead.Captain = sergeant;
		}

		private Formation ChooseFormationToLead(IEnumerable<Formation> formationsToChooseFrom, Agent agent)
		{
			bool hasMount = agent.HasMount;
			bool flag = agent.HasRangedWeapon();
			List<Formation> list = formationsToChooseFrom.ToList();
			while (list.Count > 0)
			{
				Formation formation = list.MaxBy((Formation ftcf) => ftcf.QuerySystem.FormationPower);
				list.Remove(formation);
				if ((flag || (!formation.QuerySystem.IsRangedFormation && !formation.QuerySystem.IsRangedCavalryFormation)) && (hasMount || (!formation.QuerySystem.IsCavalryFormation && !formation.QuerySystem.IsRangedCavalryFormation)))
				{
					return formation;
				}
			}
			return null;
		}
	}
	public class BannerBearerLogic : MissionLogic
	{
		private class FormationBannerController
		{
			public enum BannerState
			{
				Initialized,
				OnAgent,
				OnGround
			}

			public struct BannerInstance
			{
				public readonly Agent BannerBearer;

				public readonly GameEntity Entity;

				private readonly BannerState State;

				public bool IsOnGround => State == BannerState.OnGround;

				public bool IsOnAgent => State == BannerState.OnAgent;

				public BannerInstance(Agent bannerBearer, GameEntity entity, BannerState state)
				{
					BannerBearer = bannerBearer;
					Entity = entity;
					State = state;
				}
			}

			private int _lastActiveBannerBearerCount;

			private bool _requiresAgentStatUpdate;

			private BannerBearerLogic _bannerLogic;

			private Mission _mission;

			private Dictionary<Agent, (GameEntity bannerEntity, float lastDistance)> _bannerSearchers;

			private readonly Dictionary<UIntPtr, BannerInstance> _bannerInstances;

			private MBList<Agent> _nearbyAllyAgentsListCache = new MBList<Agent>();

			public Formation Formation { get; private set; }

			public ItemObject BannerItem { get; private set; }

			public bool HasBanner => BannerItem != null;

			public List<Agent> BannerBearers => (from instance in _bannerInstances.Values
				where instance.IsOnAgent
				select instance.BannerBearer).ToList();

			public List<GameEntity> BannersOnGround => (from instance in _bannerInstances.Values
				where instance.IsOnGround
				select instance.Entity).ToList();

			public int NumberOfBannerBearers => _bannerInstances.Values.Count((BannerInstance instance) => instance.IsOnAgent);

			public int NumberOfBanners => _bannerInstances.Count;

			public static float BannerSearchDistance => 9f;

			public FormationBannerController(Formation formation, ItemObject bannerItem, BannerBearerLogic bannerLogic, Mission mission)
			{
				Formation = formation;
				Formation.OnUnitAdded += OnAgentAdded;
				Formation.OnUnitRemoved += OnAgentRemoved;
				Formation.OnBeforeMovementOrderApplied += OnBeforeFormationMovementOrderApplied;
				Formation.OnAfterArrangementOrderApplied += OnAfterArrangementOrderApplied;
				_bannerInstances = new Dictionary<UIntPtr, BannerInstance>();
				_bannerSearchers = new Dictionary<Agent, (GameEntity, float)>();
				_requiresAgentStatUpdate = false;
				_lastActiveBannerBearerCount = 0;
				_bannerLogic = bannerLogic;
				_mission = mission;
				SetBannerItem(bannerItem);
			}

			public void SetBannerItem(ItemObject bannerItem)
			{
				if (bannerItem == null)
				{
					_ = 1;
				}
				else
					IsBannerItem(bannerItem);
				BannerItem = bannerItem;
			}

			public bool HasBannerEntity(GameEntity bannerEntity)
			{
				if (bannerEntity != null)
				{
					return _bannerInstances.Keys.Contains(bannerEntity.Pointer);
				}
				return false;
			}

			public bool HasBannerOnGround()
			{
				if (HasBanner)
				{
					return _bannerInstances.Any((KeyValuePair<UIntPtr, BannerInstance> instance) => instance.Value.IsOnGround);
				}
				return false;
			}

			public bool HasActiveBannerBearers()
			{
				return GetNumberOfActiveBannerBearers() > 0;
			}

			public bool IsBannerSearchingAgent(Agent agent)
			{
				return _bannerSearchers.Keys.Contains(agent);
			}

			public int GetNumberOfActiveBannerBearers()
			{
				int result = 0;
				if (HasBanner)
				{
					BattleBannerBearersModel bannerBearersModel = MissionGameModels.Current.BattleBannerBearersModel;
					result = _bannerInstances.Values.Count((BannerInstance instance) => instance.IsOnAgent && bannerBearersModel.CanBannerBearerProvideEffectToFormation(instance.BannerBearer, Formation));
				}
				return result;
			}

			public void UpdateAgentStats(bool forceUpdate = false)
			{
				if (forceUpdate || _requiresAgentStatUpdate)
				{
					Formation.ApplyActionOnEachUnit(delegate(Agent agent)
					{
						agent.UpdateAgentProperties();
						agent.MountAgent?.UpdateAgentProperties();
					});
					_requiresAgentStatUpdate = false;
				}
			}

			private void RepositionFormation()
			{
				Formation.SetMovementOrder(Formation.GetReadonlyMovementOrderReference());
				Formation.ApplyActionOnEachUnit(delegate(Agent agent)
				{
					agent.ForceUpdateCachedAndFormationValues(updateOnlyMovement: true, arrangementChangeAllowed: false);
				});
				Formation.SetHasPendingUnitPositions(hasPendingUnitPositions: false);
			}

			public void UpdateBannerSearchers()
			{
				List<GameEntity> bannersOnGround = BannersOnGround;
				if (!_bannerSearchers.IsEmpty())
				{
					List<Agent> list = new List<Agent>();
					foreach (KeyValuePair<Agent, (GameEntity, float)> searcherTuple in _bannerSearchers)
					{
						Agent key = searcherTuple.Key;
						if (key.IsActive())
						{
							if (!bannersOnGround.Any((GameEntity bannerEntity) => bannerEntity.Pointer == searcherTuple.Value.Item1.Pointer))
							{
								list.Add(key);
							}
						}
						else
						{
							list.Add(key);
						}
					}
					foreach (Agent item3 in list)
					{
						RemoveBannerSearcher(item3);
					}
				}
				foreach (GameEntity banner in bannersOnGround)
				{
					bool flag = false;
					if (_bannerSearchers.IsEmpty())
					{
						flag = true;
					}
					else
					{
						KeyValuePair<Agent, (GameEntity, float)> keyValuePair = _bannerSearchers.FirstOrDefault((KeyValuePair<Agent, (GameEntity bannerEntity, float lastDistance)> tuple) => tuple.Value.bannerEntity.Pointer == banner.Pointer);
						if (keyValuePair.Key == null)
						{
							flag = true;
						}
						else
						{
							Agent key2 = keyValuePair.Key;
							if (key2.IsActive())
							{
								GameEntity item = keyValuePair.Value.Item1;
								float item2 = keyValuePair.Value.Item2;
								float num = key2.Position.AsVec2.Distance(item.GlobalPosition.AsVec2);
								if (num <= item2 && num < BannerSearchDistance)
								{
									_bannerSearchers[key2] = (item, num);
								}
								else
								{
									RemoveBannerSearcher(key2);
									flag = true;
								}
							}
							else
							{
								RemoveBannerSearcher(key2);
								flag = true;
							}
						}
					}
					if (flag)
					{
						float distance;
						Agent agent = FindBestSearcherForBanner(banner, out distance);
						if (agent != null)
						{
							AddBannerSearcher(agent, banner, distance);
						}
					}
				}
			}

			public void UpdateBannerBearersForDeployment()
			{
				List<Agent> bannerBearers = BannerBearers;
				List<(Agent, bool)> list = new List<(Agent, bool)>();
				int num = 0;
				BattleBannerBearersModel battleBannerBearersModel = MissionGameModels.Current.BattleBannerBearersModel;
				if (battleBannerBearersModel.CanFormationDeployBannerBearers(Formation))
				{
					num = battleBannerBearersModel.GetDesiredNumberOfBannerBearersForFormation(Formation);
					foreach (Agent item2 in bannerBearers)
					{
						if (num > 0 && item2.Formation == Formation)
						{
							num--;
						}
						else
						{
							list.Add((item2, false));
						}
					}
				}
				else
				{
					foreach (Agent item3 in bannerBearers)
					{
						list.Add((item3, false));
					}
				}
				if (num > 0)
				{
					List<Agent> list2 = FindBannerBearableAgents(num);
					for (int i = 0; i < list2.Count; i++)
					{
						if (num <= 0)
						{
							break;
						}
						Agent item = list2[i];
						list.Add((item, true));
						num--;
					}
				}
				if (!list.IsEmpty())
				{
					BattleSideEnum side = Formation.Team.Side;
					_bannerLogic.AgentSpawnLogic.GetSpawnHorses(side);
					_ = _mission.PlayerTeam.Side;
					foreach (var item4 in list)
					{
						_bannerLogic.UpdateAgent(item4.Item1, item4.Item2);
					}
				}
				UpdateAgentStats();
				RepositionFormation();
				_bannerLogic.OnBannerBearersUpdated?.Invoke(Formation);
			}

			public void AddBannerEntity(GameEntity entity)
			{
				if (!_bannerInstances.ContainsKey(entity.Pointer))
				{
					_bannerInstances.Add(entity.Pointer, new BannerInstance(null, entity, BannerState.Initialized));
				}
			}

			public void RemoveBannerEntity(WeakGameEntity entity)
			{
				_bannerInstances.Remove(entity.Pointer);
				UpdateBannerSearchers();
				CheckRequiresAgentStatUpdate();
			}

			public void OnBannerEntityPickedUp(GameEntity entity, Agent agent)
			{
				_bannerInstances[entity.Pointer] = new BannerInstance(agent, entity, BannerState.OnAgent);
				if (agent.IsAIControlled)
				{
					agent.ResetEnemyCaches();
					agent.Defensiveness = 1f;
				}
				UpdateBannerSearchers();
				CheckRequiresAgentStatUpdate();
			}

			public void OnBannerEntityDropped(GameEntity entity)
			{
				_bannerInstances[entity.Pointer] = new BannerInstance(null, entity, BannerState.OnGround);
				UpdateBannerSearchers();
				CheckRequiresAgentStatUpdate();
			}

			public void OnBeforeFormationMovementOrderApplied(Formation formation, MovementOrder.MovementOrderEnum orderType)
			{
				if (formation == Formation)
				{
					UpdateBannerBearerArrangementPositions();
				}
			}

			public void OnAfterArrangementOrderApplied(Formation formation, ArrangementOrder.ArrangementOrderEnum orderEnum)
			{
				if (formation == Formation)
				{
					UpdateBannerBearerArrangementPositions();
				}
			}

			private Agent FindBestSearcherForBanner(GameEntity banner, out float distance)
			{
				distance = float.MaxValue;
				Agent result = null;
				Vec2 asVec = banner.GlobalPosition.AsVec2;
				_mission.GetNearbyAllyAgents(asVec, BannerSearchDistance, Formation.Team, _nearbyAllyAgentsListCache);
				BattleBannerBearersModel battleBannerBearersModel = MissionGameModels.Current.BattleBannerBearersModel;
				foreach (Agent item in _nearbyAllyAgentsListCache)
				{
					if (item.Formation == Formation && battleBannerBearersModel.CanAgentPickUpAnyBanner(item))
					{
						float num = item.Position.AsVec2.Distance(asVec);
						if (num < distance && !_bannerSearchers.ContainsKey(item))
						{
							result = item;
							distance = num;
						}
					}
				}
				return result;
			}

			private List<Agent> FindBannerBearableAgents(int count)
			{
				List<Agent> list = new List<Agent>();
				if (count > 0)
				{
					BattleBannerBearersModel bannerBearerModel = MissionGameModels.Current.BattleBannerBearersModel;
					foreach (IFormationUnit unitsWithoutLooseDetachedOne in Formation.UnitsWithoutLooseDetachedOnes)
					{
						if (unitsWithoutLooseDetachedOne is Agent agent2 && (agent2.Banner == null || agent2.Banner != BannerItem) && bannerBearerModel.CanAgentBecomeBannerBearer(agent2))
						{
							list.Add(agent2);
						}
					}
					list = list.OrderByDescending((Agent agent) => bannerBearerModel.GetAgentBannerBearingPriority(agent)).ToList();
				}
				return list;
			}

			private void UpdateBannerBearerArrangementPositions()
			{
				List<Agent> list = (from instance in _bannerInstances.Values
					where instance.IsOnAgent && instance.BannerBearer.Formation == Formation
					select instance.BannerBearer).ToList();
				List<FormationArrangementModel.ArrangementPosition> bannerBearerPositions = MissionGameModels.Current.FormationArrangementsModel.GetBannerBearerPositions(Formation, list.Count);
				if (bannerBearerPositions == null || bannerBearerPositions.IsEmpty())
				{
					return;
				}
				int i = 0;
				foreach (Agent item in list)
				{
					if (item == null || !item.IsAIControlled || item.Formation != Formation)
					{
						continue;
					}
					item.GetFormationFileAndRankInfo(out var fileIndex, out var rankIndex);
					for (; i < bannerBearerPositions.Count; i++)
					{
						FormationArrangementModel.ArrangementPosition arrangementPosition = bannerBearerPositions[i];
						int fileIndex2 = arrangementPosition.FileIndex;
						int rankIndex2 = arrangementPosition.RankIndex;
						bool flag = fileIndex == fileIndex2 && rankIndex == rankIndex2;
						if (!flag)
						{
							IFormationUnit unit = Formation.Arrangement.GetUnit(fileIndex2, rankIndex2);
							if (unit != null && unit is Agent agent)
							{
								if (agent == item)
								{
									flag = true;
								}
								else if (agent != Formation.Captain)
								{
									Formation.SwitchUnitLocations(item, agent);
									flag = true;
								}
							}
						}
						if (flag)
						{
							i++;
							break;
						}
					}
				}
			}

			private void OnAgentAdded(Formation formation, Agent agent)
			{
				if (Formation != formation)
				{
					return;
				}
				if (!_bannerLogic._isMissionEnded && _mission.Mode == MissionMode.Deployment && formation.Team.IsPlayerTeam && MissionGameModels.Current.BattleInitializationModel.CanPlayerSideDeployWithOrderOfBattle())
				{
					int minimumFormationTroopCountToBearBanners = MissionGameModels.Current.BattleBannerBearersModel.GetMinimumFormationTroopCountToBearBanners();
					if (formation.CountOfUnits == minimumFormationTroopCountToBearBanners && !_bannerLogic._playerFormationsRequiringUpdate.Contains(this))
					{
						_bannerLogic._playerFormationsRequiringUpdate.Add(this);
					}
				}
				else
				{
					UpdateBannerSearchers();
				}
			}

			private void OnAgentRemoved(Formation formation, Agent agent)
			{
				if (Formation != formation)
				{
					return;
				}
				if (!_bannerLogic._isMissionEnded && _mission.Mode == MissionMode.Deployment && formation.Team.IsPlayerTeam && MissionGameModels.Current.BattleInitializationModel.CanPlayerSideDeployWithOrderOfBattle())
				{
					int minimumFormationTroopCountToBearBanners = MissionGameModels.Current.BattleBannerBearersModel.GetMinimumFormationTroopCountToBearBanners();
					if (formation.CountOfUnits == minimumFormationTroopCountToBearBanners - 1 && !_bannerLogic._playerFormationsRequiringUpdate.Contains(this))
					{
						_bannerLogic._playerFormationsRequiringUpdate.Add(this);
					}
				}
				else
				{
					UpdateBannerSearchers();
				}
			}

			private void CheckRequiresAgentStatUpdate()
			{
				if (!_requiresAgentStatUpdate)
				{
					int numberOfActiveBannerBearers = GetNumberOfActiveBannerBearers();
					if ((numberOfActiveBannerBearers > 0 && _lastActiveBannerBearerCount == 0) || (numberOfActiveBannerBearers == 0 && _lastActiveBannerBearerCount > 0))
					{
						_requiresAgentStatUpdate = true;
						_lastActiveBannerBearerCount = numberOfActiveBannerBearers;
					}
				}
			}

			private void AddBannerSearcher(Agent searcher, GameEntity banner, float distance)
			{
				_bannerSearchers.Add(searcher, (banner, distance));
				searcher.HumanAIComponent?.DisablePickUpForAgentIfNeeded();
			}

			private void RemoveBannerSearcher(Agent searcher)
			{
				_bannerSearchers.Remove(searcher);
				if (searcher.IsActive())
				{
					searcher.HumanAIComponent?.DisablePickUpForAgentIfNeeded();
				}
			}
		}

		public const float DefaultBannerBearerAgentDefensiveness = 1f;

		public const float BannerSearcherUpdatePeriod = 3f;

		private readonly Dictionary<UIntPtr, FormationBannerController> _bannerToFormationMap = new Dictionary<UIntPtr, FormationBannerController>();

		private readonly Dictionary<Formation, FormationBannerController> _formationBannerData = new Dictionary<Formation, FormationBannerController>();

		private readonly Dictionary<Agent, Equipment> _initialSpawnEquipments = new Dictionary<Agent, Equipment>();

		private readonly BasicMissionTimer _bannerSearcherUpdateTimer;

		private readonly List<FormationBannerController> _playerFormationsRequiringUpdate = new List<FormationBannerController>();

		private bool _isMissionEnded;

		public IMissionAgentSpawnLogic AgentSpawnLogic { get; private set; }

		public event Action<Formation> OnBannerBearersUpdated;

		public event Action<Agent, bool> OnBannerBearerAgentUpdated;

		public BannerBearerLogic()
		{
			_bannerSearcherUpdateTimer = new BasicMissionTimer();
		}

		public bool IsFormationBanner(Formation formation, SpawnedItemEntity spawnedItem)
		{
			if (!IsBannerItem(spawnedItem.WeaponCopy.Item))
			{
				return false;
			}
			FormationBannerController formationControllerFromBannerEntity = GetFormationControllerFromBannerEntity(spawnedItem.GameEntity);
			if (formationControllerFromBannerEntity != null)
			{
				return formationControllerFromBannerEntity.Formation == formation;
			}
			return false;
		}

		public bool HasBannerOnGround(Formation formation)
		{
			return GetFormationControllerFromFormation(formation)?.HasBannerOnGround() ?? false;
		}

		public BannerComponent GetActiveBanner(Formation formation)
		{
			FormationBannerController formationControllerFromFormation = GetFormationControllerFromFormation(formation);
			if (formationControllerFromFormation != null)
			{
				if (!formationControllerFromFormation.HasActiveBannerBearers())
				{
					return null;
				}
				return formationControllerFromFormation.BannerItem.BannerComponent;
			}
			return null;
		}

		public List<Agent> GetFormationBannerBearers(Formation formation)
		{
			FormationBannerController formationControllerFromFormation = GetFormationControllerFromFormation(formation);
			if (formationControllerFromFormation != null)
			{
				return formationControllerFromFormation.BannerBearers;
			}
			return new List<Agent>();
		}

		public ItemObject GetFormationBanner(Formation formation)
		{
			ItemObject result = null;
			FormationBannerController formationControllerFromFormation = GetFormationControllerFromFormation(formation);
			if (formationControllerFromFormation != null)
			{
				result = formationControllerFromFormation.BannerItem;
			}
			return result;
		}

		public bool IsBannerSearchingAgent(Agent agent)
		{
			if (agent.Formation != null)
			{
				FormationBannerController formationControllerFromFormation = GetFormationControllerFromFormation(agent.Formation);
				if (formationControllerFromFormation != null)
				{
					return formationControllerFromFormation.IsBannerSearchingAgent(agent);
				}
			}
			return false;
		}

		public int GetMissingBannerCount(Formation formation)
		{
			FormationBannerController formationControllerFromFormation = GetFormationControllerFromFormation(formation);
			if (formationControllerFromFormation == null || formationControllerFromFormation.BannerItem == null)
			{
				return 0;
			}
			int num = MissionGameModels.Current.BattleBannerBearersModel.GetDesiredNumberOfBannerBearersForFormation(formation) - formationControllerFromFormation.NumberOfBanners;
			if (num <= 0)
			{
				return 0;
			}
			return num;
		}

		public Formation GetFormationFromBanner(SpawnedItemEntity spawnedItem)
		{
			WeakGameEntity gameEntity = spawnedItem.GameEntity;
			gameEntity = ((!gameEntity.IsValid) ? spawnedItem.GameEntityWithWorldPosition.GameEntity : gameEntity);
			return GetFormationControllerFromBannerEntity(gameEntity)?.Formation;
		}

		public void SetFormationBanner(Formation formation, ItemObject newBanner)
		{
			if (newBanner == null)
			{
				_ = 1;
			}
			else
				IsBannerItem(newBanner);
			FormationBannerController formationBannerController = GetFormationControllerFromFormation(formation);
			if (formationBannerController != null)
			{
				if (formationBannerController.BannerItem != newBanner)
				{
					formationBannerController.SetBannerItem(newBanner);
				}
			}
			else
			{
				formationBannerController = new FormationBannerController(formation, newBanner, this, base.Mission);
				_formationBannerData.Add(formation, formationBannerController);
			}
			formationBannerController.UpdateBannerBearersForDeployment();
		}

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			MissionGameModels.Current.BattleBannerBearersModel.InitializeModel(this);
			AgentSpawnLogic = base.Mission.GetMissionBehavior<DefaultBattleMissionAgentSpawnLogic>();
			base.Mission.OnItemPickUp += OnItemPickup;
			base.Mission.OnItemDrop += OnItemDrop;
			_initialSpawnEquipments.Clear();
		}

		protected override void OnEndMission()
		{
			base.OnEndMission();
			MissionGameModels.Current.BattleBannerBearersModel.FinalizeModel();
			base.Mission.OnItemPickUp -= OnItemPickup;
			base.Mission.OnItemDrop -= OnItemDrop;
			AgentSpawnLogic = null;
			_isMissionEnded = true;
		}

		public override void OnDeploymentFinished()
		{
			_initialSpawnEquipments.Clear();
			_isMissionEnded = false;
		}

		public override void OnMissionTick(float dt)
		{
			if (_bannerSearcherUpdateTimer.ElapsedTime >= 3f)
			{
				foreach (FormationBannerController value in _formationBannerData.Values)
				{
					value.UpdateBannerSearchers();
				}
				_bannerSearcherUpdateTimer.Reset();
			}
			if (base.Mission.Mode != MissionMode.Deployment || _playerFormationsRequiringUpdate.IsEmpty())
			{
				return;
			}
			foreach (FormationBannerController item in _playerFormationsRequiringUpdate)
			{
				item.UpdateBannerBearersForDeployment();
			}
			_playerFormationsRequiringUpdate.Clear();
		}

		public void OnItemPickup(Agent agent, SpawnedItemEntity spawnedItem)
		{
			if (IsBannerItem(spawnedItem.WeaponCopy.Item))
			{
				WeakGameEntity gameEntity = spawnedItem.GameEntity;
				FormationBannerController formationControllerFromBannerEntity = GetFormationControllerFromBannerEntity(gameEntity);
				if (formationControllerFromBannerEntity != null)
				{
					formationControllerFromBannerEntity.OnBannerEntityPickedUp(GameEntity.CreateFromWeakEntity(gameEntity), agent);
					formationControllerFromBannerEntity.UpdateAgentStats();
				}
			}
		}

		public void OnItemDrop(Agent agent, SpawnedItemEntity spawnedItem)
		{
			if (IsBannerItem(spawnedItem.WeaponCopy.Item))
			{
				FormationBannerController formationControllerFromBannerEntity = GetFormationControllerFromBannerEntity(spawnedItem.GameEntity);
				if (formationControllerFromBannerEntity != null)
				{
					formationControllerFromBannerEntity.OnBannerEntityDropped(GameEntity.CreateFromWeakEntity(spawnedItem.GameEntity));
					formationControllerFromBannerEntity.UpdateAgentStats();
				}
			}
		}

		public override void OnAgentRemoved(Agent affectedAgent, Agent affectorAgent, AgentState agentState, KillingBlow blow)
		{
			if (affectedAgent.Banner != null && agentState == AgentState.Routed)
			{
				RemoveBannerOfAgent(affectedAgent);
			}
		}

		public override void OnAgentPanicked(Agent affectedAgent)
		{
			if (affectedAgent.Banner != null)
			{
				affectedAgent.Mission.AddTickAction(Mission.MissionTickAction.DropItem, affectedAgent, 4, 0);
			}
		}

		public void UpdateAgent(Agent agent, bool willBecomeBannerBearer)
		{
			if (willBecomeBannerBearer)
			{
				Formation formation = agent.Formation;
				FormationBannerController formationControllerFromFormation = GetFormationControllerFromFormation(formation);
				ItemObject bannerItem = formationControllerFromFormation.BannerItem;
				if (agent.Banner != null)
				{
					RemoveBannerOfAgent(agent);
				}
				Equipment newSpawnEquipment = CreateBannerEquipmentForAgent(agent, bannerItem);
				agent.UpdateSpawnEquipmentAndRefreshVisuals(newSpawnEquipment);
				GameEntity gameEntity = GameEntity.CreateFromWeakEntity(agent.GetWeaponEntityFromEquipmentSlot(EquipmentIndex.ExtraWeaponSlot));
				AddBannerEntity(formationControllerFromFormation, gameEntity);
				formationControllerFromFormation.OnBannerEntityPickedUp(gameEntity, agent);
			}
			else if (agent.Banner != null)
			{
				RemoveBannerOfAgent(agent);
				agent.UpdateSpawnEquipmentAndRefreshVisuals(_initialSpawnEquipments[agent]);
			}
			agent.ForceUpdateCachedAndFormationValues(updateOnlyMovement: false, arrangementChangeAllowed: false);
			agent.SetIsAIPaused(isPaused: true);
			this.OnBannerBearerAgentUpdated?.Invoke(agent, willBecomeBannerBearer);
		}

		public Agent SpawnBannerBearer(IAgentOriginBase troopOrigin, bool isPlayerSide, Formation formation, bool spawnWithHorse, bool isReinforcement, int formationTroopCount, int formationTroopIndex, bool isAlarmed, bool wieldInitialWeapons, Vec3? initialPosition, Vec2? initialDirection, string specialActionSetSuffix = null, bool useTroopClassForSpawn = false)
		{
			FormationBannerController formationControllerFromFormation = GetFormationControllerFromFormation(formation);
			ItemObject bannerItem = formationControllerFromFormation.BannerItem;
			Agent agent = base.Mission.SpawnTroop(troopOrigin, isPlayerSide, hasFormation: true, spawnWithHorse, isReinforcement, formationTroopCount, formationTroopIndex, isAlarmed, wieldInitialWeapons, initialPosition, initialDirection, specialActionSetSuffix, bannerItem, formationControllerFromFormation.Formation.FormationIndex, useTroopClassForSpawn);
			agent.ForceUpdateCachedAndFormationValues(updateOnlyMovement: false, arrangementChangeAllowed: false);
			GameEntity gameEntity = GameEntity.CreateFromWeakEntity(agent.GetWeaponEntityFromEquipmentSlot(EquipmentIndex.ExtraWeaponSlot));
			AddBannerEntity(formationControllerFromFormation, gameEntity);
			formationControllerFromFormation.OnBannerEntityPickedUp(gameEntity, agent);
			return agent;
		}

		public static bool IsBannerItem(ItemObject item)
		{
			if (item != null && item.IsBannerItem)
			{
				return item.BannerComponent != null;
			}
			return false;
		}

		private void AddBannerEntity(FormationBannerController formationBannerController, GameEntity bannerEntity)
		{
			_bannerToFormationMap.Add(bannerEntity.Pointer, formationBannerController);
			formationBannerController.AddBannerEntity(bannerEntity);
		}

		private void RemoveBannerEntity(FormationBannerController formationBannerController, WeakGameEntity bannerEntity)
		{
			_bannerToFormationMap.Remove(bannerEntity.Pointer);
			formationBannerController.RemoveBannerEntity(bannerEntity);
		}

		private FormationBannerController GetFormationControllerFromFormation(Formation formation)
		{
			if (!_formationBannerData.TryGetValue(formation, out var value))
			{
				return null;
			}
			return value;
		}

		private FormationBannerController GetFormationControllerFromBannerEntity(WeakGameEntity bannerEntity)
		{
			if (_bannerToFormationMap.TryGetValue(bannerEntity.Pointer, out var value))
			{
				return value;
			}
			return null;
		}

		private Equipment CreateBannerEquipmentForAgent(Agent agent, ItemObject bannerItem)
		{
			Equipment spawnEquipment = agent.SpawnEquipment;
			if (!_initialSpawnEquipments.ContainsKey(agent))
			{
				_initialSpawnEquipments[agent] = spawnEquipment;
			}
			Equipment equipment = new Equipment(spawnEquipment);
			ItemObject bannerBearerReplacementWeapon = MissionGameModels.Current.BattleBannerBearersModel.GetBannerBearerReplacementWeapon(agent.Character);
			equipment[EquipmentIndex.WeaponItemBeginSlot] = new EquipmentElement(bannerBearerReplacementWeapon);
			for (int i = 1; i < 4; i++)
			{
				equipment[i] = default(EquipmentElement);
			}
			equipment[EquipmentIndex.ExtraWeaponSlot] = new EquipmentElement(bannerItem);
			return equipment;
		}

		private void RemoveBannerOfAgent(Agent agent)
		{
			WeakGameEntity weaponEntityFromEquipmentSlot = agent.GetWeaponEntityFromEquipmentSlot(EquipmentIndex.ExtraWeaponSlot);
			FormationBannerController formationControllerFromBannerEntity = GetFormationControllerFromBannerEntity(weaponEntityFromEquipmentSlot);
			if (formationControllerFromBannerEntity != null)
			{
				RemoveBannerEntity(formationControllerFromBannerEntity, weaponEntityFromEquipmentSlot);
				formationControllerFromBannerEntity.UpdateAgentStats();
			}
		}
	}
	public class BasicLeaveMissionLogic : MissionLogic
	{
		private readonly bool _askBeforeLeave;

		private readonly int _minRetreatDistance;

		public BasicLeaveMissionLogic()
			: this(askBeforeLeave: false)
		{
		}

		public BasicLeaveMissionLogic(bool askBeforeLeave)
			: this(askBeforeLeave, 5)
		{
		}

		public BasicLeaveMissionLogic(bool askBeforeLeave, int minRetreatDistance)
		{
			_askBeforeLeave = askBeforeLeave;
			_minRetreatDistance = minRetreatDistance;
		}

		public override bool MissionEnded(ref MissionResult missionResult)
		{
			if (base.Mission.MainAgent != null)
			{
				return !base.Mission.MainAgent.IsActive();
			}
			return false;
		}

		public override InquiryData OnEndMissionRequest(out bool canPlayerLeave)
		{
			canPlayerLeave = true;
			if (base.Mission.MainAgent != null && base.Mission.MainAgent.IsActive() && (float)_minRetreatDistance > 0f && base.Mission.IsPlayerCloseToAnEnemy(_minRetreatDistance))
			{
				canPlayerLeave = false;
				MBInformationManager.AddQuickInformation(GameTexts.FindText("str_can_not_retreat"));
			}
			else if (_askBeforeLeave)
			{
				return new InquiryData("", GameTexts.FindText("str_give_up_fight").ToString(), isAffirmativeOptionShown: true, isNegativeOptionShown: true, GameTexts.FindText("str_ok").ToString(), GameTexts.FindText("str_cancel").ToString(), base.Mission.OnEndMissionResult, null);
			}
			return null;
		}
	}
	public class BattleDeploymentMissionController : DeploymentMissionController
	{
		protected DefaultBattleMissionAgentSpawnLogic MissionAgentSpawnLogic;

		private BattleDeploymentHandler _battleDeploymentHandler;

		public BattleDeploymentMissionController(bool isPlayerAttacker)
			: base(isPlayerAttacker)
		{
		}

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			_battleDeploymentHandler = base.Mission.GetMissionBehavior<BattleDeploymentHandler>();
			MissionAgentSpawnLogic = base.Mission.GetMissionBehavior<DefaultBattleMissionAgentSpawnLogic>();
		}

		public override void OnRemoveBehavior()
		{
			base.OnRemoveBehavior();
		}

		protected override void OnAfterStart()
		{
			for (int i = 0; i < 2; i++)
			{
				MissionAgentSpawnLogic.SetSpawnTroops((BattleSideEnum)i, spawnTroops: false);
			}
			MissionAgentSpawnLogic.SetReinforcementsSpawnEnabled(value: false);
		}

		protected override void OnSetupTeamsOfSide(BattleSideEnum battleSide)
		{
			MissionAgentSpawnLogic.SetSpawnTroops(battleSide, spawnTroops: true, enforceSpawning: true);
			SetupAgentAIStatesForSide(battleSide);
			MissionAgentSpawnLogic.OnSideDeploymentOver(battleSide);
		}

		protected override void OnSetupTeamsFinished()
		{
			base.Mission.IsTeleportingAgents = true;
			foreach (Team team in base.Mission.Teams)
			{
				if (team.GeneralAgent != null)
				{
					base.Mission.GetFormationSpawnFrame(team, FormationClass.NumberOfRegularFormations, isReinforcement: false, out var spawnPosition, out var spawnDirection);
					if (spawnPosition.GetNavMesh() != UIntPtr.Zero && spawnPosition.IsValid)
					{
						team.GeneralAgent.TrySetFormationFrame(in spawnPosition, in spawnDirection);
					}
				}
			}
		}

		protected override void BeforeDeploymentFinished()
		{
			base.Mission.IsTeleportingAgents = false;
		}

		protected override void AfterDeploymentFinished()
		{
			MissionAgentSpawnLogic.SetReinforcementsSpawnEnabled(value: true);
			base.Mission.RemoveMissionBehavior(_battleDeploymentHandler);
		}
	}
	public class BattleEndLogic : MissionLogic, IBattleEndLogic
	{
		public enum ExitResult
		{
			False,
			NeedsPlayerConfirmation,
			SurrenderSiege,
			True
		}

		private IMissionAgentSpawnLogic _missionAgentSpawnLogic;

		private MissionTime _enemySideNotYetRetreatingTime;

		private MissionTime _playerSideNotYetRetreatingTime;

		private BasicMissionTimer _checkRetreatingTimer;

		private bool _isEnemySideRetreating;

		private bool _isPlayerSideRetreating;

		private bool _isEnemySideDepleted;

		private bool _isPlayerSideDepleted;

		private bool _isEnemyDefenderPulledBack;

		private bool _canCheckForEndCondition = true;

		private bool _canCheckForEndConditionSiege;

		private bool _enemyDefenderPullbackEnabled;

		private int _troopNumberNeededForEnemyDefenderPullBack;

		private bool _missionEndedMessageShown;

		private bool _victoryReactionsActivated;

		private bool _victoryReactionsActivatedForRetreating;

		private bool _scoreBoardOpenedOnceOnMissionEnd;

		public bool PlayerVictory
		{
			get
			{
				if (_isEnemySideRetreating || _isEnemySideDepleted)
				{
					return !_isEnemyDefenderPulledBack;
				}
				return false;
			}
		}

		public bool EnemyVictory
		{
			get
			{
				if (!_isPlayerSideRetreating)
				{
					return _isPlayerSideDepleted;
				}
				return true;
			}
		}

		public bool IsEnemySideRetreating => _isEnemySideRetreating;

		private bool _notificationsDisabled { get; set; }

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			_checkRetreatingTimer = new BasicMissionTimer();
			_missionAgentSpawnLogic = base.Mission.GetMissionBehavior<IMissionAgentSpawnLogic>();
		}

		public override void OnMissionTick(float dt)
		{
			if (base.Mission.IsMissionEnding)
			{
				if (_notificationsDisabled)
				{
					_scoreBoardOpenedOnceOnMissionEnd = true;
				}
				if (_missionEndedMessageShown && !_scoreBoardOpenedOnceOnMissionEnd)
				{
					if (_checkRetreatingTimer.ElapsedTime > 7f)
					{
						CheckIsEnemySideRetreatingOrOneSideDepleted();
						_checkRetreatingTimer.Reset();
						if (base.Mission.MissionResult != null && base.Mission.MissionResult.PlayerDefeated)
						{
							GameTexts.SetVariable("leave_key", HyperlinkTexts.GetKeyHyperlinkText(HotKeyManager.GetHotKeyId("Generic", 4)));
							MBInformationManager.AddQuickInformation(GameTexts.FindText("str_battle_lost_press_tab_to_view_results"));
						}
						else if (base.Mission.MissionResult != null && base.Mission.MissionResult.PlayerVictory)
						{
							if (_isEnemySideDepleted)
							{
								GameTexts.SetVariable("leave_key", HyperlinkTexts.GetKeyHyperlinkText(HotKeyManager.GetHotKeyId("Generic", 4)));
								MBInformationManager.AddQuickInformation(GameTexts.FindText("str_battle_won_press_tab_to_view_results"));
							}
						}
						else
						{
							GameTexts.SetVariable("leave_key", HyperlinkTexts.GetKeyHyperlinkText(HotKeyManager.GetHotKeyId("Generic", 4)));
							MBInformationManager.AddQuickInformation(GameTexts.FindText("str_battle_finished_press_tab_to_view_results"));
						}
					}
				}
				else if (_checkRetreatingTimer.ElapsedTime > 3f && !_scoreBoardOpenedOnceOnMissionEnd)
				{
					if (base.Mission.MissionResult != null && base.Mission.MissionResult.PlayerDefeated)
					{
						if (_isPlayerSideDepleted)
						{
							MBInformationManager.AddQuickInformation(GameTexts.FindText("str_battle_lost"));
						}
						else if (_isPlayerSideRetreating)
						{
							MBInformationManager.AddQuickInformation(GameTexts.FindText("str_friendlies_are_fleeing_you_lost"));
						}
					}
					else if (base.Mission.MissionResult != null && base.Mission.MissionResult.PlayerVictory)
					{
						if (_isEnemySideDepleted)
						{
							MBInformationManager.AddQuickInformation(GameTexts.FindText("str_battle_won"));
						}
						else if (_isEnemySideRetreating)
						{
							MBInformationManager.AddQuickInformation(GameTexts.FindText("str_enemies_are_fleeing_you_won"));
						}
					}
					else
					{
						MBInformationManager.AddQuickInformation(GameTexts.FindText("str_battle_finished"));
					}
					_missionEndedMessageShown = true;
					_checkRetreatingTimer.Reset();
				}
				if (_victoryReactionsActivated)
				{
					return;
				}
				AgentVictoryLogic missionBehavior = base.Mission.GetMissionBehavior<AgentVictoryLogic>();
				if (missionBehavior != null)
				{
					CheckIsEnemySideRetreatingOrOneSideDepleted();
					if (_isEnemySideDepleted)
					{
						missionBehavior.SetTimersOfVictoryReactionsOnBattleEnd(base.Mission.PlayerTeam.Side);
						_victoryReactionsActivated = true;
					}
					else if (_isPlayerSideDepleted)
					{
						missionBehavior.SetTimersOfVictoryReactionsOnBattleEnd(base.Mission.PlayerEnemyTeam.Side);
						_victoryReactionsActivated = true;
					}
					else if (_isEnemySideRetreating && !_victoryReactionsActivatedForRetreating)
					{
						missionBehavior.SetTimersOfVictoryReactionsOnRetreat(base.Mission.PlayerTeam.Side);
						_victoryReactionsActivatedForRetreating = true;
					}
					else if (_isPlayerSideRetreating && !_victoryReactionsActivatedForRetreating)
					{
						missionBehavior.SetTimersOfVictoryReactionsOnRetreat(base.Mission.PlayerEnemyTeam.Side);
						_victoryReactionsActivatedForRetreating = true;
					}
				}
			}
			else if (_checkRetreatingTimer.ElapsedTime > 1f)
			{
				CheckIsEnemySideRetreatingOrOneSideDepleted();
				_checkRetreatingTimer.Reset();
			}
		}

		public override void OnAgentRemoved(Agent affectedAgent, Agent affectorAgent, AgentState agentState, KillingBlow killingBlow)
		{
			if (_enemyDefenderPullbackEnabled && _troopNumberNeededForEnemyDefenderPullBack > 0 && affectedAgent.IsHuman && agentState == AgentState.Routed && affectedAgent.Team != null && affectedAgent.Team.Side == BattleSideEnum.Defender && affectedAgent.Team.Side != base.Mission.PlayerTeam.Side)
			{
				_troopNumberNeededForEnemyDefenderPullBack--;
				_isEnemyDefenderPulledBack = _troopNumberNeededForEnemyDefenderPullBack <= 0;
			}
		}

		public override bool MissionEnded(ref MissionResult missionResult)
		{
			bool flag = false;
			if (_isEnemySideDepleted && _isEnemyDefenderPulledBack)
			{
				missionResult = MissionResult.CreateDefenderPushedBack();
				flag = true;
			}
			else if (_isEnemySideRetreating || _isEnemySideDepleted)
			{
				missionResult = MissionResult.CreateSuccessful(base.Mission, _isEnemySideRetreating);
				flag = true;
			}
			else if (_isPlayerSideRetreating || _isPlayerSideDepleted)
			{
				missionResult = MissionResult.CreateDefeated(base.Mission);
				flag = true;
			}
			if (flag)
			{
				_missionAgentSpawnLogic.StopSpawner(BattleSideEnum.Attacker);
				_missionAgentSpawnLogic.StopSpawner(BattleSideEnum.Defender);
			}
			return flag;
		}

		protected override void OnEndMission()
		{
			if (!_isEnemySideRetreating)
			{
				return;
			}
			foreach (Agent activeAgent in base.Mission.PlayerEnemyTeam.ActiveAgents)
			{
				bool flag = activeAgent.GetMorale() < 0.01f;
				activeAgent.Origin?.SetRouted(!flag);
			}
		}

		public void ChangeCanCheckForEndCondition(bool canCheckForEndCondition)
		{
			_canCheckForEndCondition = canCheckForEndCondition;
		}

		public ExitResult TryExit()
		{
			if (GameNetwork.IsClientOrReplay)
			{
				return ExitResult.False;
			}
			if (base.Mission.MissionEnded || (!PlayerVictory && !EnemyVictory))
			{
				Agent mainAgent = base.Mission.MainAgent;
				if (mainAgent == null || !mainAgent.IsActive() || !base.Mission.IsPlayerCloseToAnEnemy())
				{
					if (!base.Mission.MissionEnded && !_isEnemySideRetreating)
					{
						if (Mission.Current.IsSiegeBattle && base.Mission.PlayerTeam.IsDefender)
						{
							return ExitResult.SurrenderSiege;
						}
						return ExitResult.NeedsPlayerConfirmation;
					}
					base.Mission.EndMission();
					return ExitResult.True;
				}
			}
			return ExitResult.False;
		}

		public void EnableEnemyDefenderPullBack(int neededTroopNumber)
		{
			_enemyDefenderPullbackEnabled = true;
			_troopNumberNeededForEnemyDefenderPullBack = neededTroopNumber;
		}

		public void SetNotificationDisabled(bool value)
		{
			_notificationsDisabled = value;
		}

		private void CheckIsEnemySideRetreatingOrOneSideDepleted()
		{
			if (!_canCheckForEndConditionSiege)
			{
				_canCheckForEndConditionSiege = base.Mission.GetMissionBehavior<BattleDeploymentHandler>() == null;
			}
			else
			{
				if (!_canCheckForEndCondition)
				{
					return;
				}
				BattleSideEnum side = base.Mission.PlayerTeam.Side;
				BattleSideEnum oppositeSide = side.GetOppositeSide();
				_isPlayerSideDepleted = _missionAgentSpawnLogic.IsSideDepleted(side);
				_isEnemySideDepleted = _missionAgentSpawnLogic.IsSideDepleted(oppositeSide);
				if (_isEnemySideDepleted || _isPlayerSideDepleted || base.Mission.GetMissionBehavior<HideoutPhasedMissionController>() != null)
				{
					return;
				}
				float num = _missionAgentSpawnLogic.GetReinforcementInterval(side) + 3f;
				if (base.Mission.MainAgent != null && base.Mission.MainAgent.IsPlayerControlled && base.Mission.MainAgent.IsActive())
				{
					_playerSideNotYetRetreatingTime = MissionTime.Now;
				}
				else
				{
					bool flag = true;
					foreach (Team team in base.Mission.Teams)
					{
						if (!team.IsFriendOf(base.Mission.PlayerTeam))
						{
							continue;
						}
						foreach (Agent activeAgent in team.ActiveAgents)
						{
							if (!activeAgent.IsRunningAway)
							{
								flag = false;
								break;
							}
						}
					}
					if (!flag)
					{
						_playerSideNotYetRetreatingTime = MissionTime.Now;
					}
				}
				if (_playerSideNotYetRetreatingTime.ElapsedSeconds > num)
				{
					_isPlayerSideRetreating = true;
				}
				if (oppositeSide == BattleSideEnum.Defender && _enemyDefenderPullbackEnabled)
				{
					return;
				}
				float num2 = _missionAgentSpawnLogic.GetReinforcementInterval(oppositeSide) + 3f;
				bool flag2 = true;
				foreach (Team team2 in base.Mission.Teams)
				{
					if (!team2.IsEnemyOf(base.Mission.PlayerTeam))
					{
						continue;
					}
					foreach (Agent activeAgent2 in team2.ActiveAgents)
					{
						if (!activeAgent2.IsRunningAway)
						{
							flag2 = false;
							break;
						}
					}
				}
				if (!flag2)
				{
					_enemySideNotYetRetreatingTime = MissionTime.Now;
				}
				if (_enemySideNotYetRetreatingTime.ElapsedSeconds > num2)
				{
					_isEnemySideRetreating = true;
				}
			}
		}
	}
	public class BattleHighlightsController : MissionLogic
	{
		private List<HighlightsController.HighlightType> _highlightTypes = new List<HighlightsController.HighlightType>
		{
			new HighlightsController.HighlightType("hlid_kill_last_enemy_on_battlefield", "Take No Prisoners", "grpid_incidents", -5000, 3000, 0f, float.MaxValue, isVisibilityRequired: false),
			new HighlightsController.HighlightType("hlid_win_battle_as_last_man_standing", "Last Man Standing", "grpid_incidents", -5000, 3000, 0f, float.MaxValue, isVisibilityRequired: false),
			new HighlightsController.HighlightType("hlid_wall_break_kill", "Wall Break Kill", "grpid_incidents", -5000, 3000, 0.25f, 100f, isVisibilityRequired: true)
		};

		private HighlightsController _highlightsController;

		public override void AfterStart()
		{
			_highlightsController = Mission.Current.GetMissionBehavior<HighlightsController>();
			foreach (HighlightsController.HighlightType highlightType in _highlightTypes)
			{
				HighlightsController.AddHighlightType(highlightType);
			}
		}

		public override void OnAgentRemoved(Agent affectedAgent, Agent affectorAgent, AgentState agentState, KillingBlow killingBlow)
		{
			if (affectorAgent == null || affectedAgent == null || !affectorAgent.IsHuman || !affectedAgent.IsHuman || (agentState != AgentState.Killed && agentState != AgentState.Unconscious))
			{
				return;
			}
			bool flag = affectorAgent?.Team.IsPlayerTeam ?? false;
			bool flag2 = affectorAgent?.IsMainAgent ?? false;
			HighlightsController.Highlight highlight = default(HighlightsController.Highlight);
			highlight.Start = Mission.Current.CurrentTime;
			highlight.End = Mission.Current.CurrentTime;
			bool flag3 = false;
			if ((flag2 || flag) && (killingBlow.WeaponRecordWeaponFlags.HasAllFlags(WeaponFlags.Burning) || killingBlow.WeaponRecordWeaponFlags.HasAllFlags(WeaponFlags.AffectsArea)))
			{
				highlight.HighlightType = _highlightsController.GetHighlightTypeWithId("hlid_wall_break_kill");
				flag3 = true;
			}
			bool flag4 = (affectedAgent.Team?.TeamAgents)?.Any((Agent agent) => agent.State != AgentState.Killed && agent.State != AgentState.Unconscious) ?? true;
			if (!flag4 && (flag2 || flag))
			{
				highlight.HighlightType = _highlightsController.GetHighlightTypeWithId("hlid_kill_last_enemy_on_battlefield");
				flag3 = true;
			}
			if (flag2)
			{
				MBReadOnlyList<Agent> mBReadOnlyList = affectorAgent.Team?.TeamAgents;
				if (mBReadOnlyList != null && !mBReadOnlyList.Any((Agent agent) => !agent.IsMainAgent && agent.State != AgentState.Killed && agent.State != AgentState.Unconscious) && !flag4)
				{
					highlight.HighlightType = _highlightsController.GetHighlightTypeWithId("hlid_win_battle_as_last_man_standing");
					flag3 = true;
				}
			}
			if (flag3)
			{
				_highlightsController.SaveHighlight(highlight, affectedAgent.Position);
			}
		}
	}
