	public class BattleObserverMissionLogic : MissionLogic
	{
		private int[] _builtAgentCountForSides;

		private int[] _removedAgentCountForSides;

		private List<Agent> _onAgentBuildCache = new List<Agent>();

		public IBattleObserver BattleObserver { get; private set; }

		public void SetObserver(IBattleObserver observer)
		{
			BattleObserver = observer;
			foreach (Agent item in _onAgentBuildCache)
			{
				BattleObserver.TroopNumberChanged(item.Team.Side, item.Origin.BattleCombatant, item.Character, 1);
				_builtAgentCountForSides[(int)item.Team.Side]++;
			}
			_onAgentBuildCache.Clear();
		}

		public override void EarlyStart()
		{
			base.EarlyStart();
			_builtAgentCountForSides = new int[2];
			_removedAgentCountForSides = new int[2];
		}

		public override void OnAgentBuild(Agent agent, Banner banner)
		{
			if (agent.IsHuman)
			{
				if (BattleObserver != null && agent.Team != Team.Invalid)
				{
					BattleSideEnum side = agent.Team.Side;
					BattleObserver.TroopNumberChanged(side, agent.Origin.BattleCombatant, agent.Character, 1);
					_builtAgentCountForSides[(int)side]++;
				}
				else
				{
					_onAgentBuildCache.Add(agent);
				}
			}
		}

		public override void OnAgentRemoved(Agent affectedAgent, Agent affectorAgent, AgentState agentState, KillingBlow blow)
		{
			if (affectedAgent.IsHuman && affectedAgent.Team != Team.Invalid)
			{
				BattleSideEnum side = affectedAgent.Team.Side;
				switch (agentState)
				{
				case AgentState.Routed:
					BattleObserver.TroopNumberChanged(side, affectedAgent.Origin.BattleCombatant, affectedAgent.Character, -1, 0, 0, 1);
					break;
				case AgentState.Unconscious:
					BattleObserver.TroopNumberChanged(side, affectedAgent.Origin.BattleCombatant, affectedAgent.Character, -1, 0, 1);
					break;
				case AgentState.Killed:
					BattleObserver.TroopNumberChanged(side, affectedAgent.Origin.BattleCombatant, affectedAgent.Character, -1, 1);
					break;
				default:
					throw new ArgumentOutOfRangeException("agentState", agentState, null);
				}
				_removedAgentCountForSides[(int)side]++;
				if (affectorAgent != null && affectorAgent.IsHuman && (agentState == AgentState.Unconscious || agentState == AgentState.Killed))
				{
					BattleObserver.TroopNumberChanged(affectorAgent.Team.Side, affectorAgent.Origin.BattleCombatant, affectorAgent.Character, 0, 0, 0, 0, 1);
				}
			}
		}

		public override void OnAgentTeamChanged(Team prevTeam, Team newTeam, Agent agent)
		{
			if (prevTeam == Team.Invalid && agent.IsHuman && newTeam != null && newTeam != Team.Invalid)
			{
				BattleObserver.TroopNumberChanged(agent.Team.Side, agent.Origin.BattleCombatant, agent.Character, 1);
				_builtAgentCountForSides[(int)agent.Team.Side]++;
			}
		}

		public override void OnMissionResultReady(MissionResult missionResult)
		{
			if (missionResult.PlayerVictory)
			{
				BattleObserver.BattleResultsReady();
			}
		}

		public float GetDeathToBuiltAgentRatioForSide(BattleSideEnum side)
		{
			return (float)_removedAgentCountForSides[(int)side] / (float)_builtAgentCountForSides[(int)side];
		}
	}
	public class BattlePowerCalculationLogic : MissionLogic, IBattlePowerCalculationLogic, IMissionBehavior
	{
		private Dictionary<Team, float>[] _sidePowerData;

		public bool IsTeamPowersCalculated { get; private set; }

		public BattlePowerCalculationLogic()
		{
			_sidePowerData = new Dictionary<Team, float>[2];
			for (int i = 0; i < 2; i++)
			{
				_sidePowerData[i] = new Dictionary<Team, float>();
			}
			IsTeamPowersCalculated = false;
		}

		public float GetTotalTeamPower(Team team)
		{
			if (!IsTeamPowersCalculated)
			{
				CalculateTeamPowers();
			}
			return _sidePowerData[(int)team.Side][team];
		}

		private void CalculateTeamPowers()
		{
			Mission.TeamCollection teams = base.Mission.Teams;
			foreach (Team item in teams)
			{
				_sidePowerData[(int)item.Side].Add(item, 0f);
			}
			IMissionAgentSpawnLogic missionBehavior = base.Mission.GetMissionBehavior<IMissionAgentSpawnLogic>();
			for (int i = 0; i < 2; i++)
			{
				BattleSideEnum battleSideEnum = (BattleSideEnum)i;
				IEnumerable<IAgentOriginBase> allTroopsForSide = missionBehavior.GetAllTroopsForSide(battleSideEnum);
				Dictionary<Team, float> dictionary = _sidePowerData[i];
				bool isPlayerSide = base.Mission.PlayerTeam != null && base.Mission.PlayerTeam.Side == battleSideEnum;
				foreach (IAgentOriginBase item2 in allTroopsForSide)
				{
					Team agentTeam = Mission.GetAgentTeam(item2, isPlayerSide);
					BasicCharacterObject troop = item2.Troop;
					dictionary[agentTeam] += troop.GetPower();
				}
			}
			foreach (Team item3 in teams)
			{
				item3.QuerySystem.Expire();
			}
			IsTeamPowersCalculated = true;
		}
	}
	public class BattleReinforcementsSpawnController : MissionLogic
	{
		private IMissionAgentSpawnLogic _missionAgentSpawnLogic;

		private bool[] _sideReinforcementSuspended = new bool[2];

		private bool[] _sideRequiresUpdate = new bool[2];

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			_missionAgentSpawnLogic = base.Mission.GetMissionBehavior<IMissionAgentSpawnLogic>();
		}

		public override void AfterStart()
		{
			foreach (Team team in base.Mission.Teams)
			{
				foreach (Formation item in team.FormationsIncludingEmpty)
				{
					item.OnBeforeMovementOrderApplied += OnBeforeFormationMovementOrderApplied;
				}
			}
		}

		public override void OnMissionTick(float dt)
		{
			for (int i = 0; i < 2; i++)
			{
				if (_sideRequiresUpdate[i])
				{
					UpdateSide((BattleSideEnum)i);
					_sideRequiresUpdate[i] = false;
				}
			}
		}

		protected override void OnEndMission()
		{
			foreach (Team team in base.Mission.Teams)
			{
				foreach (Formation item in team.FormationsIncludingEmpty)
				{
					item.OnBeforeMovementOrderApplied -= OnBeforeFormationMovementOrderApplied;
				}
			}
		}

		private void UpdateSide(BattleSideEnum side)
		{
			if (IsBattleSideRetreating(side))
			{
				if (!_sideReinforcementSuspended[(int)side] && _missionAgentSpawnLogic.IsSideSpawnEnabled(side))
				{
					_missionAgentSpawnLogic.StopSpawner(side);
					_sideReinforcementSuspended[(int)side] = true;
				}
			}
			else if (_sideReinforcementSuspended[(int)side])
			{
				_missionAgentSpawnLogic.StartSpawner(side);
				_sideReinforcementSuspended[(int)side] = false;
			}
		}

		private bool IsBattleSideRetreating(BattleSideEnum side)
		{
			bool result = true;
			foreach (Team team in base.Mission.Teams)
			{
				if (team.Side != side)
				{
					continue;
				}
				foreach (Formation item in team.FormationsIncludingEmpty)
				{
					if (item.CountOfUnits > 0 && item.GetReadonlyMovementOrderReference().OrderEnum != MovementOrder.MovementOrderEnum.Retreat)
					{
						result = false;
						break;
					}
				}
			}
			return result;
		}

		private void OnBeforeFormationMovementOrderApplied(Formation formation, MovementOrder.MovementOrderEnum orderEnum)
		{
			if (formation.GetReadonlyMovementOrderReference().OrderEnum == MovementOrder.MovementOrderEnum.Retreat || orderEnum == MovementOrder.MovementOrderEnum.Retreat)
			{
				int side = (int)formation.Team.Side;
				_sideRequiresUpdate[side] = true;
			}
		}
	}
	public class CasualtyHandler : MissionLogic
	{
		private readonly Dictionary<Formation, int> _casualtyCounts = new Dictionary<Formation, int>();

		private readonly Dictionary<Formation, float> _powerLoss = new Dictionary<Formation, float>();

		public override void OnAgentRemoved(Agent affectedAgent, Agent affectorAgent, AgentState agentState, KillingBlow killingBlow)
		{
			RegisterCasualty(affectedAgent);
		}

		public override void OnAgentFleeing(Agent affectedAgent)
		{
			RegisterCasualty(affectedAgent);
		}

		public int GetCasualtyCountOfFormation(Formation formation)
		{
			if (!_casualtyCounts.TryGetValue(formation, out var value))
			{
				value = 0;
				_casualtyCounts[formation] = 0;
			}
			return value;
		}

		public float GetCasualtyPowerLossOfFormation(Formation formation)
		{
			if (!_powerLoss.TryGetValue(formation, out var value))
			{
				value = 0f;
				_powerLoss[formation] = 0f;
			}
			return value;
		}

		private void RegisterCasualty(Agent agent)
		{
			Formation formation = agent.Formation;
			if (formation != null)
			{
				if (_casualtyCounts.ContainsKey(formation))
				{
					_casualtyCounts[formation]++;
				}
				else
				{
					_casualtyCounts[formation] = 1;
				}
				if (_powerLoss.ContainsKey(formation))
				{
					_powerLoss[formation] += agent.Character.GetPower();
				}
				else
				{
					_powerLoss[formation] = agent.Character.GetPower();
				}
			}
		}
	}
	public class CustomBattleAgentLogic : MissionLogic
	{
		public override void OnAgentHit(Agent affectedAgent, Agent affectorAgent, in MissionWeapon affectorWeapon, in Blow blow, in AttackCollisionData attackCollisionData)
		{
			if (affectedAgent.Character != null && affectorAgent?.Character != null && affectedAgent.State == AgentState.Active)
			{
				bool isFatal = affectedAgent.Health - (float)blow.InflictedDamage < 1f;
				bool isTeamKill = affectedAgent.Team.Side == affectorAgent.Team.Side;
				affectorAgent.Origin.OnScoreHit(affectedAgent.Character, affectorAgent.Formation?.Captain?.Character, blow.InflictedDamage, isFatal, isTeamKill, affectorWeapon.CurrentUsageItem);
			}
		}

		public override void OnAgentRemoved(Agent affectedAgent, Agent affectorAgent, AgentState agentState, KillingBlow killingBlow)
		{
			if ((affectorAgent == null && affectedAgent.IsMount && agentState == AgentState.Routed) || affectedAgent.Origin == null)
			{
				return;
			}
			switch (agentState)
			{
			case AgentState.Unconscious:
				affectedAgent.Origin.SetWounded();
				if (affectedAgent == base.Mission.MainAgent)
				{
					BecomeGhost();
				}
				break;
			case AgentState.Killed:
				affectedAgent.Origin.SetKilled();
				break;
			default:
				affectedAgent.Origin.SetRouted(isOrderRetreat: false);
				break;
			}
		}

		private void BecomeGhost()
		{
			Agent leader = base.Mission.PlayerEnemyTeam.Leader;
			if (leader != null && leader.IsActive())
			{
				leader.Controller = AgentControllerType.AI;
			}
			Agent mainAgent = base.Mission.MainAgent;
			if (mainAgent != null && mainAgent.IsActive())
			{
				base.Mission.MainAgent.Controller = AgentControllerType.AI;
			}
		}
	}
	public class DefaultBattleMissionAgentSpawnLogic : MissionLogic, IBattleMissionAgentSpawnLogic, IMissionAgentSpawnLogic, IMissionBehavior
