				return DefenderActivePhase;
			case BattleSideEnum.Attacker:
				return AttackerActivePhase;
			default:
				TaleWorlds.Library.Debug.FailedAssert("Wrong Side", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\MissionLogics\\DefaultBattleMissionAgentSpawnLogic.cs", "GetActivePhaseForSide", 958);
				return null;
			}
		}

		private MBReadOnlyList<(Team team, int deployingTroopCount, MissionFormationSpawnData[] formationSpawnData)> CollectSortedBattleSideTeamsData(MBList<(Team team, MissionFormationSpawnData[] formationSpawnData)> teamFormationsSpawnData)
		{
			MBList<(Team, int, MissionFormationSpawnData[])> mBList = new MBList<(Team, int, MissionFormationSpawnData[])>();
			foreach (var teamFormationsSpawnDatum in teamFormationsSpawnData)
			{
				int num = 0;
				MissionFormationSpawnData[] item = teamFormationsSpawnDatum.formationSpawnData;
				foreach (MissionFormationSpawnData missionFormationSpawnData in item)
				{
					num += missionFormationSpawnData.NumTroops;
				}
				if (num > 0)
				{
					mBList.Add((teamFormationsSpawnDatum.team, num, teamFormationsSpawnDatum.formationSpawnData));
				}
			}
			mBList.Sort(delegate((Team team, int deployingTroopCount, MissionFormationSpawnData[] formationSpawnData) t1, (Team team, int deployingTroopCount, MissionFormationSpawnData[] formationSpawnData) t2)
			{
				bool flag = t1.team == base.Mission.PlayerTeam || t1.team == base.Mission.PlayerEnemyTeam;
				bool flag2 = t2.team == base.Mission.PlayerTeam || t2.team == base.Mission.PlayerEnemyTeam;
				if (flag && flag2)
				{
					TaleWorlds.Library.Debug.FailedAssert("There can be only one main team in a battle side", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\MissionLogics\\DefaultBattleMissionAgentSpawnLogic.cs", "CollectSortedBattleSideTeamsData", 989);
					return 0;
				}
				if (!flag && !flag2)
				{
					if (t1.deployingTroopCount > t2.deployingTroopCount)
					{
						return -1;
					}
					if (t1.deployingTroopCount < t2.deployingTroopCount)
					{
						return 1;
					}
					return 0;
				}
				return flag ? 1 : (-1);
			});
			return mBList;
		}

		public static void ComputeDeploymentBaseOffsets(SpawnPathData sideSpawnPathData, float baseDeploymentOffset, out float deployingSideBaseOffset, out float opposingSideBaseOffset)
		{
			float num = 0f - sideSpawnPathData.PivotOffset;
			float num2 = sideSpawnPathData.PathLength - sideSpawnPathData.PivotOffset;
			if (2f * TaleWorlds.Library.MathF.Abs(baseDeploymentOffset) <= sideSpawnPathData.PathLength)
			{
				float num3 = 0f - baseDeploymentOffset;
				float num4 = num - TaleWorlds.Library.MathF.Min(baseDeploymentOffset, num3);
				float num5 = num2 - TaleWorlds.Library.MathF.Max(baseDeploymentOffset, num3);
				float num6 = 0f;
				if (num6 < num4)
				{
					num6 = num4;
				}
				else if (num6 > num5)
				{
					num6 = num5;
				}
				deployingSideBaseOffset = baseDeploymentOffset + num6;
				opposingSideBaseOffset = num3 + num6;
			}
			else if (baseDeploymentOffset <= 0f)
			{
				deployingSideBaseOffset = num;
				opposingSideBaseOffset = num2;
			}
			else
			{
				deployingSideBaseOffset = num2;
				opposingSideBaseOffset = num;
			}
			sideSpawnPathData.ClampPathOffset(ref deployingSideBaseOffset);
			sideSpawnPathData.ClampPathOffset(ref opposingSideBaseOffset);
		}

		public static void ComputeTeamDeploymentOffsets(SpawnPathData spawnPathData, float deploymentBaseOffset, float interTeamGapOffset, float[] teamOffsetRanges, out float[] teamDeployOffsets)
		{
			int num = teamOffsetRanges.Length;
			teamDeployOffsets = new float[num];
			if (!TryPlaceTeamsOneSide(spawnPathData, deploymentBaseOffset, teamOffsetRanges, interTeamGapOffset, searchBackwardFromBase: true, ref teamDeployOffsets))
			{
				float relativePathOffset = 0f - spawnPathData.PathLength;
				spawnPathData.ClampPathOffset(ref relativePathOffset);
				TryPlaceTeamsOneSide(spawnPathData, relativePathOffset, teamOffsetRanges, interTeamGapOffset, searchBackwardFromBase: false, ref teamDeployOffsets);
			}
		}

		private static bool TryPlaceTeamsOneSide(SpawnPathData spawnPathData, float deploymentBaseOffset, float[] teamOffsetRanges, float interTeamGapOffset, bool searchBackwardFromBase, ref float[] teamDeployOffsets)
		{
			int num = teamOffsetRanges.Length;
			for (int i = 0; i < num; i++)
			{
			}
			if (teamDeployOffsets == null)
			{
				teamDeployOffsets = new float[num];
			}
			else
			{
				for (int j = 0; j < teamDeployOffsets.Length; j++)
				{
					teamDeployOffsets[j] = 0f;
				}
			}
			int freeSegmentCount = spawnPathData.FreeSegmentCount;
			if (searchBackwardFromBase)
			{
				float num2 = deploymentBaseOffset;
				for (int k = 0; k < num; k++)
				{
					float num3 = teamOffsetRanges[k];
					if (num3 == 0f)
					{
						teamDeployOffsets[k] = num2;
						continue;
					}
					bool flag = false;
					for (int num4 = freeSegmentCount - 1; num4 >= 0; num4--)
					{
						var (num5, num6) = spawnPathData.GetFreeSegment(num4);
						if (!(num5 >= num2))
						{
							float num7 = num5;
							float num8 = num6;
							if (num8 > num2)
							{
								num8 = num2;
							}
							if (!(num8 - num7 < num3))
							{
								float num9 = num8;
								float num10 = num9 - num3;
								teamDeployOffsets[k] = num9;
								num2 = num10 - interTeamGapOffset;
								flag = true;
								break;
							}
						}
					}
					if (!flag)
					{
						return false;
					}
				}
				return true;
			}
			float num11 = deploymentBaseOffset;
			for (int num12 = num - 1; num12 >= 0; num12--)
			{
				float num13 = teamOffsetRanges[num12];
				if (num13 == 0f)
				{
					teamDeployOffsets[num12] = num11;
				}
				else
				{
					bool flag2 = false;
					for (int l = 0; l < freeSegmentCount; l++)
					{
						var (num14, num15) = spawnPathData.GetFreeSegment(l);
						if (!(num15 <= num11))
						{
							float num16 = num14;
							if (num16 < num11)
							{
								num16 = num11;
							}
							if (!(num15 - num16 < num13))
							{
								float num17 = num16 + num13;
								teamDeployOffsets[num12] = num17;
								num11 = num17 + interTeamGapOffset;
								flag2 = true;
								break;
							}
						}
					}
					if (!flag2)
					{
						return false;
					}
				}
			}
			return true;
		}

		private static ref float GetFlankDepthRef(FormationDeploymentFlank flank, ref float centerFlanksDepth, ref float leftFlanksDepth, ref float rightFlanksDepth)
		{
			return flank switch
			{
				FormationDeploymentFlank.Left => ref leftFlanksDepth, 
				FormationDeploymentFlank.Right => ref rightFlanksDepth, 
				_ => ref centerFlanksDepth, 
			};
		}
	}
	public abstract class DeploymentHandler : MissionLogic
	{
		protected MissionMode PreviousMissionMode;

		protected readonly bool IsPlayerAttacker;

		protected DeploymentMissionController _deploymentMissionController;

		private bool _areDeploymentPointsInitialized;

		public Team PlayerTeam => base.Mission.PlayerTeam;

		public event Action OnPlayerSideDeploymentReady;

		public event Action OnEnemySideDeploymentReady;

		public DeploymentHandler(bool isPlayerAttacker)
		{
			IsPlayerAttacker = isPlayerAttacker;
		}

		public override void OnBehaviorInitialize()
		{
			_deploymentMissionController = base.Mission.GetMissionBehavior<DeploymentMissionController>();
		}

		public override void EarlyStart()
		{
		}

		public override void AfterStart()
		{
			PreviousMissionMode = base.Mission.Mode;
			base.Mission.SetMissionMode(MissionMode.Deployment, atStart: true);
		}

		public override void OnRemoveBehavior()
		{
			base.OnRemoveBehavior();
			base.Mission.SetMissionMode(PreviousMissionMode, atStart: false);
		}

		public override void OnBattleSideDeployed(BattleSideEnum side)
		{
			if (side == base.Mission.PlayerTeam.Side)
			{
				this.OnPlayerSideDeploymentReady?.Invoke();
			}
			else
			{
				this.OnEnemySideDeploymentReady?.Invoke();
			}
		}

		public abstract void AutoDeployTeamUsingDeploymentPlan(Team playerTeam);

		public abstract void ForceUpdateAllUnits();

		public virtual void FinishDeployment()
		{
			_deploymentMissionController.FinishDeployment();
			(base.Mission ?? Mission.Current).IsTeleportingAgents = false;
		}

		public void InitializeDeploymentPoints()
		{
			if (_areDeploymentPointsInitialized)
			{
				return;
			}
			foreach (DeploymentPoint item in base.Mission.ActiveMissionObjects.FindAllWithType<DeploymentPoint>())
			{
				item.Hide();
			}
			_areDeploymentPointsInitialized = true;
		}

		public static void OrderController_OnOrderIssued_Aux(OrderType orderType, MBReadOnlyList<Formation> appliedFormations, OrderController orderController = null, params object[] delegateParams)
		{
			bool flag = false;
			foreach (Formation appliedFormation in appliedFormations)
			{
				if (appliedFormation.CountOfUnits > 0)
				{
					flag = true;
					break;
				}
			}
			if (flag)
			{
				switch (orderType)
				{
				case OrderType.None:
					TaleWorlds.Library.Debug.FailedAssert("false", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\MissionLogics\\DeploymentHandler.cs", "OrderController_OnOrderIssued_Aux", 159);
					break;
				case OrderType.Move:
				case OrderType.MoveToLineSegment:
				case OrderType.MoveToLineSegmentWithHorizontalLayout:
				case OrderType.FollowMe:
				case OrderType.FollowEntity:
				case OrderType.Advance:
				case OrderType.FallBack:
					ForcePositioning();
					ForceUpdateFormationParams();
					break;
				case OrderType.StandYourGround:
					ForcePositioning();
					ForceUpdateFormationParams();
					break;
				case OrderType.Charge:
				case OrderType.ChargeWithTarget:
					ForcePositioning();
					ForceUpdateFormationParams();
					break;
				case OrderType.Retreat:
					ForcePositioning();
					ForceUpdateFormationParams();
					break;
				case OrderType.LookAtEnemy:
				case OrderType.LookAtDirection:
					ForcePositioning();
					ForceUpdateFormationParams();
					break;
				case OrderType.ArrangementLine:
				case OrderType.ArrangementCloseOrder:
				case OrderType.ArrangementLoose:
				case OrderType.ArrangementCircular:
				case OrderType.ArrangementSchiltron:
				case OrderType.ArrangementVee:
				case OrderType.ArrangementColumn:
				case OrderType.ArrangementScatter:
					ForceUpdateFormationParams();
					break;
				case OrderType.FormCustom:
				case OrderType.FormDeep:
				case OrderType.FormWide:
				case OrderType.FormWider:
					ForceUpdateFormationParams();
					break;
				case OrderType.Mount:
				case OrderType.Dismount:
					ForceUpdateFormationParams();
					break;
				case OrderType.AIControlOn:
				case OrderType.AIControlOff:
					ForcePositioning();
					ForceUpdateFormationParams();
					break;
				case OrderType.Transfer:
				case OrderType.Use:
				case OrderType.AttackEntity:
					ForceUpdateFormationParams();
					break;
				case OrderType.PointDefence:
					TaleWorlds.Library.Debug.FailedAssert("will be removed", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\MissionLogics\\DeploymentHandler.cs", "OrderController_OnOrderIssued_Aux", 231);
					break;
				default:
					TaleWorlds.Library.Debug.FailedAssert("false", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\MissionLogics\\DeploymentHandler.cs", "OrderController_OnOrderIssued_Aux", 234);
					break;
				case OrderType.CohesionHigh:
				case OrderType.CohesionMedium:
				case OrderType.CohesionLow:
				case OrderType.HoldFire:
				case OrderType.FireAtWill:
					break;
				}
			}
			void ForcePositioning()
			{
				foreach (Formation appliedFormation2 in appliedFormations)
				{
					if (appliedFormation2.CountOfUnits > 0)
					{
						Vec2 direction = appliedFormation2.FacingOrder.GetDirection(appliedFormation2);
						appliedFormation2.SetPositioning(appliedFormation2.GetReadonlyMovementOrderReference().CreateNewOrderWorldPositionMT(appliedFormation2, WorldPosition.WorldPositionEnforcedCache.None), direction);
					}
				}
			}
			void ForceUpdateFormationParams()
			{
				foreach (Formation appliedFormation3 in appliedFormations)
				{
					if (appliedFormation3.CountOfUnits > 0 && (orderController == null || orderController.FormationUpdateEnabledAfterSetOrder))
					{
						MovementOrder readonlyMovementOrderReference = appliedFormation3.GetReadonlyMovementOrderReference();
						bool flag2 = false;
						if (appliedFormation3.IsPlayerTroopInFormation)
						{
							flag2 = readonlyMovementOrderReference.OrderEnum == MovementOrder.MovementOrderEnum.Follow;
						}
						bool num = readonlyMovementOrderReference.OrderEnum == MovementOrder.MovementOrderEnum.Stop;
						OrderController.TryCancelStopOrder(appliedFormation3);
						appliedFormation3.ApplyActionOnEachUnit(delegate(Agent agent)
						{
							agent.ForceUpdateCachedAndFormationValues(updateOnlyMovement: true, arrangementChangeAllowed: false);
						}, flag2 ? Mission.Current.InitialPlayerAgent : null);
						appliedFormation3.SetHasPendingUnitPositions(hasPendingUnitPositions: false);
						if (num)
						{
							appliedFormation3.SetMovementOrder(MovementOrder.MovementOrderStop);
						}
					}
				}
			}
		}
	}
	public abstract class DeploymentMissionController : MissionLogic
	{
		protected readonly bool IsPlayerAttacker;

		protected BattleSideEnum PlayerSide;

		protected BattleSideEnum EnemySide;

		protected bool AfterSetupTeamsCalled;

		public bool TeamSetupOver { get; private set; }

		public event Action OnAfterSetupTeams;

		public DeploymentMissionController(bool isPlayerAttacker)
		{
			IsPlayerAttacker = isPlayerAttacker;
			PlayerSide = (IsPlayerAttacker ? BattleSideEnum.Attacker : BattleSideEnum.Defender);
			EnemySide = ((!IsPlayerAttacker) ? BattleSideEnum.Attacker : BattleSideEnum.Defender);
		}

		public override void AfterStart()
		{
			base.Mission.AllowAiTicking = false;
			OnAfterStart();
		}

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			base.Mission.AreOrderGesturesEnabled_AdditionalCondition += AreOrderGesturesEnabled_AdditionalCondition;
		}

		public void FinishDeployment()
		{
			BeforeDeploymentFinished();
			if (IsPlayerAttacker)
			{
				UnhideAgentsOfSide(BattleSideEnum.Defender);
			}
			Mission.Current.OnDeploymentFinished();
			foreach (Team team in base.Mission.Teams)
			{
				foreach (Formation item in team.FormationsIncludingSpecialAndEmpty)
				{
					if (item.CountOfUnits <= 0)
					{
						continue;
					}
					item.ApplyActionOnEachUnit(delegate(Agent agent)
					{
						if (agent.IsAIControlled)
						{
							agent.SetAlarmState(Agent.AIStateFlag.Alarmed);
							agent.SetIsAIPaused(isPaused: false);
							if (agent.GetAgentFlags().HasAnyFlag(AgentFlag.CanWieldWeapon))
							{
								agent.ResetEnemyCaches();
							}
							agent.HumanAIComponent?.SyncBehaviorParamsIfNecessary();
						}
					});
				}
			}
			Agent initialPlayerAgent = base.Mission.InitialPlayerAgent;
			initialPlayerAgent.SetDetachableFromFormation(value: true);
			initialPlayerAgent.Controller = AgentControllerType.Player;
			base.Mission.AllowAiTicking = true;
			base.Mission.DisableDying = false;
			base.Mission.SetFallAvoidSystemActive(fallAvoidActive: false);
			Mission.Current.OnAfterDeploymentFinished();
			AfterDeploymentFinished();
			base.Mission.RemoveMissionBehavior(this);
		}

		public override void OnMissionTick(float dt)
		{
			base.OnMissionTick(dt);
			if (!TeamSetupOver && base.Mission.Scene != null)
			{
				SetupTeams();
				TeamSetupOver = true;
			}
			if (TeamSetupOver && !AfterSetupTeamsCalled)
			{
				this.OnAfterSetupTeams?.Invoke();
				AfterSetupTeamsCalled = true;
			}
		}

		protected void SetupAgentAIStatesForSide(BattleSideEnum battleSide)
		{
			foreach (Team item in Mission.GetTeamsOfSide(battleSide))
			{
				foreach (Formation item2 in item.FormationsIncludingSpecialAndEmpty)
				{
					if (item2.CountOfUnits <= 0)
					{
						continue;
					}
					item2.ApplyActionOnEachUnit(delegate(Agent agent)
					{
						if (agent.IsAIControlled)
						{
							agent.SetAlarmState(Agent.AIStateFlag.None);
							agent.SetIsAIPaused(isPaused: true);
						}
					});
				}
			}
		}

		protected abstract void OnAfterStart();

		protected abstract void OnSetupTeamsOfSide(BattleSideEnum side);

		protected abstract void OnSetupTeamsFinished();

		protected abstract void BeforeDeploymentFinished();

		protected abstract void AfterDeploymentFinished();

		protected virtual void SetupAIOfEnemySide(BattleSideEnum enemySide)
		{
			Team team = ((enemySide == BattleSideEnum.Attacker) ? base.Mission.AttackerTeam : base.Mission.DefenderTeam);
			SetupAIOfEnemyTeam(team);
			Team team2 = ((enemySide == BattleSideEnum.Attacker) ? base.Mission.AttackerAllyTeam : base.Mission.DefenderAllyTeam);
			if (team2 != null)
			{
				SetupAIOfEnemyTeam(team2);
			}
		}

		protected virtual void SetupAIOfEnemyTeam(Team team)
		{
			foreach (Formation item in team.FormationsIncludingEmpty)
			{
				if (item.CountOfUnits > 0)
				{
					item.SetControlledByAI(isControlledByAI: true);
				}
			}
			team.QuerySystem.Expire();
			base.Mission.AllowAiTicking = true;
			base.Mission.ForceTickOccasionally = true;
			team.ResetTactic();
			bool isTeleportingAgents = Mission.Current.IsTeleportingAgents;
			base.Mission.IsTeleportingAgents = true;
			team.Tick(0f);
			base.Mission.IsTeleportingAgents = isTeleportingAgents;
			base.Mission.AllowAiTicking = false;
			base.Mission.ForceTickOccasionally = false;
		}

		private void SetupTeams()
		{
			Utilities.SetLoadingScreenPercentage(0.92f);
			base.Mission.DisableDying = true;
			base.Mission.SetFallAvoidSystemActive(fallAvoidActive: true);
			OnSetupTeamsOfSide(EnemySide);
			SetupAIOfEnemySide(EnemySide);
			if (IsPlayerAttacker)
			{
				HideAgentsOfSide(BattleSideEnum.Defender);
			}
			OnSetupTeamsOfSide(PlayerSide);
			Agent initialPlayerAgent = base.Mission.InitialPlayerAgent;
			initialPlayerAgent.Controller = AgentControllerType.None;
			initialPlayerAgent.SetIsAIPaused(isPaused: true);
			initialPlayerAgent.SetDetachableFromFormation(value: false);
			OnSetupTeamsFinished();
			base.Mission.AreOrderGesturesEnabled_AdditionalCondition -= AreOrderGesturesEnabled_AdditionalCondition;
			Utilities.SetLoadingScreenPercentage(0.96f);
			if (!MissionGameModels.Current.BattleInitializationModel.CanPlayerSideDeployWithOrderOfBattle())
			{
				FinishDeployment();
			}
		}

		private void HideAgentsOfSide(BattleSideEnum side)
		{
			foreach (Agent agent in base.Mission.Agents)
			{
				if (agent.IsHuman && agent.Team != null && agent.Team.Side == side)
				{
					agent.SetRenderCheckEnabled(value: false);
					agent.AgentVisuals.SetVisible(value: false);
					agent.MountAgent?.SetRenderCheckEnabled(value: false);
					agent.MountAgent?.AgentVisuals.SetVisible(value: false);
				}
			}
		}

		private void UnhideAgentsOfSide(BattleSideEnum side)
		{
			foreach (Agent agent in base.Mission.Agents)
			{
				if (agent.IsHuman && agent.Team != null && agent.Team.Side == side)
				{
					agent.SetRenderCheckEnabled(value: true);
					agent.AgentVisuals.SetVisible(value: true);
					agent.MountAgent?.SetRenderCheckEnabled(value: true);
					agent.MountAgent?.AgentVisuals.SetVisible(value: true);
				}
			}
		}

		private bool AreOrderGesturesEnabled_AdditionalCondition()
		{
			return false;
		}
	}
