	public class MissionBattleSideSpawnContext
	{
		private readonly IBattleMissionAgentSpawnLogic _spawnLogic;

		private readonly BattleSideEnum _side;

		private readonly IMissionTroopSupplier _troopSupplier;

		private BannerBearerLogic _bannerBearerLogic;

		private readonly MBArrayList<Formation> _spawnedFormations;

		private bool _spawnWithHorses;

		private float _reinforcementBatchPriority;

		private int _reinforcementQuotaRequirement;

		private int _reinforcementBatchSize;

		private int _reinforcementsSpawnedInLastBatch;

		private int _numSpawnedTroops;

		private readonly List<IAgentOriginBase> _reservedTroops = new List<IAgentOriginBase>();

		private List<(Team team, List<IAgentOriginBase> origins)> _troopOriginsToSpawnPerTeam;

		private readonly (int currentTroopIndex, int troopCount)[] _reinforcementSpawnedUnitCountPerFormation;

		private readonly Dictionary<IAgentOriginBase, int> _reinforcementTroopFormationAssignments;

		public bool TroopSpawnActive { get; private set; }

		public bool IsPlayerSide { get; }

		public bool ReinforcementSpawnActive { get; private set; }

		public bool SpawnWithHorses => _spawnWithHorses;

		public bool ReinforcementsNotifiedOnLastBatch { get; private set; }

		public int NumberOfActiveTroops => _numSpawnedTroops - _troopSupplier.NumRemovedTroops;

		public int ReinforcementQuotaRequirement => _reinforcementQuotaRequirement;

		public int ReinforcementsSpawnedInLastBatch => _reinforcementsSpawnedInLastBatch;

		public float ReinforcementBatchSize => _reinforcementBatchSize;

		public bool HasReservedTroops => _reservedTroops.Count > 0;

		public bool HasSpawnableReinforcements
		{
			get
			{
				if (ReinforcementSpawnActive && HasReservedTroops)
				{
					return ReinforcementBatchSize > 0f;
				}
				return false;
			}
		}

		public bool ForceSpawnPlayerMounted { get; private set; }

		public float ReinforcementBatchPriority => _reinforcementBatchPriority;

		public int ReservedTroopsCount => _reservedTroops.Count;

		public int GetNumberOfPlayerControllableTroops()
		{
			return _troopSupplier.GetNumberOfPlayerControllableTroops();
		}

		public MissionBattleSideSpawnContext(IBattleMissionAgentSpawnLogic spawnLogic, BattleSideEnum side, IMissionTroopSupplier troopSupplier, bool isPlayerSide, bool forceSpawnPlayerMounted = true)
		{
			_spawnLogic = spawnLogic;
			_side = side;
			_spawnWithHorses = true;
			_spawnedFormations = new MBArrayList<Formation>();
			_troopSupplier = troopSupplier;
			_reinforcementQuotaRequirement = 0;
			_reinforcementBatchSize = 0;
			_reinforcementSpawnedUnitCountPerFormation = new(int, int)[8];
			_reinforcementTroopFormationAssignments = new Dictionary<IAgentOriginBase, int>();
			IsPlayerSide = isPlayerSide;
			ReinforcementsNotifiedOnLastBatch = false;
			ForceSpawnPlayerMounted = forceSpawnPlayerMounted;
		}

		public int TryReinforcementSpawn()
		{
			int num = 0;
			if (ReinforcementSpawnActive && TroopSpawnActive && _reservedTroops.Count > 0)
			{
				int num2 = DefaultBattleMissionAgentSpawnLogic.MaxNumberOfAgentsForMission - _spawnLogic.NumberOfAgents;
				int reservedTroopQuota = GetReservedTroopQuota(0);
				if (num2 >= reservedTroopQuota)
				{
					num = SpawnTroops(1, isReinforcement: true);
					if (num > 0)
					{
						_reinforcementQuotaRequirement -= reservedTroopQuota;
						if (_reservedTroops.Count >= _reinforcementBatchSize)
						{
							_reinforcementQuotaRequirement += GetReservedTroopQuota(_reinforcementBatchSize - 1);
						}
						_reinforcementBatchPriority /= 2f;
					}
				}
			}
			_reinforcementsSpawnedInLastBatch += num;
			return num;
		}

		public void GetTeamFormationsSpawnData(out MBList<(Team team, MissionFormationSpawnData[] formationSpawnData)> teamFormationsSpawnData)
		{
			Mission mission = Mission.Current;
			teamFormationsSpawnData = new MBList<(Team, MissionFormationSpawnData[])>();
			foreach (Team item2 in mission.Teams.Where((Team t) => t.Side == _side && t == mission.PlayerTeam).Concat(mission.Teams.Where((Team t) => t.Side == _side && t != mission.PlayerTeam)))
			{
				if (item2.Side == _side)
				{
					MissionFormationSpawnData[] array = new MissionFormationSpawnData[11];
					for (int i = 0; i < array.Length; i++)
					{
						array[i].FootTroopCount = 0;
						array[i].MountedTroopCount = 0;
					}
					teamFormationsSpawnData.Add((item2, array));
				}
			}
			foreach (IAgentOriginBase reservedTroop in _reservedTroops)
			{
				FormationClass agentTroopClass = Mission.Current.GetAgentTroopClass(_side, reservedTroop.Troop);
				bool isPlayerSide = _side == Mission.Current.PlayerTeam.Side;
				Team troopTeam = Mission.GetAgentTeam(reservedTroop, isPlayerSide);
				MissionFormationSpawnData[] item = teamFormationsSpawnData.FirstOrDefault(((Team team, MissionFormationSpawnData[] formationSpawnData) tf) => tf.team == troopTeam).formationSpawnData;
				if (reservedTroop.Troop.HasMount() && SpawnWithHorses)
				{
					item[(int)agentTroopClass].MountedTroopCount++;
				}
				else
				{
					item[(int)agentTroopClass].FootTroopCount++;
				}
			}
		}

		public void ReserveTroops(int number)
		{
			if (number > 0 && _troopSupplier.AnyTroopRemainsToBeSupplied)
			{
				_reservedTroops.AddRange(_troopSupplier.SupplyTroops(number));
			}
		}

		public BasicCharacterObject GetGeneralCharacter()
		{
			return _troopSupplier.GetGeneralCharacter();
		}

		public bool CheckReinforcementBatch()
		{
			MissionSpawnPhase missionSpawnPhase = null;
			missionSpawnPhase = ((_side != 0) ? _spawnLogic.AttackerActivePhase : _spawnLogic.DefenderActivePhase);
			_reinforcementsSpawnedInLastBatch = 0;
			ReinforcementsNotifiedOnLastBatch = false;
			int val = 0;
			MissionSpawnSettings spawnSettings = _spawnLogic.SpawnSettings;
			switch (spawnSettings.ReinforcementTroopsSpawnMethod)
			{
			case MissionSpawnSettings.ReinforcementSpawnMethod.Balanced:
				val = ComputeBalancedBatch(missionSpawnPhase);
				break;
			case MissionSpawnSettings.ReinforcementSpawnMethod.Wave:
				val = ComputeWaveBatch(missionSpawnPhase);
				break;
			case MissionSpawnSettings.ReinforcementSpawnMethod.Fixed:
				val = ComputeFixedBatch(missionSpawnPhase);
				break;
			}
			val = Math.Min(val, missionSpawnPhase.RemainingSpawnNumber);
			val -= _reservedTroops.Count;
			if (val > 0)
			{
				int count = _reservedTroops.Count;
				ReserveTroops(val);
				if (count < _reinforcementBatchSize)
				{
					int num = Math.Min(_reservedTroops.Count, _reinforcementBatchSize);
					for (int i = count; i < num; i++)
					{
						_reinforcementQuotaRequirement += GetReservedTroopQuota(i);
					}
				}
			}
			_reinforcementBatchPriority = _reservedTroops.Count;
			bool flag = false;
			flag = ((spawnSettings.ReinforcementTroopsSpawnMethod != MissionSpawnSettings.ReinforcementSpawnMethod.Wave) ? (_reservedTroops.Count > 0 && (_reservedTroops.Count >= _reinforcementBatchSize || missionSpawnPhase.RemainingSpawnNumber <= _reinforcementBatchSize)) : (_reservedTroops.Count > 0));
			ReinforcementSpawnActive = flag;
			if (ReinforcementSpawnActive)
			{
				ResetReinforcementSpawnedUnitCountsPerFormation();
				foreach (Team team in Mission.Current.Teams)
				{
					if (team.Side == _side)
					{
						_spawnLogic.DeploymentPlan.UpdateReinforcementPlan(team);
					}
				}
			}
			return ReinforcementSpawnActive;
		}

		public IEnumerable<IAgentOriginBase> GetAllTroops()
		{
			return _troopSupplier.GetAllTroops();
		}

		public int SpawnTroops(int number, bool isReinforcement)
		{
			if (number <= 0)
			{
				return 0;
			}
			List<IAgentOriginBase> list = new List<IAgentOriginBase>();
			int num = TaleWorlds.Library.MathF.Min(_reservedTroops.Count, number);
			if (num > 0)
			{
				for (int i = 0; i < num; i++)
				{
					IAgentOriginBase item = _reservedTroops[i];
					list.Add(item);
				}
				_reservedTroops.RemoveRange(0, num);
			}
			int numberToAllocate = number - num;
			list.AddRange(_troopSupplier.SupplyTroops(numberToAllocate));
			Mission current = Mission.Current;
			if (_troopOriginsToSpawnPerTeam == null)
			{
				_troopOriginsToSpawnPerTeam = new List<(Team, List<IAgentOriginBase>)>();
				foreach (Team team in current.Teams)
				{
					bool flag = team.Side == current.PlayerTeam.Side;
					if ((IsPlayerSide && flag) || (!IsPlayerSide && !flag))
					{
						_troopOriginsToSpawnPerTeam.Add((team, new List<IAgentOriginBase>()));
					}
				}
			}
			else
			{
				foreach (var item2 in _troopOriginsToSpawnPerTeam)
				{
					item2.origins.Clear();
				}
			}
			int num2 = 0;
			foreach (IAgentOriginBase item3 in list)
			{
				Team agentTeam = Mission.GetAgentTeam(item3, IsPlayerSide);
				foreach (var item4 in _troopOriginsToSpawnPerTeam)
				{
					if (agentTeam == item4.team)
					{
						num2++;
						item4.origins.Add(item3);
					}
				}
			}
			int num3 = 0;
			List<IAgentOriginBase> list2 = new List<IAgentOriginBase>();
			foreach (var item5 in _troopOriginsToSpawnPerTeam)
			{
				if (item5.origins.IsEmpty())
				{
					continue;
				}
				int num4 = 0;
				List<(IAgentOriginBase, int)> list3 = null;
				if (isReinforcement)
				{
					list3 = new List<(IAgentOriginBase, int)>();
					foreach (IAgentOriginBase item6 in item5.origins)
					{
						_reinforcementTroopFormationAssignments.TryGetValue(item6, out var value);
						list3.Add((item6, value));
					}
				}
				else
				{
					list3 = MissionGameModels.Current.BattleSpawnModel.GetInitialSpawnAssignments(_side, item5.origins);
				}
				for (int j = 0; j < 8; j++)
				{
					int num5 = 0;
					int num6 = 0;
					list2.Clear();
					IAgentOriginBase agentOriginBase = null;
					foreach (var (agentOriginBase2, num7) in list3)
					{
						if (j != num7)
						{
							continue;
						}
						if (agentOriginBase2.Troop == Game.Current.PlayerTroop)
						{
							agentOriginBase = agentOriginBase2;
							continue;
						}
						if (agentOriginBase2.Troop.HasMount())
						{
							num5++;
						}
						else
						{
							num6++;
						}
						list2.Add(agentOriginBase2);
					}
					if (agentOriginBase != null)
					{
						if (agentOriginBase.Troop.HasMount())
						{
							num5++;
						}
						else
						{
							num6++;
						}
						list2.Add(agentOriginBase);
					}
					int count = list2.Count;
					if (count <= 0)
					{
						continue;
					}
					bool isMounted = _spawnWithHorses && DefaultMissionDeploymentPlan.HasSignificantMountedTroops(num6, num5);
					int num8 = 0;
					int num9 = count;
					if (ReinforcementSpawnActive)
					{
						num8 = _reinforcementSpawnedUnitCountPerFormation[j].currentTroopIndex;
						num9 = _reinforcementSpawnedUnitCountPerFormation[j].troopCount;
					}
					Formation formation = item5.team.GetFormation((FormationClass)j);
					if (!formation.HasBeenPositioned)
					{
						formation.BeginSpawn(num9, isMounted);
						current.SetFormationPositioningFromDeploymentPlan(formation);
						_spawnedFormations.Add(formation);
					}
					foreach (IAgentOriginBase item7 in list2)
					{
						if (!item7.Troop.IsHero && _bannerBearerLogic != null && current.Mode != MissionMode.Deployment && _bannerBearerLogic.GetMissingBannerCount(formation) > 0)
						{
							_bannerBearerLogic.SpawnBannerBearer(item7, IsPlayerSide, formation, _spawnWithHorses, isReinforcement, num9, num8, isAlarmed: true, wieldInitialWeapons: true, null, null, null, current.IsSallyOutBattle);
						}
						else
						{
							bool spawnWithHorse = (item7.Troop.IsPlayerCharacter && ForceSpawnPlayerMounted) || _spawnWithHorses;
							current.SpawnTroop(item7, IsPlayerSide, hasFormation: true, spawnWithHorse, isReinforcement, num9, num8, isAlarmed: true, wieldInitialWeapons: true, null, null, null, null, formation.FormationIndex, current.IsSallyOutBattle);
						}
						_numSpawnedTroops++;
						num8++;
						num4++;
					}
					if (ReinforcementSpawnActive)
					{
						_reinforcementSpawnedUnitCountPerFormation[j].currentTroopIndex = num8;
					}
				}
				if (num4 > 0)
				{
					item5.team.QuerySystem.Expire();
				}
				num3 += num4;
				foreach (Formation item8 in item5.team.FormationsIncludingEmpty)
				{
					if (item8.CountOfUnits > 0 && item8.IsSpawning)
					{
						item8.EndSpawn();
					}
				}
			}
			return num3;
		}

		public void SetSpawnWithHorses(bool spawnWithHorses)
		{
			_spawnWithHorses = spawnWithHorses;
		}

		private int ComputeBalancedBatch(MissionSpawnPhase activePhase)
		{
			int result = 0;
			if (activePhase != null && activePhase.RemainingSpawnNumber > 0)
			{
				MissionSpawnSettings spawnSettings = _spawnLogic.SpawnSettings;
				int reinforcementBatchSize = _reinforcementBatchSize;
				_reinforcementBatchSize = (int)((float)_spawnLogic.BattleSize * spawnSettings.ReinforcementBatchPercentage);
				if (reinforcementBatchSize != _reinforcementBatchSize)
				{
					UpdateReinforcementQuotaRequirement(reinforcementBatchSize);
				}
				int num = activePhase.TotalSpawnNumber - activePhase.InitialSpawnedNumber;
				result = TaleWorlds.Library.MathF.Max(1, _reservedTroops.Count + (int)((float)num * spawnSettings.DesiredReinforcementPercentage));
				result = TaleWorlds.Library.MathF.Min(result, activePhase.InitialSpawnedNumber - NumberOfActiveTroops);
			}
			return result;
		}

		private int ComputeFixedBatch(MissionSpawnPhase activePhase)
		{
			int result = 0;
			if (activePhase != null && activePhase.RemainingSpawnNumber > 0)
			{
				MissionSpawnSettings spawnSettings = _spawnLogic.SpawnSettings;
				float num = ((_side == BattleSideEnum.Defender) ? spawnSettings.DefenderReinforcementBatchPercentage : spawnSettings.AttackerReinforcementBatchPercentage);
				int reinforcementBatchSize = _reinforcementBatchSize;
				_reinforcementBatchSize = (int)((float)_spawnLogic.TotalSpawnNumber * num);
				if (reinforcementBatchSize != _reinforcementBatchSize)
				{
					UpdateReinforcementQuotaRequirement(reinforcementBatchSize);
				}
				result = TaleWorlds.Library.MathF.Max(1, _reinforcementBatchSize);
			}
			return result;
		}

		private int ComputeWaveBatch(MissionSpawnPhase activePhase)
		{
			int result = 0;
			if (activePhase != null && activePhase.RemainingSpawnNumber > 0 && _reservedTroops.IsEmpty())
			{
				MissionSpawnSettings spawnSettings = _spawnLogic.SpawnSettings;
				int reinforcementBatchSize = _reinforcementBatchSize;
				int num = (_reinforcementBatchSize = (int)Math.Max(1f, (float)activePhase.InitialSpawnedNumber * spawnSettings.ReinforcementWavePercentage));
				if (reinforcementBatchSize != _reinforcementBatchSize)
				{
					UpdateReinforcementQuotaRequirement(reinforcementBatchSize);
				}
				if (activePhase.InitialSpawnedNumber - activePhase.NumberActiveTroops >= num)
				{
					result = num;
				}
			}
			return result;
		}

		public void SetBannerBearerLogic(BannerBearerLogic bannerBearerLogic)
		{
			_bannerBearerLogic = bannerBearerLogic;
		}

		private void UpdateReinforcementQuotaRequirement(int previousBatchSize)
		{
			if (_reinforcementBatchSize < previousBatchSize)
			{
				for (int num = TaleWorlds.Library.MathF.Min(_reservedTroops.Count - 1, previousBatchSize - 1); num >= _reinforcementBatchSize; num--)
				{
					_reinforcementQuotaRequirement -= GetReservedTroopQuota(num);
				}
			}
			else if (_reinforcementBatchSize > previousBatchSize)
			{
				int num2 = TaleWorlds.Library.MathF.Min(_reservedTroops.Count - 1, _reinforcementBatchSize - 1);
				for (int i = previousBatchSize; i <= num2; i++)
				{
					_reinforcementQuotaRequirement += GetReservedTroopQuota(i);
				}
			}
		}

		public void SetReinforcementsNotifiedOnLastBatch(bool value)
		{
			ReinforcementsNotifiedOnLastBatch = value;
		}

		private void ResetReinforcementSpawnedUnitCountsPerFormation()
		{
			for (int i = 0; i < 8; i++)
			{
				_reinforcementSpawnedUnitCountPerFormation[i].currentTroopIndex = 0;
				_reinforcementSpawnedUnitCountPerFormation[i].troopCount = 0;
			}
			_reinforcementTroopFormationAssignments.Clear();
			foreach (var reinforcementAssignment in MissionGameModels.Current.BattleSpawnModel.GetReinforcementAssignments(_side, _reservedTroops))
			{
				int item = reinforcementAssignment.formationIndex;
				_reinforcementTroopFormationAssignments.Add(reinforcementAssignment.origin, reinforcementAssignment.formationIndex);
				_reinforcementSpawnedUnitCountPerFormation[item].troopCount++;
			}
		}

		public void SetSpawnTroops(bool spawnTroops)
		{
			TroopSpawnActive = spawnTroops;
		}

		private int GetReservedTroopQuota(int index)
		{
			if (!_spawnWithHorses || !_reservedTroops[index].Troop.IsMounted)
			{
				return 1;
			}
			return 2;
		}

		public void OnInitialSpawnOver()
		{
			foreach (Formation spawnedFormation in _spawnedFormations)
			{
				spawnedFormation.EndSpawn();
			}
		}
	}
	public class MissionBoundaryCrossingHandler : MissionLogic
	{
		private float _leewayTime;

		private List<Agent> _agentsToPunish;

		private Dictionary<Agent, MissionTimer> _agentTimers;

		private MissionTimer _mainAgentLeaveTimer;

		private IVehicleHandler _vehicleHandler;

		public event Action<float, float> StartTime;

		public event Action StopTime;

		public event Action<float> TimeCount;

		public MissionBoundaryCrossingHandler(float leewayTime = 10f)
		{
			_leewayTime = leewayTime;
		}

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			if (GameNetwork.IsSessionActive)
			{
				AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode.Add);
			}
			if (GameNetwork.IsServer)
			{
				_agentTimers = new Dictionary<Agent, MissionTimer>();
				_agentsToPunish = new List<Agent>();
			}
			_vehicleHandler = base.Mission.GetMissionBehavior<IVehicleHandler>();
		}

		public override void OnRemoveBehavior()
		{
			if (GameNetwork.IsSessionActive)
			{
				AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode.Remove);
			}
			base.OnRemoveBehavior();
		}

		private void AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode mode)
		{
			GameNetwork.NetworkMessageHandlerRegisterer networkMessageHandlerRegisterer = new GameNetwork.NetworkMessageHandlerRegisterer(mode);
			if (GameNetwork.IsClient)
			{
				networkMessageHandlerRegisterer.Register<SetBoundariesState>(HandleServerEventSetPeerBoundariesState);
			}
		}

		private void OnAgentWentOut(Agent agent, float startTimeInSeconds)
		{
			MissionTimer missionTimer = (GameNetwork.IsClient ? MissionTimer.CreateSynchedTimerClient(startTimeInSeconds, _leewayTime) : new MissionTimer(_leewayTime));
			if (GameNetwork.IsServer)
			{
				_agentTimers.Add(agent, missionTimer);
				NetworkCommunicator networkCommunicator = agent.MissionPeer?.GetNetworkPeer();
				if (networkCommunicator != null && !networkCommunicator.IsServerPeer)
				{
					GameNetwork.BeginModuleEventAsServer(networkCommunicator);
					GameNetwork.WriteMessage(new SetBoundariesState(isOutside: true, missionTimer.GetStartTime().NumberOfTicks));
					GameNetwork.EndModuleEventAsServer();
				}
			}
			if (base.Mission.MainAgent == agent)
			{
				_mainAgentLeaveTimer = missionTimer;
				this.StartTime?.Invoke(_leewayTime, 0f);
				MatrixFrame cameraFrame = Mission.Current.GetCameraFrame();
				Vec3 position = cameraFrame.origin + cameraFrame.rotation.u;
				if (Mission.Current.Mode == MissionMode.Battle)
				{
					MBSoundEvent.PlaySound(SoundEvent.GetEventIdFromString("event:/alerts/report/out_of_map"), position);
				}
			}
		}

		private void OnAgentWentInOrRemoved(Agent agent, bool isAgentRemoved)
		{
			if (GameNetwork.IsServer)
			{
				_agentTimers.Remove(agent);
				if (!isAgentRemoved)
				{
					NetworkCommunicator networkCommunicator = agent.MissionPeer?.GetNetworkPeer();
					if (networkCommunicator != null && !networkCommunicator.IsServerPeer)
					{
						GameNetwork.BeginModuleEventAsServer(networkCommunicator);
						GameNetwork.WriteMessage(new SetBoundariesState(isOutside: false));
						GameNetwork.EndModuleEventAsServer();
					}
				}
			}
			if (base.Mission.MainAgent == agent)
			{
				_mainAgentLeaveTimer = null;
				this.StopTime?.Invoke();
			}
		}

		private void HandleAgentPunishmentsServer()
		{
			foreach (Agent item in _agentsToPunish)
			{
				Blow b = new Blow(item.Index);
				b.WeaponRecord.FillAsMeleeBlow(null, null, -1, 0);
				b.DamageType = DamageTypes.Blunt;
				b.BaseMagnitude = 10000f;
				b.WeaponRecord.WeaponClass = WeaponClass.Undefined;
				b.GlobalPosition = item.Position;
				b.DamagedPercentage = 1f;
				item.Die(b);
			}
			_agentsToPunish.Clear();
		}

		private void DecideOrHandleAgentPunishment(Agent agent)
		{
			if (GameNetwork.IsSessionActive)
			{
				if (GameNetwork.IsServer)
				{
					_agentsToPunish.Add(agent);
					if (agent.MountAgent != null)
					{
						_agentsToPunish.Add(agent.MountAgent);
					}
				}
			}
			else
			{
				base.Mission.RetreatMission();
			}
		}

		public override void OnClearScene()
		{
			if (GameNetwork.IsServer)
			{
				foreach (Agent item in _agentTimers.Keys.ToList())
				{
					OnAgentWentInOrRemoved(item, isAgentRemoved: true);
				}
				return;
			}
			if (_mainAgentLeaveTimer != null)
			{
				if (base.Mission.MainAgent != null)
				{
					OnAgentWentInOrRemoved(base.Mission.MainAgent, isAgentRemoved: true);
				}
				else
				{
					_mainAgentLeaveTimer = null;
				}
			}
		}

		public override void OnAgentRemoved(Agent affectedAgent, Agent affectorAgent, AgentState agentState, KillingBlow blow)
		{
			OnAgentWentInOrRemoved(affectedAgent, isAgentRemoved: true);
		}

		public override void OnMissionTick(float dt)
		{
			base.OnMissionTick(dt);
			if (GameNetwork.IsServer)
			{
				for (int num = base.Mission.Agents.Count - 1; num >= 0; num--)
				{
					Agent agent = base.Mission.Agents[num];
					if (agent.MissionPeer != null)
					{
						TickForAgentAsServer(agent);
					}
				}
				HandleAgentPunishmentsServer();
			}
			else if (!GameNetwork.IsSessionActive && Agent.Main != null)
			{
				TickForMainAgent();
			}
			if (_mainAgentLeaveTimer != null)
			{
				_mainAgentLeaveTimer.Check();
				float obj = 1f - _mainAgentLeaveTimer.GetRemainingTimeInSeconds(synched: true) / _leewayTime;
				this.TimeCount?.Invoke(obj);
			}
		}

		private void TickForMainAgent()
		{
			WeakGameEntity vehicleEntity;
			bool isAgentOutside = ((_vehicleHandler == null || !_vehicleHandler.IsAgentInVehicle(Agent.Main, out vehicleEntity)) ? (!base.Mission.IsPositionInsideBoundaries(Agent.Main.Position.AsVec2)) : (!base.Mission.IsPositionInsideBoundaries(vehicleEntity.GlobalPosition.AsVec2)));
			bool isTimerActiveForAgent = _mainAgentLeaveTimer != null;
			HandleAgentStateChange(Agent.Main, isAgentOutside, isTimerActiveForAgent, _mainAgentLeaveTimer);
		}

		private void TickForAgentAsServer(Agent agent)
		{
			bool isAgentOutside = !base.Mission.IsPositionInsideBoundaries(agent.Position.AsVec2);
			bool flag = _agentTimers.ContainsKey(agent);
			HandleAgentStateChange(agent, isAgentOutside, flag, flag ? _agentTimers[agent] : null);
		}

		private void HandleAgentStateChange(Agent agent, bool isAgentOutside, bool isTimerActiveForAgent, MissionTimer timerInstance)
		{
			if (isAgentOutside && !isTimerActiveForAgent)
			{
				OnAgentWentOut(agent, 0f);
			}
			else if (!isAgentOutside && isTimerActiveForAgent)
			{
				OnAgentWentInOrRemoved(agent, isAgentRemoved: false);
			}
			else if (isAgentOutside && timerInstance.Check())
			{
				DecideOrHandleAgentPunishment(agent);
			}
		}

		private void HandleServerEventSetPeerBoundariesState(SetBoundariesState message)
		{
			if (message.IsOutside)
			{
				OnAgentWentOut(base.Mission.MainAgent, message.StateStartTimeInSeconds);
			}
			else
			{
				OnAgentWentInOrRemoved(base.Mission.MainAgent, isAgentRemoved: false);
			}
		}
	}
	public class MissionBoundaryPlacer : MissionLogic
	{
		public override void EarlyStart()
		{
			AddMissionBoundaries();
		}

		public void AddMissionBoundaries()
		{
			MBList<Vec2> softBoundaryPoints = MBSceneUtilities.GetSoftBoundaryPoints(base.Mission.Scene);
			if (softBoundaryPoints.Count == 0)
			{
				base.Mission.Scene.GetBoundingBox(out var min, out var max);
				float num = TaleWorlds.Library.MathF.Min(2f, max.x - min.x);
				float num2 = TaleWorlds.Library.MathF.Min(2f, max.y - min.y);
				List<Vec2> collection = new List<Vec2>
				{
					new Vec2(min.x + num, min.y + num2),
					new Vec2(max.x - num, min.y + num2),
					new Vec2(max.x - num, max.y - num2),
					new Vec2(min.x + num, max.y - num2)
				};
				softBoundaryPoints.AddRange(collection);
			}
			base.Mission.Boundaries.Add("walk_area", softBoundaryPoints);
		}
	}
	public class MissionCombatantsLogic : MissionLogic
	{
		protected readonly IEnumerable<IBattleCombatant> BattleCombatants;

		protected readonly IBattleCombatant PlayerBattleCombatant;

		protected readonly IBattleCombatant DefenderLeaderBattleCombatant;

		protected readonly IBattleCombatant AttackerLeaderBattleCombatant;

		protected readonly Mission.MissionTeamAITypeEnum TeamAIType;

		protected readonly bool IsPlayerSergeant;

		public BattleSideEnum PlayerSide
		{
			get
			{
				if (PlayerBattleCombatant == null)
				{
					return BattleSideEnum.None;
				}
				if (PlayerBattleCombatant != DefenderLeaderBattleCombatant)
				{
					return BattleSideEnum.Attacker;
				}
				return BattleSideEnum.Defender;
			}
		}

		public MissionCombatantsLogic(IEnumerable<IBattleCombatant> battleCombatants, IBattleCombatant playerBattleCombatant, IBattleCombatant defenderLeaderBattleCombatant, IBattleCombatant attackerLeaderBattleCombatant, Mission.MissionTeamAITypeEnum teamAIType, bool isPlayerSergeant)
		{
			if (battleCombatants == null)
			{
				battleCombatants = new IBattleCombatant[2] { defenderLeaderBattleCombatant, attackerLeaderBattleCombatant };
			}
			BattleCombatants = battleCombatants;
			PlayerBattleCombatant = playerBattleCombatant;
			DefenderLeaderBattleCombatant = defenderLeaderBattleCombatant;
			AttackerLeaderBattleCombatant = attackerLeaderBattleCombatant;
			TeamAIType = teamAIType;
			IsPlayerSergeant = isPlayerSergeant;
		}

		public Banner GetBannerForSide(BattleSideEnum side)
		{
			if (side != 0)
			{
				return AttackerLeaderBattleCombatant.Banner;
			}
			return DefenderLeaderBattleCombatant.Banner;
		}

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			if (!base.Mission.Teams.IsEmpty())
			{
				throw new MBIllegalValueException("Number of teams is not 0.");
			}
			BattleSideEnum playerSide = PlayerBattleCombatant.Side;
			BattleSideEnum oppositeSide = playerSide.GetOppositeSide();
			if (playerSide == BattleSideEnum.Defender)
			{
				AddPlayerTeam(playerSide);
			}
			else
			{
				AddEnemyTeam(oppositeSide);
			}
			if (playerSide == BattleSideEnum.Attacker)
			{
				AddPlayerTeam(playerSide);
			}
			else
			{
				AddEnemyTeam(oppositeSide);
			}
			bool isNavalLandHybridMission = TeamAIType == Mission.MissionTeamAITypeEnum.NavalRaid;
			if (SupportsAllyTeamOnPlayerSide(BattleCombatants.Where((IBattleCombatant cmbt) => cmbt.Side == playerSide), PlayerBattleCombatant, IsPlayerSergeant, isNavalLandHybridMission, out var allyCombatant))
			{
				AddPlayerAllyTeam(playerSide, allyCombatant);
			}
		}

		public override void EarlyStart()
		{
			Mission.Current.MissionTeamAIType = TeamAIType;
			switch (TeamAIType)
			{
			case Mission.MissionTeamAITypeEnum.FieldBattle:
				foreach (Team team2 in Mission.Current.Teams)
				{
					team2.AddTeamAI(new TeamAIGeneral(base.Mission, team2));
				}
				break;
			case Mission.MissionTeamAITypeEnum.Siege:
				foreach (Team team3 in Mission.Current.Teams)
				{
					if (team3.Side == BattleSideEnum.Attacker)
					{
						team3.AddTeamAI(new TeamAISiegeAttacker(base.Mission, team3, 5f, 1f));
					}
					if (team3.Side == BattleSideEnum.Defender)
					{
						team3.AddTeamAI(new TeamAISiegeDefender(base.Mission, team3, 5f, 1f));
					}
				}
				break;
			case Mission.MissionTeamAITypeEnum.SallyOut:
				foreach (Team team4 in Mission.Current.Teams)
				{
					if (team4.Side == BattleSideEnum.Attacker)
					{
						team4.AddTeamAI(new TeamAISallyOutDefender(base.Mission, team4, 5f, 1f));
					}
					else
					{
						team4.AddTeamAI(new TeamAISallyOutAttacker(base.Mission, team4, 5f, 1f));
					}
				}
				break;
			}
			if (Mission.Current.Teams.Count <= 0)
			{
				return;
			}
			switch (Mission.Current.MissionTeamAIType)
			{
			case Mission.MissionTeamAITypeEnum.NoTeamAI:
				foreach (Team team5 in Mission.Current.Teams)
				{
					if (team5.HasTeamAi)
					{
						team5.AddTacticOption(new TacticCharge(team5));
					}
				}
				break;
			case Mission.MissionTeamAITypeEnum.FieldBattle:
				foreach (Team team in Mission.Current.Teams)
				{
					if (!team.HasTeamAi)
					{
						continue;
					}
					int num = BattleCombatants.Where((IBattleCombatant bc) => bc.Side == team.Side).Max((IBattleCombatant bcs) => bcs.GetTacticsSkillAmount());
					team.AddTacticOption(new TacticCharge(team));
					if ((float)num >= 20f)
					{
						team.AddTacticOption(new TacticFullScaleAttack(team));
						if (team.Side == BattleSideEnum.Defender)
						{
							team.AddTacticOption(new TacticDefensiveEngagement(team));
							team.AddTacticOption(new TacticDefensiveLine(team));
						}
						if (team.Side == BattleSideEnum.Attacker)
						{
							team.AddTacticOption(new TacticRangedHarrassmentOffensive(team));
						}
					}
					if ((float)num >= 50f)
					{
						team.AddTacticOption(new TacticFrontalCavalryCharge(team));
						if (team.Side == BattleSideEnum.Defender)
						{
							team.AddTacticOption(new TacticDefensiveRing(team));
							team.AddTacticOption(new TacticHoldChokePoint(team));
						}
						if (team.Side == BattleSideEnum.Attacker)
						{
							team.AddTacticOption(new TacticCoordinatedRetreat(team));
						}
					}
				}
				break;
			case Mission.MissionTeamAITypeEnum.Siege:
				foreach (Team team6 in Mission.Current.Teams)
				{
					if (team6.HasTeamAi)
					{
						if (team6.Side == BattleSideEnum.Attacker)
						{
							team6.AddTacticOption(new TacticBreachWalls(team6));
						}
						if (team6.Side == BattleSideEnum.Defender)
						{
							team6.AddTacticOption(new TacticDefendCastle(team6));
						}
					}
				}
				break;
			case Mission.MissionTeamAITypeEnum.SallyOut:
				foreach (Team team7 in Mission.Current.Teams)
				{
					if (team7.HasTeamAi)
					{
						if (team7.Side == BattleSideEnum.Defender)
						{
							team7.AddTacticOption(new TacticSallyOutHitAndRun(team7));
						}
						if (team7.Side == BattleSideEnum.Attacker)
						{
							team7.AddTacticOption(new TacticSallyOutDefense(team7));
						}
						team7.AddTacticOption(new TacticCharge(team7));
					}
				}
				break;
			}
			foreach (Team team8 in base.Mission.Teams)
			{
				team8.QuerySystem.Expire();
				team8.ResetTactic();
			}
		}

		public override void AfterStart()
		{
			base.Mission.SetMissionMode(MissionMode.Battle, atStart: true);
		}

		public IEnumerable<IBattleCombatant> GetAllCombatants()
		{
			foreach (IBattleCombatant battleCombatant in BattleCombatants)
			{
				yield return battleCombatant;
			}
		}

		protected void AddPlayerTeam(BattleSideEnum playerSide)
		{
			base.Mission.Teams.Add(playerSide, PlayerBattleCombatant.PrimaryColorPair.Item1, PlayerBattleCombatant.PrimaryColorPair.Item2, PlayerBattleCombatant.Banner);
			base.Mission.PlayerTeam = ((playerSide == BattleSideEnum.Attacker) ? base.Mission.AttackerTeam : base.Mission.DefenderTeam);
		}

		protected void AddEnemyTeam(BattleSideEnum enemySide)
		{
			IBattleCombatant battleCombatant = ((enemySide == BattleSideEnum.Attacker) ? AttackerLeaderBattleCombatant : DefenderLeaderBattleCombatant);
			base.Mission.Teams.Add(enemySide, battleCombatant.PrimaryColorPair.Item1, battleCombatant.PrimaryColorPair.Item2, battleCombatant.Banner);
		}

		protected void AddPlayerAllyTeam(BattleSideEnum playerSide, IBattleCombatant allyCombatant)
		{
			base.Mission.Teams.Add(playerSide, allyCombatant.PrimaryColorPair.Item1, allyCombatant.PrimaryColorPair.Item2, allyCombatant.Banner);
			if (playerSide != BattleSideEnum.Attacker)
			{
				_ = base.Mission.DefenderAllyTeam;
			}
			else
			{
				_ = base.Mission.AttackerAllyTeam;
			}
		}

		public static bool SupportsAllyTeamOnPlayerSide(IEnumerable<IBattleCombatant> playerSideBattleCombatants, IBattleCombatant playerBattleCombatant, bool isPlayerSergeant, bool isNavalLandHybridMission, out IBattleCombatant allyCombatant)
		{
			allyCombatant = null;
			if (isNavalLandHybridMission)
			{
				return false;
			}
			BasicCharacterObject general = playerBattleCombatant.General;
			foreach (IBattleCombatant playerSideBattleCombatant in playerSideBattleCombatants)
			{
				if (playerSideBattleCombatant != playerBattleCombatant && (!isPlayerSergeant || playerSideBattleCombatant.General != general) && !playerSideBattleCombatant.IsUnderPlayersCommand(playerBattleCombatant.Side) && playerSideBattleCombatant.GetNumberOfMissionReadyTroops() > 0)
				{
					allyCombatant = playerSideBattleCombatant;
					return true;
				}
			}
			return false;
		}
	}
