	public class RecordMissionLogic : MissionLogic
	{
		private float _lastRecordedTime = -1f;

		public override void OnBehaviorInitialize()
		{
			base.Mission.Recorder.StartRecording();
		}

		public override void OnMissionTick(float dt)
		{
			base.OnMissionTick(dt);
			if (_lastRecordedTime + 0.02f < base.Mission.CurrentTime)
			{
				_lastRecordedTime = base.Mission.CurrentTime;
				base.Mission.Recorder.RecordCurrentState();
			}
		}

		public override void OnEndMissionInternal()
		{
			base.OnEndMissionInternal();
			base.Mission.Recorder.BackupRecordToFile("Mission_record_" + $"{DateTime.Now:yyyy-MM-dd_hh-mm-ss-tt}_" + Process.GetCurrentProcess().Id, Game.Current.GameType.GetType().Name, base.Mission.SceneLevels);
			GameNetwork.ResetMissionData();
		}
	}
	public class ReplayMissionLogic : MissionLogic
	{
		private bool _isMultiplayer;

		public string FileName { get; private set; }

		public ReplayMissionLogic(bool isMultiplayer, string fileName = "")
		{
			if (!string.IsNullOrEmpty(fileName))
			{
				FileName = fileName;
			}
			_isMultiplayer = isMultiplayer;
		}

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			if (_isMultiplayer)
			{
				GameNetwork.AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode.Add);
			}
			MBCommon.CurrentGameType = MBCommon.GameType.SingleReplay;
			GameNetwork.InitializeClientSide(null, 0, -1, -1);
			base.Mission.Recorder.RestoreRecordFromFile(FileName);
		}

		public override void OnRemoveBehavior()
		{
			if (_isMultiplayer)
			{
				GameNetwork.AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode.Remove);
				GameNetwork.EndReplay();
			}
			GameNetwork.TerminateClientSide();
			base.Mission.Recorder.ClearRecordBuffers();
			base.OnRemoveBehavior();
		}
	}
	public class SallyOutEndLogic : MissionLogic
	{
		private enum EndConditionCheckState
		{
			Deactive,
			Active,
			Idle
		}

		private EndConditionCheckState _checkState;

		private float _nextCheckTime;

		private float _dtSum;

		public bool IsSallyOutOver { get; private set; }

		public override void OnMissionTick(float dt)
		{
			if (!CheckTimer(dt))
			{
				return;
			}
			if (_checkState == EndConditionCheckState.Deactive)
			{
				foreach (Team item in base.Mission.Teams.Where((Team t) => t.Side == BattleSideEnum.Defender))
				{
					foreach (Formation item2 in item.FormationsIncludingSpecialAndEmpty)
					{
						if (item2.CountOfUnits > 0 && item2.CountOfUnits > 0 && !TeamAISiegeComponent.IsFormationInsideCastle(item2, includeOnlyPositionedUnits: true, 0.1f))
						{
							_checkState = EndConditionCheckState.Active;
							return;
						}
					}
				}
				return;
			}
			if (_checkState == EndConditionCheckState.Idle)
			{
				_checkState = EndConditionCheckState.Active;
			}
		}

		public override bool MissionEnded(ref MissionResult missionResult)
		{
			if (IsSallyOutOver)
			{
				missionResult = MissionResult.CreateSuccessful(base.Mission);
				return true;
			}
			if (_checkState != EndConditionCheckState.Active)
			{
				return false;
			}
			foreach (Team team in base.Mission.Teams)
			{
				switch (team.Side)
				{
				case BattleSideEnum.Attacker:
					if (TeamAISiegeComponent.IsFormationGroupInsideCastle(team.FormationsIncludingSpecialAndEmpty, includeOnlyPositionedUnits: false, 0.1f))
					{
						_checkState = EndConditionCheckState.Idle;
						return false;
					}
					break;
				case BattleSideEnum.Defender:
					if (team.FormationsIncludingEmpty.Any((Formation f) => f.CountOfUnits > 0 && !TeamAISiegeComponent.IsFormationInsideCastle(f, includeOnlyPositionedUnits: false, 0.9f)))
					{
						_checkState = EndConditionCheckState.Idle;
						return false;
					}
					break;
				}
			}
			IsSallyOutOver = true;
			missionResult = MissionResult.CreateSuccessful(base.Mission);
			return true;
		}

		private bool CheckTimer(float dt)
		{
			_dtSum += dt;
			if (_dtSum < _nextCheckTime)
			{
				return false;
			}
			_dtSum = 0f;
			_nextCheckTime = 0.8f + MBRandom.RandomFloat * 0.4f;
			return true;
		}
	}
	public abstract class SallyOutMissionController : MissionLogic
	{
		private const float BesiegedTotalTroopRatio = 0.25f;

		private const float BesiegedInitialTroopRatio = 0.1f;

		private const float BesiegedReinforcementRatio = 0.01f;

		private const float BesiegerInitialTroopRatio = 0.1f;

		private const float BesiegerReinforcementRatio = 0.1f;

		private const float BesiegedInitialInterval = 1f;

		private const float BesiegerInitialInterval = 90f;

		private const float BesiegerIntervalChange = 15f;

		private const int BesiegerIntervalChangeCount = 5;

		private const float PlayerToGateSquaredDistanceThreshold = 25f;

		private SallyOutMissionNotificationsHandler _sallyOutNotificationsHandler;

		private List<CastleGate> _castleGates;

		private BasicMissionTimer _besiegedDeploymentTimer;

		private BasicMissionTimer _besiegerActivationTimer;

		private MBReadOnlyList<SiegeWeapon> _besiegerSiegeEngines;

		protected DefaultBattleMissionAgentSpawnLogic MissionAgentSpawnLogic;

		private bool _isSallyOutAmbush;

		private float BesiegedDeploymentDuration => 55f;

		private float BesiegerActivationDuration => 8f;

		public MBReadOnlyList<SiegeWeapon> BesiegerSiegeEngines => _besiegerSiegeEngines;

		public SallyOutMissionController(bool isSallyOutAmbush)
		{
			_isSallyOutAmbush = isSallyOutAmbush;
		}

		public override void OnBehaviorInitialize()
		{
			MissionAgentSpawnLogic = base.Mission.GetMissionBehavior<DefaultBattleMissionAgentSpawnLogic>();
			_sallyOutNotificationsHandler = new SallyOutMissionNotificationsHandler(MissionAgentSpawnLogic, this);
			Mission.Current.GetOverriddenFleePositionForAgent += GetSallyOutFleePositionForAgent;
		}

		public override void AfterStart()
		{
			_sallyOutNotificationsHandler.OnAfterStart();
			GetInitialTroopCounts(out var besiegedTotalTroopCount, out var besiegerTotalTroopCount);
			SetupInitialSpawn(besiegedTotalTroopCount, besiegerTotalTroopCount);
			_castleGates = base.Mission.MissionObjects.FindAllWithType<CastleGate>().ToList();
			_besiegedDeploymentTimer = new BasicMissionTimer();
			TeamAIComponent teamAI = base.Mission.DefenderTeam.TeamAI;
			teamAI.OnNotifyTacticalDecision = (TeamAIComponent.TacticalDecisionDelegate)Delegate.Combine(teamAI.OnNotifyTacticalDecision, new TeamAIComponent.TacticalDecisionDelegate(OnDefenderTeamTacticalDecision));
		}

		public override void OnMissionTick(float dt)
		{
			_sallyOutNotificationsHandler.OnMissionTick(dt);
			UpdateTimers();
		}

		public override void OnDeploymentFinished()
		{
			_besiegerSiegeEngines = GetBesiegerSiegeEngines();
			DisableSiegeEngines();
			if (_isSallyOutAmbush)
			{
				Mission.Current.AddMissionBehavior(new SallyOutEndLogic());
			}
			_sallyOutNotificationsHandler.OnDeploymentFinished();
			_besiegerActivationTimer = new BasicMissionTimer();
			DeactivateBesiegers();
			ActivateDefenders();
		}

		protected override void OnEndMission()
		{
			_sallyOutNotificationsHandler.OnMissionEnd();
			Mission.Current.GetOverriddenFleePositionForAgent -= GetSallyOutFleePositionForAgent;
		}

		protected abstract void GetInitialTroopCounts(out int besiegedTotalTroopCount, out int besiegerTotalTroopCount);

		private void UpdateTimers()
		{
			if (_besiegedDeploymentTimer != null)
			{
				if (_besiegedDeploymentTimer.ElapsedTime >= BesiegedDeploymentDuration)
				{
					foreach (CastleGate castleGate in _castleGates)
					{
						castleGate.SetAutoOpenState(isEnabled: true);
					}
					_besiegedDeploymentTimer = null;
				}
				else
				{
					foreach (CastleGate castleGate2 in _castleGates)
					{
						if (!castleGate2.IsDestroyed && !castleGate2.IsGateOpen)
						{
							castleGate2.OpenDoor();
						}
					}
				}
			}
			else
			{
				Agent mainAgent = base.Mission.MainAgent;
				if (mainAgent != null && mainAgent.IsActive())
				{
					Vec3 eyeGlobalPosition = mainAgent.GetEyeGlobalPosition();
					foreach (CastleGate castleGate3 in _castleGates)
					{
						if (!castleGate3.IsDestroyed && !castleGate3.IsGateOpen && eyeGlobalPosition.DistanceSquared(castleGate3.GameEntity.GlobalPosition) <= 25f)
						{
							castleGate3.OpenDoor();
						}
					}
				}
			}
			if (_besiegerActivationTimer != null && _besiegerActivationTimer.ElapsedTime >= BesiegerActivationDuration)
			{
				ActivateBesiegers();
				_besiegerActivationTimer = null;
			}
		}

		private void ActivateDefenders()
		{
			if (base.Mission.DefenderAllyTeam != null)
			{
				foreach (Agent item in base.Mission.DefenderAllyTeam.ActiveAgents.ToList())
				{
					FormationClass formationIndex = item.Formation.FormationIndex;
					item.SetTeam(base.Mission.DefenderTeam, sync: true);
					item.Formation = base.Mission.DefenderTeam.GetFormation(formationIndex);
				}
			}
			foreach (Formation item2 in base.Mission.DefenderTeam.FormationsIncludingSpecialAndEmpty)
			{
				item2.SetMovementOrder(MovementOrder.MovementOrderCharge);
			}
		}

		private void AdjustTotalTroopCounts(ref int besiegedTotalTroopCount, ref int besiegerTotalTroopCount)
		{
			float num = 0.25f;
			float num2 = 1f - num;
			int b = (int)((float)MissionAgentSpawnLogic.BattleSize * num);
			int b2 = (int)((float)MissionAgentSpawnLogic.BattleSize * num2);
			besiegedTotalTroopCount = TaleWorlds.Library.MathF.Min(besiegedTotalTroopCount, b);
			besiegerTotalTroopCount = TaleWorlds.Library.MathF.Min(besiegerTotalTroopCount, b2);
			float num3 = num2 / num;
			if ((float)besiegerTotalTroopCount / (float)besiegedTotalTroopCount <= num3)
			{
				int a = (int)((float)besiegerTotalTroopCount / num3);
				besiegedTotalTroopCount = TaleWorlds.Library.MathF.Min(a, besiegedTotalTroopCount);
			}
			else
			{
				int a2 = (int)((float)besiegedTotalTroopCount * num3);
				besiegerTotalTroopCount = TaleWorlds.Library.MathF.Min(a2, besiegerTotalTroopCount);
			}
		}

		private void SetupInitialSpawn(int besiegedTotalTroopCount, int besiegerTotalTroopCount)
		{
			AdjustTotalTroopCounts(ref besiegedTotalTroopCount, ref besiegerTotalTroopCount);
			int num = besiegedTotalTroopCount + besiegerTotalTroopCount;
			int defenderInitialSpawn = TaleWorlds.Library.MathF.Min(besiegedTotalTroopCount, TaleWorlds.Library.MathF.Ceiling((float)num * 0.1f));
			int attackerInitialSpawn = TaleWorlds.Library.MathF.Min(besiegerTotalTroopCount, TaleWorlds.Library.MathF.Ceiling((float)num * 0.1f));
			MissionAgentSpawnLogic.SetSpawnHorses(BattleSideEnum.Defender, spawnHorses: true);
			MissionAgentSpawnLogic.SetSpawnHorses(BattleSideEnum.Attacker, spawnHorses: false);
			MissionSpawnSettings spawnSettings = CreateSallyOutSpawnSettings(0.01f, 0.1f);
			MissionAgentSpawnLogic.InitWithSinglePhase(besiegedTotalTroopCount, besiegerTotalTroopCount, defenderInitialSpawn, attackerInitialSpawn, spawnDefenders: false, spawnAttackers: false, in spawnSettings);
			MissionAgentSpawnLogic.SetCustomReinforcementSpawnTimer(new SallyOutReinforcementSpawnTimer(1f, 90f, 15f, 5));
		}

		private WorldPosition? GetSallyOutFleePositionForAgent(Agent agent)
		{
			if (!agent.IsHuman)
			{
				return null;
			}
			Formation formation = agent.Formation;
			if (formation == null || formation.Team.Side == BattleSideEnum.Attacker)
			{
				return null;
			}
			bool num = !agent.HasMount;
			bool isRangedCached = agent.IsRangedCached;
			FormationClass fClass = ((!num) ? (isRangedCached ? FormationClass.HorseArcher : FormationClass.Cavalry) : (isRangedCached ? FormationClass.Ranged : FormationClass.Infantry));
			return Mission.Current.DeploymentPlan.GetFormationPlan(formation.Team, fClass).CreateNewDeploymentWorldPosition(WorldPosition.WorldPositionEnforcedCache.GroundVec3);
		}

		private static MissionSpawnSettings CreateSallyOutSpawnSettings(float besiegedReinforcementPercentage, float besiegerReinforcementPercentage)
		{
			return new MissionSpawnSettings(MissionSpawnSettings.InitialSpawnMethod.FreeAllocation, MissionSpawnSettings.ReinforcementTimingMethod.CustomTimer, MissionSpawnSettings.ReinforcementSpawnMethod.Fixed, 0f, 0f, 0f, 0f, 0, besiegedReinforcementPercentage, besiegerReinforcementPercentage);
		}

		private void OnDefenderTeamTacticalDecision(in TacticalDecision decision)
		{
			if (decision.DecisionCode == 31)
			{
				_sallyOutNotificationsHandler.OnBesiegedSideFallsbackToKeep();
			}
		}

		private void DeactivateBesiegers()
		{
			foreach (Formation item in base.Mission.AttackerTeam.FormationsIncludingSpecialAndEmpty)
			{
				item.SetMovementOrder(MovementOrder.MovementOrderStop);
				item.SetFiringOrder(FiringOrder.FiringOrderHoldYourFire);
				item.SetControlledByAI(isControlledByAI: false);
			}
		}

		private void ActivateBesiegers()
		{
			_ = base.Mission.AttackerTeam;
			foreach (Formation item in base.Mission.AttackerTeam.FormationsIncludingSpecialAndEmpty)
			{
				item.SetControlledByAI(isControlledByAI: true);
			}
		}

		public static MBReadOnlyList<SiegeWeapon> GetBesiegerSiegeEngines()
		{
			MBList<SiegeWeapon> mBList = new MBList<SiegeWeapon>();
			foreach (MissionObject activeMissionObject in Mission.Current.ActiveMissionObjects)
			{
				if (activeMissionObject is SiegeWeapon { DestructionComponent: not null, Side: BattleSideEnum.Attacker } siegeWeapon)
				{
					mBList.Add(siegeWeapon);
				}
			}
			return mBList;
		}

		public static void DisableSiegeEngines()
		{
			for (int num = Mission.Current.ActiveMissionObjects.Count - 1; num >= 0; num--)
			{
				if (Mission.Current.ActiveMissionObjects[num] is SiegeWeapon { DestructionComponent: not null, IsDeactivated: false } siegeWeapon)
				{
					siegeWeapon.Disable();
					siegeWeapon.Deactivate();
				}
			}
		}
	}
	public class SallyOutMissionNotificationsHandler
	{
		private enum NotificationType
		{
			SallyOutObjective,
			BesiegerSideStrenghtening,
			BesiegerSideReinforcementsSpawned,
			BesiegedSideTacticalRetreat,
			BesiegedSidePlayerPullbackRequest,
			SiegeEnginesDestroyed
		}

		private const float NotificationCheckInterval = 5f;

		private DefaultBattleMissionAgentSpawnLogic _spawnLogic;

		private SallyOutMissionController _sallyOutController;

		private bool _isPlayerBesieged;

		private MBReadOnlyList<SiegeWeapon> _besiegerSiegeEngines;

		private Queue<NotificationType> _notificationsQueue;

		private BasicMissionTimer _notificationTimer;

		private bool _notificationTimerEnabled = true;

		private bool _objectiveMessageSent;

		private bool _siegeEnginesDestroyedMessageSent;

		private bool _besiegersStrengtheningMessageSent;

		private int _besiegerSpawnedTroopCount;

		public SallyOutMissionNotificationsHandler(DefaultBattleMissionAgentSpawnLogic spawnLogic, SallyOutMissionController sallyOutController)
		{
			_spawnLogic = spawnLogic;
			_sallyOutController = sallyOutController;
			_spawnLogic.OnReinforcementsSpawned += OnReinforcementsSpawned;
			_spawnLogic.OnInitialTroopsSpawned += OnInitialTroopsSpawned;
			_besiegerSpawnedTroopCount = 0;
			_notificationTimer = new BasicMissionTimer();
			_notificationsQueue = new Queue<NotificationType>();
		}

		public void OnBesiegedSideFallsbackToKeep()
		{
			if (_isPlayerBesieged)
			{
				if (Mission.Current.PlayerTeam.FormationsIncludingEmpty.Any((Formation f) => f.IsAIControlled && f.CountOfUnits > 0))
				{
					_notificationsQueue.Enqueue(NotificationType.BesiegedSideTacticalRetreat);
					if (Mission.Current.MainAgent != null && Mission.Current.MainAgent.IsActive())
					{
						_notificationsQueue.Enqueue(NotificationType.BesiegedSidePlayerPullbackRequest);
					}
				}
			}
			else
			{
				_notificationsQueue.Enqueue(NotificationType.BesiegedSideTacticalRetreat);
			}
		}

		public void OnAfterStart()
		{
			_isPlayerBesieged = Mission.Current.PlayerTeam.Side == BattleSideEnum.Defender;
			SetNotificationTimerEnabled(value: false);
		}

		public void OnMissionEnd()
		{
			_spawnLogic.OnReinforcementsSpawned -= OnReinforcementsSpawned;
			_spawnLogic.OnInitialTroopsSpawned -= OnInitialTroopsSpawned;
		}

		public void OnDeploymentFinished()
		{
			SetNotificationTimerEnabled(value: true);
			_besiegerSiegeEngines = _sallyOutController.BesiegerSiegeEngines;
		}

		public void OnMissionTick(float dt)
		{
			if (_notificationTimerEnabled && _notificationTimer.ElapsedTime >= 5f)
			{
				CheckPeriodicNotifications();
				if (!_notificationsQueue.IsEmpty())
				{
					NotificationType type = _notificationsQueue.Dequeue();
					SendNotification(type);
				}
				_notificationTimer.Reset();
			}
		}

		private void SetNotificationTimerEnabled(bool value, bool resetTimer = true)
		{
			_notificationTimerEnabled = value;
			if (resetTimer)
			{
				_notificationTimer.Reset();
			}
		}

		private void CheckPeriodicNotifications()
		{
			if (!_objectiveMessageSent)
			{
				_notificationsQueue.Enqueue(NotificationType.SallyOutObjective);
				_objectiveMessageSent = true;
			}
			if (!_siegeEnginesDestroyedMessageSent && IsSiegeEnginesDestroyed())
			{
				_notificationsQueue.Enqueue(NotificationType.SiegeEnginesDestroyed);
				_siegeEnginesDestroyedMessageSent = true;
			}
			if (!_besiegersStrengtheningMessageSent && _spawnLogic.NumberOfRemainingDefenderTroops == 0 && _besiegerSpawnedTroopCount >= _spawnLogic.NumberOfActiveDefenderTroops)
			{
				_notificationsQueue.Enqueue(NotificationType.BesiegerSideStrenghtening);
				_besiegersStrengtheningMessageSent = true;
			}
		}

		private void SendNotification(NotificationType type)
		{
			int num = -1;
			if (_isPlayerBesieged)
			{
				switch (type)
				{
				case NotificationType.SallyOutObjective:
					MBInformationManager.AddQuickInformation(GameTexts.FindText("str_sally_out_besieged_objective_message"));
					num = SoundEvent.GetEventIdFromString("event:/alerts/horns/move");
					break;
				case NotificationType.BesiegerSideReinforcementsSpawned:
					MBInformationManager.AddQuickInformation(GameTexts.FindText("str_enemy_reinforcements_arrived"));
					num = SoundEvent.GetEventIdFromString("event:/alerts/horns/reinforcements");
					break;
				case NotificationType.BesiegerSideStrenghtening:
					MBInformationManager.AddQuickInformation(GameTexts.FindText("str_sally_out_enemy_becoming_strong_message"));
					num = SoundEvent.GetEventIdFromString("event:/alerts/horns/retreat");
					break;
				case NotificationType.SiegeEnginesDestroyed:
					MBInformationManager.AddQuickInformation(GameTexts.FindText("str_sally_out_enemy_siege_engines_destroyed_message"));
					num = SoundEvent.GetEventIdFromString("event:/alerts/horns/move");
					break;
				case NotificationType.BesiegedSideTacticalRetreat:
					MBInformationManager.AddQuickInformation(GameTexts.FindText("str_sally_out_allied_troops_tactical_retreat_message"));
					num = SoundEvent.GetEventIdFromString("event:/alerts/horns/retreat");
					break;
				case NotificationType.BesiegedSidePlayerPullbackRequest:
					MBInformationManager.AddQuickInformation(GameTexts.FindText("str_sally_out_allied_pullback_or_take_command_message"));
					break;
				}
			}
			else
			{
				switch (type)
				{
				case NotificationType.SallyOutObjective:
					MBInformationManager.AddQuickInformation(GameTexts.FindText("str_sally_out_besieger_objective_message"));
					num = SoundEvent.GetEventIdFromString("event:/alerts/horns/move");
					break;
				case NotificationType.BesiegerSideReinforcementsSpawned:
					MBInformationManager.AddQuickInformation(GameTexts.FindText("str_allied_reinforcements_arrived"));
					num = SoundEvent.GetEventIdFromString("event:/alerts/horns/reinforcements");
					break;
				case NotificationType.SiegeEnginesDestroyed:
					MBInformationManager.AddQuickInformation(GameTexts.FindText("str_sally_out_allied_siege_engines_destroyed_message"));
					num = SoundEvent.GetEventIdFromString("event:/alerts/horns/move");
					break;
				case NotificationType.BesiegedSideTacticalRetreat:
					MBInformationManager.AddQuickInformation(GameTexts.FindText("str_enemy_troops_fall_back_to_keep_message"));
					num = SoundEvent.GetEventIdFromString("event:/alerts/horns/move");
					break;
				}
			}
			if (num >= 0)
			{
				PlayNotificationSound(num);
			}
		}

		private void PlayNotificationSound(int soundId)
		{
			MatrixFrame cameraFrame = Mission.Current.GetCameraFrame();
			Vec3 position = cameraFrame.origin + cameraFrame.rotation.u;
			MBSoundEvent.PlaySound(soundId, position);
		}

		private void OnInitialTroopsSpawned(BattleSideEnum battleSide, int numberOfTroopsSpawned)
		{
			if (battleSide == BattleSideEnum.Attacker)
			{
				_besiegerSpawnedTroopCount += numberOfTroopsSpawned;
			}
		}

		private void OnReinforcementsSpawned(BattleSideEnum battleSide, int numberOfTroopsSpawned)
		{
			if (battleSide == BattleSideEnum.Attacker)
			{
				_besiegerSpawnedTroopCount += numberOfTroopsSpawned;
				_notificationsQueue.Enqueue(NotificationType.BesiegerSideReinforcementsSpawned);
			}
		}

		private bool IsSiegeEnginesDestroyed()
		{
			if (_besiegerSiegeEngines != null)
			{
				return _besiegerSiegeEngines.All((SiegeWeapon siegeEngine) => siegeEngine.DestructionComponent.IsDestroyed);
			}
			return false;
		}
	}
	public class SallyOutReinforcementSpawnTimer : ICustomReinforcementSpawnTimer
	{
		private BasicMissionTimer _besiegedSideTimer;

		private BasicMissionTimer _besiegerSideTimer;

		private float _besiegedInterval;

		private float _besiegerInterval;

		private float _besiegerIntervalChange;

		private int _besiegerRemainingIntervalChanges;

		public SallyOutReinforcementSpawnTimer(float besiegedInterval, float besiegerInterval, float besiegerIntervalChange, int besiegerIntervalChangeCount)
		{
			_besiegedSideTimer = new BasicMissionTimer();
			_besiegedInterval = besiegedInterval;
			_besiegerSideTimer = new BasicMissionTimer();
			_besiegerInterval = besiegerInterval;
			_besiegerIntervalChange = besiegerIntervalChange;
			_besiegerRemainingIntervalChanges = besiegerIntervalChangeCount;
		}

		public bool Check(BattleSideEnum side)
		{
			switch (side)
			{
			case BattleSideEnum.Attacker:
				if (_besiegerSideTimer.ElapsedTime >= _besiegerInterval)
				{
					if (_besiegerRemainingIntervalChanges > 0)
					{
						_besiegerInterval -= _besiegerIntervalChange;
						_besiegerRemainingIntervalChanges--;
					}
					_besiegerSideTimer.Reset();
					return true;
				}
				break;
			case BattleSideEnum.Defender:
				if (_besiegedSideTimer.ElapsedTime >= _besiegedInterval)
				{
					_besiegedSideTimer.Reset();
					return true;
				}
				break;
			}
			return false;
		}

		public void ResetTimer(BattleSideEnum side)
		{
			switch (side)
			{
			case BattleSideEnum.Attacker:
				_besiegerSideTimer.Reset();
				break;
			case BattleSideEnum.Defender:
				_besiegedSideTimer.Reset();
				break;
			}
		}
	}
	public class SiegeDeploymentMissionController : DeploymentMissionController
	{
		protected DefaultBattleMissionAgentSpawnLogic MissionAgentSpawnLogic;

		private SiegeDeploymentHandler _siegeDeploymentHandler;

		public SiegeDeploymentMissionController(bool isPlayerAttacker)
			: base(isPlayerAttacker)
		{
		}

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			_siegeDeploymentHandler = base.Mission.GetMissionBehavior<SiegeDeploymentHandler>();
			MissionAgentSpawnLogic = base.Mission.GetMissionBehavior<DefaultBattleMissionAgentSpawnLogic>();
		}

		public List<ItemObject> GetSiegeMissiles()
		{
			List<ItemObject> list = new List<ItemObject>();
			foreach (WeakGameEntity item in Mission.Current.GetActiveEntitiesWithScriptComponentOfType<RangedSiegeWeapon>())
			{
				RangedSiegeWeapon firstScriptOfType = item.GetFirstScriptOfType<RangedSiegeWeapon>();
				if (!string.IsNullOrEmpty(firstScriptOfType.MissileItemID))
				{
					ItemObject @object = MBObjectManager.Instance.GetObject<ItemObject>(firstScriptOfType.MissileItemID);
					if (!list.Contains(@object))
					{
						list.Add(@object);
					}
				}
				foreach (ItemObject item2 in new List<ItemObject>
				{
					MBObjectManager.Instance.GetObject<ItemObject>(firstScriptOfType.MultipleProjectileId),
					MBObjectManager.Instance.GetObject<ItemObject>(firstScriptOfType.MultipleProjectileFlyingId),
					MBObjectManager.Instance.GetObject<ItemObject>(firstScriptOfType.MultipleFireProjectileId),
					MBObjectManager.Instance.GetObject<ItemObject>(firstScriptOfType.MultipleFireProjectileFlyingId),
					MBObjectManager.Instance.GetObject<ItemObject>(firstScriptOfType.SingleProjectileId),
					MBObjectManager.Instance.GetObject<ItemObject>(firstScriptOfType.SingleProjectileFlyingId),
					MBObjectManager.Instance.GetObject<ItemObject>(firstScriptOfType.SingleFireProjectileId),
					MBObjectManager.Instance.GetObject<ItemObject>(firstScriptOfType.SingleFireProjectileFlyingId)
				})
				{
					if (!list.Contains(item2))
					{
						list.Add(item2);
					}
				}
			}
			foreach (WeakGameEntity item3 in Mission.Current.GetActiveEntitiesWithScriptComponentOfType<StonePile>())
			{
				StonePile firstScriptOfType2 = item3.GetFirstScriptOfType<StonePile>();
				if (!string.IsNullOrEmpty(firstScriptOfType2.GivenItemID))
				{
					ItemObject object2 = MBObjectManager.Instance.GetObject<ItemObject>(firstScriptOfType2.GivenItemID);
					if (!list.Contains(object2))
					{
						list.Add(object2);
					}
				}
			}
			return list;
		}

		protected override void OnAfterStart()
		{
			_siegeDeploymentHandler.InitializeDeploymentPoints();
			for (int i = 0; i < 2; i++)
			{
				MissionAgentSpawnLogic.SetSpawnTroops((BattleSideEnum)i, spawnTroops: false);
			}
			MissionAgentSpawnLogic.SetReinforcementsSpawnEnabled(value: false);
		}

		protected override void OnSetupTeamsOfSide(BattleSideEnum battleSide)
		{
			foreach (Team team2 in base.Mission.Teams)
			{
				if (team2.Side == battleSide && team2.GeneralAgent != null && team2.GeneralAgent != base.Mission.InitialPlayerAgent)
				{
					team2.GeneralAgent.SetDetachableFromFormation(value: false);
				}
			}
			Team team = ((battleSide == BattleSideEnum.Attacker) ? base.Mission.AttackerTeam : base.Mission.DefenderTeam);
			if (team == base.Mission.PlayerTeam)
			{
				_siegeDeploymentHandler.RemoveUnavailableDeploymentPoints(battleSide);
				_siegeDeploymentHandler.UnHideDeploymentPoints(battleSide);
				_siegeDeploymentHandler.DeployAllSiegeWeaponsOfPlayer();
			}
			else
			{
				_siegeDeploymentHandler.DeployAllSiegeWeaponsOfAi();
			}
			MissionAgentSpawnLogic.SetSpawnTroops(battleSide, spawnTroops: true, enforceSpawning: true);
			foreach (WeakGameEntity item in base.Mission.GetActiveEntitiesWithScriptComponentOfType<SiegeWeapon>())
			{
				SiegeWeapon firstScriptOfType = item.GetFirstScriptOfType<SiegeWeapon>();
				if (firstScriptOfType != null && firstScriptOfType.GetSide() == battleSide)
				{
					firstScriptOfType.TickAuxForInit();
				}
			}
			SetupAgentAIStatesForSide(battleSide);
			if (team == base.Mission.PlayerTeam)
			{
				foreach (Formation item2 in team.FormationsIncludingEmpty)
				{
					item2.SetControlledByAI(isControlledByAI: true);
				}
			}
			MissionAgentSpawnLogic.OnSideDeploymentOver(team.Side);
		}

		protected override void OnSetupTeamsFinished()
		{
			base.Mission.IsTeleportingAgents = true;
			Agent initialPlayerAgent = base.Mission.InitialPlayerAgent;
			if (initialPlayerAgent == null)
			{
				return;
			}
			Team team = initialPlayerAgent.Team;
			if (team == null)
			{
				return;
			}
			if (base.Mission.DeploymentPlan.HasPlayerSpawnFrame(team.Side))
			{
				base.Mission.DeploymentPlan.GetPlayerSpawnFrame(team.Side, out var position, out var direction);
				if (position.GetNavMesh() != UIntPtr.Zero && position.IsValid)
				{
					initialPlayerAgent.TrySetFormationFrame(in position, in direction);
				}
			}
			else if (team.GeneralAgent == initialPlayerAgent)
			{
				base.Mission.GetFormationSpawnFrame(team, FormationClass.NumberOfRegularFormations, isReinforcement: false, out var spawnPosition, out var spawnDirection);
				if (spawnPosition.GetNavMesh() != UIntPtr.Zero && spawnPosition.IsValid)
				{
					initialPlayerAgent.TrySetFormationFrame(in spawnPosition, in spawnDirection);
				}
			}
		}

		protected override void BeforeDeploymentFinished()
		{
			BattleSideEnum side = base.Mission.PlayerTeam.Side;
			_siegeDeploymentHandler.RemoveDeploymentPoints(side);
			foreach (SiegeLadder item in (from sl in Mission.Current.ActiveMissionObjects.FindAllWithType<SiegeLadder>()
				where !sl.GameEntity.IsVisibleIncludeParents()
				select sl).ToList())
			{
				item.SetDisabledSynched();
			}
			foreach (Team team in base.Mission.Teams)
			{
				if (team.GeneralAgent != null && team.GeneralAgent != base.Mission.InitialPlayerAgent)
				{
					team.GeneralAgent.SetDetachableFromFormation(value: true);
				}
			}
			base.Mission.IsTeleportingAgents = false;
		}

		protected override void AfterDeploymentFinished()
		{
			MissionAgentSpawnLogic.SetReinforcementsSpawnEnabled(value: true);
			base.Mission.RemoveMissionBehavior(_siegeDeploymentHandler);
		}
	}
	public delegate void DeploymentMissionEvent();
	public class SiegeMissionPreparationHandler : MissionLogic
	{
		private enum SiegeMissionType
		{
			Assault,
			SallyOut,
			ReliefForce
		}

		private const string SallyOutTag = "sally_out";

		private const string AssaultTag = "siege_assault";

		private const string DamageDecalTag = "damage_decal";

		private float[] _wallHitPointPercentages;

		private bool _hasAnySiegeTower;

		private SiegeMissionType _siegeMissionType;

		private Scene MissionScene => Mission.Current.Scene;

		public SiegeMissionPreparationHandler(bool isSallyOut, bool isReliefForceAttack, float[] wallHitPointPercentages, bool hasAnySiegeTower)
		{
			if (isSallyOut)
			{
				_siegeMissionType = SiegeMissionType.SallyOut;
			}
			else if (isReliefForceAttack)
			{
				_siegeMissionType = SiegeMissionType.ReliefForce;
			}
			else
			{
				_siegeMissionType = SiegeMissionType.Assault;
			}
			_wallHitPointPercentages = wallHitPointPercentages;
			_hasAnySiegeTower = hasAnySiegeTower;
		}

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			SetUpScene();
		}

		private void SetUpScene()
		{
			ArrangeBesiegerDeploymentPointsAndMachines();
			ArrangeEntitiesForMissionType();
			ArrangeDestructedMeshes();
			if (_siegeMissionType != 0)
			{
				ArrangeSiegeMachinesForNonAssaultMission();
			}
		}

		private void ArrangeBesiegerDeploymentPointsAndMachines()
		{
			bool num = _siegeMissionType == SiegeMissionType.Assault;
			TaleWorlds.Library.Debug.Print("{SIEGE} ArrangeBesiegerDeploymentPointsAndMachines", 0, TaleWorlds.Library.Debug.DebugColor.DarkCyan, 64uL);
			TaleWorlds.Library.Debug.Print("{SIEGE} MissionType: " + _siegeMissionType, 0, TaleWorlds.Library.Debug.DebugColor.DarkCyan, 64uL);
			if (!num)
			{
				SiegeLadder[] array = base.Mission.ActiveMissionObjects.FindAllWithType<SiegeLadder>().ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					array[i].SetDisabledSynched();
				}
			}
		}

		private void ArrangeEntitiesForMissionType()
		{
			string text = ((_siegeMissionType == SiegeMissionType.Assault) ? "sally_out" : "siege_assault");
			TaleWorlds.Library.Debug.Print("{SIEGE} ArrangeEntitiesForMissionType", 0, TaleWorlds.Library.Debug.DebugColor.DarkCyan, 64uL);
			TaleWorlds.Library.Debug.Print("{SIEGE} MissionType: " + _siegeMissionType, 0, TaleWorlds.Library.Debug.DebugColor.DarkCyan, 64uL);
			TaleWorlds.Library.Debug.Print("{SIEGE} TagToBeRemoved: " + text, 0, TaleWorlds.Library.Debug.DebugColor.DarkCyan, 64uL);
			foreach (WeakGameEntity item in MissionScene.FindWeakEntitiesWithTag(text).ToList())
			{
				item.Remove(77);
			}
		}

		private void ArrangeDestructedMeshes()
		{
			float num = 0f;
			float[] wallHitPointPercentages = _wallHitPointPercentages;
			foreach (float num2 in wallHitPointPercentages)
			{
				num += num2;
			}
			if (!_wallHitPointPercentages.IsEmpty())
			{
				num /= (float)_wallHitPointPercentages.Length;
			}
			float num3 = MBMath.Lerp(0f, 0.7f, 1f - num);
			IEnumerable<SynchedMissionObject> enumerable = base.Mission.MissionObjects.OfType<SynchedMissionObject>();
			IEnumerable<DestructableComponent> destructibleComponents = enumerable.OfType<DestructableComponent>();
			foreach (StrategicArea item2 in base.Mission.ActiveMissionObjects.OfType<StrategicArea>().ToList())
			{
				item2.DetermineAssociatedDestructibleComponents(destructibleComponents);
			}
			foreach (SynchedMissionObject item3 in enumerable)
			{
				if (_hasAnySiegeTower && item3.GameEntity.HasTag("tower_merlon"))
				{
					item3.SetVisibleSynched(value: false, forceChildrenVisible: true);
					continue;
				}
				DestructableComponent firstScriptOfType = item3.GameEntity.GetFirstScriptOfType<DestructableComponent>();
				if (firstScriptOfType != null && firstScriptOfType.CanBeDestroyedInitially && num3 > 0f && MBRandom.RandomFloat <= num3)
				{
					firstScriptOfType.PreDestroy();
				}
			}
			if (num3 >= 0.1f)
			{
				List<WeakGameEntity> list = base.Mission.Scene.FindWeakEntitiesWithTag("damage_decal").ToList();
				foreach (WeakGameEntity item4 in list)
				{
					item4.GetFirstScriptOfType<SynchedMissionObject>().SetVisibleSynched(value: false);
				}
				for (int num4 = TaleWorlds.Library.MathF.Floor((float)list.Count * num3); num4 > 0; num4--)
				{
					WeakGameEntity item = list[MBRandom.RandomInt(list.Count)];
					list.Remove(item);
					item.GetFirstScriptOfType<SynchedMissionObject>().SetVisibleSynched(value: true);
				}
			}
			List<WallSegment> list2 = new List<WallSegment>();
			List<WallSegment> list3 = (from ws in base.Mission.ActiveMissionObjects.FindAllWithType<WallSegment>()
				where ws.DefenseSide != FormationAI.BehaviorSide.BehaviorSideNotSet && ws.GameEntity.GetChildren().Any((WeakGameEntity ge) => ge.HasTag("broken_child"))
				select ws).ToList();
			wallHitPointPercentages = _wallHitPointPercentages;
			foreach (float f in wallHitPointPercentages)
			{
				WallSegment wallSegment = FindRightMostWall(list3);
				if (TaleWorlds.Library.MathF.Abs(f) < 1E-05f)
				{
					wallSegment.OnChooseUsedWallSegment(isBroken: true);
					list2.Add(wallSegment);
				}
				else
				{
					wallSegment.OnChooseUsedWallSegment(isBroken: false);
				}
				list3.Remove(wallSegment);
			}
			foreach (WallSegment item5 in list3)
			{
				item5.OnChooseUsedWallSegment(isBroken: false);
			}
			if (!(num3 >= 0.1f))
			{
				return;
			}
			List<SiegeWeapon> list4 = new List<SiegeWeapon>();
			foreach (SiegeWeapon primarySiegeWeapon in from sw in base.Mission.ActiveMissionObjects.FindAllWithType<SiegeWeapon>()
				where sw is IPrimarySiegeWeapon
				select sw)
			{
				if (list2.Any((WallSegment b) => b.DefenseSide == ((IPrimarySiegeWeapon)primarySiegeWeapon).WeaponSide))
				{
					list4.Add(primarySiegeWeapon);
				}
			}
			list4.ForEach(delegate(SiegeWeapon siegeWeaponToRemove)
			{
				siegeWeaponToRemove.SetDisabledSynched();
			});
		}

		private WallSegment FindRightMostWall(List<WallSegment> wallList)
		{
			int count = wallList.Count;
			if (count == 1)
			{
				return wallList[0];
			}
			BatteringRam batteringRam = base.Mission.ActiveMissionObjects.FindAllWithType<BatteringRam>().First();
			if (count == 2)
			{
				if (Vec3.CrossProduct(wallList[0].GameEntity.GlobalPosition - batteringRam.GameEntity.GlobalPosition, wallList[1].GameEntity.GlobalPosition - batteringRam.GameEntity.GlobalPosition).z < 0f)
				{
					return wallList[1];
				}
				return wallList[0];
			}
			return null;
		}

		private void ArrangeSiegeMachinesForNonAssaultMission()
		{
			foreach (WeakGameEntity item in Mission.Current.GetActiveEntitiesWithScriptComponentOfType<SiegeWeapon>())
			{
				SiegeWeapon firstScriptOfType = item.GetFirstScriptOfType<SiegeWeapon>();
				if (!(firstScriptOfType is RangedSiegeWeapon))
				{
					firstScriptOfType.Deactivate();
				}
			}
		}
	}
