		public struct ScoreboardHeader
		{
			private readonly Func<MissionPeer, string> _playerGetterFunc;

			private readonly Func<BotData, string> _botGetterFunc;

			public readonly string Id;

			public readonly TextObject Name;

			public ScoreboardHeader(string id, Func<MissionPeer, string> playerGetterFunc, Func<BotData, string> botGetterFunc)
			{
				Id = id;
				Name = GameTexts.FindText("str_scoreboard_header", id);
				_playerGetterFunc = playerGetterFunc;
				_botGetterFunc = botGetterFunc;
			}

			public string GetValueOf(MissionPeer missionPeer)
			{
				if (missionPeer == null || _playerGetterFunc == null)
				{
					TaleWorlds.Library.Debug.FailedAssert("Scoreboard header values are invalid: Peer: " + (missionPeer?.ToString() ?? "NULL") + " Getter: " + (_playerGetterFunc?.ToString() ?? "NULL"), "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\Multiplayer\\MissionNetworkLogics\\MissionScoreboardComponent.cs", "GetValueOf", 43);
					return string.Empty;
				}
				try
				{
					return _playerGetterFunc(missionPeer);
				}
				catch (Exception ex)
				{
					TaleWorlds.Library.Debug.FailedAssert($"An error occured while trying to get scoreboard value ({Id}) for peer: {missionPeer.Name}. Exception: {ex.InnerException}", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\Multiplayer\\MissionNetworkLogics\\MissionScoreboardComponent.cs", "GetValueOf", 53);
					return string.Empty;
				}
			}

			public string GetValueOf(BotData botData)
			{
				if (botData == null || _botGetterFunc == null)
				{
					TaleWorlds.Library.Debug.FailedAssert("Scoreboard header values are invalid: Bot Data: " + (botData?.ToString() ?? "NULL") + " Getter: " + (_botGetterFunc?.ToString() ?? "NULL"), "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\Multiplayer\\MissionNetworkLogics\\MissionScoreboardComponent.cs", "GetValueOf", 62);
					return string.Empty;
				}
				try
				{
					return _botGetterFunc(botData);
				}
				catch (Exception ex)
				{
					TaleWorlds.Library.Debug.FailedAssert($"An error occured while trying to get scoreboard value ({Id}) for a bot. Exception: {ex.InnerException}", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\Multiplayer\\MissionNetworkLogics\\MissionScoreboardComponent.cs", "GetValueOf", 72);
					return string.Empty;
				}
			}
