	public enum MultiplayerPollRejectReason
	{
		NotEnoughPlayersToOpenPoll,
		HasOngoingPoll,
		TooManyPollRequests,
		KickPollTargetNotSynced,
		Count
	}
	public class MultiplayerPollComponent : MissionNetwork
	{
		private abstract class MultiplayerPoll
		{
			public enum Type
			{
				KickPlayer,
				BanPlayer,
				ChangeGame
			}

			private const int TimeoutInSeconds = 30;

			public Action<MultiplayerPoll> OnClosedOnServer;

			public Action<MultiplayerPoll> OnCancelledOnServer;

			public int AcceptedCount;

			public int RejectedCount;

			private readonly List<NetworkCommunicator> _participantsToVote;

			private readonly MultiplayerGameType _gameType;

			public Type PollType { get; }

			public bool IsOpen { get; private set; }

			private int OpenTime { get; }

			private int CloseTime { get; set; }

			public List<NetworkCommunicator> ParticipantsToVote => _participantsToVote;

			protected MultiplayerPoll(MultiplayerGameType gameType, Type pollType, List<NetworkCommunicator> participantsToVote)
			{
				_gameType = gameType;
				PollType = pollType;
				if (participantsToVote != null)
				{
					_participantsToVote = participantsToVote;
				}
				OpenTime = Environment.TickCount;
				CloseTime = 0;
				AcceptedCount = 0;
				RejectedCount = 0;
				IsOpen = true;
			}

			public virtual bool IsCancelled()
			{
				return false;
			}

			public virtual List<NetworkCommunicator> GetPollProgressReceivers()
			{
				return GameNetwork.NetworkPeers.ToList();
			}

			public void Tick()
			{
				if (!GameNetwork.IsServer)
				{
					return;
				}
				for (int num = _participantsToVote.Count - 1; num >= 0; num--)
				{
					if (!_participantsToVote[num].IsConnectionActive)
					{
						_participantsToVote.RemoveAt(num);
					}
				}
				if (IsCancelled())
				{
					OnCancelledOnServer?.Invoke(this);
				}
				else if (OpenTime < Environment.TickCount - 30000 || ResultsFinalized())
				{
					OnClosedOnServer?.Invoke(this);
				}
			}

			public void Close()
			{
				CloseTime = Environment.TickCount;
				IsOpen = false;
			}

			public void Cancel()
			{
				Close();
			}

			public bool ApplyVote(NetworkCommunicator peer, bool accepted)
			{
				bool result = false;
				if (_participantsToVote.Contains(peer))
				{
					if (accepted)
					{
						AcceptedCount++;
					}
					else
					{
						RejectedCount++;
					}
					_participantsToVote.Remove(peer);
					result = true;
				}
				return result;
			}

			public bool GotEnoughAcceptVotesToEnd()
			{
				bool flag = false;
				if (_gameType == MultiplayerGameType.Skirmish || _gameType == MultiplayerGameType.Captain)
				{
					return AcceptedByAllParticipants();
				}
				return AcceptedByMajority();
			}

			private bool GotEnoughRejectVotesToEnd()
			{
				bool flag = false;
				if (_gameType == MultiplayerGameType.Skirmish || _gameType == MultiplayerGameType.Captain)
				{
					return RejectedByAtLeastOneParticipant();
				}
				return RejectedByMajority();
			}

			private bool AcceptedByAllParticipants()
			{
				return AcceptedCount == GetPollParticipantCount();
			}

			private bool AcceptedByMajority()
			{
				return (float)AcceptedCount / (float)GetPollParticipantCount() > 0.50001f;
			}

			private bool RejectedByAtLeastOneParticipant()
			{
				return RejectedCount > 0;
			}

			private bool RejectedByMajority()
			{
				return (float)RejectedCount / (float)GetPollParticipantCount() > 0.50001f;
			}

			private int GetPollParticipantCount()
			{
				return _participantsToVote.Count + AcceptedCount + RejectedCount;
			}

			private bool ResultsFinalized()
			{
				if (!GotEnoughAcceptVotesToEnd() && !GotEnoughRejectVotesToEnd())
				{
					return _participantsToVote.Count == 0;
				}
				return true;
			}
		}

		private class KickPlayerPoll : MultiplayerPoll
		{
			public const int RequestLimitPerPeer = 2;

			private readonly Team _team;

			public NetworkCommunicator TargetPeer { get; }

			public KickPlayerPoll(MultiplayerGameType gameType, List<NetworkCommunicator> participantsToVote, NetworkCommunicator targetPeer, Team team)
				: base(gameType, Type.KickPlayer, participantsToVote)
			{
				TargetPeer = targetPeer;
				_team = team;
			}

			public override bool IsCancelled()
			{
				if (TargetPeer.IsConnectionActive)
				{
					return TargetPeer.QuitFromMission;
				}
				return true;
			}

			public override List<NetworkCommunicator> GetPollProgressReceivers()
			{
				List<NetworkCommunicator> list = new List<NetworkCommunicator>();
				foreach (NetworkCommunicator networkPeer in GameNetwork.NetworkPeers)
				{
					MissionPeer component = networkPeer.GetComponent<MissionPeer>();
					if (component != null && component.Team == _team)
					{
						list.Add(networkPeer);
					}
				}
				return list;
			}
		}

		private class BanPlayerPoll : MultiplayerPoll
		{
			public NetworkCommunicator TargetPeer { get; }

			public BanPlayerPoll(MultiplayerGameType gameType, List<NetworkCommunicator> participantsToVote, NetworkCommunicator targetPeer)
				: base(gameType, Type.BanPlayer, participantsToVote)
			{
				TargetPeer = targetPeer;
			}
		}

		private class ChangeGamePoll : MultiplayerPoll
		{
			public string GameType { get; }

			public string MapName { get; }

			public ChangeGamePoll(MultiplayerGameType currentGameType, List<NetworkCommunicator> participantsToVote, string gameType, string scene)
				: base(currentGameType, Type.ChangeGame, participantsToVote)
			{
				GameType = gameType;
				MapName = scene;
			}
		}

		public const int MinimumParticipantCountRequired = 3;

		public Action<MissionPeer, MissionPeer, bool> OnKickPollOpened;

		public Action<MultiplayerPollRejectReason> OnPollRejected;

		public Action<int, int> OnPollUpdated;

		public Action OnPollClosed;

		public Action OnPollCancelled;

		private MissionLobbyComponent _missionLobbyComponent;

		private MultiplayerGameNotificationsComponent _notificationsComponent;

		private MultiplayerPoll _ongoingPoll;

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			_missionLobbyComponent = base.Mission.GetMissionBehavior<MissionLobbyComponent>();
			_notificationsComponent = base.Mission.GetMissionBehavior<MultiplayerGameNotificationsComponent>();
		}

		public override void OnMissionTick(float dt)
		{
			base.OnMissionTick(dt);
			_ongoingPoll?.Tick();
		}

		public void Vote(bool accepted)
		{
			if (GameNetwork.IsServer)
			{
				if (GameNetwork.MyPeer != null)
				{
					ApplyVote(GameNetwork.MyPeer, accepted);
				}
			}
			else if (_ongoingPoll != null && _ongoingPoll.IsOpen)
			{
				GameNetwork.BeginModuleEventAsClient();
				GameNetwork.WriteMessage(new PollResponse(accepted));
				GameNetwork.EndModuleEventAsClient();
			}
		}

		private void ApplyVote(NetworkCommunicator peer, bool accepted)
		{
			if (_ongoingPoll != null && _ongoingPoll.ApplyVote(peer, accepted))
			{
				List<NetworkCommunicator> pollProgressReceivers = _ongoingPoll.GetPollProgressReceivers();
				int count = pollProgressReceivers.Count;
				for (int i = 0; i < count; i++)
				{
					GameNetwork.BeginModuleEventAsServer(pollProgressReceivers[i]);
					GameNetwork.WriteMessage(new PollProgress(_ongoingPoll.AcceptedCount, _ongoingPoll.RejectedCount));
					GameNetwork.EndModuleEventAsServer();
				}
				UpdatePollProgress(_ongoingPoll.AcceptedCount, _ongoingPoll.RejectedCount);
			}
		}

		private void RejectPollOnServer(NetworkCommunicator pollCreatorPeer, MultiplayerPollRejectReason rejectReason)
		{
			if (pollCreatorPeer.IsMine)
			{
				RejectPoll(rejectReason);
				return;
			}
			GameNetwork.BeginModuleEventAsServer(pollCreatorPeer);
			GameNetwork.WriteMessage(new PollRequestRejected((int)rejectReason));
			GameNetwork.EndModuleEventAsServer();
		}

		private void RejectPoll(MultiplayerPollRejectReason rejectReason)
		{
			if (!GameNetwork.IsDedicatedServer)
			{
				_notificationsComponent.PollRejected(rejectReason);
			}
			OnPollRejected?.Invoke(rejectReason);
		}

		private void UpdatePollProgress(int votesAccepted, int votesRejected)
		{
			OnPollUpdated?.Invoke(votesAccepted, votesRejected);
		}

		private void CancelPoll()
		{
			if (_ongoingPoll != null)
			{
				_ongoingPoll.Cancel();
				_ongoingPoll = null;
			}
			OnPollCancelled?.Invoke();
		}

		private void OnPollCancelledOnServer(MultiplayerPoll multiplayerPoll)
		{
			List<NetworkCommunicator> pollProgressReceivers = multiplayerPoll.GetPollProgressReceivers();
			int count = pollProgressReceivers.Count;
			for (int i = 0; i < count; i++)
			{
				GameNetwork.BeginModuleEventAsServer(pollProgressReceivers[i]);
				GameNetwork.WriteMessage(new PollCancelled());
				GameNetwork.EndModuleEventAsServer();
			}
			CancelPoll();
		}

		public void RequestKickPlayerPoll(NetworkCommunicator peer, bool banPlayer)
		{
			if (GameNetwork.IsServer)
			{
				if (GameNetwork.MyPeer != null)
				{
					OpenKickPlayerPollOnServer(GameNetwork.MyPeer, peer, banPlayer);
				}
			}
			else
			{
				GameNetwork.BeginModuleEventAsClient();
				GameNetwork.WriteMessage(new KickPlayerPollRequested(peer, banPlayer));
				GameNetwork.EndModuleEventAsClient();
			}
		}

		private void OpenKickPlayerPollOnServer(NetworkCommunicator pollCreatorPeer, NetworkCommunicator targetPeer, bool banPlayer)
		{
			if (_ongoingPoll == null)
			{
				bool num = pollCreatorPeer?.IsConnectionActive ?? false;
				bool flag = targetPeer?.IsConnectionActive ?? false;
				if (!(num && flag))
				{
					return;
				}
				if (targetPeer.IsSynchronized)
				{
					MissionPeer component = pollCreatorPeer.GetComponent<MissionPeer>();
					if (component == null)
					{
						return;
					}
					if (component.RequestedKickPollCount < 2)
					{
						List<NetworkCommunicator> list = new List<NetworkCommunicator>();
						foreach (NetworkCommunicator networkPeer in GameNetwork.NetworkPeers)
						{
							if (networkPeer != targetPeer && networkPeer.IsSynchronized)
							{
								MissionPeer component2 = networkPeer.GetComponent<MissionPeer>();
								if (component2 != null && component2.Team == component.Team)
								{
									list.Add(networkPeer);
								}
							}
						}
						int count = list.Count;
						if (count + 1 >= 3)
						{
							OpenKickPlayerPoll(targetPeer, pollCreatorPeer, banPlayer: false, list);
							for (int i = 0; i < count; i++)
							{
								GameNetwork.BeginModuleEventAsServer(_ongoingPoll.ParticipantsToVote[i]);
								GameNetwork.WriteMessage(new KickPlayerPollOpened(pollCreatorPeer, targetPeer, banPlayer));
								GameNetwork.EndModuleEventAsServer();
							}
							GameNetwork.BeginModuleEventAsServer(targetPeer);
							GameNetwork.WriteMessage(new KickPlayerPollOpened(pollCreatorPeer, targetPeer, banPlayer));
							GameNetwork.EndModuleEventAsServer();
							component.IncrementRequestedKickPollCount();
						}
						else
						{
							RejectPollOnServer(pollCreatorPeer, MultiplayerPollRejectReason.NotEnoughPlayersToOpenPoll);
						}
					}
					else
					{
						RejectPollOnServer(pollCreatorPeer, MultiplayerPollRejectReason.TooManyPollRequests);
					}
				}
				else
				{
					RejectPollOnServer(pollCreatorPeer, MultiplayerPollRejectReason.KickPollTargetNotSynced);
				}
			}
			else
			{
				RejectPollOnServer(pollCreatorPeer, MultiplayerPollRejectReason.HasOngoingPoll);
			}
		}

		private void OpenKickPlayerPoll(NetworkCommunicator targetPeer, NetworkCommunicator pollCreatorPeer, bool banPlayer, List<NetworkCommunicator> participantsToVote)
		{
			MissionPeer component = pollCreatorPeer.GetComponent<MissionPeer>();
			MissionPeer component2 = targetPeer.GetComponent<MissionPeer>();
			_ongoingPoll = new KickPlayerPoll(_missionLobbyComponent.MissionType, participantsToVote, targetPeer, component.Team);
			if (GameNetwork.IsServer)
			{
				MultiplayerPoll ongoingPoll = _ongoingPoll;
				ongoingPoll.OnClosedOnServer = (Action<MultiplayerPoll>)Delegate.Combine(ongoingPoll.OnClosedOnServer, new Action<MultiplayerPoll>(OnKickPlayerPollClosedOnServer));
				MultiplayerPoll ongoingPoll2 = _ongoingPoll;
				ongoingPoll2.OnCancelledOnServer = (Action<MultiplayerPoll>)Delegate.Combine(ongoingPoll2.OnCancelledOnServer, new Action<MultiplayerPoll>(OnPollCancelledOnServer));
			}
			OnKickPollOpened?.Invoke(component, component2, banPlayer);
			if (GameNetwork.MyPeer == pollCreatorPeer)
			{
				Vote(accepted: true);
			}
		}

		private void OnKickPlayerPollClosedOnServer(MultiplayerPoll multiplayerPoll)
		{
			KickPlayerPoll kickPlayerPoll = multiplayerPoll as KickPlayerPoll;
			bool flag = kickPlayerPoll.GotEnoughAcceptVotesToEnd();
			GameNetwork.BeginBroadcastModuleEvent();
			GameNetwork.WriteMessage(new KickPlayerPollClosed(kickPlayerPoll.TargetPeer, flag));
			GameNetwork.EndBroadcastModuleEvent(GameNetwork.EventBroadcastFlags.None);
			CloseKickPlayerPoll(flag, kickPlayerPoll.TargetPeer);
			if (flag)
			{
				DisconnectInfo disconnectInfo = kickPlayerPoll.TargetPeer.PlayerConnectionInfo.GetParameter<DisconnectInfo>("DisconnectInfo") ?? new DisconnectInfo();
				disconnectInfo.Type = DisconnectType.KickedByPoll;
				kickPlayerPoll.TargetPeer.PlayerConnectionInfo.AddParameter("DisconnectInfo", disconnectInfo);
				GameNetwork.AddNetworkPeerToDisconnectAsServer(kickPlayerPoll.TargetPeer);
			}
		}

		private void CloseKickPlayerPoll(bool accepted, NetworkCommunicator targetPeer)
		{
			if (_ongoingPoll != null)
			{
				_ongoingPoll.Close();
				_ongoingPoll = null;
			}
			OnPollClosed?.Invoke();
			if (!GameNetwork.IsDedicatedServer && accepted && !targetPeer.IsMine)
			{
				_notificationsComponent.PlayerKicked(targetPeer);
			}
		}

		private void OnBanPlayerPollClosedOnServer(MultiplayerPoll multiplayerPoll)
		{
			MissionPeer component = (multiplayerPoll as BanPlayerPoll).TargetPeer.GetComponent<MissionPeer>();
			if (component != null)
			{
				NetworkCommunicator networkPeer = component.GetNetworkPeer();
				DisconnectInfo disconnectInfo = networkPeer.PlayerConnectionInfo.GetParameter<DisconnectInfo>("DisconnectInfo") ?? new DisconnectInfo();
				disconnectInfo.Type = DisconnectType.BannedByPoll;
				networkPeer.PlayerConnectionInfo.AddParameter("DisconnectInfo", disconnectInfo);
				GameNetwork.AddNetworkPeerToDisconnectAsServer(networkPeer);
				if (GameNetwork.IsServer)
				{
					CustomGameBannedPlayerManager.AddBannedPlayer(component.Peer.Id, Environment.TickCount + 600000);
				}
				if (GameNetwork.IsDedicatedServer)
				{
					throw new NotImplementedException();
				}
				NetworkMain.GameClient.KickPlayer(component.Peer.Id, banPlayer: true);
			}
		}

		private void StartChangeGamePollOnServer(NetworkCommunicator pollCreatorPeer, string gameType, string scene)
		{
			if (_ongoingPoll == null)
			{
				List<NetworkCommunicator> participantsToVote = GameNetwork.NetworkPeers.ToList();
				_ongoingPoll = new ChangeGamePoll(_missionLobbyComponent.MissionType, participantsToVote, gameType, scene);
				if (GameNetwork.IsServer)
				{
					MultiplayerPoll ongoingPoll = _ongoingPoll;
					ongoingPoll.OnClosedOnServer = (Action<MultiplayerPoll>)Delegate.Combine(ongoingPoll.OnClosedOnServer, new Action<MultiplayerPoll>(OnChangeGamePollClosedOnServer));
				}
				if (!GameNetwork.IsDedicatedServer)
				{
					ShowChangeGamePoll(gameType, scene);
				}
				GameNetwork.BeginBroadcastModuleEvent();
				GameNetwork.WriteMessage(new NetworkMessages.FromServer.ChangeGamePoll(gameType, scene));
				GameNetwork.EndBroadcastModuleEvent(GameNetwork.EventBroadcastFlags.None);
			}
			else
			{
				RejectPollOnServer(pollCreatorPeer, MultiplayerPollRejectReason.HasOngoingPoll);
			}
		}

		private void StartChangeGamePoll(string gameType, string map)
		{
			if (GameNetwork.IsServer)
			{
				if (GameNetwork.MyPeer != null)
				{
					StartChangeGamePollOnServer(GameNetwork.MyPeer, gameType, map);
				}
			}
			else
			{
				GameNetwork.BeginModuleEventAsClient();
				GameNetwork.WriteMessage(new NetworkMessages.FromClient.ChangeGamePoll(gameType, map));
				GameNetwork.EndModuleEventAsClient();
			}
		}

		private void ShowChangeGamePoll(string gameType, string scene)
		{
		}

		private void OnChangeGamePollClosedOnServer(MultiplayerPoll multiplayerPoll)
		{
			ChangeGamePoll changeGamePoll = multiplayerPoll as ChangeGamePoll;
			MultiplayerOptions.OptionType.GameType.SetValue(changeGamePoll.GameType);
			MultiplayerOptions.Instance.OnGameTypeChanged();
			MultiplayerOptions.OptionType.Map.SetValue(changeGamePoll.MapName);
			_missionLobbyComponent.SetStateEndingAsServer();
		}

		protected override void AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegistererContainer registerer)
		{
			if (GameNetwork.IsClient)
			{
				registerer.RegisterBaseHandler<PollRequestRejected>(HandleServerEventPollRequestRejected);
				registerer.RegisterBaseHandler<PollProgress>(HandleServerEventUpdatePollProgress);
				registerer.RegisterBaseHandler<PollCancelled>(HandleServerEventPollCancelled);
				registerer.RegisterBaseHandler<KickPlayerPollOpened>(HandleServerEventKickPlayerPollOpened);
				registerer.RegisterBaseHandler<KickPlayerPollClosed>(HandleServerEventKickPlayerPollClosed);
				registerer.RegisterBaseHandler<NetworkMessages.FromServer.ChangeGamePoll>(HandleServerEventChangeGamePoll);
			}
			else if (GameNetwork.IsServer)
			{
				registerer.RegisterBaseHandler<PollResponse>(HandleClientEventPollResponse);
				registerer.RegisterBaseHandler<KickPlayerPollRequested>(HandleClientEventKickPlayerPollRequested);
				registerer.RegisterBaseHandler<NetworkMessages.FromClient.ChangeGamePoll>(HandleClientEventChangeGamePoll);
			}
		}

		private bool HandleClientEventChangeGamePoll(NetworkCommunicator peer, GameNetworkMessage baseMessage)
		{
			NetworkMessages.FromClient.ChangeGamePoll changeGamePoll = (NetworkMessages.FromClient.ChangeGamePoll)baseMessage;
			StartChangeGamePollOnServer(peer, changeGamePoll.GameType, changeGamePoll.Map);
			return true;
		}

		private bool HandleClientEventKickPlayerPollRequested(NetworkCommunicator peer, GameNetworkMessage baseMessage)
		{
			KickPlayerPollRequested kickPlayerPollRequested = (KickPlayerPollRequested)baseMessage;
			OpenKickPlayerPollOnServer(peer, kickPlayerPollRequested.PlayerPeer, kickPlayerPollRequested.BanPlayer);
			return true;
		}

		private bool HandleClientEventPollResponse(NetworkCommunicator peer, GameNetworkMessage baseMessage)
		{
			PollResponse pollResponse = (PollResponse)baseMessage;
			ApplyVote(peer, pollResponse.Accepted);
			return true;
		}

		private void HandleServerEventChangeGamePoll(GameNetworkMessage baseMessage)
		{
			NetworkMessages.FromServer.ChangeGamePoll changeGamePoll = (NetworkMessages.FromServer.ChangeGamePoll)baseMessage;
			ShowChangeGamePoll(changeGamePoll.GameType, changeGamePoll.Map);
		}

		private void HandleServerEventKickPlayerPollOpened(GameNetworkMessage baseMessage)
		{
			KickPlayerPollOpened kickPlayerPollOpened = (KickPlayerPollOpened)baseMessage;
			OpenKickPlayerPoll(kickPlayerPollOpened.PlayerPeer, kickPlayerPollOpened.InitiatorPeer, kickPlayerPollOpened.BanPlayer, null);
		}

		private void HandleServerEventUpdatePollProgress(GameNetworkMessage baseMessage)
		{
			PollProgress pollProgress = (PollProgress)baseMessage;
			UpdatePollProgress(pollProgress.VotesAccepted, pollProgress.VotesRejected);
		}

		private void HandleServerEventPollCancelled(GameNetworkMessage baseMessage)
		{
			CancelPoll();
		}

		private void HandleServerEventKickPlayerPollClosed(GameNetworkMessage baseMessage)
		{
			KickPlayerPollClosed kickPlayerPollClosed = (KickPlayerPollClosed)baseMessage;
			CloseKickPlayerPoll(kickPlayerPollClosed.Accepted, kickPlayerPollClosed.PlayerPeer);
		}

		private void HandleServerEventPollRequestRejected(GameNetworkMessage baseMessage)
		{
			PollRequestRejected pollRequestRejected = (PollRequestRejected)baseMessage;
			RejectPoll((MultiplayerPollRejectReason)pollRequestRejected.Reason);
		}
	}
	public class MultiplayerRoundComponent : MissionNetwork, IRoundComponent, IMissionBehavior
	{
		public const int RoundEndDelayTime = 3;

		public const int RoundEndWaitTime = 8;

		public const int MatchEndWaitTime = 5;

		public const int WarmupEndWaitTime = 30;

		private MissionMultiplayerGameModeBaseClient _gameModeClient;

		public float RemainingRoundTime => _gameModeClient.TimerComponent.GetRemainingTime(isSynched: true);

		public float LastRoundEndRemainingTime { get; private set; }

		public MultiplayerRoundState CurrentRoundState { get; private set; }

		public int RoundCount { get; private set; }

		public BattleSideEnum RoundWinner { get; private set; }

		public RoundEndReason RoundEndReason { get; private set; }

		public event Action OnRoundStarted;

		public event Action OnPreparationEnded;

		public event Action OnPreRoundEnding;

		public event Action OnRoundEnding;

		public event Action OnPostRoundEnded;

		public event Action OnCurrentRoundStateChanged;

		public override void AfterStart()
		{
			AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode.Add);
			_gameModeClient = Mission.Current.GetMissionBehavior<MissionMultiplayerGameModeBaseClient>();
		}

		protected override void OnUdpNetworkHandlerClose()
		{
			AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode.Remove);
		}

		private void AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode mode)
		{
			GameNetwork.NetworkMessageHandlerRegisterer networkMessageHandlerRegisterer = new GameNetwork.NetworkMessageHandlerRegisterer(mode);
			if (GameNetwork.IsClient)
			{
				networkMessageHandlerRegisterer.Register<RoundStateChange>(HandleServerEventChangeRoundState);
				networkMessageHandlerRegisterer.Register<RoundCountChange>(HandleServerEventRoundCountChange);
				networkMessageHandlerRegisterer.Register<RoundWinnerChange>(HandleServerEventRoundWinnerChange);
				networkMessageHandlerRegisterer.Register<RoundEndReasonChange>(HandleServerEventRoundEndReasonChange);
			}
		}

		private void HandleServerEventChangeRoundState(RoundStateChange message)
		{
			if (CurrentRoundState == MultiplayerRoundState.InProgress)
			{
				LastRoundEndRemainingTime = message.RemainingTimeOnPreviousState;
			}
			CurrentRoundState = message.RoundState;
			switch (CurrentRoundState)
			{
			case MultiplayerRoundState.Preparation:
				_gameModeClient.TimerComponent.StartTimerAsClient(message.StateStartTimeInSeconds, MultiplayerOptions.OptionType.RoundPreparationTimeLimit.GetIntValue());
				if (this.OnRoundStarted != null)
				{
					this.OnRoundStarted();
				}
				break;
			case MultiplayerRoundState.InProgress:
				_gameModeClient.TimerComponent.StartTimerAsClient(message.StateStartTimeInSeconds, MultiplayerOptions.OptionType.RoundTimeLimit.GetIntValue());
				if (this.OnPreparationEnded != null)
				{
					this.OnPreparationEnded();
				}
				break;
			case MultiplayerRoundState.Ending:
				_gameModeClient.TimerComponent.StartTimerAsClient(message.StateStartTimeInSeconds, 3f);
				if (this.OnPreRoundEnding != null)
				{
					this.OnPreRoundEnding();
				}
				if (this.OnRoundEnding != null)
				{
					this.OnRoundEnding();
				}
				break;
			case MultiplayerRoundState.Ended:
				_gameModeClient.TimerComponent.StartTimerAsClient(message.StateStartTimeInSeconds, 5f);
				if (this.OnPostRoundEnded != null)
				{
					this.OnPostRoundEnded();
				}
				break;
			case MultiplayerRoundState.MatchEnded:
				_gameModeClient.TimerComponent.StartTimerAsClient(message.StateStartTimeInSeconds, 5f);
				break;
			}
			this.OnCurrentRoundStateChanged?.Invoke();
		}

		private void HandleServerEventRoundCountChange(RoundCountChange message)
		{
			RoundCount = message.RoundCount;
		}

		private void HandleServerEventRoundWinnerChange(RoundWinnerChange message)
		{
			RoundWinner = message.RoundWinner;
		}

		private void HandleServerEventRoundEndReasonChange(RoundEndReasonChange message)
		{
			RoundEndReason = message.RoundEndReason;
		}
	}
	public enum MultiplayerRoundState
	{
		WaitingForPlayers,
		Preparation,
		InProgress,
		Ending,
		Ended,
		MatchEnded,
		NumberOfRoundStates
	}
	public enum RoundEndReason
	{
		Invalid = -1,
		SideDepleted,
		RoundTimeEnded,
		GameModeSpecificEnded
	}
	public class MultiplayerRoundController : MissionNetwork, IRoundComponent, IMissionBehavior
	{
		private MissionMultiplayerGameModeBase _gameModeServer;

		private int _roundCount;

		private BattleSideEnum _roundWinner;

		private RoundEndReason _roundEndReason;

		private MissionLobbyComponent _missionLobbyComponent;

		private bool _roundTimeOver;

		private MissionTime _currentRoundStateStartTime;

		private bool _equipmentUpdateDisabled = true;

		public int RoundCount
		{
			get
			{
				return _roundCount;
			}
			set
			{
				if (_roundCount != value)
				{
					_roundCount = value;
					if (GameNetwork.IsServer)
					{
						GameNetwork.BeginBroadcastModuleEvent();
						GameNetwork.WriteMessage(new RoundCountChange(_roundCount));
						GameNetwork.EndBroadcastModuleEvent(GameNetwork.EventBroadcastFlags.None);
					}
				}
			}
		}

		public BattleSideEnum RoundWinner
		{
			get
			{
				return _roundWinner;
			}
			set
			{
				if (_roundWinner != value)
				{
					_roundWinner = value;
					if (GameNetwork.IsServer)
					{
						GameNetwork.BeginBroadcastModuleEvent();
						GameNetwork.WriteMessage(new RoundWinnerChange(value));
						GameNetwork.EndBroadcastModuleEvent(GameNetwork.EventBroadcastFlags.None);
					}
				}
			}
		}

		public RoundEndReason RoundEndReason
		{
			get
			{
				return _roundEndReason;
			}
			set
			{
				if (_roundEndReason != value)
				{
					_roundEndReason = value;
					if (GameNetwork.IsServer)
					{
						GameNetwork.BeginBroadcastModuleEvent();
						GameNetwork.WriteMessage(new RoundEndReasonChange(value));
						GameNetwork.EndBroadcastModuleEvent(GameNetwork.EventBroadcastFlags.None);
					}
				}
			}
		}

		public bool IsMatchEnding { get; private set; }

		public float LastRoundEndRemainingTime { get; private set; }

		public float RemainingRoundTime => _gameModeServer.TimerComponent.GetRemainingTime(isSynched: false);

		public MultiplayerRoundState CurrentRoundState { get; private set; }

		public bool IsRoundInProgress => CurrentRoundState == MultiplayerRoundState.InProgress;

		public event Action OnRoundStarted;

		public event Action OnPreparationEnded;

		public event Action OnPreRoundEnding;

		public event Action OnRoundEnding;

		public event Action OnPostRoundEnded;

		public event Action OnCurrentRoundStateChanged;

		public void EnableEquipmentUpdate()
		{
			_equipmentUpdateDisabled = false;
		}

		public override void AfterStart()
		{
			AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode.Add);
			if (GameNetwork.IsServerOrRecorder)
			{
				_gameModeServer = Mission.Current.GetMissionBehavior<MissionMultiplayerGameModeBase>();
			}
			_missionLobbyComponent = Mission.Current.GetMissionBehavior<MissionLobbyComponent>();
			_roundCount = 0;
			_gameModeServer.TimerComponent.StartTimerAsServer(8f);
		}

		private void EndRound()
		{
			if (this.OnPreRoundEnding != null)
			{
				this.OnPreRoundEnding();
			}
			ChangeRoundState(MultiplayerRoundState.Ending);
			_gameModeServer.TimerComponent.StartTimerAsServer(3f);
			_roundTimeOver = false;
			if (this.OnRoundEnding != null)
			{
				this.OnRoundEnding();
			}
		}

		private bool CheckPostEndRound()
		{
			return _gameModeServer.TimerComponent.CheckIfTimerPassed();
		}

		private bool CheckPostMatchEnd()
		{
			return _gameModeServer.TimerComponent.CheckIfTimerPassed();
		}

		private void PostRoundEnd()
		{
			_gameModeServer.TimerComponent.StartTimerAsServer(5f);
			ChangeRoundState(MultiplayerRoundState.Ended);
			if (_roundCount == MultiplayerOptions.OptionType.RoundTotal.GetIntValue() || CheckForMatchEndEarly() || !HasEnoughCharactersOnBothSides())
			{
				IsMatchEnding = true;
			}
			if (this.OnPostRoundEnded != null)
			{
				this.OnPostRoundEnded();
			}
		}

		private void PostMatchEnd()
		{
			_gameModeServer.TimerComponent.StartTimerAsServer(5f);
			ChangeRoundState(MultiplayerRoundState.MatchEnded);
			_missionLobbyComponent.SetStateEndingAsServer();
		}

		public override void OnRemoveBehavior()
		{
			GameNetwork.RemoveNetworkHandler(this);
			base.OnRemoveBehavior();
		}

		private void AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode mode)
		{
			GameNetwork.NetworkMessageHandlerRegisterer networkMessageHandlerRegisterer = new GameNetwork.NetworkMessageHandlerRegisterer(mode);
			if (!GameNetwork.IsClient && GameNetwork.IsServer)
			{
				networkMessageHandlerRegisterer.Register<CultureVoteClient>(HandleClientEventCultureSelect);
			}
		}

		protected override void OnUdpNetworkHandlerClose()
		{
			AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode.Remove);
		}

		public override void OnPreDisplayMissionTick(float dt)
		{
			if (GameNetwork.IsServer)
			{
				if (_missionLobbyComponent.CurrentMultiplayerState == MissionLobbyComponent.MultiplayerGameState.WaitingFirstPlayers)
				{
					return;
				}
				if (!IsMatchEnding && _missionLobbyComponent.CurrentMultiplayerState != MissionLobbyComponent.MultiplayerGameState.Ending && (CurrentRoundState == MultiplayerRoundState.WaitingForPlayers || CurrentRoundState == MultiplayerRoundState.Ended))
				{
					if (CheckForNewRound())
					{
						BeginNewRound();
					}
					else if (IsMatchEnding)
					{
						PostMatchEnd();
					}
				}
				else if (CurrentRoundState == MultiplayerRoundState.Preparation)
				{
					if (CheckForPreparationEnd())
					{
						EndPreparation();
						StartSpawning(_equipmentUpdateDisabled);
					}
				}
				else if (CurrentRoundState == MultiplayerRoundState.InProgress)
				{
					if (CheckForRoundEnd())
					{
						EndRound();
					}
				}
				else if (CurrentRoundState == MultiplayerRoundState.Ending)
				{
					if (CheckPostEndRound())
					{
						PostRoundEnd();
					}
				}
				else if (CurrentRoundState == MultiplayerRoundState.Ended && IsMatchEnding && CheckPostMatchEnd())
				{
					PostMatchEnd();
				}
			}
			else
			{
				_gameModeServer.TimerComponent.CheckIfTimerPassed();
			}
		}

		private void ChangeRoundState(MultiplayerRoundState newRoundState)
		{
			if (CurrentRoundState != newRoundState)
			{
				if (CurrentRoundState == MultiplayerRoundState.InProgress)
				{
					LastRoundEndRemainingTime = RemainingRoundTime;
				}
				CurrentRoundState = newRoundState;
				_currentRoundStateStartTime = MissionTime.Now;
				this.OnCurrentRoundStateChanged?.Invoke();
				GameNetwork.BeginBroadcastModuleEvent();
				GameNetwork.WriteMessage(new RoundStateChange(newRoundState, _currentRoundStateStartTime.NumberOfTicks, TaleWorlds.Library.MathF.Ceiling(LastRoundEndRemainingTime)));
				GameNetwork.EndBroadcastModuleEvent(GameNetwork.EventBroadcastFlags.None);
			}
		}

		protected override void HandleLateNewClientAfterLoadingFinished(NetworkCommunicator networkPeer)
		{
		}

		public bool HandleClientEventCultureSelect(NetworkCommunicator peer, CultureVoteClient message)
		{
			peer.GetComponent<MissionPeer>().HandleVoteChange(message.VotedType, message.VotedCulture);
			return true;
		}

		private bool CheckForRoundEnd()
		{
			if (!_roundTimeOver)
			{
				_roundTimeOver = _gameModeServer.TimerComponent.CheckIfTimerPassed();
			}
			if (_gameModeServer.CheckIfOvertime() || !_roundTimeOver)
			{
				return _gameModeServer.CheckForRoundEnd();
			}
			return true;
		}

		private bool CheckForNewRound()
		{
			if (CurrentRoundState == MultiplayerRoundState.WaitingForPlayers || _gameModeServer.TimerComponent.CheckIfTimerPassed())
			{
				int[] array = new int[2];
				foreach (NetworkCommunicator networkPeer in GameNetwork.NetworkPeers)
				{
					MissionPeer component = networkPeer.GetComponent<MissionPeer>();
					if (networkPeer.IsSynchronized && component?.Team != null && component.Team.Side != BattleSideEnum.None)
					{
						array[(int)component.Team.Side]++;
					}
				}
				if (array.Sum() < MultiplayerOptions.OptionType.MinNumberOfPlayersForMatchStart.GetIntValue() && RoundCount == 0)
				{
					IsMatchEnding = true;
					return false;
				}
				return true;
			}
			return false;
		}

		private bool HasEnoughCharactersOnBothSides()
		{
			bool num = MultiplayerOptions.OptionType.NumberOfBotsTeam1.GetIntValue() > 0 || GameNetwork.NetworkPeers.Count((NetworkCommunicator q) => q.GetComponent<MissionPeer>() != null && q.GetComponent<MissionPeer>().Team == Mission.Current.AttackerTeam) > 0;
			bool flag = MultiplayerOptions.OptionType.NumberOfBotsTeam2.GetIntValue() > 0 || GameNetwork.NetworkPeers.Count((NetworkCommunicator q) => q.GetComponent<MissionPeer>() != null && q.GetComponent<MissionPeer>().Team == Mission.Current.DefenderTeam) > 0;
			return num && flag;
		}

		private void BeginNewRound()
		{
			if (CurrentRoundState == MultiplayerRoundState.WaitingForPlayers)
			{
				_gameModeServer.ClearPeerCounts();
			}
			ChangeRoundState(MultiplayerRoundState.Preparation);
			RoundCount++;
			Mission.Current.ResetMission();
			_gameModeServer.MultiplayerTeamSelectComponent.BalanceTeams();
			_gameModeServer.TimerComponent.StartTimerAsServer(MultiplayerOptions.OptionType.RoundPreparationTimeLimit.GetIntValue());
			this.OnRoundStarted?.Invoke();
			_gameModeServer.SpawnComponent.ToggleUpdatingSpawnEquipment(canUpdate: true);
		}

		private bool CheckForPreparationEnd()
		{
			if (CurrentRoundState != MultiplayerRoundState.Preparation)
			{
				return false;
			}
			return _gameModeServer.TimerComponent.CheckIfTimerPassed();
		}

		private void EndPreparation()
		{
			if (this.OnPreparationEnded != null)
			{
				this.OnPreparationEnded();
			}
		}

		private void StartSpawning(bool disableEquipmentUpdate = true)
		{
			_gameModeServer.TimerComponent.StartTimerAsServer(MultiplayerOptions.OptionType.RoundTimeLimit.GetIntValue());
			if (disableEquipmentUpdate)
			{
				_gameModeServer.SpawnComponent.ToggleUpdatingSpawnEquipment(canUpdate: false);
			}
			ChangeRoundState(MultiplayerRoundState.InProgress);
		}

		private bool CheckForMatchEndEarly()
		{
			bool result = false;
			MissionScoreboardComponent missionBehavior = Mission.Current.GetMissionBehavior<MissionScoreboardComponent>();
			if (missionBehavior != null)
			{
				for (int i = 0; i < 2; i++)
				{
					if (missionBehavior.GetRoundScore((BattleSideEnum)i) > MultiplayerOptions.OptionType.RoundTotal.GetIntValue() / 2)
					{
						result = true;
						break;
					}
				}
			}
			return result;
		}

		protected override void HandleNewClientAfterSynchronized(NetworkCommunicator networkPeer)
		{
			if (!networkPeer.IsServerPeer)
			{
				GameNetwork.BeginModuleEventAsServer(networkPeer);
				GameNetwork.WriteMessage(new RoundStateChange(CurrentRoundState, _currentRoundStateStartTime.NumberOfTicks, TaleWorlds.Library.MathF.Ceiling(LastRoundEndRemainingTime)));
				GameNetwork.EndModuleEventAsServer();
				GameNetwork.BeginModuleEventAsServer(networkPeer);
				GameNetwork.WriteMessage(new RoundWinnerChange(RoundWinner));
				GameNetwork.EndModuleEventAsServer();
				GameNetwork.BeginModuleEventAsServer(networkPeer);
				GameNetwork.WriteMessage(new RoundCountChange(RoundCount));
				GameNetwork.EndModuleEventAsServer();
			}
		}
	}
	public class MultiplayerTeamSelectComponent : MissionNetwork
	{
		public delegate void OnSelectingTeamDelegate(List<Team> disableTeams);

		private MissionNetworkComponent _missionNetworkComponent;

		private MissionMultiplayerGameModeBase _gameModeServer;

		private HashSet<PlayerId> _platformFriends;

		private Dictionary<Team, IEnumerable<VirtualPlayer>> _friendsPerTeam;

		public bool TeamSelectionEnabled { get; private set; }

		public event OnSelectingTeamDelegate OnSelectingTeam;

		public event Action OnMyTeamChange;

		public event Action OnUpdateTeams;

		public event Action OnUpdateFriendsPerTeam;

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			_missionNetworkComponent = base.Mission.GetMissionBehavior<MissionNetworkComponent>();
			_gameModeServer = base.Mission.GetMissionBehavior<MissionMultiplayerGameModeBase>();
			if (BannerlordNetwork.LobbyMissionType == LobbyMissionType.Matchmaker)
			{
				TeamSelectionEnabled = false;
			}
			else
			{
				TeamSelectionEnabled = true;
			}
		}

		protected override void AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegistererContainer registerer)
		{
			if (GameNetwork.IsServer)
			{
				registerer.RegisterBaseHandler<TeamChange>(HandleClientEventTeamChange);
			}
		}

		private void OnMyClientSynchronized()
		{
			base.Mission.GetMissionBehavior<MissionNetworkComponent>().OnMyClientSynchronized -= OnMyClientSynchronized;
			if (Mission.Current.GetMissionBehavior<MissionLobbyComponent>().CurrentMultiplayerState != MissionLobbyComponent.MultiplayerGameState.Ending && GameNetwork.MyPeer.GetComponent<MissionPeer>().Team == null)
			{
				SelectTeam();
			}
		}

		public override void AfterStart()
		{
			_platformFriends = new HashSet<PlayerId>();
			foreach (PlayerId allFriendsInAllPlatform in FriendListService.GetAllFriendsInAllPlatforms())
			{
				_platformFriends.Add(allFriendsInAllPlatform);
			}
			_friendsPerTeam = new Dictionary<Team, IEnumerable<VirtualPlayer>>();
			MissionPeer.OnTeamChanged += UpdateTeams;
			if (GameNetwork.IsClient)
			{
				MissionNetworkComponent missionBehavior = base.Mission.GetMissionBehavior<MissionNetworkComponent>();
				if (TeamSelectionEnabled)
				{
					missionBehavior.OnMyClientSynchronized += OnMyClientSynchronized;
				}
			}
		}

		public override void OnRemoveBehavior()
		{
			MissionPeer.OnTeamChanged -= UpdateTeams;
			this.OnMyTeamChange = null;
			base.OnRemoveBehavior();
		}

		private bool HandleClientEventTeamChange(NetworkCommunicator peer, GameNetworkMessage baseMessage)
		{
			TeamChange teamChange = (TeamChange)baseMessage;
			if (TeamSelectionEnabled)
			{
				if (teamChange.AutoAssign)
				{
					AutoAssignTeam(peer);
				}
				else
				{
					Team teamFromTeamIndex = Mission.MissionNetworkHelper.GetTeamFromTeamIndex(teamChange.TeamIndex);
					ChangeTeamServer(peer, teamFromTeamIndex);
				}
			}
			return true;
		}

		public void SelectTeam()
		{
			if (this.OnSelectingTeam != null)
			{
				List<Team> disabledTeams = GetDisabledTeams();
				this.OnSelectingTeam(disabledTeams);
			}
		}

		public void UpdateTeams(NetworkCommunicator peer, Team oldTeam, Team newTeam)
		{
			if (this.OnUpdateTeams != null)
			{
				this.OnUpdateTeams();
			}
			if (GameNetwork.IsMyPeerReady)
			{
				CacheFriendsForTeams();
			}
			if (newTeam.Side != BattleSideEnum.None)
			{
				MissionPeer component = peer.GetComponent<MissionPeer>();
				component.SelectedTroopIndex = 0;
				component.NextSelectedTroopIndex = 0;
				component.OverrideCultureWithTeamCulture();
			}
		}

		public List<Team> GetDisabledTeams()
		{
			List<Team> list = new List<Team>();
			if (MultiplayerOptions.OptionType.AutoTeamBalanceThreshold.GetIntValue() == 0)
			{
				return list;
			}
			Team myTeam = (GameNetwork.IsMyPeerReady ? GameNetwork.MyPeer.GetComponent<MissionPeer>().Team : null);
			Team[] array = (from q in base.Mission.Teams
				where q != base.Mission.SpectatorTeam
				orderby (myTeam != null) ? ((q != myTeam) ? GetPlayerCountForTeam(q) : (GetPlayerCountForTeam(q) - 1)) : GetPlayerCountForTeam(q)
				select q).ToArray();
			Team[] array2 = array;
			foreach (Team team in array2)
			{
				int num = GetPlayerCountForTeam(team);
				int num2 = GetPlayerCountForTeam(array[0]);
				if (myTeam == team)
				{
					num--;
				}
				if (myTeam == array[0])
				{
					num2--;
				}
				if (num - num2 >= MultiplayerOptions.OptionType.AutoTeamBalanceThreshold.GetIntValue())
				{
					list.Add(team);
				}
			}
			return list;
		}

		public void ChangeTeamServer(NetworkCommunicator networkPeer, Team team)
		{
			MissionPeer component = networkPeer.GetComponent<MissionPeer>();
			Team team2 = component.Team;
			if (team2 != null && team2 != base.Mission.SpectatorTeam && team2 != team && component.ControlledAgent != null)
			{
				Blow b = new Blow(component.ControlledAgent.Index);
				b.DamageType = DamageTypes.Invalid;
				b.BaseMagnitude = 10000f;
				b.GlobalPosition = component.ControlledAgent.Position;
				b.DamagedPercentage = 1f;
				component.ControlledAgent.Die(b, Agent.KillInfo.TeamSwitch);
			}
			component.Team = team;
			BasicCultureObject culture = (component.Team.IsAttacker ? MBObjectManager.Instance.GetObject<BasicCultureObject>(MultiplayerOptions.OptionType.CultureTeam1.GetStrValue()) : MBObjectManager.Instance.GetObject<BasicCultureObject>(MultiplayerOptions.OptionType.CultureTeam2.GetStrValue()));
			component.Culture = culture;
			if (team != team2)
			{
				if (component.HasSpawnedAgentVisuals)
				{
					component.HasSpawnedAgentVisuals = false;
					MBDebug.Print("HasSpawnedAgentVisuals = false for peer: " + component.Name + " because he just changed his team");
					component.SpawnCountThisRound = 0;
					Mission.Current.GetMissionBehavior<MultiplayerMissionAgentVisualSpawnComponent>().RemoveAgentVisuals(component, sync: true);
					if (GameNetwork.IsServerOrRecorder)
					{
						GameNetwork.BeginBroadcastModuleEvent();
						GameNetwork.WriteMessage(new RemoveAgentVisualsForPeer(component.GetNetworkPeer()));
						GameNetwork.EndBroadcastModuleEvent(GameNetwork.EventBroadcastFlags.None);
					}
					component.HasSpawnedAgentVisuals = false;
				}
				if (!_gameModeServer.IsGameModeHidingAllAgentVisuals && !networkPeer.IsServerPeer)
				{
					_missionNetworkComponent?.OnPeerSelectedTeam(component);
				}
				_gameModeServer.OnPeerChangedTeam(networkPeer, team2, team);
				component.SpawnTimer.Reset(Mission.Current.CurrentTime, 0.1f);
				component.WantsToSpawnAsBot = false;
				component.HasSpawnTimerExpired = false;
			}
			UpdateTeams(networkPeer, team2, team);
		}

		public void ChangeTeam(Team team)
		{
			if (team == GameNetwork.MyPeer.GetComponent<MissionPeer>().Team)
			{
				return;
			}
			if (GameNetwork.IsServer)
			{
				Mission.Current.PlayerTeam = team;
				ChangeTeamServer(GameNetwork.MyPeer, team);
			}
			else
			{
				foreach (NetworkCommunicator networkPeer in GameNetwork.NetworkPeers)
				{
					networkPeer.GetComponent<MissionPeer>()?.ClearAllVisuals();
				}
				GameNetwork.BeginModuleEventAsClient();
				GameNetwork.WriteMessage(new TeamChange(autoAssign: false, team.TeamIndex));
				GameNetwork.EndModuleEventAsClient();
			}
			if (this.OnMyTeamChange != null)
			{
				this.OnMyTeamChange();
			}
		}

		public int GetPlayerCountForTeam(Team team)
		{
			int num = 0;
			foreach (NetworkCommunicator networkPeer in GameNetwork.NetworkPeers)
			{
				MissionPeer component = networkPeer.GetComponent<MissionPeer>();
				if (component?.Team != null && component.Team == team)
				{
					num++;
				}
			}
			return num;
		}

		private void CacheFriendsForTeams()
		{
			_friendsPerTeam.Clear();
			if (_platformFriends.Count <= 0)
			{
				return;
			}
			List<MissionPeer> list = new List<MissionPeer>();
			foreach (NetworkCommunicator networkPeer in GameNetwork.NetworkPeers)
			{
				MissionPeer component = networkPeer.GetComponent<MissionPeer>();
				if (component != null && _platformFriends.Contains(networkPeer.VirtualPlayer.Id))
				{
					list.Add(component);
				}
			}
			foreach (Team team in base.Mission.Teams)
			{
				if (team != null)
				{
					_friendsPerTeam.Add(team, from x in list
						where x.Team == team
						select x.Peer);
				}
			}
			if (this.OnUpdateFriendsPerTeam != null)
			{
				this.OnUpdateFriendsPerTeam();
			}
		}

		public IEnumerable<VirtualPlayer> GetFriendsForTeam(Team team)
		{
			if (_friendsPerTeam.ContainsKey(team))
			{
				return _friendsPerTeam[team];
			}
			return new List<VirtualPlayer>();
		}

		public void BalanceTeams()
		{
			if (MultiplayerOptions.OptionType.AutoTeamBalanceThreshold.GetIntValue() == 0)
			{
				return;
			}
			int num = GetPlayerCountForTeam(Mission.Current.AttackerTeam);
			int i;
			for (i = GetPlayerCountForTeam(Mission.Current.DefenderTeam); num > i + MultiplayerOptions.OptionType.AutoTeamBalanceThreshold.GetIntValue(); i++)
			{
				MissionPeer missionPeer = null;
				foreach (NetworkCommunicator networkPeer in GameNetwork.NetworkPeers)
				{
					if (networkPeer.IsSynchronized)
					{
						MissionPeer component = networkPeer.GetComponent<MissionPeer>();
						if (component?.Team != null && component.Team == base.Mission.AttackerTeam && (missionPeer == null || component.JoinTime >= missionPeer.JoinTime))
						{
							missionPeer = component;
						}
					}
				}
				ChangeTeamServer(missionPeer.GetNetworkPeer(), Mission.Current.DefenderTeam);
				num--;
			}
			while (i > num + MultiplayerOptions.OptionType.AutoTeamBalanceThreshold.GetIntValue())
			{
				MissionPeer missionPeer2 = null;
				foreach (NetworkCommunicator networkPeer2 in GameNetwork.NetworkPeers)
				{
					if (networkPeer2.IsSynchronized)
					{
						MissionPeer component2 = networkPeer2.GetComponent<MissionPeer>();
						if (component2?.Team != null && component2.Team == base.Mission.DefenderTeam && (missionPeer2 == null || component2.JoinTime >= missionPeer2.JoinTime))
						{
							missionPeer2 = component2;
						}
					}
				}
				ChangeTeamServer(missionPeer2.GetNetworkPeer(), Mission.Current.AttackerTeam);
				num++;
				i--;
			}
		}

		public void AutoAssignTeam(NetworkCommunicator peer)
		{
			if (GameNetwork.IsServer)
			{
				List<Team> disabledTeams = GetDisabledTeams();
				List<Team> list = base.Mission.Teams.Where((Team x) => !disabledTeams.Contains(x) && x.Side != BattleSideEnum.None).ToList();
				Team team;
				if (list.Count > 1)
				{
					int[] array = new int[list.Count];
					foreach (NetworkCommunicator networkPeer in GameNetwork.NetworkPeers)
					{
						MissionPeer component = networkPeer.GetComponent<MissionPeer>();
						if (component?.Team == null)
						{
							continue;
						}
						for (int i = 0; i < list.Count; i++)
						{
							if (component.Team == list[i])
							{
								array[i]++;
							}
						}
					}
					int num = -1;
					int num2 = -1;
					for (int j = 0; j < array.Length; j++)
					{
						if (num2 < 0 || array[j] < num)
						{
							num2 = j;
							num = array[j];
						}
					}
					team = list[num2];
				}
				else
				{
					team = list[0];
				}
				if (!peer.IsMine)
				{
					ChangeTeamServer(peer, team);
				}
				else
				{
					ChangeTeam(team);
				}
			}
			else
			{
				GameNetwork.BeginModuleEventAsClient();
				GameNetwork.WriteMessage(new TeamChange(autoAssign: true, -1));
				GameNetwork.EndModuleEventAsClient();
				if (this.OnMyTeamChange != null)
				{
					this.OnMyTeamChange();
				}
			}
		}
	}
	public class MultiplayerTimerComponent : MissionNetwork
	{
		private MissionTimer _missionTimer;

		public bool IsTimerRunning { get; private set; }

		public void StartTimerAsServer(float duration)
		{
			_missionTimer = new MissionTimer(duration);
			IsTimerRunning = true;
		}

		public void StartTimerAsClient(float startTime, float duration)
		{
			_missionTimer = MissionTimer.CreateSynchedTimerClient(startTime, duration);
			IsTimerRunning = true;
		}

		public float GetRemainingTime(bool isSynched)
		{
			if (!IsTimerRunning)
			{
				return 0f;
			}
			float remainingTimeInSeconds = _missionTimer.GetRemainingTimeInSeconds(isSynched);
			if (isSynched)
			{
				return TaleWorlds.Library.MathF.Min(remainingTimeInSeconds, _missionTimer.GetTimerDuration());
			}
			return remainingTimeInSeconds;
		}

		public bool CheckIfTimerPassed()
		{
			if (IsTimerRunning)
			{
				return _missionTimer.Check();
			}
			return false;
		}

		public MissionTime GetCurrentTimerStartTime()
		{
			return _missionTimer.GetStartTime();
		}
	}
	public class MultiplayerWarmupComponent : MissionNetwork
	{
		public enum WarmupStates
		{
			WaitingForPlayers,
			InProgress,
			Ending,
			Ended
		}

		public const int RespawnPeriodInWarmup = 3;

		public const int WarmupEndWaitTime = 30;

		private MissionMultiplayerGameModeBase _gameMode;

		private MultiplayerTimerComponent _timerComponent;

		private MissionLobbyComponent _lobbyComponent;

		private MissionTime _currentStateStartTime;

		private WarmupStates _warmupState;

		public static float TotalWarmupDuration => MultiplayerOptions.OptionType.WarmupTimeLimitInSeconds.GetIntValue();

		public bool IsInWarmup => WarmupState != WarmupStates.Ended;

		private WarmupStates WarmupState
		{
			get
			{
				return _warmupState;
			}
			set
			{
				_warmupState = value;
				if (GameNetwork.IsServer)
				{
					_currentStateStartTime = MissionTime.Now;
					GameNetwork.BeginBroadcastModuleEvent();
					GameNetwork.WriteMessage(new WarmupStateChange(_warmupState, _currentStateStartTime.NumberOfTicks));
					GameNetwork.EndBroadcastModuleEvent(GameNetwork.EventBroadcastFlags.None);
				}
			}
		}

		public event Action OnWarmupEnding;

		public event Action OnWarmupEnded;

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			_gameMode = base.Mission.GetMissionBehavior<MissionMultiplayerGameModeBase>();
			_timerComponent = base.Mission.GetMissionBehavior<MultiplayerTimerComponent>();
			_lobbyComponent = base.Mission.GetMissionBehavior<MissionLobbyComponent>();
		}

		public override void AfterStart()
		{
			base.AfterStart();
			AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode.Add);
		}

		protected override void OnUdpNetworkHandlerClose()
		{
			AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode.Remove);
		}

		private void AddRemoveMessageHandlers(GameNetwork.NetworkMessageHandlerRegisterer.RegisterMode mode)
		{
			GameNetwork.NetworkMessageHandlerRegisterer networkMessageHandlerRegisterer = new GameNetwork.NetworkMessageHandlerRegisterer(mode);
			if (GameNetwork.IsClient)
			{
				networkMessageHandlerRegisterer.Register<WarmupStateChange>(HandleServerEventWarmupStateChange);
			}
		}

		public bool CheckForWarmupProgressEnd()
		{
			if (!_gameMode.CheckForWarmupEnd())
			{
				return _timerComponent.GetRemainingTime(isSynched: false) <= 30f;
			}
			return true;
		}

		public override void OnPreDisplayMissionTick(float dt)
		{
			if (!GameNetwork.IsServer || _lobbyComponent.CurrentMultiplayerState == MissionLobbyComponent.MultiplayerGameState.Ending)
			{
				return;
			}
			switch (WarmupState)
			{
			case WarmupStates.WaitingForPlayers:
				BeginWarmup();
				break;
			case WarmupStates.InProgress:
				if (CheckForWarmupProgressEnd())
				{
					EndWarmupProgress();
				}
				break;
			case WarmupStates.Ending:
				if (_timerComponent.CheckIfTimerPassed())
				{
					EndWarmup();
				}
				break;
			case WarmupStates.Ended:
				if (_timerComponent.CheckIfTimerPassed())
				{
					base.Mission.RemoveMissionBehavior(this);
				}
				break;
			default:
				throw new ArgumentOutOfRangeException();
			}
		}

		private void BeginWarmup()
		{
			WarmupState = WarmupStates.InProgress;
			Mission.Current.ResetMission();
			_gameMode.MultiplayerTeamSelectComponent.BalanceTeams();
			_timerComponent.StartTimerAsServer(TotalWarmupDuration);
			_gameMode.SpawnComponent.SpawningBehavior.Clear();
			SpawnComponent.SetWarmupSpawningBehavior();
		}

		public void EndWarmupProgress()
		{
			WarmupState = WarmupStates.Ending;
			_timerComponent.StartTimerAsServer(30f);
			this.OnWarmupEnding?.Invoke();
		}

		private void EndWarmup()
		{
			WarmupState = WarmupStates.Ended;
			_timerComponent.StartTimerAsServer(3f);
			this.OnWarmupEnded?.Invoke();
			if (!GameNetwork.IsDedicatedServer)
			{
				PlayBattleStartingSound();
			}
			Mission.Current.ResetMission();
			_gameMode.MultiplayerTeamSelectComponent.BalanceTeams();
			_gameMode.SpawnComponent.SpawningBehavior.Clear();
			SpawnComponent.SetSpawningBehaviorForCurrentGameType(_gameMode.GetMissionType());
			if (!CanMatchStartAfterWarmup())
			{
				_lobbyComponent.SetStateEndingAsServer();
			}
		}

		public bool CanMatchStartAfterWarmup()
		{
			bool[] array = new bool[2];
			foreach (NetworkCommunicator networkPeer in GameNetwork.NetworkPeers)
			{
				MissionPeer component = networkPeer.GetComponent<MissionPeer>();
				if (component?.Team != null && component.Team.Side != BattleSideEnum.None)
				{
					array[(int)component.Team.Side] = true;
				}
				if (array[1] && array[0])
				{
					return true;
				}
			}
			return false;
		}

		public override void OnRemoveBehavior()
		{
			base.OnRemoveBehavior();
			this.OnWarmupEnding = null;
			this.OnWarmupEnded = null;
			if (GameNetwork.IsServer && !_gameMode.UseRoundController() && _lobbyComponent.CurrentMultiplayerState != MissionLobbyComponent.MultiplayerGameState.Ending)
			{
				_gameMode.SpawnComponent.SpawningBehavior.RequestStartSpawnSession();
			}
		}

		protected override void HandleNewClientAfterSynchronized(NetworkCommunicator networkPeer)
		{
			if (IsInWarmup && !networkPeer.IsServerPeer)
			{
				GameNetwork.BeginModuleEventAsServer(networkPeer);
				GameNetwork.WriteMessage(new WarmupStateChange(_warmupState, _currentStateStartTime.NumberOfTicks));
				GameNetwork.EndModuleEventAsServer();
			}
		}

		private void HandleServerEventWarmupStateChange(WarmupStateChange message)
		{
			WarmupState = message.WarmupState;
			switch (WarmupState)
			{
			case WarmupStates.InProgress:
				_timerComponent.StartTimerAsClient(message.StateStartTimeInSeconds, TotalWarmupDuration);
				break;
			case WarmupStates.Ending:
				_timerComponent.StartTimerAsClient(message.StateStartTimeInSeconds, 30f);
				this.OnWarmupEnding?.Invoke();
				break;
			case WarmupStates.Ended:
				_timerComponent.StartTimerAsClient(message.StateStartTimeInSeconds, 3f);
				this.OnWarmupEnded?.Invoke();
				PlayBattleStartingSound();
				break;
			}
		}

		private void PlayBattleStartingSound()
		{
			MatrixFrame cameraFrame = Mission.Current.GetCameraFrame();
			Vec3 position = cameraFrame.origin + cameraFrame.rotation.u;
			MissionPeer missionPeer = GameNetwork.MyPeer?.GetComponent<MissionPeer>();
			if (missionPeer?.Team != null)
			{
				string text = ((missionPeer.Team.Side == BattleSideEnum.Attacker) ? MultiplayerOptions.OptionType.CultureTeam1.GetStrValue() : MultiplayerOptions.OptionType.CultureTeam2.GetStrValue());
				MBSoundEvent.PlaySound(SoundEvent.GetEventIdFromString("event:/alerts/rally/" + text.ToLower()), position);
			}
			else
			{
				MBSoundEvent.PlaySound(SoundEvent.GetEventIdFromString("event:/alerts/rally/generic"), position);
			}
		}

		[CommandLineFunctionality.CommandLineArgumentFunction("end_warmup", "mp_host")]
		public static string CommandEndWarmup(List<string> strings)
		{
			if (Mission.Current == null)
			{
				return "end_warmup can only be called within a mission.";
			}
			if (!GameNetwork.IsServer)
			{
				return "end_warmup can only be called by the server.";
			}
			MultiplayerWarmupComponent missionBehavior = Mission.Current.GetMissionBehavior<MultiplayerWarmupComponent>();
			if (missionBehavior == null)
			{
				return "end_warmup can only be called when the game is in warmup.";
			}
			missionBehavior.EndWarmupProgress();
			return "Success";
		}
	}
	public class SpawnComponent : MissionLogic
	{
