		public WeaponData GetWeaponData(bool needBatchedVersionForMeshes)
		{
			if (!IsEmpty && Item.WeaponComponent != null)
			{
				WeaponComponent weaponComponent = Item.WeaponComponent;
				WeaponData weaponData = default(WeaponData);
				weaponData.WeaponKind = (int)Item.Id.InternalValue;
				weaponData.ItemHolsterIndices = Item.GetItemHolsterIndices();
				weaponData.ReloadPhase = ReloadPhase;
				weaponData.Difficulty = Item.Difficulty;
				weaponData.BaseWeight = GetBaseWeight();
				weaponData.HasFlagAnimation = false;
				weaponData.WeaponFrame = weaponComponent.PrimaryWeapon.Frame;
				weaponData.ScaleFactor = Item.ScaleFactor;
				weaponData.TotalInertia = weaponComponent.PrimaryWeapon.TotalInertia;
				weaponData.CenterOfMass = weaponComponent.PrimaryWeapon.CenterOfMass;
				weaponData.CenterOfMass3D = weaponComponent.PrimaryWeapon.CenterOfMass3D;
				weaponData.HolsterPositionShift = Item.HolsterPositionShift;
				weaponData.TrailParticleName = weaponComponent.PrimaryWeapon.TrailParticleName;
				weaponData.SkeletonName = Item.SkeletonName;
				weaponData.StaticAnimationName = Item.StaticAnimationName;
				weaponData.AmmoOffset = weaponComponent.PrimaryWeapon.AmmoOffset;
				WeaponData weaponData2 = weaponData;
				string physicsMaterial = weaponComponent.PrimaryWeapon.PhysicsMaterial;
				weaponData2.PhysicsMaterialIndex = (string.IsNullOrEmpty(physicsMaterial) ? PhysicsMaterial.InvalidPhysicsMaterial.Index : PhysicsMaterial.GetFromName(physicsMaterial).Index);
				weaponData2.FlyingSoundCode = SoundManager.GetEventGlobalIndex(weaponComponent.PrimaryWeapon.FlyingSoundCode);
				weaponData2.PassbySoundCode = SoundManager.GetEventGlobalIndex(weaponComponent.PrimaryWeapon.PassbySoundCode);
				weaponData2.StickingFrame = weaponComponent.PrimaryWeapon.StickingFrame;
				weaponData2.CollisionShape = ((!needBatchedVersionForMeshes || string.IsNullOrEmpty(Item.CollisionBodyName)) ? null : PhysicsShape.GetFromResource(Item.CollisionBodyName));
				weaponData2.Shape = ((!needBatchedVersionForMeshes || string.IsNullOrEmpty(Item.BodyName)) ? null : PhysicsShape.GetFromResource(Item.BodyName));
				weaponData2.DataValue = _dataValue;
				weaponData2.CurrentUsageIndex = CurrentUsageIndex;
				int rangedUsageIndex = GetRangedUsageIndex();
				if (GetConsumableIfAny(out var consumableWeapon))
				{
					weaponData2.AirFrictionConstant = ItemObject.GetAirFrictionConstant(consumableWeapon.WeaponClass, consumableWeapon.WeaponFlags);
				}
				else if (rangedUsageIndex >= 0)
				{
					weaponData2.AirFrictionConstant = ItemObject.GetAirFrictionConstant(GetWeaponComponentDataForUsage(rangedUsageIndex).WeaponClass, GetWeaponComponentDataForUsage(rangedUsageIndex).WeaponFlags);
				}
				weaponData2.GlossMultiplier = GlossMultiplier;
				weaponData2.HasLowerHolsterPriority = Item.HasLowerHolsterPriority;
				OnGetWeaponDataHandler?.Invoke(ref weaponData2, this, isFemale: false, Banner, needBatchedVersionForMeshes);
				return weaponData2;
			}
			return WeaponData.InvalidWeaponData;
		}

		public WeaponStatsData[] GetWeaponStatsData()
		{
			WeaponStatsData[] array = new WeaponStatsData[_weapons.Count];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = GetWeaponStatsDataForUsage(i);
			}
			return array;
		}

		public WeaponStatsData GetWeaponStatsDataForUsage(int usageIndex)
		{
			WeaponStatsData result = default(WeaponStatsData);
			WeaponComponentData weaponComponentData = _weapons[usageIndex];
			result.WeaponClass = (int)weaponComponentData.WeaponClass;
			result.AmmoClass = (int)weaponComponentData.AmmoClass;
			result.Properties = (uint)Item.ItemFlags;
			result.WeaponFlags = (ulong)weaponComponentData.WeaponFlags;
			result.ItemUsageIndex = (string.IsNullOrEmpty(weaponComponentData.ItemUsage) ? (-1) : weaponComponentData.GetItemUsageIndex());
			result.ThrustSpeed = weaponComponentData.GetModifiedThrustSpeed(ItemModifier);
			result.SwingSpeed = weaponComponentData.GetModifiedSwingSpeed(ItemModifier);
			result.MissileSpeed = weaponComponentData.GetModifiedMissileSpeed(ItemModifier);
			result.ShieldArmor = weaponComponentData.GetModifiedArmor(ItemModifier);
			result.Accuracy = weaponComponentData.Accuracy;
			result.WeaponLength = weaponComponentData.WeaponLength;
			result.WeaponBalance = weaponComponentData.WeaponBalance;
			result.ThrustDamage = weaponComponentData.GetModifiedThrustDamage(ItemModifier);
			result.ThrustDamageType = (int)weaponComponentData.ThrustDamageType;
			result.SwingDamage = weaponComponentData.GetModifiedSwingDamage(ItemModifier);
			result.SwingDamageType = (int)weaponComponentData.SwingDamageType;
			result.DefendSpeed = weaponComponentData.GetModifiedHandling(ItemModifier);
			result.SweetSpot = weaponComponentData.SweetSpotReach;
			result.MaxDataValue = _modifiedMaxDataValue;
			result.WeaponFrame = weaponComponentData.Frame;
			result.RotationSpeed = weaponComponentData.RotationSpeed;
			result.ReloadPhaseCount = weaponComponentData.ReloadPhaseCount;
			return result;
		}

