		[EngineStruct("Float_compression_info", false, null)]
		public struct Float
		{
			[CustomEngineStructMemberData("min_value")]
			private readonly float minimumValue;

			[CustomEngineStructMemberData("max_value")]
			private readonly float maximumValue;

			[CustomEngineStructMemberData(true)]
			private readonly float precision;

			[CustomEngineStructMemberData("num_bits")]
			private readonly int numberOfBits;

			public static Float FullPrecision { get; } = new Float(isFullPrecision: true);


			public Float(float minimumValue, float maximumValue, int numberOfBits)
			{
				this.minimumValue = minimumValue;
				this.maximumValue = maximumValue;
				this.numberOfBits = numberOfBits;
				float num = maximumValue - minimumValue;
				int num2 = (1 << numberOfBits) - 1;
				precision = num / (float)num2;
			}

			public Float(float minimumValue, int numberOfBits, float precision)
			{
				this.minimumValue = minimumValue;
				this.precision = precision;
				this.numberOfBits = numberOfBits;
				int num = (1 << numberOfBits) - 1;
				float num2 = precision * (float)num;
				maximumValue = num2 + minimumValue;
			}

			private Float(bool isFullPrecision)
			{
				minimumValue = float.MinValue;
				maximumValue = float.MaxValue;
				precision = 0f;
				numberOfBits = 32;
			}

			public int GetNumBits()
			{
				return numberOfBits;
			}

			public float GetMaximumValue()
			{
				return maximumValue;
			}

			public float GetMinimumValue()
			{
				return minimumValue;
			}

			public float GetPrecision()
			{
				return precision;
			}

			public void ClampValueAccordingToLimits(ref float x)
			{
				x = TaleWorlds.Library.MathF.Clamp(x, minimumValue, maximumValue);
			}
		}
	}
	public static class CustomGameBannedPlayerManager
	{
		private struct BannedPlayer
		{
			public PlayerId PlayerId { get; set; }

			public int BanDueTime { get; set; }
		}

		private static Dictionary<PlayerId, BannedPlayer> _bannedPlayersInternal;

		private static Dictionary<PlayerId, BannedPlayer> _bannedPlayers
		{
			get
			{
				if (_bannedPlayersInternal == null)
				{
					_bannedPlayersInternal = new Dictionary<PlayerId, BannedPlayer>();
				}
				return _bannedPlayersInternal;
			}
		}

		public static void AddBannedPlayer(PlayerId playerId, int banDueTime)
		{
			_bannedPlayers[playerId] = new BannedPlayer
			{
				PlayerId = playerId,
				BanDueTime = banDueTime
			};
		}

		public static bool IsUserBanned(PlayerId playerId)
		{
			if (_bannedPlayers.ContainsKey(playerId))
			{
				return _bannedPlayers[playerId].BanDueTime > Environment.TickCount;
			}
			return false;
		}
	}
