		[MBCallback(null, false)]
		internal static bool HandleNetworkPacketAsClient()
		{
			if (!TWParallel.IsMainThread())
			{
				TaleWorlds.Library.Debug.FailedAssert("Network messages should be handled from main thread", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Network\\GameNetwork.cs", "HandleNetworkPacketAsClient", 1204);
			}
			bool bufferReadValid = true;
			int num = GameNetworkMessage.ReadIntFromPacket(CompressionBasic.NetworkComponentEventTypeFromServerCompressionInfo, ref bufferReadValid);
			if (bufferReadValid && num >= 0 && num < _gameNetworkMessageIdsFromServer.Count)
			{
				GameNetworkMessage gameNetworkMessage = Activator.CreateInstance(_gameNetworkMessageIdsFromServer[num]) as GameNetworkMessage;
				gameNetworkMessage.MessageId = num;
				TaleWorlds.Library.Debug.Print("Reading message: " + gameNetworkMessage.GetType().Name, 0, TaleWorlds.Library.Debug.DebugColor.White, 17179869184uL);
				bufferReadValid = gameNetworkMessage.Read();
				if (bufferReadValid)
				{
					if (!NetworkMain.GameClient.IsInGame && !IsReplay && !NetworkMain.CommunityClient.IsInGame)
					{
						TaleWorlds.Library.Debug.Print("ignoring post mission message: " + gameNetworkMessage.GetType().Name, 0, TaleWorlds.Library.Debug.DebugColor.White, 17179869184uL);
					}
					else
					{
						bool flag = false;
						bool flag2 = true;
						if ((gameNetworkMessage.GetLogFilter() & MultiplayerLogging) != MultiplayerMessageFilter.None)
						{
							if (GameNetworkMessage.IsClientMissionOver)
							{
								TaleWorlds.Library.Debug.Print("WARNING: Entering message processing while client mission is over");
							}
							TaleWorlds.Library.Debug.Print("Processing message: " + gameNetworkMessage.GetType().Name + ": " + gameNetworkMessage.GetLogFormat(), 0, TaleWorlds.Library.Debug.DebugColor.White, 17179869184uL);
						}
						if (_fromServerBaseMessageHandlers.TryGetValue(num, out var value))
						{
							foreach (GameNetworkMessage.ServerMessageHandlerDelegate<GameNetworkMessage> item in value)
							{
								try
								{
									item(gameNetworkMessage);
								}
								catch
								{
									TaleWorlds.Library.Debug.Print("Exception in handler of " + num, 0, TaleWorlds.Library.Debug.DebugColor.White, 17179869184uL);
									TaleWorlds.Library.Debug.Print("Exception in handler of " + gameNetworkMessage.GetType().Name, 0, TaleWorlds.Library.Debug.DebugColor.Red, 17179869184uL);
								}
							}
							flag2 = false;
							flag = value.Count != 0;
						}
						if (_fromServerMessageHandlers.TryGetValue(num, out var value2))
						{
							foreach (object item2 in value2)
							{
								(item2 as Delegate).DynamicInvokeWithLog(gameNetworkMessage);
							}
							flag2 = false;
							flag = flag || value2.Count != 0;
						}
						if (flag2)
						{
							TaleWorlds.Library.Debug.Print("Invalid messageId " + num, 0, TaleWorlds.Library.Debug.DebugColor.White, 17179869184uL);
							TaleWorlds.Library.Debug.Print("Invalid messageId " + gameNetworkMessage.GetType().Name, 0, TaleWorlds.Library.Debug.DebugColor.White, 17179869184uL);
						}
						else if (!flag)
						{
							TaleWorlds.Library.Debug.Print("No message handler found for " + gameNetworkMessage.GetType().Name, 0, TaleWorlds.Library.Debug.DebugColor.Red, 17179869184uL);
						}
					}
				}
				else
				{
					TaleWorlds.Library.Debug.Print("Invalid message read for: " + gameNetworkMessage.GetType().Name, 0, TaleWorlds.Library.Debug.DebugColor.White, 17179869184uL);
				}
			}
			else
			{
				TaleWorlds.Library.Debug.Print("Invalid message id read: " + num, 0, TaleWorlds.Library.Debug.DebugColor.White, 17179869184uL);
			}
			return bufferReadValid;
		}

