	public class AnimatedFlag : ScriptComponentBehavior
	{
		private float _prevTheta;

		private float _prevSkew;

		private Vec3 _prevFlagMeshFrame;

		private float _time;

		public AnimatedFlag()
		{
			_prevFlagMeshFrame = new Vec3(0f, 0f, 0f, -1f);
			_prevTheta = 0f;
			_prevSkew = 0f;
			_time = 0f;
		}

		protected internal override void OnInit()
		{
			base.OnInit();
			SetScriptComponentToTick(GetTickRequirement());
			MBDebug.Print("AnimatedFlag : OnInit called.", 0, TaleWorlds.Library.Debug.DebugColor.Yellow);
		}

		private void SmoothTheta(ref float theta, float dt)
		{
			float num = theta - _prevTheta;
			if (num > System.MathF.PI)
			{
				num -= System.MathF.PI * 2f;
				_prevTheta += System.MathF.PI * 2f;
			}
			else if (num < -System.MathF.PI)
			{
				num += System.MathF.PI * 2f;
				_prevTheta -= System.MathF.PI * 2f;
			}
			num = TaleWorlds.Library.MathF.Min(num, 150f * dt);
			theta = _prevTheta + num * 0.05f;
		}

		public override TickRequirement GetTickRequirement()
		{
			return TickRequirement.Tick | base.GetTickRequirement();
		}

		protected internal override void OnTick(float dt)
		{
			if (dt == 0f)
			{
				return;
			}
			MatrixFrame globalFrame = base.GameEntity.GetGlobalFrame();
			MetaMesh metaMesh = base.GameEntity.GetMetaMesh(0);
			if (!(metaMesh == null))
			{
				Vec3 vec = globalFrame.origin - _prevFlagMeshFrame;
				vec.x /= dt;
				vec.y /= dt;
				vec.z /= dt;
				vec = new Vec3(20f, 0f, -10f) * 0.1f - vec;
				if (!(vec.LengthSquared < 1E-08f))
				{
					Vec3 vec2 = globalFrame.rotation.TransformToLocal(in vec);
					vec2.z = 0f;
					vec2.Normalize();
					float theta = TaleWorlds.Library.MathF.Atan2(vec2.y, vec2.x);
					SmoothTheta(ref theta, dt);
					Vec3 scalingVector = metaMesh.Frame.rotation.GetScaleVector();
					MatrixFrame identity = MatrixFrame.Identity;
					identity.Scale(in scalingVector);
					identity.rotation.RotateAboutUp(theta);
					_prevTheta = theta;
					float num = TaleWorlds.Library.MathF.Acos(Vec3.DotProduct(vec, globalFrame.rotation.u) / vec.Length);
					float a = num - _prevSkew;
					a = TaleWorlds.Library.MathF.Min(a, 150f * dt);
					num = (_prevSkew += a * 0.05f);
					float num2 = MBMath.ClampFloat(vec.Length, 0.001f, 10000f);
					_time += dt * num2 * 0.5f;
					metaMesh.Frame = identity;
					metaMesh.VectorUserData = new Vec3(TaleWorlds.Library.MathF.Cos(num), 1f - TaleWorlds.Library.MathF.Sin(num), 0f, _time);
					_prevFlagMeshFrame = globalFrame.origin;
				}
			}
		}

		protected internal override bool IsOnlyVisual()
		{
			return true;
		}
	}
	public class Bird : MissionObject
	{
		private enum State
		{
			TakingOff,
			Airborne,
			Landing,
			Perched
		}

		[EditableScriptComponentVariable(true, "")]
		private float _flyingSpeedInKph = 14.4f;

		[EditableScriptComponentVariable(true, "")]
		private string _idleAnimation = "anim_bird_idle";

		[EditableScriptComponentVariable(true, "")]
		private string _landingAnimation = "anim_bird_landing";

		[EditableScriptComponentVariable(true, "")]
		private string _takingOffAnimation = "anim_bird_flying";

		[EditableScriptComponentVariable(true, "")]
		private string _flyCycleAnimation = "anim_bird_cycle";

		[EditableScriptComponentVariable(true, "")]
		private bool _canLand = true;

		public bool CanFly;

		private State _state;

		private BasicMissionTimer _timer;

		private State ComputeInitialState()
		{
			if (CanFly && !_canLand)
			{
				return State.Airborne;
			}
			return State.Perched;
		}

		protected internal override void OnInit()
		{
			base.OnInit();
			base.GameEntity.SetAnimationSoundActivation(activate: true);
			base.GameEntity.Skeleton.SetAnimationAtChannel(_idleAnimation, 0);
			base.GameEntity.Skeleton.SetAnimationParameterAtChannel(0, MBRandom.RandomFloat * 0.5f);
			_timer = new BasicMissionTimer();
			SetState(ComputeInitialState());
			SetScriptComponentToTick(GetTickRequirement());
		}

		protected internal override void OnEditorInit()
		{
			base.OnEditorInit();
			base.GameEntity.Skeleton.SetAnimationAtChannel(_idleAnimation, 0);
			base.GameEntity.Skeleton.SetAnimationParameterAtChannel(0, 0f);
			_timer = new BasicMissionTimer();
			SetState(ComputeInitialState());
		}

		public override TickRequirement GetTickRequirement()
		{
			return TickRequirement.Tick | base.GetTickRequirement();
		}

		private void SetState(State newState)
		{
			_state = newState;
			OnStateChanged();
		}

		private void OnStateChanged()
		{
			switch (_state)
			{
			case State.TakingOff:
				base.GameEntity.Skeleton.SetAnimationAtChannel(_takingOffAnimation, 0);
				_timer.Reset();
				break;
			case State.Airborne:
				base.GameEntity.Skeleton.SetAnimationAtChannel(_flyCycleAnimation, 0);
				_timer.Set(0f - MBRandom.RandomFloatRanged(5f, 15f));
				ApplyAnimationDisplacement();
				break;
			case State.Landing:
				base.GameEntity.Skeleton.SetAnimationAtChannel(_landingAnimation, 0);
				_timer.Reset();
				ApplyAnimationDisplacement();
				break;
			case State.Perched:
				base.GameEntity.Skeleton.SetAnimationAtChannel(_idleAnimation, 0);
				base.GameEntity.Skeleton.SetAnimationParameterAtChannel(0, MBRandom.RandomFloat * 0.5f);
				_timer.Set(0f - MBRandom.RandomFloatRanged(5f, 18f));
				break;
			default:
				TaleWorlds.Library.Debug.FailedAssert("Unknown state please handle!", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Objects\\Bird.cs", "OnStateChanged", 138);
				break;
			}
		}

		protected internal override void OnTick(float dt)
		{
			switch (_state)
			{
			case State.TakingOff:
				if (base.GameEntity.Skeleton.GetAnimationParameterAtChannel(0) > 0.99f)
				{
					SetState(State.Airborne);
				}
				break;
			case State.Airborne:
				if (_timer.ElapsedTime > 0f)
				{
					if (_canLand)
					{
						SetState(State.Landing);
					}
					else
					{
						base.GameEntity.SetVisibilityExcludeParents(visible: false);
					}
				}
				else
				{
					ApplyFlyingMovement(dt);
				}
				break;
			case State.Landing:
				if (base.GameEntity.Skeleton.GetAnimationParameterAtChannel(0) > 0.99f)
				{
					SetState(State.Perched);
				}
				break;
			case State.Perched:
				if (CanFly && _timer.ElapsedTime > 0f && base.GameEntity.Skeleton.GetAnimationParameterAtChannel(0) > 0.99f)
				{
					SetState(State.TakingOff);
				}
				break;
			}
		}

		private void ApplyFlyingMovement(float dt)
		{
			float num = _flyingSpeedInKph * (5f / 18f) * dt;
			MatrixFrame frame = base.GameEntity.GetGlobalFrame();
			Vec3 vec = frame.rotation.f.NormalizedCopy();
			frame.origin -= vec * num;
			base.GameEntity.SetGlobalFrame(in frame);
		}

		private void ApplyAnimationDisplacement()
		{
			MatrixFrame frame = base.GameEntity.GetGlobalFrame();
			Vec3 vec = frame.rotation.f.NormalizedCopy();
			Vec3 vec2 = frame.rotation.u.NormalizedCopy();
			if (_state == State.Airborne)
			{
				frame.origin -= vec * 20f - vec2 * 6.5f;
			}
			else if (_state == State.Landing)
			{
				frame.origin -= vec * 20f + vec2 * 6.5f;
			}
			base.GameEntity.SetGlobalFrame(in frame);
		}
	}
	public class BoundaryWallView : ScriptComponentBehavior
	{
		private List<Vec2> _lastPoints = new List<Vec2>();

		private List<Vec2> _lastAttackerPoints = new List<Vec2>();

		private List<Vec2> _lastDefenderPoints = new List<Vec2>();

		private float timer;

		protected internal override void OnInit()
		{
			throw new Exception("This should only be used in editor.");
		}

		protected internal override void OnEditorTick(float dt)
		{
			base.OnEditorTick(dt);
			timer += dt;
			if (!MBEditor.BorderHelpersEnabled() || timer < 0.2f)
			{
				return;
			}
			timer = 0f;
			if (base.Scene == null)
			{
				return;
			}
			bool flag = CalculateBoundaries("walk_area_vertex", ref _lastPoints);
			bool flag2 = CalculateBoundaries("defender_area_vertex", ref _lastDefenderPoints);
			bool flag3 = CalculateBoundaries("attacker_area_vertex", ref _lastAttackerPoints);
			if (_lastPoints.Count >= 3 || _lastDefenderPoints.Count >= 3 || _lastAttackerPoints.Count >= 3)
			{
				if (flag || flag2 || flag3)
				{
					base.GameEntity.ClearEntityComponents(resetAll: true, removeScripts: false, deleteChildEntities: true);
					base.GameEntity.SetName("editor_map_border");
					Mesh mesh = CreateBoundaryMesh(base.Scene, _lastPoints);
					if (mesh != null)
					{
						base.GameEntity.AddMesh(mesh);
					}
					Color color = new Color(0f, 0f, 0.8f);
					Mesh mesh2 = CreateBoundaryMesh(base.Scene, _lastDefenderPoints, color.ToUnsignedInteger());
					if (mesh2 != null)
					{
						base.GameEntity.AddMesh(mesh2);
					}
					Color color2 = new Color(0f, 0.8f, 0.8f);
					Mesh mesh3 = CreateBoundaryMesh(base.Scene, _lastAttackerPoints, color2.ToUnsignedInteger());
					if (mesh3 != null)
					{
						base.GameEntity.AddMesh(mesh3);
					}
				}
			}
			else
			{
				base.GameEntity.ClearEntityComponents(resetAll: true, removeScripts: false, deleteChildEntities: true);
			}
		}

		private bool CalculateBoundaries(string vertexTag, ref List<Vec2> lastPoints)
		{
			IEnumerable<WeakGameEntity> source = base.Scene.FindWeakEntitiesWithTag(vertexTag);
			source = source.Where((WeakGameEntity e) => !e.EntityFlags.HasAnyFlag(EntityFlags.DontSaveToScene));
			int num = source.Count();
			bool flag = false;
			if (num >= 3)
			{
				List<Vec2> source2 = source.Select((WeakGameEntity e) => e.GlobalPosition.AsVec2).ToList();
				Vec2 mid = new Vec2(source2.Average((Vec2 p) => p.x), source2.Average((Vec2 p) => p.y));
				source2 = source2.OrderBy((Vec2 p) => TaleWorlds.Library.MathF.Atan2(p.x - mid.x, p.y - mid.y)).ToList();
				if (lastPoints != null && lastPoints.Count == source2.Count)
				{
					flag = true;
					for (int i = 0; i < source2.Count; i++)
					{
						if (source2[i] != lastPoints[i])
						{
							flag = false;
							break;
						}
					}
				}
				lastPoints = source2;
				return !flag;
			}
			return false;
		}

		public static Mesh CreateBoundaryMesh(Scene scene, ICollection<Vec2> boundaryPoints, uint meshColor = 536918784u)
		{
			if (boundaryPoints == null || boundaryPoints.Count < 3)
			{
				return null;
			}
			Mesh mesh = Mesh.CreateMesh();
			UIntPtr uIntPtr = mesh.LockEditDataWrite();
			scene.GetBoundingBox(out var min, out var max);
			max.z += 50f;
			min.z -= 50f;
			for (int i = 0; i < boundaryPoints.Count; i++)
			{
				Vec2 point = boundaryPoints.ElementAt(i);
				Vec2 point2 = boundaryPoints.ElementAt((i + 1) % boundaryPoints.Count);
				float height = 0f;
				float height2 = 0f;
				if (!scene.IsAtmosphereIndoor)
				{
					if (!scene.GetHeightAtPoint(point, BodyFlags.CommonCollisionExcludeFlagsForCombat, ref height))
					{
						MBDebug.ShowWarning("GetHeightAtPoint failed at CreateBoundaryEntity!");
						return null;
					}
					if (!scene.GetHeightAtPoint(point2, BodyFlags.CommonCollisionExcludeFlagsForCombat, ref height2))
					{
						MBDebug.ShowWarning("GetHeightAtPoint failed at CreateBoundaryEntity!");
						return null;
					}
				}
				else
				{
					height = min.z;
					height2 = min.z;
				}
				Vec3 vec = point.ToVec3(height);
				Vec3 vec2 = point2.ToVec3(height2);
				Vec3 vec3 = Vec3.Up * 2f;
				Vec3 p = vec;
				Vec3 p2 = vec2;
				Vec3 vec4 = vec;
				Vec3 p3 = vec2;
				p.z = TaleWorlds.Library.MathF.Min(p.z, min.z);
				p2.z = TaleWorlds.Library.MathF.Min(p2.z, min.z);
				vec4.z = TaleWorlds.Library.MathF.Max(vec4.z, max.z);
				p3.z = TaleWorlds.Library.MathF.Max(p3.z, max.z);
				p -= vec3;
				p2 -= vec3;
				vec4 += vec3;
				p3 += vec3;
				mesh.AddTriangle(p, p2, vec4, Vec2.Zero, Vec2.Side, Vec2.Forward, meshColor, uIntPtr);
				mesh.AddTriangle(vec4, p2, p3, Vec2.Forward, Vec2.Side, Vec2.One, meshColor, uIntPtr);
			}
			mesh.SetMaterial("editor_map_border");
			mesh.VisibilityMask = VisibilityMaskFlags.Final | VisibilityMaskFlags.EditModeBorders;
			mesh.SetColorAlpha(150u);
			mesh.SetMeshRenderOrder(250);
			mesh.CullingMode = MBMeshCullingMode.None;
			float vectorArgument = 25f;
			if (MBEditor.IsEditModeOn && scene.IsEditorScene())
			{
				vectorArgument = 100000f;
			}
			IEnumerable<WeakGameEntity> source = scene.FindWeakEntitiesWithTag("walk_area_vertex");
			float vectorArgument2 = (source.Any() ? source.Average((WeakGameEntity ent) => ent.GlobalPosition.z) : 0f);
			mesh.SetVectorArgument(vectorArgument, vectorArgument2, 0f, 0f);
			mesh.ComputeNormals();
			mesh.ComputeTangents();
			mesh.RecomputeBoundingBox();
			mesh.UnlockEditDataWrite(uIntPtr);
			return mesh;
		}
	}
	public class CameraDisplay : ScriptComponentBehavior
	{
		private Camera _myCamera;

		private SceneView _sceneView;

		public int renderOrder;

		private void BuildView()
		{
			_sceneView = SceneView.CreateSceneView();
			_myCamera = Camera.CreateCamera();
			_sceneView.SetScene(base.GameEntity.Scene);
			_sceneView.SetPostfxFromConfig();
			_sceneView.SetRenderOption(View.ViewRenderOptions.ClearColor, value: false);
			_sceneView.SetRenderOption(View.ViewRenderOptions.ClearDepth, value: true);
			_sceneView.SetScale(new Vec2(0.2f, 0.2f));
		}

		private void SetCamera()
		{
			Vec2 realScreenResolution = Screen.RealScreenResolution;
			float aspectRatioXY = realScreenResolution.x / realScreenResolution.y;
			MatrixFrame globalFrame = base.GameEntity.GetGlobalFrame();
			_myCamera.SetFovVertical(System.MathF.PI / 4f, aspectRatioXY, 0.2f, 200f);
			_myCamera.Frame = globalFrame;
			_sceneView.SetCamera(_myCamera);
		}

		private void RenderCameraFrustrum()
		{
			_myCamera.RenderFrustrum();
		}

		protected internal override void OnEditorInit()
		{
			BuildView();
		}

		protected internal override void OnInit()
		{
			BuildView();
		}

		protected internal override void OnEditorTick(float dt)
		{
			base.OnEditorTick(dt);
			if (MBEditor.IsEntitySelected(base.GameEntity))
			{
				RenderCameraFrustrum();
				_sceneView.SetEnable(value: true);
			}
			else
			{
				_sceneView.SetEnable(value: false);
			}
		}

		protected override void OnRemoved(int removeReason)
		{
			base.OnRemoved(removeReason);
			_sceneView = null;
			_myCamera = null;
		}
	}
