		{
			base.OnInit();
			_lightningTimer = MBRandom.RandomFloat * LightningRate;
			SetScriptComponentToTick(GetTickRequirement());
		}

		protected internal override bool MovesEntity()
		{
			return false;
		}

		protected internal override void OnEditorTick(float dt)
		{
			TickAux(dt);
		}

		protected internal override void OnTick(float dt)
		{
			TickAux(dt);
		}

		private void SpawnBolt()
		{
			_boltIntensity = 1f;
			Random random = new Random();
			float x = (random.NextFloat() * 2f - 1f) * LightTravelRadius;
			float y = (random.NextFloat() * 2f - 1f) * LightTravelRadius;
			Vec3 localPosition = new Vec3(x, y);
			base.GameEntity.SetLocalPosition(localPosition);
			Vec3 position = base.GameEntity.GlobalPosition;
			SoundManager.StartOneShotEvent("event:/map/ambient/node/thunder", in position);
		}

		private void SetLightIntensity(float intensity)
		{
			Light light = base.GameEntity.GetComponentAtIndex(0, TaleWorlds.Engine.GameEntity.ComponentType.Light) as Light;
			Light light2 = base.GameEntity.GetComponentAtIndex(1, TaleWorlds.Engine.GameEntity.ComponentType.Light) as Light;
			float timeOfDay = base.Scene.TimeOfDay;
			if (light != null && light2 != null)
			{
				if (timeOfDay < 3.5f || timeOfDay > 21f)
				{
					float num = ((timeOfDay > 20f) ? MBMath.Map(timeOfDay, 20f, 24f, 4f, 1f) : MBMath.Map(timeOfDay, 0f, 6f, 1f, 4f));
					light.Intensity = LightIntensity * intensity * num;
					light2.Intensity = LightIntensity * intensity * num / 4f;
				}
				else
				{
					float num2 = ((timeOfDay < 12f) ? MBMath.Map(timeOfDay, 6f, 12f, 100f, 200f) : MBMath.Map(timeOfDay, 12f, 20f, 200f, 100f));
					light.Intensity = LightIntensity * intensity * num2;
					light2.Intensity = LightIntensity * intensity * num2 / 2f;
				}
			}
		}

		private float CalculateBoltIntensity(float dt)
		{
			_boltIntensity -= dt * BoltSpeed;
			if (_boltIntensity < 0f)
			{
				_boltIntensity = 0f;
			}
			return _boltIntensity;
		}

		private void TickAux(float dt)
		{
			_lightningTimer += dt;
			if (IsBoltEnabled)
			{
				base.GameEntity.ResumeParticleSystem(doChildren: true);
			}
			if (_lightningTimer > LightningRate)
			{
				_lightningTimer = 0f;
				_spawnLightning = true;
			}
			if (!_spawnLightning)
			{
				return;
			}
			_boltTimer += dt * BoltSpeed;
			SetLightIntensity(CalculateBoltIntensity(dt));
			if (_boltTimer > BoltLife)
			{
				if (IsBoltEnabled)
				{
					base.GameEntity.PauseParticleSystem(doChildren: false);
				}
				SpawnBolt();
				if (IsBoltEnabled)
				{
					base.GameEntity.BurstEntityParticle(doChildren: false);
				}
				SetLightIntensity(0f);
				_currentNumberOfLightning++;
				if (_currentNumberOfLightning == 2)
				{
					_spawnLightning = false;
					_currentNumberOfLightning = 0;
				}
				_boltTimer = 0f;
			}
		}
	}
	public class MapAtmosphereProbe : ScriptComponentBehavior
	{
		public bool visualizeRadius = true;

		public bool hideAllProbes = true;

		public static bool hideAllProbesStatic = true;

		public float minRadius = 1f;

		public float maxRadius = 2f;

		public float rainDensity;

		public float temperature;

		public string atmosphereType;

		public string colorGrade;

		private MetaMesh innerSphereMesh;

		private MetaMesh outerSphereMesh;

		public float GetInfluenceAmount(Vec3 worldPosition)
		{
			return MBMath.SmoothStep(minRadius, maxRadius, worldPosition.Distance(base.GameEntity.GetGlobalFrame().origin));
		}

		public MapAtmosphereProbe()
		{
			hideAllProbes = hideAllProbesStatic;
			if (MBEditor.IsEditModeOn)
			{
				innerSphereMesh = MetaMesh.GetCopy("physics_sphere_detailed");
				outerSphereMesh = MetaMesh.GetCopy("physics_sphere_detailed");
				innerSphereMesh.SetMaterial(Material.GetFromResource("light_radius_visualizer"));
				outerSphereMesh.SetMaterial(Material.GetFromResource("light_radius_visualizer"));
			}
		}

		protected internal override void OnEditorTick(float dt)
		{
			base.OnEditorTick(dt);
			if (visualizeRadius && !hideAllProbesStatic)
			{
				uint num = 16711680u;
				uint num2 = 720640u;
				if (MBEditor.IsEntitySelected(base.GameEntity))
				{
					num |= 0x80000000u;
					num2 |= 0x80000000u;
				}
				else
				{
					num |= 0x40000000u;
					num2 |= 0x40000000u;
				}
				innerSphereMesh.SetFactor1(num);
				outerSphereMesh.SetFactor1(num2);
				MatrixFrame frame = default(MatrixFrame);
				frame.origin = base.GameEntity.GetGlobalFrame().origin;
				frame.rotation = Mat3.Identity;
				frame.rotation.ApplyScaleLocal(minRadius);
				MatrixFrame frame2 = default(MatrixFrame);
				frame2.origin = base.GameEntity.GetGlobalFrame().origin;
				frame2.rotation = Mat3.Identity;
				frame2.rotation.ApplyScaleLocal(maxRadius);
				innerSphereMesh.SetVectorArgument(minRadius, maxRadius, 0f, 0f);
				outerSphereMesh.SetVectorArgument(minRadius, maxRadius, 0f, 0f);
				MBEditor.RenderEditorMesh(innerSphereMesh, frame);
				MBEditor.RenderEditorMesh(outerSphereMesh, frame2);
			}
		}

		protected internal override void OnEditorVariableChanged(string variableName)
		{
			base.OnEditorVariableChanged(variableName);
			if (variableName == "minRadius")
			{
				minRadius = MBMath.ClampFloat(minRadius, 0.1f, maxRadius);
			}
			if (variableName == "maxRadius")
			{
				maxRadius = MBMath.ClampFloat(maxRadius, minRadius, float.MaxValue);
			}
			if (variableName == "hideAllProbes")
			{
				hideAllProbesStatic = hideAllProbes;
			}
		}
	}
	public class Mover : ScriptComponentBehavior
	{
		[EditorVisibleScriptComponentVariable(true)]
		private string _pathname = "";

		[EditorVisibleScriptComponentVariable(true)]
		private float _speed;

		[EditorVisibleScriptComponentVariable(true)]
		private bool _moveGhost;

		private GameEntity _moverGhost;

		private PathTracker _tracker;

		protected internal override void OnEditorTick(float dt)
		{
			if (base.GameEntity.EntityFlags.HasAnyFlag(EntityFlags.IsHelper))
			{
				return;
			}
			if (_moverGhost == null && _pathname != "")
			{
				CreateOrUpdateMoverGhost();
			}
			if (_tracker == null || !_tracker.IsValid)
			{
				return;
			}
			if (_moveGhost)
			{
				_tracker.Advance(_speed * dt);
				if (_tracker.TotalDistanceTraveled >= _tracker.GetPathLength())
				{
					_tracker.Reset();
				}
			}
			else
			{
				_tracker.Advance(0f);
			}
			MatrixFrame frame = _tracker.CurrentFrame;
			_moverGhost.SetFrame(ref frame);
		}

		protected internal override void OnEditorVariableChanged(string variableName)
		{
			if (variableName == "_pathname")
			{
				CreateOrUpdateMoverGhost();
			}
			else if (variableName == "_moveGhost")
			{
				if (!_moveGhost)
				{
					_moverGhost.SetVisibilityExcludeParents(visible: false);
				}
				else
				{
					_moverGhost.SetVisibilityExcludeParents(visible: true);
				}
			}
		}

		private void CreateOrUpdateMoverGhost()
		{
			TaleWorlds.Engine.Path pathWithName = base.GameEntity.Scene.GetPathWithName(_pathname);
			if (pathWithName != null)
			{
				_tracker = new PathTracker(pathWithName, Vec3.One);
				_tracker.Reset();
				base.GameEntity.SetLocalPosition(_tracker.CurrentFrame.origin);
				if (_moverGhost == null)
				{
					_moverGhost = TaleWorlds.Engine.GameEntity.CopyFrom(base.GameEntity.Scene, base.GameEntity);
					_moverGhost.EntityFlags |= EntityFlags.IsHelper | EntityFlags.DontSaveToScene | EntityFlags.DoNotTick;
					_moverGhost.SetAlpha(0.2f);
				}
				else
				{
					_moverGhost.SetLocalPosition(_tracker.CurrentFrame.origin);
				}
			}
		}

		protected internal override void OnInit()
		{
			base.OnInit();
			TaleWorlds.Engine.Path pathWithName = base.GameEntity.Scene.GetPathWithName(_pathname);
			if (pathWithName != null)
			{
				_tracker = new PathTracker(pathWithName, Vec3.One);
				_tracker.Reset();
				base.GameEntity.SetLocalPosition(_tracker.CurrentFrame.origin);
			}
			SetScriptComponentToTick(GetTickRequirement());
		}

		public override TickRequirement GetTickRequirement()
		{
			if (base.GameEntity.IsVisibleIncludeParents())
			{
				return TickRequirement.Tick | base.GetTickRequirement();
			}
			return base.GetTickRequirement();
		}

		protected internal override void OnTick(float dt)
		{
			if (Mission.Current.Mode == MissionMode.Battle && _tracker != null && _tracker.IsValid && _tracker.TotalDistanceTraveled < _tracker.GetPathLength())
			{
				_tracker.Advance(_speed * dt);
				MatrixFrame frame = _tracker.CurrentFrame;
				base.GameEntity.SetFrame(ref frame);
			}
		}
	}
	public class MultiplayerSceneValidator : ScriptComponentBehavior
	{
		public SimpleButton SelectFaultyEntities;

		protected internal override void OnEditorVariableChanged(string variableName)
		{
			base.OnEditorVariableChanged(variableName);
			if (variableName == "SelectFaultyEntities")
			{
				SelectInvalidEntities();
			}
		}

		protected internal override void OnSceneSave(string saveFolder)
		{
			base.OnSceneSave(saveFolder);
			foreach (GameEntity invalidEntity in GetInvalidEntities())
			{
				_ = invalidEntity;
			}
		}

		private List<GameEntity> GetInvalidEntities()
		{
			List<GameEntity> list = new List<GameEntity>();
			List<GameEntity> entities = new List<GameEntity>();
			base.Scene.GetEntities(ref entities);
			foreach (GameEntity item in entities)
			{
				foreach (ScriptComponentBehavior scriptComponent in item.GetScriptComponents())
				{
					if (scriptComponent != null && (scriptComponent.GetType().IsSubclassOf(typeof(MissionObject)) || (scriptComponent.GetType() == typeof(MissionObject) && scriptComponent.IsOnlyVisual())))
					{
						list.Add(item);
						break;
					}
				}
			}
			return list;
		}

		private void SelectInvalidEntities()
		{
			base.GameEntity.DeselectEntityOnEditor();
			foreach (GameEntity invalidEntity in GetInvalidEntities())
			{
				invalidEntity.SelectEntityOnEditor();
			}
		}
	}
	public class PathTracker
	{
		private readonly TaleWorlds.Engine.Path _path;

		private readonly Vec3 _initialScale;

		private int _version = -1;

		public float TotalDistanceTraveled { get; set; }

		public bool HasChanged
		{
			get
			{
				if (_path != null)
				{
					return _version < _path.GetVersion();
				}
				return false;
			}
		}

		public bool IsValid => _path != null;

		public bool HasReachedEnd => TotalDistanceTraveled >= _path.TotalDistance;

		public float PathTraveledPercentage => TotalDistanceTraveled / _path.TotalDistance;

		public MatrixFrame CurrentFrame
		{
			get
			{
				MatrixFrame frameForDistance = _path.GetFrameForDistance(TotalDistanceTraveled);
				frameForDistance.rotation.RotateAboutUp(System.MathF.PI);
				frameForDistance.rotation.ApplyScaleLocal(in _initialScale);
				return frameForDistance;
			}
		}

		public PathTracker(TaleWorlds.Engine.Path path, Vec3 initialScaleOfEntity)
		{
			_path = path;
			_initialScale = initialScaleOfEntity;
			if (path != null)
			{
				UpdateVersion();
			}
			Reset();
		}

		public void UpdateVersion()
		{
			_version = _path.GetVersion();
		}

		public bool PathExists()
		{
			return _path != null;
		}

		public void Advance(float deltaDistance)
		{
			TotalDistanceTraveled += deltaDistance;
			TotalDistanceTraveled = TaleWorlds.Library.MathF.Min(TotalDistanceTraveled, _path.TotalDistance);
		}

		public float GetPathLength()
		{
			return _path.TotalDistance;
		}

		public void CurrentFrameAndColor(out MatrixFrame frame, out Vec3 color)
		{
			_path.GetFrameAndColorForDistance(TotalDistanceTraveled, out frame, out color);
			frame.rotation.RotateAboutUp(System.MathF.PI);
			frame.rotation.ApplyScaleLocal(in _initialScale);
		}

		public void Reset()
		{
			TotalDistanceTraveled = 0f;
		}
	}
	public class RandomParticleSpawner : ScriptComponentBehavior
	{
		private float _timeUntilNextParticleSpawn;

		public float spawnInterval = 3f;

		private void InitScript()
		{
			_timeUntilNextParticleSpawn = spawnInterval;
		}

		private void CheckSpawnParticle(float dt)
		{
			_timeUntilNextParticleSpawn -= dt;
			if (!(_timeUntilNextParticleSpawn <= 0f))
			{
				return;
			}
			int childCount = base.GameEntity.ChildCount;
			if (childCount > 0)
			{
				int index = MBRandom.RandomInt(childCount);
				WeakGameEntity child = base.GameEntity.GetChild(index);
				int componentCount = child.GetComponentCount(TaleWorlds.Engine.GameEntity.ComponentType.ParticleSystemInstanced);
				for (int i = 0; i < componentCount; i++)
				{
					((ParticleSystem)child.GetComponentAtIndex(i, TaleWorlds.Engine.GameEntity.ComponentType.ParticleSystemInstanced)).Restart();
				}
			}
			_timeUntilNextParticleSpawn += spawnInterval;
		}

		protected internal override void OnInit()
		{
			base.OnInit();
			InitScript();
			SetScriptComponentToTick(GetTickRequirement());
		}

		protected internal override void OnEditorInit()
		{
			base.OnEditorInit();
			OnInit();
		}

		public override TickRequirement GetTickRequirement()
		{
			return TickRequirement.Tick | base.GetTickRequirement();
		}

		protected internal override void OnTick(float dt)
		{
			CheckSpawnParticle(dt);
		}

		protected internal override void OnEditorTick(float dt)
		{
			base.OnEditorTick(dt);
			CheckSpawnParticle(dt);
		}

		protected internal override bool MovesEntity()
		{
			return true;
		}
	}
