		protected void CollectGameEntities(bool calledFromOnInit)
		{
			CollectDynamicGameEntities(calledFromOnInit);
			if (!GameNetwork.IsClientOrReplay)
			{
				List<WeakGameEntity> list = base.GameEntity.CollectChildrenEntitiesWithTag("plank");
				if (list.Count > 0)
				{
					_plank = list.FirstOrDefault().GetFirstScriptOfType<SynchedMissionObject>();
				}
			}
		}

		protected void OnNextDestructionState()
		{
			CollectDynamicGameEntities(calledFromOnInit: false);
			UpdateDoorBodies(updateAnyway: true);
		}

		protected void CollectDynamicGameEntities(bool calledFromOnInit)
		{
			_attackOnlyDoorColliders.Clear();
			List<WeakGameEntity> list;
			if (calledFromOnInit)
			{
				list = base.GameEntity.CollectChildrenEntitiesWithTag("gate").ToList();
				_leftExtraColliderDisabled = false;
				_rightExtraColliderDisabled = false;
				_agentColliderLeft = TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(base.GameEntity.GetFirstChildEntityWithTag("collider_agent_l"));
				_agentColliderRight = TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(base.GameEntity.GetFirstChildEntityWithTag("collider_agent_r"));
			}
			else
			{
				list = (from x in base.GameEntity.CollectChildrenEntitiesWithTag("gate")
					where x.IsVisibleIncludeParents()
					select x).ToList();
			}
			if (list.Count == 0)
			{
				return;
			}
			if (list.Count > 1)
			{
				int num = int.MinValue;
				int num2 = int.MaxValue;
				WeakGameEntity weakGameEntity = WeakGameEntity.Invalid;
				WeakGameEntity weakGameEntity2 = WeakGameEntity.Invalid;
				foreach (WeakGameEntity item in list)
				{
					int num3 = int.Parse(item.Tags.FirstOrDefault((string x) => x.Contains("state_")).Split(new char[1] { '_' }).Last());
					if (num3 > num)
					{
						num = num3;
						weakGameEntity = item;
					}
					if (num3 < num2)
					{
						num2 = num3;
						weakGameEntity2 = item;
					}
				}
				_door = (calledFromOnInit ? weakGameEntity2.GetFirstScriptOfType<SynchedMissionObject>() : weakGameEntity.GetFirstScriptOfType<SynchedMissionObject>());
			}
			else
			{
				_door = list[0].GetFirstScriptOfType<SynchedMissionObject>();
			}
			_doorSkeleton = _door.GameEntity.Skeleton;
			WeakGameEntity weakEntity = _door.GameEntity.CollectChildrenEntitiesWithTag("collider_r").FirstOrDefault();
			if (weakEntity.IsValid)
			{
				_attackOnlyDoorColliders.Add(TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(weakEntity));
			}
			WeakGameEntity weakEntity2 = _door.GameEntity.CollectChildrenEntitiesWithTag("collider_l").FirstOrDefault();
			if (weakEntity2.IsValid)
			{
				_attackOnlyDoorColliders.Add(TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(weakEntity2));
			}
			if (!weakEntity.IsValid || !weakEntity2.IsValid)
			{
				_agentColliderLeft?.SetVisibilityExcludeParents(visible: false);
				_agentColliderRight?.SetVisibilityExcludeParents(visible: false);
			}
			WeakGameEntity weakGameEntity3 = _door.GameEntity.CollectChildrenEntitiesWithTag(ExtraCollisionObjectTagLeft).FirstOrDefault();
			if (weakGameEntity3.IsValid)
			{
				if (!ActivateExtraColliders)
				{
					weakGameEntity3.RemovePhysics();
				}
				else
				{
					if (!calledFromOnInit)
					{
						MatrixFrame frame = ((_extraColliderLeft != null) ? _extraColliderLeft.GetFrame() : _doorSkeleton.GetBoneEntitialFrameWithName(LeftDoorBoneName));
						_extraColliderLeft = TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(weakGameEntity3);
						_extraColliderLeft.SetFrame(ref frame);
					}
					else
					{
						_extraColliderLeft = TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(weakGameEntity3);
					}
					if (_leftExtraColliderDisabled)
					{
						_extraColliderLeft.SetBodyFlags(_extraColliderLeft.BodyFlag | BodyFlags.Disabled);
					}
					else
					{
						_extraColliderLeft.SetBodyFlags(_extraColliderLeft.BodyFlag & ~BodyFlags.Disabled);
					}
				}
			}
			WeakGameEntity weakGameEntity4 = _door.GameEntity.CollectChildrenEntitiesWithTag(ExtraCollisionObjectTagRight).FirstOrDefault();
			if (weakGameEntity4.IsValid)
			{
				if (!ActivateExtraColliders)
				{
					weakGameEntity4.RemovePhysics();
				}
				else
				{
					if (!calledFromOnInit)
					{
						MatrixFrame frame2 = ((_extraColliderRight != null) ? _extraColliderRight.GetFrame() : _doorSkeleton.GetBoneEntitialFrameWithName(RightDoorBoneName));
						_extraColliderRight = TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(weakGameEntity4);
						_extraColliderRight.SetFrame(ref frame2);
					}
					else
					{
						_extraColliderRight = TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(weakGameEntity4);
					}
					if (_rightExtraColliderDisabled)
					{
						_extraColliderRight.SetBodyFlags(_extraColliderRight.BodyFlag | BodyFlags.Disabled);
					}
					else
					{
						_extraColliderRight.SetBodyFlags(_extraColliderRight.BodyFlag & ~BodyFlags.Disabled);
					}
				}
			}
			if (_door != null && _doorSkeleton != null)
			{
				_leftDoorBoneIndex = Skeleton.GetBoneIndexFromName(_doorSkeleton.GetName(), LeftDoorBoneName);
				_rightDoorBoneIndex = Skeleton.GetBoneIndexFromName(_doorSkeleton.GetName(), RightDoorBoneName);
			}
		}

		private void InitializeExtraColliderPositions()
		{
			if (_extraColliderLeft != null)
			{
				MatrixFrame frame = _doorSkeleton.GetBoneEntitialFrameWithName(LeftDoorBoneName);
				_extraColliderLeft.SetFrame(ref frame);
				_extraColliderLeft.SetVisibilityExcludeParents(visible: true);
			}
			if (_extraColliderRight != null)
			{
				MatrixFrame frame2 = _doorSkeleton.GetBoneEntitialFrameWithName(RightDoorBoneName);
				_extraColliderRight.SetFrame(ref frame2);
				_extraColliderRight.SetVisibilityExcludeParents(visible: true);
			}
			UpdateDoorBodies(updateAnyway: true);
			foreach (GameEntity attackOnlyDoorCollider in _attackOnlyDoorColliders)
			{
				attackOnlyDoorCollider.SetVisibilityExcludeParents(visible: true);
			}
			if (_agentColliderLeft != null)
			{
				_agentColliderLeft.SetVisibilityExcludeParents(visible: true);
			}
			if (_agentColliderRight != null)
			{
				_agentColliderRight.SetVisibilityExcludeParents(visible: true);
			}
		}

		private void OnHitTaken(DestructableComponent hitComponent, Agent hitterAgent, in MissionWeapon weapon, ScriptComponentBehavior attackerScriptComponentBehavior, int inflictedDamage)
		{
			if (!GameNetwork.IsClientOrReplay && inflictedDamage >= 200 && State == GateState.Closed && attackerScriptComponentBehavior is BatteringRam)
			{
				_plank?.SetAnimationAtChannelSynched(PlankHitAnimationName, 0);
				_door.SetAnimationAtChannelSynched(HitAnimationName, 0);
				Mission.Current.MakeSound(BatteringRamHitSoundIdCache, base.GameEntity.GlobalPosition, soundCanBePredicted: false, isReliable: true, -1, -1);
			}
		}

		private void OnDestroyed(DestructableComponent destroyedComponent, Agent destroyerAgent, in MissionWeapon weapon, ScriptComponentBehavior attackerScriptComponentBehavior, int inflictedDamage)
		{
			if (GameNetwork.IsClientOrReplay)
			{
				return;
			}
			_plank?.SetVisibleSynched(value: false);
			foreach (StandingPoint standingPoint in base.StandingPoints)
			{
				standingPoint.SetIsDeactivatedSynched(value: true);
			}
			if (attackerScriptComponentBehavior is BatteringRam)
			{
				_door.SetAnimationAtChannelSynched(DestroyAnimationName, 0);
			}
			SetGateNavMeshState(isEnabled: true);
		}

		private int OnCalculateDestructionStateIndex(int destructionStateIndex, int inflictedDamage, int destructionStateCount)
		{
			if (inflictedDamage < 200)
			{
				return destructionStateIndex;
			}
			return TaleWorlds.Library.MathF.Min(destructionStateIndex, destructionStateCount - 1);
		}

		protected internal override bool OnCheckForProblems()
		{
			bool result = base.OnCheckForProblems();
			if (base.GameEntity.HasTag("outer_gate") && base.GameEntity.HasTag("inner_gate"))
			{
				MBEditor.AddEntityWarning(base.GameEntity, "This castle gate has both outer and inner tag at the same time.");
				result = true;
			}
			if (base.GameEntity.CollectChildrenEntitiesWithTag("wait_pos").Count != 1)
			{
				MBEditor.AddEntityWarning(base.GameEntity, "There must be one entity with wait position tag under castle gate.");
				result = true;
			}
			if (base.GameEntity.HasTag("outer_gate"))
			{
				uint visibilityMask = base.GameEntity.GetVisibilityLevelMaskIncludingParents();
				WeakGameEntity weakGameEntity = base.GameEntity.GetChildren().FirstOrDefault((WeakGameEntity x) => x.HasTag("middle_pos") && x.GetVisibilityLevelMaskIncludingParents() == visibilityMask);
				if (weakGameEntity.IsValid)
				{
					WeakGameEntity weakGameEntity2 = base.Scene.FindWeakEntitiesWithTag("inner_gate").FirstOrDefault((WeakGameEntity x) => x.GetVisibilityLevelMaskIncludingParents() == visibilityMask);
					if (weakGameEntity2 != null)
					{
						if (weakGameEntity2.HasScriptOfType<CastleGate>())
						{
							Vec2 va = weakGameEntity2.GlobalPosition.AsVec2 - weakGameEntity.GlobalPosition.AsVec2;
							Vec2 vb = base.GameEntity.GlobalPosition.AsVec2 - weakGameEntity.GlobalPosition.AsVec2;
							if (Vec2.DotProduct(va, vb) <= 0f)
							{
								MBEditor.AddEntityWarning(base.GameEntity, "Outer gate's middle position must not be between outer and inner gate.");
								result = true;
							}
						}
						else
						{
							MBEditor.AddEntityWarning(base.GameEntity, weakGameEntity2.Name + " this entity has inner gate tag but doesn't have castle gate script.");
							result = true;
						}
					}
					else
					{
						MBEditor.AddEntityWarning(base.GameEntity, "There is no entity with inner gate tag.");
						result = true;
					}
				}
				else
				{
					MBEditor.AddEntityWarning(base.GameEntity, "Outer gate doesn't have any middle positions");
					result = true;
				}
			}
			Vec3 scaleVector = base.GameEntity.GetGlobalFrame().rotation.GetScaleVector();
			if (TaleWorlds.Library.MathF.Abs(scaleVector.x - scaleVector.y) > 1E-05f || TaleWorlds.Library.MathF.Abs(scaleVector.x - scaleVector.z) > 1E-05f || TaleWorlds.Library.MathF.Abs(scaleVector.y - scaleVector.z) > 1E-05f)
			{
				MBEditor.AddEntityWarning(base.GameEntity, "$$$ Non uniform scale on CastleGate at scene " + base.GameEntity.Scene.GetName());
				result = true;
			}
			return result;
		}

		public Vec3 GetTargetingOffset()
		{
			return Vec3.Zero;
		}
	}
	public class DeploymentPoint : SynchedMissionObject
	{
		public enum DeploymentPointType
		{
			BatteringRam,
			TowerLadder,
			Breach,
			Ranged
		}

		public enum DeploymentPointState
		{
			NotDeployed,
			BatteringRam,
			SiegeLadder,
			SiegeTower,
			Breach,
			Ranged
		}

		public BattleSideEnum Side = BattleSideEnum.Attacker;

		public float Radius = 3f;

		public string SiegeWeaponTag = "dpWeapon";

		private readonly List<GameEntity> _highlightedEntites = new List<GameEntity>();

		private DeploymentPointType _deploymentPointType;

		private List<SiegeLadder> _associatedSiegeLadders;

		private bool _isBreachSideDeploymentPoint;

		private MBList<SynchedMissionObject> _weapons;

		public Vec3 DeploymentTargetPosition { get; private set; }

		public WallSegment AssociatedWallSegment { get; private set; }

		public IEnumerable<SynchedMissionObject> DeployableWeapons => _weapons.Where((SynchedMissionObject w) => !w.IsDisabled);

		public bool IsDeployed => DeployedWeapon != null;

		public SynchedMissionObject DeployedWeapon { get; private set; }

		public SynchedMissionObject DisbandedWeapon { get; private set; }

		public IEnumerable<Type> DeployableWeaponTypes => DeployableWeapons.Select(MissionSiegeWeaponsController.GetWeaponType);

		public event Action<DeploymentPoint, SynchedMissionObject> OnDeploymentStateChanged;

		public event Action<DeploymentPoint> OnDeploymentPointTypeDetermined;

		public event Action<DeploymentPoint> OnDeployOrDisband;

		protected internal override void OnInit()
		{
			_weapons = new MBList<SynchedMissionObject>();
		}

		public override void AfterMissionStart()
		{
			base.OnInit();
			if (!GameNetwork.IsClientOrReplay)
			{
				_weapons = GetWeaponsUnder();
				_associatedSiegeLadders = new List<SiegeLadder>();
				if (DeployableWeapons.IsEmpty())
				{
					SetVisibleSynched(value: false);
					SetBreachSideDeploymentPoint();
				}
				base.AfterMissionStart();
				if (!GameNetwork.IsClientOrReplay)
				{
					DetermineDeploymentPointType();
				}
				HideAllWeapons();
			}
		}

		private void SetBreachSideDeploymentPoint()
		{
			TaleWorlds.Library.Debug.Print("Deployment point " + (base.GameEntity.IsValid ? ("upgrade level mask " + base.GameEntity.GetUpgradeLevelMask()) : "no game entity.") + "\n");
			_isBreachSideDeploymentPoint = true;
			_deploymentPointType = DeploymentPointType.Breach;
			FormationAI.BehaviorSide deploymentPointSide = (_weapons.FirstOrDefault((SynchedMissionObject w) => w is SiegeTower) as IPrimarySiegeWeapon).WeaponSide;
			AssociatedWallSegment = Mission.Current.ActiveMissionObjects.FindAllWithType<WallSegment>().FirstOrDefault((WallSegment ws) => ws.DefenseSide == deploymentPointSide);
			DeploymentTargetPosition = AssociatedWallSegment.GameEntity.GlobalPosition;
		}

		public Vec3 GetDeploymentOrigin()
		{
			return base.GameEntity.GlobalPosition;
		}

		public DeploymentPointState GetDeploymentPointState()
		{
			switch (_deploymentPointType)
			{
			case DeploymentPointType.BatteringRam:
				if (!IsDeployed)
				{
					return DeploymentPointState.NotDeployed;
				}
				return DeploymentPointState.BatteringRam;
			case DeploymentPointType.Breach:
				return DeploymentPointState.Breach;
			case DeploymentPointType.Ranged:
				if (!IsDeployed)
				{
					return DeploymentPointState.NotDeployed;
				}
				return DeploymentPointState.Ranged;
			case DeploymentPointType.TowerLadder:
				if (!IsDeployed)
				{
					return DeploymentPointState.SiegeLadder;
				}
				return DeploymentPointState.SiegeTower;
			default:
				MBDebug.ShowWarning("Undefined deployment point type fetched.");
				return DeploymentPointState.NotDeployed;
			}
		}

		public DeploymentPointType GetDeploymentPointType()
		{
			return _deploymentPointType;
		}

		public List<SiegeLadder> GetAssociatedSiegeLadders()
		{
			return _associatedSiegeLadders;
		}

		private void DetermineDeploymentPointType()
		{
			if (_isBreachSideDeploymentPoint)
			{
				_deploymentPointType = DeploymentPointType.Breach;
			}
			else if (_weapons.Any((SynchedMissionObject w) => w is BatteringRam))
			{
				_deploymentPointType = DeploymentPointType.BatteringRam;
				DeploymentTargetPosition = (_weapons.First((SynchedMissionObject w) => w is BatteringRam) as IPrimarySiegeWeapon).TargetCastlePosition.GameEntity.GlobalPosition;
			}
			else if (_weapons.Any((SynchedMissionObject w) => w is SiegeTower))
			{
				SiegeTower tower = _weapons.FirstOrDefault((SynchedMissionObject w) => w is SiegeTower) as SiegeTower;
				_deploymentPointType = DeploymentPointType.TowerLadder;
				DeploymentTargetPosition = tower.TargetCastlePosition.GameEntity.GlobalPosition;
				_associatedSiegeLadders = (from sl in Mission.Current.ActiveMissionObjects.FindAllWithType<SiegeLadder>()
					where sl.WeaponSide == tower.WeaponSide
					select sl).ToList();
			}
			else
			{
				_deploymentPointType = DeploymentPointType.Ranged;
				DeploymentTargetPosition = Vec3.Invalid;
			}
			this.OnDeploymentPointTypeDetermined?.Invoke(this);
		}

		public MBList<SynchedMissionObject> GetWeaponsUnder()
		{
			List<SiegeWeapon> list;
			if (Mission.Current.Teams[0].TeamAI is TeamAISiegeComponent teamAISiegeComponent)
			{
				list = teamAISiegeComponent.SceneSiegeWeapons;
			}
			else
			{
				List<GameEntity> entities = new List<GameEntity>();
				base.GameEntity.Scene.GetEntities(ref entities);
				list = (from se in entities
					where se.HasScriptOfType<SiegeWeapon>()
					select se.GetScriptComponents<SiegeWeapon>().FirstOrDefault()).ToList();
			}
			MBList<SynchedMissionObject> mBList = new MBList<SynchedMissionObject>();
			float num = Radius * Radius;
			foreach (SiegeWeapon item in list)
			{
				if (item.GameEntity.HasTag(SiegeWeaponTag) || (item.GameEntity.Parent.IsValid && item.GameEntity.Parent.HasTag(SiegeWeaponTag)) || (item.GameEntity != base.GameEntity && item.GameEntity.GlobalPosition.DistanceSquared(base.GameEntity.GlobalPosition) < num))
				{
					mBList.Add(item);
				}
			}
			return mBList;
		}

		public IEnumerable<SpawnerBase> GetSpawnersForEditor()
		{
			List<GameEntity> entities = new List<GameEntity>();
			base.GameEntity.Scene.GetEntities(ref entities);
			IEnumerable<SpawnerBase> source = from se in entities
				where se.HasScriptOfType<SpawnerBase>()
				select se.GetScriptComponents<SpawnerBase>().FirstOrDefault();
			IEnumerable<SpawnerBase> first = from ssw in source
				where ssw.GameEntity.HasTag(SiegeWeaponTag)
				select (ssw);
			Vec3 globalPosition = base.GameEntity.GlobalPosition;
			float radiusSquared = Radius * Radius;
			IEnumerable<SpawnerBase> second = from ssw in source
				where ssw.GameEntity != base.GameEntity && ssw.GameEntity.GlobalPosition.DistanceSquared(globalPosition) < radiusSquared
				select (ssw);
			return first.Concat(second).Distinct();
		}

		protected internal override void OnEditorInit()
		{
			base.OnEditorInit();
			_weapons = null;
		}

		protected internal override void OnEditorTick(float dt)
		{
			base.OnEditorTick(dt);
			foreach (GameEntity highlightedEntite in _highlightedEntites)
			{
				highlightedEntite.SetContourColor(null);
			}
			_highlightedEntites.Clear();
			if (!MBEditor.IsEntitySelected(base.GameEntity))
			{
				return;
			}
			uint num = 4294901760u;
			if (Radius > 0f)
			{
				DebugExtensions.RenderDebugCircleOnTerrain(base.Scene, base.GameEntity.GetGlobalFrame(), Radius, num);
			}
			foreach (SpawnerBase item in GetSpawnersForEditor())
			{
				item.GameEntity.SetContourColor(num);
				_highlightedEntites.Add(TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(item.GameEntity));
			}
		}

		private void OnDeploymentStateChangedAux(SynchedMissionObject targetObject)
		{
			if (IsDeployed)
			{
				targetObject.SetVisibleSynched(value: true);
				targetObject.SetPhysicsStateSynched(value: true);
			}
			else
			{
				targetObject.SetVisibleSynched(value: false);
				targetObject.SetPhysicsStateSynched(value: false);
			}
			this.OnDeploymentStateChanged?.Invoke(this, targetObject);
			if (targetObject is SiegeWeapon siegeWeapon)
			{
				siegeWeapon.OnDeploymentStateChanged(IsDeployed);
			}
		}

		public void Deploy(Type t)
		{
			DeployedWeapon = _weapons.First((SynchedMissionObject w) => MissionSiegeWeaponsController.GetWeaponType(w) == t);
			OnDeploymentStateChangedAux(DeployedWeapon);
			ToggleDeploymentPointVisibility(visible: false);
			ToggleDeployedWeaponVisibility(visible: true);
			this.OnDeployOrDisband?.Invoke(this);
		}

		public void Deploy(SiegeWeapon s)
		{
			DeployedWeapon = s;
			DisbandedWeapon = null;
			OnDeploymentStateChangedAux(s);
			ToggleDeploymentPointVisibility(visible: false);
			ToggleDeployedWeaponVisibility(visible: true);
			this.OnDeployOrDisband?.Invoke(this);
		}

		public ScriptComponentBehavior Disband()
		{
			ToggleDeploymentPointVisibility(visible: true);
			ToggleDeployedWeaponVisibility(visible: false);
			DisbandedWeapon = DeployedWeapon;
			DeployedWeapon = null;
			OnDeploymentStateChangedAux(DisbandedWeapon);
			this.OnDeployOrDisband?.Invoke(this);
			return DisbandedWeapon;
		}

		public void Hide()
		{
			ToggleDeploymentPointVisibility(visible: false);
			foreach (SynchedMissionObject item in GetWeaponsUnder())
			{
				if (item != null)
				{
					item.SetVisibleSynched(value: false);
					item.SetPhysicsStateSynched(value: false);
				}
			}
		}

		public void Show()
		{
			ToggleDeploymentPointVisibility(!IsDeployed);
			if (IsDeployed)
			{
				ToggleDeployedWeaponVisibility(visible: true);
			}
		}

		private void ToggleDeploymentPointVisibility(bool visible)
		{
			SetVisibleSynched(visible);
			SetPhysicsStateSynched(visible);
		}

		private void ToggleDeployedWeaponVisibility(bool visible)
		{
			ToggleWeaponVisibility(visible, DeployedWeapon);
		}

		public void ToggleWeaponVisibility(bool visible, SynchedMissionObject weapon)
		{
			WeakGameEntity weakGameEntity = weapon?.GameEntity.Parent ?? WeakGameEntity.Invalid;
			SynchedMissionObject synchedMissionObject = (weakGameEntity.IsValid ? weakGameEntity.GetFirstScriptOfType<SynchedMissionObject>() : null);
			if (synchedMissionObject != null)
			{
				synchedMissionObject.SetVisibleSynched(visible);
				synchedMissionObject.SetPhysicsStateSynched(visible);
			}
			else
			{
				weapon?.SetVisibleSynched(visible);
				weapon?.SetPhysicsStateSynched(visible);
			}
			if (!(weapon is SiegeWeapon) || !weapon.GameEntity.Parent.IsValid)
			{
				return;
			}
			foreach (WeakGameEntity child in weapon.GameEntity.Parent.GetChildren())
			{
				SiegeMachineStonePile firstScriptOfType = child.GetFirstScriptOfType<SiegeMachineStonePile>();
				if (firstScriptOfType != null)
				{
					firstScriptOfType.SetPhysicsStateSynched(visible);
					break;
				}
			}
		}

		public void HideAllWeapons()
		{
			foreach (SynchedMissionObject deployableWeapon in DeployableWeapons)
			{
				ToggleWeaponVisibility(visible: false, deployableWeapon);
			}
		}
	}
	public class DestructableComponent : SynchedMissionObject, IFocusable
	{
		[DefineSynchedMissionObjectType(typeof(DestructableComponent))]
		public struct DestructableComponentRecord : ISynchedMissionObjectReadableRecord
		{
			public float HitPoint { get; private set; }

			public int DestructionState { get; private set; }

			public int ForceIndex { get; private set; }

			public bool IsMissionObject { get; private set; }

			public DestructableComponentRecord(float hitPoint, int destructionState, int forceIndex, bool isMissionObject)
			{
				HitPoint = hitPoint;
				DestructionState = destructionState;
				ForceIndex = forceIndex;
				IsMissionObject = isMissionObject;
			}

			public bool ReadFromNetwork(ref bool bufferReadValid)
			{
				HitPoint = GameNetworkMessage.ReadFloatFromPacket(CompressionMission.UsableGameObjectHealthCompressionInfo, ref bufferReadValid);
				DestructionState = GameNetworkMessage.ReadIntFromPacket(CompressionMission.UsableGameObjectDestructionStateCompressionInfo, ref bufferReadValid);
				ForceIndex = -1;
				if (DestructionState != 0)
				{
					IsMissionObject = GameNetworkMessage.ReadBoolFromPacket(ref bufferReadValid);
					if (IsMissionObject)
					{
						ForceIndex = GameNetworkMessage.ReadMissionObjectIdFromPacket(ref bufferReadValid).Id;
					}
				}
				return bufferReadValid;
			}
		}

		public delegate void OnHitTakenAndDestroyedDelegate(DestructableComponent target, Agent attackerAgent, in MissionWeapon weapon, ScriptComponentBehavior attackerScriptComponentBehavior, int inflictedDamage);

		public const string CleanStateTag = "operational";

		public static float MaxBlowMagnitude = 20f;

		public string DestructionStates;

		public bool DestroyedByStoneOnly;

		public bool CanBeDestroyedInitially = true;

		public float MaxHitPoint = 100f;

		public bool DestroyOnAnyHit;

		public bool PassHitOnToParent;

		public string ReferenceEntityTag;

		public string HeavyHitParticlesTag;

		public float HeavyHitParticlesThreshold = 5f;

		public string ParticleEffectOnDestroy = "";

		public string SoundEffectOnDestroy = "";

		public float SoundAndParticleEffectHeightOffset;

		public float SoundAndParticleEffectForwardOffset;

		public BattleSideEnum BattleSide = BattleSideEnum.None;

		[EditableScriptComponentVariable(false, "")]
		public Func<int, int, int, int> OnCalculateDestructionStateIndex;

		private float _hitPoint;

		private string OriginalStateTag = "operational";

		private GameEntity _referenceEntity;

		private GameEntity _previousState;

		private GameEntity _originalState;

		private string[] _destructionStates;

		private int _currentStateIndex;

		private List<GameEntity> _heavyHitParticles;

		public float HitPoint
		{
			get
			{
				return _hitPoint;
			}
			set
			{
				if (!_hitPoint.Equals(value))
				{
					_hitPoint = TaleWorlds.Library.MathF.Max(value, 0f);
					if (GameNetwork.IsServerOrRecorder)
					{
						GameNetwork.BeginBroadcastModuleEvent();
						GameNetwork.WriteMessage(new SyncObjectHitpoints(base.Id, value));
						GameNetwork.EndBroadcastModuleEvent(GameNetwork.EventBroadcastFlags.AddToMissionRecord);
					}
				}
			}
		}

		public FocusableObjectType FocusableObjectType => FocusableObjectType.None;

		public virtual bool IsFocusable => true;

		public bool IsDestroyed => HitPoint <= 0f;

		public GameEntity CurrentState { get; private set; }

		private bool HasDestructionState
		{
			get
			{
				if (_destructionStates != null)
				{
					return !_destructionStates.IsEmpty();
				}
				return false;
			}
		}

		public event Action OnNextDestructionState;

		public event OnHitTakenAndDestroyedDelegate OnDestroyed;

		public event OnHitTakenAndDestroyedDelegate OnHitTaken;

		protected override void OnRemoved(int removeReason)
		{
			base.OnRemoved(removeReason);
			_referenceEntity = null;
			_previousState = null;
			_originalState = null;
			CurrentState = null;
		}

		protected DestructableComponent()
		{
		}

		protected internal override void OnInit()
		{
			base.OnInit();
			_hitPoint = MaxHitPoint;
			_referenceEntity = TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(string.IsNullOrEmpty(ReferenceEntityTag) ? base.GameEntity : base.GameEntity.GetFirstChildEntityWithTag(ReferenceEntityTag));
			if (!string.IsNullOrEmpty(DestructionStates))
			{
				_destructionStates = DestructionStates.Replace(" ", string.Empty).Split(new char[1] { ',' });
				bool flag = false;
				string[] destructionStates = _destructionStates;
				foreach (string item in destructionStates)
				{
					if (string.IsNullOrEmpty(item))
					{
						continue;
					}
					WeakGameEntity gameEntity = base.GameEntity.GetChildren().FirstOrDefault((WeakGameEntity x) => x.Name == item);
					if (gameEntity.IsValid)
					{
						PhysicsShape physicsShape = null;
						gameEntity.AddBodyFlags(BodyFlags.Moveable);
						physicsShape = gameEntity.GetBodyShape();
						if (physicsShape != null)
						{
							PhysicsShape.AddPreloadQueueWithName(physicsShape.GetName(), gameEntity.GetGlobalScale());
							flag = true;
						}
						continue;
					}
					GameEntity gameEntity2 = TaleWorlds.Engine.GameEntity.Instantiate(null, item, callScriptCallbacks: false);
					List<GameEntity> children = new List<GameEntity>();
					gameEntity2.GetChildrenRecursive(ref children);
					children.Add(gameEntity2);
					PhysicsShape physicsShape2 = null;
					foreach (GameEntity item2 in children)
					{
						physicsShape2 = item2.GetBodyShape();
						if (physicsShape2 != null)
						{
							Vec3 globalScale = item2.GetGlobalScale();
							Vec3 globalScale2 = _referenceEntity.GetGlobalScale();
							PhysicsShape.AddPreloadQueueWithName(scale: new Vec3(globalScale.x * globalScale2.x, globalScale.y * globalScale2.y, globalScale.z * globalScale2.z), bodyName: physicsShape2.GetName());
							flag = true;
						}
					}
				}
				if (flag)
				{
					PhysicsShape.ProcessPreloadQueue();
				}
			}
			WeakGameEntity originalState = GetOriginalState(base.GameEntity);
			_originalState = TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(originalState.IsValid ? originalState : base.GameEntity);
			CurrentState = _originalState;
			_originalState.AddBodyFlags(BodyFlags.Moveable);
			List<WeakGameEntity> children2 = new List<WeakGameEntity>();
			base.GameEntity.GetChildrenRecursive(ref children2);
			foreach (WeakGameEntity item3 in children2.Where((WeakGameEntity child) => child.BodyFlag.HasAnyFlag(BodyFlags.Dynamic)))
			{
				item3.SetPhysicsState(isEnabled: false, setChildren: true);
				item3.SetFrameChanged();
			}
			_heavyHitParticles = TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(base.GameEntity).CollectChildrenEntitiesWithTag(HeavyHitParticlesTag);
			base.GameEntity.SetAnimationSoundActivation(activate: true);
		}

		public WeakGameEntity GetOriginalState(WeakGameEntity parent)
		{
			int childCount = parent.ChildCount;
			for (int i = 0; i < childCount; i++)
			{
				WeakGameEntity child = parent.GetChild(i);
				if (!child.HasScriptOfType<DestructableComponent>())
				{
					if (child.HasTag(OriginalStateTag))
					{
						return child;
					}
					WeakGameEntity originalState = GetOriginalState(child);
					if (originalState.IsValid)
					{
						return originalState;
					}
				}
			}
			return WeakGameEntity.Invalid;
		}

		protected internal override void OnEditorInit()
		{
			base.OnEditorInit();
			_referenceEntity = TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(string.IsNullOrEmpty(ReferenceEntityTag) ? base.GameEntity : base.GameEntity.GetFirstChildEntityWithTag(ReferenceEntityTag));
		}

		protected internal override void OnEditorVariableChanged(string variableName)
		{
			base.OnEditorVariableChanged(variableName);
			if (variableName.Equals(ReferenceEntityTag))
			{
				_referenceEntity = TaleWorlds.Engine.GameEntity.CreateFromWeakEntity(string.IsNullOrEmpty(ReferenceEntityTag) ? base.GameEntity : base.GameEntity.GetFirstChildEntityWithTag(ReferenceEntityTag));
			}
		}

		protected internal override void OnMissionReset()
		{
			base.OnMissionReset();
			Reset();
		}

		public void Reset()
		{
			RestoreEntity();
			_hitPoint = MaxHitPoint;
			_currentStateIndex = 0;
		}

		private void RestoreEntity()
		{
			if (_destructionStates != null)
			{
				int i;
				for (i = 0; i < _destructionStates.Length; i++)
				{
					WeakGameEntity weakGameEntity = base.GameEntity.GetChildren().FirstOrDefault((WeakGameEntity x) => x.Name == _destructionStates[i].ToString());
					if (weakGameEntity.IsValid)
					{
						weakGameEntity.Skeleton?.SetAnimationAtChannel(-1, 0);
					}
				}
			}
			if (CurrentState != _originalState)
			{
				CurrentState.SetVisibilityExcludeParents(visible: false);
				CurrentState.SetPhysicsState(isEnabled: false, setChildren: true);
				CurrentState = _originalState;
			}
			CurrentState.SetVisibilityExcludeParents(visible: true);
			CurrentState.SetPhysicsState(isEnabled: true, setChildren: true);
			CurrentState.SetFrameChanged();
		}

