				}
				float num = 0.05f;
				foreach (StandingPoint rotateStandingPoint in _rotateStandingPoints)
				{
					if (rotateStandingPoint.HasUser && !rotateStandingPoint.UserAgent.IsInBeingStruckAction)
					{
						num += 0.1f;
					}
				}
				return num;
			}
		}

