		public override SiegeEngineType GetSiegeEngineType()
		{
			if (DefaultSide != BattleSideEnum.Attacker)
			{
				return DefaultSiegeEngineTypes.Catapult;
			}
			return DefaultSiegeEngineTypes.Onager;
