		private void PlayMovementSound()
		{
			if (!_isMoveSoundPlaying)
			{
				_movementSound = SoundEvent.CreateEvent(MovementSoundCodeID, MainObject.GameEntity.Scene);
				_movementSound.Play();
				_isMoveSoundPlaying = true;
