		private MatrixFrame FindGroundFrameForWheels(ref MatrixFrame frame)
		{
			return FindGroundFrameForWheelsStatic(ref frame, AxleLength, _wheelDiameter, MainObject.GameEntity, _wheels, MainObject.Scene);
		}

