	public class SceneLeveler : ScriptComponentBehavior
	{
		public string SourceSelectionSetName = "";

		public string TargetSelectionSetName = "";

		public SimpleButton CreateLevel1;

		public SimpleButton CreateLevel2;

		public SimpleButton CreateLevel3;

		public SimpleButton DeleteLevel1;

		public SimpleButton DeleteLevel2;

		public SimpleButton DeleteLevel3;

		public SimpleButton SelectEntitiesWithoutLevel;

		protected internal override void OnEditorVariableChanged(string variableName)
		{
			switch (variableName)
			{
			case "CreateLevel1":
				OnLevelizeButtonPressed(1);
				break;
			case "CreateLevel2":
				OnLevelizeButtonPressed(2);
				break;
			case "CreateLevel3":
				OnLevelizeButtonPressed(3);
				break;
			case "DeleteLevel1":
				OnDeleteButtonPressed(1);
				break;
			case "DeleteLevel2":
				OnDeleteButtonPressed(2);
				break;
			case "DeleteLevel3":
				OnDeleteButtonPressed(3);
				break;
			case "SelectEntitiesWithoutLevel":
				OnSelectEntitiesWithoutLevelButtonPressed();
				break;
			}
		}

		private void OnLevelizeButtonPressed(int level)
		{
			if (SourceSelectionSetName.IsEmpty())
			{
				MessageManager.DisplayMessage("ApplyToSelectionSet is empty!");
				return;
			}
			if (TargetSelectionSetName.IsEmpty())
			{
				MessageManager.DisplayMessage("NewSelectionSetName is empty!");
				return;
			}
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			int num4 = 0;
			GameEntity.UpgradeLevelMask levelMask = GetLevelMask(level);
			List<GameEntity> list = CollectEntitiesWithLevel();
			List<GameEntity> list2 = new List<GameEntity>();
			foreach (GameEntity item in list)
			{
				string text = FindPossiblePrefabName(item);
				if (text.IsEmpty())
				{
					num++;
					continue;
				}
				GameEntity.UpgradeLevelMask upgradeLevelMask = item.GetUpgradeLevelMask();
				if ((upgradeLevelMask & levelMask) != 0)
				{
					num2++;
					list2.Add(item);
					continue;
				}
				string prefabName = ConvertPrefabName(text, levelMask);
				GameEntity gameEntity = TaleWorlds.Engine.GameEntity.Instantiate(base.Scene, prefabName, item.GetGlobalFrame());
				if (gameEntity == null)
				{
					num3++;
					continue;
				}
				num4++;
				GameEntity.UpgradeLevelMask upgradeLevelMask2 = upgradeLevelMask & ~TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level1 & ~TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level2 & ~TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level3;
				upgradeLevelMask2 |= levelMask;
				gameEntity.SetUpgradeLevelMask(upgradeLevelMask2);
				CopyScriptParameters(gameEntity, item);
				list2.Add(gameEntity);
			}
			TaleWorlds.Library.Debug.Print("Created Entities : " + num4 + "\nAlready Visible In Desired Level : " + num2 + "\nWithout Prefab For Level : " + num3 + "\nWithout Prefab Info : " + num, 0, TaleWorlds.Library.Debug.DebugColor.Magenta);
			Utilities.CreateSelectionInEditor(list2, TargetSelectionSetName);
		}

		private void CopyScriptParameters(GameEntity entity, GameEntity copyFromEntity)
		{
			if (copyFromEntity.HasScriptComponent("WallSegment") && !entity.HasScriptComponent("WallSegment"))
			{
				entity.CopyScriptComponentFromAnotherEntity(copyFromEntity, "WallSegment");
			}
			if (copyFromEntity.HasScriptComponent("mesh_bender") && !entity.HasScriptComponent("mesh_bender"))
			{
				entity.CopyScriptComponentFromAnotherEntity(copyFromEntity, "mesh_bender");
			}
			for (int i = 0; i < entity.ChildCount && i < copyFromEntity.ChildCount; i++)
			{
				CopyScriptParameters(entity.GetChild(i), copyFromEntity.GetChild(i));
			}
		}

		private GameEntity.UpgradeLevelMask GetLevelMask(int level)
		{
			return level switch
			{
				2 => TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level2, 
				1 => TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level1, 
				_ => TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level3, 
			};
		}

		private string GetLevelSubString(GameEntity.UpgradeLevelMask levelMask)
		{
			return levelMask switch
			{
				TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level1 => "_l1", 
				TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level2 => "_l2", 
				TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level3 => "_l3", 
				_ => "", 
			};
		}

		private string ConvertPrefabName(string prefabName, GameEntity.UpgradeLevelMask newLevelMask)
		{
			string text = prefabName;
			string levelSubString = GetLevelSubString(newLevelMask);
			if (newLevelMask != TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level1)
			{
				text = text.Replace(GetLevelSubString(TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level1), levelSubString);
			}
			if (newLevelMask != TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level2)
			{
				text = text.Replace(GetLevelSubString(TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level2), levelSubString);
			}
			if (newLevelMask != TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level3)
			{
				text = text.Replace(GetLevelSubString(TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level3), levelSubString);
			}
			if (text.Equals(prefabName))
			{
				return "";
			}
			return text;
		}

		private string FindPossiblePrefabName(GameEntity gameEntity)
		{
			string prefabName = gameEntity.GetPrefabName();
			if (prefabName.IsEmpty())
			{
				return gameEntity.GetOldPrefabName();
			}
			return prefabName;
		}

		private void OnDeleteButtonPressed(int level)
		{
			if (SourceSelectionSetName.IsEmpty())
			{
				MessageManager.DisplayMessage("ApplyToSelectionSet is empty!");
				return;
			}
			List<GameEntity> list = CollectEntitiesWithLevel();
			GameEntity.UpgradeLevelMask levelMask = GetLevelMask(level);
			List<GameEntity> list2 = new List<GameEntity>();
			int num = 0;
			int num2 = 0;
			foreach (GameEntity item in list)
			{
				GameEntity.UpgradeLevelMask upgradeLevelMask = item.GetUpgradeLevelMask();
				if (upgradeLevelMask == levelMask)
				{
					list2.Add(item);
					num++;
				}
				else if ((upgradeLevelMask & levelMask) != 0)
				{
					item.SetUpgradeLevelMask(upgradeLevelMask & ~levelMask);
					num2++;
				}
			}
			Utilities.DeleteEntitiesInEditorScene(list2);
			TextObject textObject = new TextObject("{=!}Deleted entity count : {DELETED_ENTRY_COUNT}");
			TextObject textObject2 = new TextObject("{=!}Removed level mask count : {REMOVED_LEVEL_MASK}");
			textObject.SetTextVariable("DELETED_ENTRY_COUNT", num);
			textObject2.SetTextVariable("REMOVED_LEVEL_MASK", num2);
			MessageManager.DisplayMessage(textObject.ToString());
			MessageManager.DisplayMessage(textObject2.ToString());
		}

		private void OnSelectEntitiesWithoutLevelButtonPressed()
		{
			List<GameEntity> entities = new List<GameEntity>();
			base.Scene.GetEntities(ref entities);
			List<GameEntity> list = entities.FindAll((GameEntity x) => x.GetUpgradeLevelMask() == TaleWorlds.Engine.GameEntity.UpgradeLevelMask.None);
			TextObject textObject = new TextObject("{=!}Selected entity count : {SELECTED_ENTITIES}");
			textObject.SetTextVariable("SELECTED_ENTITIES", list.Count);
			MessageManager.DisplayMessage(textObject.ToString());
			if (list.Count > 0)
			{
				Utilities.SelectEntities(list);
			}
		}

		private List<GameEntity> CollectEntitiesWithLevel()
		{
			List<GameEntity> gameEntities = new List<GameEntity>();
			Utilities.GetEntitiesOfSelectionSet(SourceSelectionSetName, ref gameEntities);
			for (int num = gameEntities.Count - 1; num >= 0; num--)
			{
				if ((gameEntities[num].GetUpgradeLevelMask() & (TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level1 | TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level2 | TaleWorlds.Engine.GameEntity.UpgradeLevelMask.Level3)) == 0)
				{
					gameEntities.RemoveAt(num);
				}
			}
			return gameEntities;
		}
	}
}
namespace TaleWorlds.MountAndBlade.Source.Objects.Siege
{
	public class AgentPathNavMeshChecker
	{
		public enum Direction
		{
			ForwardOnly,
			BackwardOnly,
			BothDirections
		}

		private BattleSideEnum _teamToCollect;

		private Direction _directionToCollect;

		private MatrixFrame _pathFrameToCheck;

		private float _radiusToCheck;

		private Mission _mission;

		private int _navMeshId;

		private TaleWorlds.Core.Timer _tickOccasionallyTimer;

		private MBList<Agent> _nearbyAgents = new MBList<Agent>();

		private bool _isBeingUsed;

		private TaleWorlds.Core.Timer _setBeingUsedToFalseTimer;

		private float _maxDistanceCheck;

		private float _agentMoveTime;

		public AgentPathNavMeshChecker(Mission mission, MatrixFrame pathFrameToCheck, float radiusToCheck, int navMeshId, BattleSideEnum teamToCollect, Direction directionToCollect, float maxDistanceCheck, float agentMoveTime)
		{
			_mission = mission;
			_pathFrameToCheck = pathFrameToCheck;
			_radiusToCheck = radiusToCheck;
			_navMeshId = navMeshId;
			_teamToCollect = teamToCollect;
			_directionToCollect = directionToCollect;
			_maxDistanceCheck = maxDistanceCheck;
			_agentMoveTime = agentMoveTime;
		}

		public void Tick(float dt)
		{
			float currentTime = _mission.CurrentTime;
			if (_tickOccasionallyTimer == null || _tickOccasionallyTimer.Check(currentTime))
			{
				float dt2 = dt;
				if (_tickOccasionallyTimer != null)
				{
					dt2 = _tickOccasionallyTimer.ElapsedTime();
				}
				_tickOccasionallyTimer = new TaleWorlds.Core.Timer(currentTime, 0.1f + MBRandom.RandomFloat * 0.1f);
				TickOccasionally(dt2);
			}
			bool flag = false;
			foreach (Agent nearbyAgent in _nearbyAgents)
			{
				Vec3 position = nearbyAgent.Position;
				if ((_teamToCollect != BattleSideEnum.None && (nearbyAgent.Team == null || nearbyAgent.Team.Side != _teamToCollect)) || !nearbyAgent.IsAIControlled)
				{
					continue;
				}
				if (nearbyAgent.GetCurrentNavigationFaceId() == _navMeshId)
				{
					flag = true;
					break;
				}
				if (_isBeingUsed && position.DistanceSquared(_pathFrameToCheck.origin) < _radiusToCheck * _radiusToCheck)
				{
					flag = true;
					break;
				}
				if (nearbyAgent.MovementVelocity.LengthSquared > 0.01f && nearbyAgent.HasPathThroughNavigationFaceIdFromDirection(direction: (_directionToCollect == Direction.ForwardOnly) ? _pathFrameToCheck.rotation.f.AsVec2 : ((_directionToCollect != Direction.BackwardOnly) ? Vec2.Zero : (-_pathFrameToCheck.rotation.f.AsVec2)), navigationFaceId: _navMeshId))
				{
					float num = nearbyAgent.GetPathDistanceToPoint(ref _pathFrameToCheck.origin);
					if (num >= 100000f)
					{
						num = nearbyAgent.Position.Distance(_pathFrameToCheck.origin);
					}
					if (num < _radiusToCheck * 2f || num / nearbyAgent.GetMaximumForwardUnlimitedSpeed() < _agentMoveTime)
					{
						flag = true;
					}
				}
			}
			if (flag)
			{
				_isBeingUsed = true;
				_setBeingUsedToFalseTimer = null;
			}
			else if (_setBeingUsedToFalseTimer == null)
			{
				_setBeingUsedToFalseTimer = new TaleWorlds.Core.Timer(currentTime, 1f);
			}
			if (_setBeingUsedToFalseTimer != null && _setBeingUsedToFalseTimer.Check(currentTime))
			{
				_setBeingUsedToFalseTimer = null;
				_isBeingUsed = false;
			}
		}

		public void TickOccasionally(float dt)
		{
			_nearbyAgents = _mission.GetNearbyAgents(_pathFrameToCheck.origin.AsVec2, _maxDistanceCheck, _nearbyAgents);
		}

		public bool HasAgentsUsingPath()
		{
			return _isBeingUsed;
		}
	}
}
namespace TaleWorlds.MountAndBlade.Source.Missions
{
	public abstract class BaseBattleMissionController : MissionLogic
	{
		protected readonly Game game;

		protected bool IsPlayerAttacker { get; private set; }

		protected int DeployedAttackerTroopCount { get; private set; }

		protected int DeployedDefenderTroopCount { get; private set; }

		protected BaseBattleMissionController(bool isPlayerAttacker)
		{
			IsPlayerAttacker = isPlayerAttacker;
			game = Game.Current;
		}

		public override void EarlyStart()
		{
			EarlyStart();
		}

		public override void AfterStart()
		{
			base.AfterStart();
			CreateTeams();
			base.Mission.SetMissionMode(MissionMode.Battle, atStart: true);
		}

		protected virtual void SetupTeam(Team team)
		{
			if (team.Side == BattleSideEnum.Attacker)
			{
				CreateAttackerTroops();
			}
			else
			{
				CreateDefenderTroops();
			}
			if (team == base.Mission.PlayerTeam)
			{
				CreatePlayer();
			}
		}

		protected abstract void CreateDefenderTroops();

		protected abstract void CreateAttackerTroops();

		public virtual TeamAIComponent GetTeamAI(Team team, float thinkTimerTime = 5f, float applyTimerTime = 1f)
		{
			return new TeamAIGeneral(base.Mission, team, thinkTimerTime, applyTimerTime);
		}

		public override void OnMissionTick(float dt)
		{
			base.OnMissionTick(dt);
		}

		[Conditional("DEBUG")]
		private void DebugTick()
		{
			if (Input.DebugInput.IsHotKeyPressed("SwapToEnemy"))
			{
				BecomeEnemy();
			}
			if (Input.DebugInput.IsHotKeyDown("BaseBattleMissionControllerHotkeyBecomePlayer"))
			{
				BecomePlayer();
			}
		}

		protected bool IsPlayerDead()
		{
			if (base.Mission.MainAgent != null)
			{
				return !base.Mission.MainAgent.IsActive();
			}
			return true;
		}

		public override bool MissionEnded(ref MissionResult missionResult)
		{
			if (!base.Mission.IsDeploymentFinished)
			{
				return false;
			}
			if (IsPlayerDead())
			{
				missionResult = MissionResult.CreateDefeated(base.Mission);
				return true;
			}
			if (base.Mission.GetMemberCountOfSide(BattleSideEnum.Attacker) == 0)
			{
				missionResult = ((base.Mission.PlayerTeam.Side == BattleSideEnum.Attacker) ? MissionResult.CreateDefeated(base.Mission) : MissionResult.CreateSuccessful(base.Mission));
				return true;
			}
			if (base.Mission.GetMemberCountOfSide(BattleSideEnum.Defender) == 0)
			{
				missionResult = ((base.Mission.PlayerTeam.Side == BattleSideEnum.Attacker) ? MissionResult.CreateSuccessful(base.Mission) : MissionResult.CreateDefeated(base.Mission));
				return true;
			}
			return false;
		}

		public override InquiryData OnEndMissionRequest(out bool canPlayerLeave)
		{
			canPlayerLeave = true;
			if (!IsPlayerDead() && base.Mission.IsPlayerCloseToAnEnemy())
			{
				canPlayerLeave = false;
				MBInformationManager.AddQuickInformation(GameTexts.FindText("str_can_not_retreat"));
			}
			else
			{
				MissionResult missionResult = null;
				if (!IsPlayerDead() && !MissionEnded(ref missionResult))
				{
					return new InquiryData("", GameTexts.FindText("str_retreat_question").ToString(), isAffirmativeOptionShown: true, isNegativeOptionShown: true, GameTexts.FindText("str_ok").ToString(), GameTexts.FindText("str_cancel").ToString(), base.Mission.OnEndMissionResult, null);
				}
			}
			return null;
		}

		public override void OnAgentRemoved(Agent affectedAgent, Agent affectorAgent, AgentState agentState, KillingBlow killingBlow)
		{
		}

		private void CreateTeams()
		{
			if (!base.Mission.Teams.IsEmpty())
			{
				throw new MBIllegalValueException("Number of teams is not 0.");
			}
			base.Mission.Teams.Add(BattleSideEnum.Defender, 4278190335u, 4278190335u);
			base.Mission.Teams.Add(BattleSideEnum.Attacker, 4278255360u, 4278255360u);
			if (IsPlayerAttacker)
			{
				base.Mission.PlayerTeam = base.Mission.AttackerTeam;
			}
			else
			{
				base.Mission.PlayerTeam = base.Mission.DefenderTeam;
			}
			TeamAIComponent teamAI = GetTeamAI(base.Mission.DefenderTeam);
			base.Mission.DefenderTeam.AddTeamAI(teamAI);
			TeamAIComponent teamAI2 = GetTeamAI(base.Mission.AttackerTeam);
			base.Mission.AttackerTeam.AddTeamAI(teamAI2);
		}

		protected void IncrementDeploymedTroops(BattleSideEnum side)
		{
			if (side == BattleSideEnum.Attacker)
			{
				DeployedAttackerTroopCount++;
			}
			else
			{
				DeployedDefenderTroopCount++;
			}
		}

		protected virtual void CreatePlayer()
		{
			game.PlayerTroop = Game.Current.ObjectManager.GetObject<BasicCharacterObject>("main_hero");
			FormationClass formationClass = base.Mission.GetFormationSpawnClass(base.Mission.PlayerTeam, FormationClass.NumberOfRegularFormations);
			if (formationClass != FormationClass.NumberOfRegularFormations)
			{
				formationClass = game.PlayerTroop.DefaultFormationClass;
			}
			base.Mission.GetFormationSpawnFrame(base.Mission.PlayerTeam, formationClass, isReinforcement: false, out var spawnPosition, out var spawnDirection);
			Mission mission = base.Mission;
			AgentBuildData agentBuildData = new AgentBuildData(game.PlayerTroop).Team(base.Mission.PlayerTeam);
			Vec3 position = spawnPosition.GetGroundVec3();
			Agent agent = mission.SpawnAgent(agentBuildData.InitialPosition(in position).InitialDirection(in spawnDirection).Controller(AgentControllerType.Player));
			agent.WieldInitialWeapons();
			base.Mission.MainAgent = agent;
		}

		protected void BecomeEnemy()
		{
			base.Mission.MainAgent.Controller = AgentControllerType.AI;
			base.Mission.PlayerEnemyTeam.Leader.Controller = AgentControllerType.Player;
			SwapTeams();
		}

		protected void BecomePlayer()
		{
			base.Mission.MainAgent.Controller = AgentControllerType.Player;
			base.Mission.PlayerEnemyTeam.Leader.Controller = AgentControllerType.AI;
			SwapTeams();
		}

		protected void SwapTeams()
		{
			base.Mission.PlayerTeam = base.Mission.PlayerEnemyTeam;
			IsPlayerAttacker = !IsPlayerAttacker;
		}
	}
	public class BattleSpawnLogic : MissionLogic
