	public class CaravanBattleMissionHandler : MissionLogic
	{
		private GameEntity _entity;

		private int _unitCount;

		private bool _isCamelCulture;

		private bool _isCaravan;

		private readonly string[] _camelLoadHarnesses = new string[2] { "camel_saddle_a", "camel_saddle_b" };

		private readonly string[] _camelMountableHarnesses = new string[1] { "camel_saddle" };

		private readonly string[] _muleLoadHarnesses = new string[3] { "mule_load_a", "mule_load_b", "mule_load_c" };

		private readonly string[] _muleMountableHarnesses = new string[3] { "aseran_village_harness", "steppe_fur_harness", "steppe_harness" };

		private const string CaravanPrefabName = "caravan_scattered_goods_prop";

		private const string VillagerGoodsPrefabName = "villager_scattered_goods_prop";

		public CaravanBattleMissionHandler(int unitCount, bool isCamelCulture, bool isCaravan)
		{
			_unitCount = unitCount;
			_isCamelCulture = isCamelCulture;
			_isCaravan = isCaravan;
		}

		public override void AfterStart()
		{
			base.AfterStart();
			float pathOffset = Mission.ComputeSpawnPathDeploymentOffset((int)((float)_unitCount * 1.5f), base.Mission.GetInitialSpawnPath());
			WorldFrame spawnPathFrame = base.Mission.GetSpawnPathFrame(base.Mission.DefenderTeam.Side, pathOffset);
			Scene scene = Mission.Current.Scene;
			string prefabName = (_isCaravan ? "caravan_scattered_goods_prop" : "villager_scattered_goods_prop");
			ref Mat3 rotation = ref spawnPathFrame.Rotation;
			Vec3 o = spawnPathFrame.Origin.GetGroundVec3();
			_entity = GameEntity.Instantiate(scene, prefabName, new MatrixFrame(in rotation, in o));
			_entity.SetMobility(GameEntity.Mobility.Dynamic);
			foreach (GameEntity child in _entity.GetChildren())
			{
				Mission.Current.Scene.GetTerrainHeightAndNormal(child.GlobalPosition.AsVec2, out var height, out var normal);
				MatrixFrame frame = child.GetGlobalFrame();
				frame.origin.z = height;
				frame.rotation.u = normal;
				frame.rotation.Orthonormalize();
				child.SetGlobalFrame(in frame);
			}
			IEnumerable<GameEntity> enumerable = from c in _entity.GetChildren()
				where c.HasTag("caravan_animal_spawn")
				select c;
			int num = (int)((float)enumerable.Count() * 0.4f);
			foreach (GameEntity item in enumerable)
			{
				MatrixFrame globalFrame = item.GetGlobalFrame();
				string objectName;
				if (_isCamelCulture)
				{
					if (num > 0)
					{
						int num2 = MBRandom.RandomInt(_camelMountableHarnesses.Length);
						objectName = _camelMountableHarnesses[num2];
					}
					else
					{
						int num3 = MBRandom.RandomInt(_camelLoadHarnesses.Length);
						objectName = _camelLoadHarnesses[num3];
					}
				}
				else if (num > 0)
				{
					int num4 = MBRandom.RandomInt(_muleMountableHarnesses.Length);
					objectName = _muleMountableHarnesses[num4];
				}
				else
				{
					int num5 = MBRandom.RandomInt(_muleLoadHarnesses.Length);
					objectName = _muleLoadHarnesses[num5];
				}
				ItemRosterElement harnessRosterElement = new ItemRosterElement(Game.Current.ObjectManager.GetObject<ItemObject>(objectName));
				ItemRosterElement rosterElement = (_isCamelCulture ? ((num-- > 0) ? new ItemRosterElement(Game.Current.ObjectManager.GetObject<ItemObject>("pack_camel")) : new ItemRosterElement(Game.Current.ObjectManager.GetObject<ItemObject>("pack_camel_unmountable"))) : ((num-- > 0) ? new ItemRosterElement(Game.Current.ObjectManager.GetObject<ItemObject>("mule")) : new ItemRosterElement(Game.Current.ObjectManager.GetObject<ItemObject>("mule_unmountable"))));
				Mission current2 = Mission.Current;
				ref Vec3 origin = ref globalFrame.origin;
				Vec2 initialDirection = globalFrame.rotation.f.AsVec2.Normalized();
				Agent agent = current2.SpawnMonster(rosterElement, harnessRosterElement, in origin, in initialDirection);
				agent.SetAgentFlags(agent.GetAgentFlags() & ~AgentFlag.CanWander);
			}
			TacticalPosition firstScriptInFamilyDescending = _entity.GetFirstScriptInFamilyDescending<TacticalPosition>();
			if (firstScriptInFamilyDescending == null)
			{
				return;
			}
			foreach (Team team in Mission.Current.Teams)
			{
				team.TeamAI.TacticalPositions.Add(firstScriptInFamilyDescending);
			}
		}
	}
	public class DebugAgentTeleporterMissionController : MissionLogic
	{
		public override void AfterStart()
		{
		}

		public override void OnMissionTick(float dt)
		{
			Agent agent = null;
			int debugAgent = base.Mission.GetDebugAgent();
			foreach (Agent agent3 in base.Mission.Agents)
			{
				if (debugAgent == agent3.Index)
				{
					agent = agent3;
					break;
				}
			}
			if (agent == null && base.Mission.Agents.Count > 0)
			{
				int num = MBRandom.RandomInt(base.Mission.Agents.Count);
				int count = base.Mission.Agents.Count;
				int num2 = num;
				do
				{
					Agent agent2 = base.Mission.Agents[num2];
					if (agent2 != Agent.Main && agent2.IsActive())
					{
						agent = agent2;
						base.Mission.SetDebugAgent(num2);
						break;
					}
					num2 = (num2 + 1) % count;
				}
				while (num2 != num);
			}
			if (agent == null)
			{
				return;
			}
			MatrixFrame lastFinalRenderCameraFrame = base.Mission.Scene.LastFinalRenderCameraFrame;
			if (Input.DebugInput.IsKeyDown(InputKey.MiddleMouseButton))
			{
				base.Mission.Scene.RayCastForClosestEntityOrTerrain(lastFinalRenderCameraFrame.origin, lastFinalRenderCameraFrame.origin + -lastFinalRenderCameraFrame.rotation.u * 100f, out var _, 0.01f, BodyFlags.CommonCollisionExcludeFlags);
			}
			if (Input.DebugInput.IsKeyReleased(InputKey.MiddleMouseButton) && base.Mission.Scene.RayCastForClosestEntityOrTerrain(lastFinalRenderCameraFrame.origin, lastFinalRenderCameraFrame.origin + -lastFinalRenderCameraFrame.rotation.u * 100f, out var collisionDistance2, 0.01f, BodyFlags.CommonCollisionExcludeFlags))
			{
				Vec3 position = lastFinalRenderCameraFrame.origin + -lastFinalRenderCameraFrame.rotation.u * collisionDistance2;
				if (Input.DebugInput.IsHotKeyReleased("DebugAgentTeleportMissionControllerHotkeyTeleportMainAgent"))
				{
					agent.TeleportToPosition(position);
				}
				else
				{
					Vec2 vec = -lastFinalRenderCameraFrame.rotation.u.AsVec2;
					WorldPosition scriptedPosition = new WorldPosition(base.Mission.Scene, UIntPtr.Zero, position, hasValidZ: false);
					agent.SetScriptedPositionAndDirection(ref scriptedPosition, vec.RotationInRadians, addHumanLikeDelay: false, Agent.AIScriptedFrameFlags.NoAttack);
				}
			}
			if (Input.DebugInput.IsHotKeyPressed("DebugAgentTeleportMissionControllerHotkeyDisableScriptedMovement"))
			{
				agent.DisableScriptedMovement();
			}
		}
	}
	public class DebugObjectDestroyerMissionController : MissionLogic
	{
		private GameEntity _contouredEntity;

		public override void OnMissionTick(float dt)
		{
			base.OnMissionTick(dt);
			Vec3 lastFinalRenderCameraPosition = base.Mission.Scene.LastFinalRenderCameraPosition;
			Vec3 vec = -base.Mission.Scene.LastFinalRenderCameraFrame.rotation.u;
			float collisionDistance;
			WeakGameEntity collidedEntity;
			bool flag = Mission.Current.Scene.RayCastForClosestEntityOrTerrain(lastFinalRenderCameraPosition, lastFinalRenderCameraPosition + vec * 100f, out collisionDistance, out collidedEntity, 0.01f, BodyFlags.OnlyCollideWithRaycast);
			if (Input.DebugInput.IsShiftDown() && Agent.Main != null && collidedEntity.IsValid && !collidedEntity.HasScriptOfType<DestructableComponent>())
			{
				foreach (DestructableComponent item in Mission.Current.ActiveMissionObjects.Where((MissionObject x) => x is DestructableComponent))
				{
					if ((item.GameEntity.GlobalPosition - Agent.Main.Position).Length < 5f)
					{
						collidedEntity = item.GameEntity;
					}
				}
			}
			WeakGameEntity weakGameEntity = WeakGameEntity.Invalid;
			if (flag && (Input.DebugInput.IsKeyDown(InputKey.MiddleMouseButton) || Input.DebugInput.IsKeyReleased(InputKey.MiddleMouseButton)))
			{
				Vec3 vec2 = lastFinalRenderCameraPosition + vec * collisionDistance;
				if (collidedEntity.IsValid)
				{
					bool flag2 = Input.DebugInput.IsKeyReleased(InputKey.MiddleMouseButton);
					int weaponKind = 0;
					if (flag2)
					{
						weaponKind = (int)(Input.DebugInput.IsAltDown() ? Game.Current.ObjectManager.GetObject<ItemObject>("boulder").Id.InternalValue : ((!Input.DebugInput.IsControlDown()) ? Game.Current.ObjectManager.GetObject<ItemObject>("ballista_projectile").Id.InternalValue : Game.Current.ObjectManager.GetObject<ItemObject>("pot").Id.InternalValue));
					}
					WeakGameEntity weakGameEntity2 = collidedEntity;
					DestructableComponent destructableComponent2 = null;
					while (destructableComponent2 == null && weakGameEntity2.IsValid)
					{
						destructableComponent2 = weakGameEntity2.GetFirstScriptOfType<DestructableComponent>();
						weakGameEntity2 = weakGameEntity2.Parent;
					}
					if (destructableComponent2 != null && !destructableComponent2.IsDestroyed)
					{
						if (flag2)
						{
							if (Agent.Main != null)
							{
								DestructableComponent destructableComponent3 = destructableComponent2;
								Agent main = Agent.Main;
								Vec3 impactPosition = vec2 - vec * 0.1f;
								MissionWeapon weapon = new MissionWeapon(ItemObject.GetItemFromWeaponKind(weaponKind), null, null);
								destructableComponent3.TriggerOnHit(main, 400, impactPosition, vec, in weapon, -1, null);
							}
						}
						else
						{
							weakGameEntity = destructableComponent2.GameEntity;
						}
					}
				}
			}
			if (weakGameEntity != _contouredEntity && _contouredEntity != null)
			{
				_contouredEntity.SetContourColor(null);
			}
			_contouredEntity = GameEntity.CreateFromWeakEntity(weakGameEntity);
			if (_contouredEntity != null)
			{
				_contouredEntity.SetContourColor(4294967040u);
			}
		}
	}
