				TaleWorlds.Library.Debug.FailedAssert("Trying to start an objective that was already started.", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\Objectives\\MissionObjective.cs", "Start", 38);
				return;
