				return;
			}
			IsCompleted = true;
			OnComplete();
		}

		private void CheckNameUpdates()
		{
			bool flag = false;
			if (_cachedName != Name)
			{
				_cachedName = Name;
				flag = true;
			}
			if (_cachedDescription != Description)
			{
				_cachedDescription = Description;
				flag = true;
			}
			if (flag)
			{
				this.OnUpdated?.Invoke();
