			public readonly uint Color1Uint;

			public readonly Color Color2;

			public readonly uint Color2Uint;

			public readonly Color ClothingColor1;

			public readonly uint ClothingColor1Uint;

			public readonly Color ClothingColor2;

			public readonly uint ClothingColor2Uint;

			public readonly Color BannerBackgroundColor;

			public readonly uint BannerBackgroundColorUint;

			public readonly Color BannerForegroundColor;

			public readonly uint BannerForegroundColorUint;

			public MultiplayerCultureColorInfo(BasicCultureObject culture, bool swapColors)
			{
				Culture = culture;
				Color1 = Color.FromUint(Color1Uint = ((!swapColors) ? culture?.Color : culture?.Color2) ?? 0);
				Color2 = Color.FromUint(Color2Uint = ((!swapColors) ? culture?.Color2 : culture?.Color) ?? 0);
				ClothingColor1 = Color.FromUint(ClothingColor1Uint = ((!swapColors) ? culture?.Color : culture?.Color2) ?? 0);
				ClothingColor2 = Color.FromUint(ClothingColor2Uint = ((!swapColors) ? culture?.Color2 : culture?.Color) ?? 0);
				BannerBackgroundColor = Color.FromUint(BannerBackgroundColorUint = ((!swapColors) ? culture?.BackgroundColor1 : culture?.BackgroundColor2) ?? 0);
				BannerForegroundColor = Color.FromUint(BannerForegroundColorUint = ((!swapColors) ? culture?.ForegroundColor1 : culture?.ForegroundColor2) ?? 0);
			}
		}

		public readonly MultiplayerCultureColorInfo AttackerColors;

		public readonly MultiplayerCultureColorInfo DefenderColors;

		public MultiplayerBattleColors(MultiplayerCultureColorInfo attackerColors, MultiplayerCultureColorInfo defenderColors)
		{
			AttackerColors = attackerColors;
			DefenderColors = defenderColors;
		}

		public static MultiplayerBattleColors CreateWith(BasicCultureObject attackerCulture, BasicCultureObject defenderCulture)
		{
			return GetCultureColors(attackerCulture, defenderCulture);
		}

		public MultiplayerCultureColorInfo GetPeerColors(MissionPeer peer)
		{
			if (peer == null)
			{
				return AttackerColors;
			}
			if (AttackerColors.Culture == DefenderColors.Culture)
			{
				if (peer.Team != null)
				{
					if (peer.Team.Side != BattleSideEnum.Attacker)
					{
						return DefenderColors;
					}
					return AttackerColors;
				}
				return AttackerColors;
			}
			if (peer.Culture != AttackerColors.Culture)
			{
				return DefenderColors;
			}
			return AttackerColors;
		}

		private static MultiplayerBattleColors GetCultureColors(BasicCultureObject attackerCulture, BasicCultureObject defenderCulture)
		{
			if (attackerCulture == null)
			{
				attackerCulture = GetFallbackCulture();
			}
			if (defenderCulture == null)
			{
				defenderCulture = GetFallbackCulture();
			}
			bool swapColors = !string.IsNullOrEmpty(attackerCulture.StringId) && !string.IsNullOrEmpty(defenderCulture.StringId) && attackerCulture.StringId == defenderCulture.StringId;
			MultiplayerCultureColorInfo attackerColors = new MultiplayerCultureColorInfo(attackerCulture, swapColors: false);
			MultiplayerCultureColorInfo defenderColors = new MultiplayerCultureColorInfo(defenderCulture, swapColors);
			return new MultiplayerBattleColors(attackerColors, defenderColors);
		}

		private static BasicCultureObject GetFallbackCulture()
		{
			MBReadOnlyList<BasicCultureObject> objectTypeList = MBObjectManager.Instance.GetObjectTypeList<BasicCultureObject>();
			if (objectTypeList != null && objectTypeList.Count > 0)
			{
				return objectTypeList.FirstOrDefault();
			}
			TaleWorlds.Library.Debug.FailedAssert("No culture objects in the object manager", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\Multiplayer\\MultiplayerBattleColors.cs", "GetFallbackCulture", 114);
			return null;
		}
	}
}
namespace TaleWorlds.MountAndBlade.Missions.MissionLogics
{
	public class MissionHintLogic : MissionLogic
	{
		public delegate void MissionHintChangedDelegate(MissionHint previousHint, MissionHint newHint);

		public MissionHint ActiveHint { get; private set; }

		public event MissionHintChangedDelegate OnActiveHintChanged;

		public void SetActiveHint(MissionHint hint)
		{
			MissionHint activeHint = ActiveHint;
			ActiveHint = hint;
			this.OnActiveHintChanged?.Invoke(activeHint, ActiveHint);
		}

		public void Clear()
		{
			SetActiveHint(null);
		}
	}
	public class MissionObjectiveLogic : MissionLogic
	{
		private MissionObjective _currentObjective;

		public MissionObjective CurrentObjective => _currentObjective;

		public void StartObjective(MissionObjective objective)
		{
			if (objective == null || objective.IsStarted || objective.IsCompleted)
			{
				TaleWorlds.Library.Debug.FailedAssert("Trying to start an invalid mission objective.", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\MissionLogics\\MissionObjectiveLogic.cs", "StartObjective", 20);
				return;
			}
			CompleteCurrentObjective();
			_currentObjective = objective;
			if (_currentObjective != null && _currentObjective.GetIsActivationRequirementsMet())
			{
				StartObjectiveAux();
			}
		}

		private void StartObjectiveAux()
		{
			TaleWorlds.Library.Debug.Print("Mission: Start objective: " + _currentObjective.UniqueId);
			_currentObjective.Start();
		}

		public void CompleteCurrentObjective()
		{
			if (_currentObjective != null)
			{
				TaleWorlds.Library.Debug.Print("Mission: Complete objective: " + _currentObjective.UniqueId);
				_currentObjective.Complete();
				_currentObjective = null;
			}
		}

		public override void OnMissionTick(float dt)
		{
			base.OnMissionTick(dt);
			if (_currentObjective != null && !_currentObjective.IsStarted && _currentObjective.GetIsActivationRequirementsMet())
			{
				StartObjectiveAux();
			}
			_currentObjective?.Tick(dt);
			if (_currentObjective != null && _currentObjective.IsStarted && _currentObjective.GetIsCompletionRequirementsMet())
			{
				CompleteCurrentObjective();
			}
		}
	}
}
namespace TaleWorlds.MountAndBlade.Missions.Handlers
{
	public class BattleDeploymentHandler : DeploymentHandler
	{
		public BattleDeploymentHandler(bool isPlayerAttacker)
			: base(isPlayerAttacker)
		{
		}

		public override void OnRemoveBehavior()
		{
			base.OnRemoveBehavior();
			if (base.PlayerTeam != null)
			{
				base.PlayerTeam.OnOrderIssued -= OrderController_OnOrderIssued;
			}
		}

		public override void AfterStart()
		{
			base.AfterStart();
			base.PlayerTeam.OnOrderIssued += OrderController_OnOrderIssued;
		}

		public override void AutoDeployTeamUsingDeploymentPlan(Team team)
		{
			List<Formation> list = team.FormationsIncludingEmpty.ToList();
			if (list.Count <= 0)
			{
				return;
			}
			bool isTeleportingAgents = base.Mission.IsTeleportingAgents;
			base.Mission.IsTeleportingAgents = true;
			OrderController orderController = (team.IsPlayerTeam ? team.PlayerOrderController : team.MasterOrderController);
			orderController.SelectAllFormations();
			SetDefaultFormationOrders(orderController);
			orderController.ClearSelectedFormations();
			IMissionDeploymentPlan deploymentPlan = base.Mission.DeploymentPlan;
			if (deploymentPlan.IsPlanMade(team))
			{
				foreach (Formation item in list)
				{
					IFormationDeploymentPlan formationPlan = deploymentPlan.GetFormationPlan(team, item.FormationIndex);
					base.Mission.GetFormationSpawnFrame(item.Team, item.FormationIndex, isReinforcement: false, out var spawnPosition, out var spawnDirection);
					if (formationPlan.HasDimensions)
					{
						item.SetFormOrder(FormOrder.FormOrderCustom(formationPlan.PlannedWidth));
					}
					item.SetMovementOrder(MovementOrder.MovementOrderMove(spawnPosition));
					item.SetFacingOrder(FacingOrder.FacingOrderLookAtDirection(spawnDirection));
					item.SetPositioning(spawnPosition, spawnDirection, item.ArrangementOrder.GetUnitSpacing());
					item.ApplyActionOnEachUnit(delegate(Agent agent)
					{
						agent.ForceUpdateCachedAndFormationValues(updateOnlyMovement: true, arrangementChangeAllowed: false);
					});
					item.SetHasPendingUnitPositions(hasPendingUnitPositions: false);
					item.SetMovementOrder(MovementOrder.MovementOrderStop);
				}
			}
			else
			{
				TaleWorlds.Library.Debug.FailedAssert("Failed to deploy team. Initial deployment plan is not made yet.", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\Missions\\MissionLogics\\BattleDeploymentHandler.cs", "AutoDeployTeamUsingDeploymentPlan", 84);
			}
			foreach (Formation item2 in list)
			{
				item2.ApplyActionOnEachUnit(delegate(Agent agent)
				{
					agent.ForceUpdateCachedAndFormationValues(updateOnlyMovement: true, arrangementChangeAllowed: false);
				});
				item2.SetHasPendingUnitPositions(hasPendingUnitPositions: false);
			}
			base.Mission.IsTeleportingAgents = isTeleportingAgents;
		}

		public override void ForceUpdateAllUnits()
		{
			DeploymentHandler.OrderController_OnOrderIssued_Aux(OrderType.Move, base.PlayerTeam.FormationsIncludingSpecialAndEmpty, null);
		}

		public void SetDefaultFormationOrders(OrderController orderController)
		{
			orderController.SetOrder(OrderType.AIControlOff);
			orderController.SetFormationUpdateEnabledAfterSetOrder(value: false);
			orderController.SetOrder(OrderType.Mount);
			orderController.SetOrder(OrderType.FireAtWill);
			orderController.SetOrder(OrderType.ArrangementLine);
			orderController.SetOrder(OrderType.StandYourGround);
			orderController.SetOrder((base.Mission.IsSiegeBattle || base.Mission.IsSallyOutBattle) ? OrderType.AIControlOn : OrderType.AIControlOff);
			orderController.SetFormationUpdateEnabledAfterSetOrder(value: true);
		}

		private void OrderController_OnOrderIssued(OrderType orderType, MBReadOnlyList<Formation> appliedFormations, OrderController orderController, params object[] delegateParams)
		{
			DeploymentHandler.OrderController_OnOrderIssued_Aux(orderType, appliedFormations, orderController, delegateParams);
		}
	}
	public class SiegeDeploymentHandler : BattleDeploymentHandler
	{
		private IMissionSiegeWeaponsController _defenderSiegeWeaponsController;

		private IMissionSiegeWeaponsController _attackerSiegeWeaponsController;

		private WorldPosition _defenderReferencePosition;

		public IEnumerable<DeploymentPoint> PlayerDeploymentPoints { get; private set; }

		public IEnumerable<DeploymentPoint> AllDeploymentPoints { get; private set; }

		public SiegeDeploymentHandler(bool isPlayerAttacker)
			: base(isPlayerAttacker)
		{
		}

		public override void OnBehaviorInitialize()
		{
			base.OnBehaviorInitialize();
			MissionSiegeEnginesLogic missionBehavior = base.Mission.GetMissionBehavior<MissionSiegeEnginesLogic>();
			_defenderSiegeWeaponsController = missionBehavior.GetSiegeWeaponsController(BattleSideEnum.Defender);
			_attackerSiegeWeaponsController = missionBehavior.GetSiegeWeaponsController(BattleSideEnum.Attacker);
			_defenderReferencePosition = WorldPosition.Invalid;
		}

		public override void OnRemoveBehavior()
		{
			base.OnRemoveBehavior();
			base.Mission.IsFormationUnitPositionAvailable_AdditionalCondition -= Mission_IsFormationUnitPositionAvailable_AdditionalCondition;
		}

		public override void AfterStart()
		{
			base.AfterStart();
			AllDeploymentPoints = Mission.Current.ActiveMissionObjects.FindAllWithType<DeploymentPoint>();
			PlayerDeploymentPoints = AllDeploymentPoints.Where((DeploymentPoint dp) => dp.Side == base.PlayerTeam.Side);
			foreach (DeploymentPoint allDeploymentPoint in AllDeploymentPoints)
			{
				allDeploymentPoint.OnDeploymentStateChanged += OnDeploymentStateChange;
			}
			base.Mission.IsFormationUnitPositionAvailable_AdditionalCondition += Mission_IsFormationUnitPositionAvailable_AdditionalCondition;
			foreach (DeploymentPoint playerDeploymentPoint in PlayerDeploymentPoints)
			{
				playerDeploymentPoint.OnDeployOrDisband += OnWeaponDeployOrDisband;
			}
			base.Mission.PlayerTeam.OnFormationsChangedInDeployment += OnFormationsChanged;
		}

		private void OnWeaponDeployOrDisband(DeploymentPoint deploymentPoint)
		{
			if (deploymentPoint.IsDeployed)
			{
				(deploymentPoint.DeployedWeapon as SiegeWeapon)?.TickAuxForInit();
				AutoAssignDetachmentsForDeployment(base.PlayerTeam);
			}
			foreach (Formation item in base.PlayerTeam.FormationsIncludingEmpty)
			{
				item.ApplyActionOnEachUnit(delegate(Agent agent)
				{
					agent.ForceUpdateCachedAndFormationValues(updateOnlyMovement: false, arrangementChangeAllowed: false);
				});
			}
		}

		public override void FinishDeployment()
		{
			foreach (DeploymentPoint allDeploymentPoint in AllDeploymentPoints)
			{
				allDeploymentPoint.OnDeploymentStateChanged -= OnDeploymentStateChange;
			}
			foreach (DeploymentPoint playerDeploymentPoint in PlayerDeploymentPoints)
			{
				playerDeploymentPoint.OnDeployOrDisband -= OnWeaponDeployOrDisband;
			}
			base.Mission.PlayerTeam.OnFormationsChangedInDeployment -= OnFormationsChanged;
			base.FinishDeployment();
		}

		public void DeployAllSiegeWeaponsOfPlayer()
		{
			BattleSideEnum side = (IsPlayerAttacker ? BattleSideEnum.Attacker : BattleSideEnum.Defender);
			new SiegeWeaponAutoDeployer((from dp in base.Mission.ActiveMissionObjects.FindAllWithType<DeploymentPoint>()
				where dp.Side == side
				select dp).ToList(), GetWeaponsControllerOfSide(side)).DeployAll(side);
		}

		public int GetMaxDeployableWeaponCountOfPlayer(Type weapon)
		{
			return GetWeaponsControllerOfSide(IsPlayerAttacker ? BattleSideEnum.Attacker : BattleSideEnum.Defender).GetMaxDeployableWeaponCount(weapon);
		}

		public void DeployAllSiegeWeaponsOfAi()
		{
			BattleSideEnum side = ((!IsPlayerAttacker) ? BattleSideEnum.Attacker : BattleSideEnum.Defender);
			new SiegeWeaponAutoDeployer((from dp in base.Mission.ActiveMissionObjects.FindAllWithType<DeploymentPoint>()
				where dp.Side == side
				select dp).ToList(), GetWeaponsControllerOfSide(side)).DeployAll(side);
			RemoveDeploymentPoints(side);
		}

		public void RemoveDeploymentPoints(BattleSideEnum side)
		{
			DeploymentPoint[] array = (from dp in base.Mission.ActiveMissionObjects.FindAllWithType<DeploymentPoint>()
				where dp.Side == side
				select dp).ToArray();
			foreach (DeploymentPoint deploymentPoint in array)
			{
				SynchedMissionObject[] array2 = deploymentPoint.DeployableWeapons.ToArray();
				foreach (SynchedMissionObject synchedMissionObject in array2)
				{
					if ((deploymentPoint.DeployedWeapon == null || !synchedMissionObject.GameEntity.IsVisibleIncludeParents()) && synchedMissionObject is SiegeWeapon siegeWeapon)
					{
						siegeWeapon.SetDisabledSynched();
					}
				}
				deploymentPoint.SetDisabledSynched();
			}
		}

		public void RemoveUnavailableDeploymentPoints(BattleSideEnum side)
		{
			IMissionSiegeWeaponsController weapons = ((side == BattleSideEnum.Defender) ? _defenderSiegeWeaponsController : _attackerSiegeWeaponsController);
			DeploymentPoint[] array = (from dp in base.Mission.ActiveMissionObjects.FindAllWithType<DeploymentPoint>()
				where dp.Side == side
				select dp).ToArray();
			foreach (DeploymentPoint deploymentPoint in array)
			{
				if (deploymentPoint.DeployableWeaponTypes.Any((Type wt) => weapons.GetMaxDeployableWeaponCount(wt) > 0))
				{
					continue;
				}
				foreach (SiegeWeapon item in deploymentPoint.DeployableWeapons.Select((SynchedMissionObject sw) => sw as SiegeWeapon))
				{
					item.SetDisabledSynched();
				}
				deploymentPoint.SetDisabledSynched();
			}
		}

		public void UnHideDeploymentPoints(BattleSideEnum side)
		{
			foreach (DeploymentPoint item in from dp in base.Mission.ActiveMissionObjects.FindAllWithType<DeploymentPoint>()
				where !dp.IsDisabled && dp.Side == side
				select dp)
			{
				item.Show();
			}
		}

		public int GetDeployableWeaponCountOfPlayer(Type weapon)
		{
			return GetWeaponsControllerOfSide(IsPlayerAttacker ? BattleSideEnum.Attacker : BattleSideEnum.Defender).GetMaxDeployableWeaponCount(weapon) - PlayerDeploymentPoints.Count((DeploymentPoint dp) => dp.IsDeployed && MissionSiegeWeaponsController.GetWeaponType(dp.DeployedWeapon) == weapon);
		}

		public void AutoDeployTeamUsingTeamAI(Team team, bool autoAssignDetachments = true)
		{
			List<Formation> list = team.FormationsIncludingEmpty.ToList();
			bool allowAiTicking = base.Mission.AllowAiTicking;
			bool forceTickOccasionally = base.Mission.ForceTickOccasionally;
			bool isTeleportingAgents = base.Mission.IsTeleportingAgents;
			base.Mission.AllowAiTicking = true;
			base.Mission.ForceTickOccasionally = true;
			base.Mission.IsTeleportingAgents = true;
			OrderController orderController = (team.IsPlayerTeam ? team.PlayerOrderController : team.MasterOrderController);
			orderController.SelectAllFormations();
			SetDefaultFormationOrders(orderController);
			team.ResetTactic();
			team.Tick(0f);
			foreach (Formation item in list)
			{
				item.ApplyActionOnEachUnit(delegate(Agent agent)
				{
					agent.ForceUpdateCachedAndFormationValues(updateOnlyMovement: false, arrangementChangeAllowed: false);
				});
				item.SetHasPendingUnitPositions(hasPendingUnitPositions: false);
			}
			orderController.ClearSelectedFormations();
			if (autoAssignDetachments)
			{
				AutoAssignDetachmentsForDeployment(team);
			}
			base.Mission.IsTeleportingAgents = isTeleportingAgents;
			base.Mission.ForceTickOccasionally = forceTickOccasionally;
			base.Mission.AllowAiTicking = allowAiTicking;
		}

		public void AutoAssignDetachmentsForDeployment(Team team)
		{
			List<Formation> list = team.FormationsIncludingEmpty.ToList();
			bool allowAiTicking = base.Mission.AllowAiTicking;
			bool isTeleportingAgents = base.Mission.IsTeleportingAgents;
			base.Mission.AllowAiTicking = true;
			base.Mission.IsTeleportingAgents = true;
			if (!team.DetachmentManager.Detachments.IsEmpty())
			{
				foreach (Formation item in list)
				{
					item.ApplyActionOnEachUnit(delegate(Agent agent)
					{
						agent.Formation?.Team.DetachmentManager.TickAgent(agent);
					});
				}
				int num = 0;
				int num2 = 0;
				foreach (var detachment in team.DetachmentManager.Detachments)
				{
					num += detachment.Item1.GetNumberOfUsableSlots();
				}
				foreach (Formation item2 in team.FormationsIncludingEmpty)
				{
					num2 += item2.CountOfDetachableNonPlayerUnits;
				}
				for (int i = 0; i < TaleWorlds.Library.MathF.Min(num, num2); i++)
				{
					team.DetachmentManager.TickDetachments();
				}
				foreach (Formation item3 in list)
				{
					item3.ApplyActionOnEachUnit(delegate(Agent agent)
					{
						if (agent.Detachment != null)
						{
							agent.ForceUpdateCachedAndFormationValues(updateOnlyMovement: false, arrangementChangeAllowed: false);
						}
					});
				}
			}
			base.Mission.IsTeleportingAgents = isTeleportingAgents;
			base.Mission.AllowAiTicking = allowAiTicking;
		}

		private void OnFormationsChanged(Team team)
		{
			AutoAssignDetachmentsForDeployment(team);
		}

		protected bool Mission_IsFormationUnitPositionAvailable_AdditionalCondition(WorldPosition position, Team team)
		{
			if (team != null && team.Side == BattleSideEnum.Defender)
			{
				Scene scene = base.Mission.Scene;
				if (!_defenderReferencePosition.IsValid)
				{
					WeakGameEntity weakGameEntity = scene.FindWeakEntityWithTag("defender_infantry");
					_defenderReferencePosition = new WorldPosition(scene, UIntPtr.Zero, weakGameEntity.GlobalPosition, hasValidZ: false);
				}
				return scene.DoesPathExistBetweenPositions(_defenderReferencePosition, position);
			}
			return true;
		}

		private void OnDeploymentStateChange(DeploymentPoint deploymentPoint, SynchedMissionObject targetObject)
		{
			if (!deploymentPoint.IsDeployed && base.PlayerTeam.DetachmentManager.ContainsDetachment(deploymentPoint.DisbandedWeapon as IDetachment))
			{
				base.PlayerTeam.DetachmentManager.DestroyDetachment(deploymentPoint.DisbandedWeapon as IDetachment);
			}
			if (targetObject is SiegeWeapon missionWeapon)
			{
				IMissionSiegeWeaponsController weaponsControllerOfSide = GetWeaponsControllerOfSide(deploymentPoint.Side);
				if (deploymentPoint.IsDeployed)
				{
					weaponsControllerOfSide.OnWeaponDeployed(missionWeapon);
				}
				else
				{
					weaponsControllerOfSide.OnWeaponUndeployed(missionWeapon);
				}
			}
		}

		private IMissionSiegeWeaponsController GetWeaponsControllerOfSide(BattleSideEnum side)
		{
			if (side != 0)
			{
				return _attackerSiegeWeaponsController;
			}
			return _defenderSiegeWeaponsController;
		}

		public Vec2 GetEstimatedAverageDefenderPosition()
		{
			base.Mission.GetFormationSpawnFrame(Mission.Current.DefenderTeam, FormationClass.Infantry, isReinforcement: false, out var spawnPosition, out var _);
			return spawnPosition.AsVec2;
		}

		[Conditional("DEBUG")]
		private void AssertSiegeWeapons(IEnumerable<DeploymentPoint> allDeploymentPoints)
		{
			HashSet<SynchedMissionObject> hashSet = new HashSet<SynchedMissionObject>();
			foreach (SynchedMissionObject item in allDeploymentPoints.SelectMany((DeploymentPoint amo) => amo.DeployableWeapons))
			{
				if (!hashSet.Add(item))
				{
					break;
				}
			}
		}
	}
}
