namespace TaleWorlds.MountAndBlade.DividableTasks
{
	public class FindMostDangerousThreat : DividableTask
	{
		private Agent _targetAgent;

		private FormationSearchThreatTask _formationSearchThreatTask;

		private List<Threat> _threats;

		private RangedSiegeWeapon _weapon;

		private Threat _currentThreat;

		private bool _hasOngoingThreatTask;

		public FindMostDangerousThreat(DividableTask continueToTask = null)
			: base(continueToTask)
		{
			SetTaskFinished();
			_formationSearchThreatTask = new FormationSearchThreatTask();
		}

		protected override bool UpdateExtra()
		{
			bool flag = false;
			if (_hasOngoingThreatTask)
			{
				if (_formationSearchThreatTask.Update())
				{
					_hasOngoingThreatTask = false;
					if (!(flag = _formationSearchThreatTask.GetResult(out _targetAgent)))
					{
						_threats.Remove(_currentThreat);
						_currentThreat = null;
					}
				}
			}
			else
			{
				int num = 5;
				do
				{
					num--;
					flag = true;
					int num2 = -1;
					float num3 = float.MinValue;
					bool flag2 = false;
					for (int i = 0; i < _threats.Count; i++)
					{
						Threat threat = _threats[i];
						if (!flag2 || threat.ForceTarget)
						{
							if (!flag2 && threat.ForceTarget)
							{
								flag2 = true;
								num3 = threat.ThreatValue;
								num2 = i;
							}
							else if (threat.ThreatValue > num3)
							{
								num3 = threat.ThreatValue;
								num2 = i;
							}
						}
					}
					if (num2 < 0)
					{
						continue;
					}
					_currentThreat = _threats[num2];
					if (_currentThreat.Formation != null)
					{
						_formationSearchThreatTask.Prepare(_currentThreat.Formation, _weapon);
						_hasOngoingThreatTask = true;
						flag = false;
						break;
					}
					if ((_currentThreat.TargetableObject == null && _currentThreat.Agent == null) || !_weapon.CanShootAtThreat(_currentThreat))
					{
						if (!_currentThreat.ForceTarget)
						{
							_threats.RemoveAt(num2);
						}
						_currentThreat = null;
						flag = false;
					}
				}
				while (!flag && num > 0);
			}
			if (!flag)
			{
				return _threats.Count == 0;
			}
			return true;
		}

		public void Prepare(List<Threat> threats, RangedSiegeWeapon weapon)
		{
			ResetTaskStatus();
			_hasOngoingThreatTask = false;
			_weapon = weapon;
			_threats = threats;
			foreach (Threat threat in _threats)
			{
				threat.ThreatValue *= 0.9f + MBRandom.RandomFloat * 0.2f;
			}
			if (_currentThreat != null)
			{
				_currentThreat = _threats.SingleOrDefault((Threat t) => t.Equals(_currentThreat));
				if (_currentThreat != null)
				{
					_currentThreat.ThreatValue *= 2f;
				}
			}
		}

		public Threat GetResult(out Agent targetAgent)
		{
			targetAgent = _targetAgent;
			return _currentThreat;
		}
	}
	public class FormationSearchThreatTask : DividableTask
	{
		private Agent _targetAgent;

		private const float CheckCountRatio = 0.1f;

		private RangedSiegeWeapon _weapon;

		private Formation _formation;

		private int _storedIndex;

		private int _checkCountPerTick;

		private bool _result;

		protected override bool UpdateExtra()
		{
			_result = _formation.HasUnitWithConditionLimitedRandom((Agent agent) => _weapon.CanShootAtAgent(agent), _storedIndex, _checkCountPerTick, out _targetAgent);
			_storedIndex += _checkCountPerTick;
			if (_storedIndex < _formation.CountOfUnits)
			{
				return _result;
			}
			return true;
		}

		public void Prepare(Formation formation, RangedSiegeWeapon weapon)
		{
			ResetTaskStatus();
			_formation = formation;
			_weapon = weapon;
			_storedIndex = 0;
			_checkCountPerTick = (int)((float)_formation.CountOfUnits * 0.1f) + 1;
		}

		public bool GetResult(out Agent targetAgent)
		{
			targetAgent = _targetAgent;
			return _result;
		}
	}
}
namespace TaleWorlds.MountAndBlade.AI
{
	public class SiegeWeaponAutoDeployer
	{
		private IMissionSiegeWeaponsController siegeWeaponsController;

		private List<DeploymentPoint> deploymentPoints;

		public SiegeWeaponAutoDeployer(List<DeploymentPoint> deploymentPoints, IMissionSiegeWeaponsController weaponsController)
		{
			this.deploymentPoints = deploymentPoints;
			siegeWeaponsController = weaponsController;
		}

		public void DeployAll(BattleSideEnum side)
		{
			switch (side)
			{
			case BattleSideEnum.Attacker:
				DeployAllForAttackers();
				break;
			case BattleSideEnum.Defender:
				DeployAllForDefenders();
				break;
			default:
				TaleWorlds.Library.Debug.FailedAssert("Invalid side", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.MountAndBlade\\AI\\SiegeWeaponAutoDeployer.cs", "DeployAll", 32);
				break;
			}
		}

		private bool DeployWeaponFrom(DeploymentPoint dp)
		{
			IEnumerable<Type> source = dp.DeployableWeaponTypes.Where((Type t) => deploymentPoints.Count((DeploymentPoint dep) => dep.IsDeployed && MissionSiegeWeaponsController.GetWeaponType(dep.DeployedWeapon) == t) < siegeWeaponsController.GetMaxDeployableWeaponCount(t));
			if (!source.IsEmpty())
			{
				Type t2 = source.MaxBy((Type t) => GetWeaponValue(t));
				dp.Deploy(t2);
				return true;
			}
			return false;
		}

		private void DeployAllForAttackers()
		{
			List<DeploymentPoint> list = deploymentPoints.Where((DeploymentPoint dp) => !dp.IsDisabled && !dp.IsDeployed).ToList();
			list.Shuffle();
			int num = deploymentPoints.Count((DeploymentPoint dp) => dp.GetDeploymentPointType() == DeploymentPoint.DeploymentPointType.Breach);
			bool flag = Mission.Current.AttackerTeam != Mission.Current.PlayerTeam && num >= 2;
			foreach (DeploymentPoint item in list)
			{
				if (!flag || item.GetDeploymentPointType() == DeploymentPoint.DeploymentPointType.Ranged)
				{
					DeployWeaponFrom(item);
				}
			}
		}

		private void DeployAllForDefenders()
		{
			Mission current = Mission.Current;
			_ = current.Scene;
			List<ICastleKeyPosition> castleKeyPositions = (from amo in current.ActiveMissionObjects
				select amo.GameEntity into e
				select e.GetFirstScriptOfType<UsableMachine>() into um
				where um is ICastleKeyPosition
				select um).Cast<ICastleKeyPosition>().Where(delegate(ICastleKeyPosition x)
			{
				IPrimarySiegeWeapon attackerSiegeWeapon = x.AttackerSiegeWeapon;
				return attackerSiegeWeapon == null || attackerSiegeWeapon.WeaponSide != FormationAI.BehaviorSide.BehaviorSideNotSet;
			}).ToList();
			List<DeploymentPoint> list = deploymentPoints.Where((DeploymentPoint dp) => !dp.IsDeployed).ToList();
			while (!list.IsEmpty())
			{
				Threat maxThreat = RangedSiegeWeaponAi.ThreatSeeker.GetMaxThreat(castleKeyPositions);
				Vec3 mostDangerousThreatPosition = maxThreat.TargetingPosition;
				DeploymentPoint deploymentPoint = list.MinBy((DeploymentPoint dp) => dp.GameEntity.GlobalPosition.DistanceSquared(mostDangerousThreatPosition));
				if (DeployWeaponFrom(deploymentPoint))
				{
					maxThreat.ThreatValue *= 0.5f;
				}
				list.Remove(deploymentPoint);
			}
		}

		protected virtual float GetWeaponValue(Type weaponType)
		{
			if (weaponType == typeof(BatteringRam) || weaponType == typeof(SiegeTower) || weaponType == typeof(SiegeLadder))
			{
				return 0.9f + MBRandom.RandomFloat * 0.2f;
			}
			if (typeof(RangedSiegeWeapon).IsAssignableFrom(weaponType))
			{
				return 0.7f + MBRandom.RandomFloat * 0.2f;
			}
			return 1f;
		}
	}
}
namespace TaleWorlds.MountAndBlade.AI.AgentComponents
{
	public class ScriptedMovementComponent : AgentComponent
	{
		private bool _isInDialogueRange;

		private readonly bool _isCharacterToTalkTo;

		private readonly float _dialogueTriggerProximity = 10f;

		private readonly float _agentSpeedLimit;

		private Agent _targetAgent;

		public ScriptedMovementComponent(Agent agent, bool isCharacterToTalkTo = false, float dialogueProximityOffset = 0f)
			: base(agent)
		{
			_isCharacterToTalkTo = isCharacterToTalkTo;
			_agentSpeedLimit = Agent.GetMaximumSpeedLimit();
			if (!_isCharacterToTalkTo)
			{
				Agent.SetMaximumSpeedLimit(MBRandom.RandomFloatRanged(0.2f, 0.3f), isMultiplier: true);
				_dialogueTriggerProximity += dialogueProximityOffset;
			}
		}

		public void SetTargetAgent(Agent targetAgent)
		{
			_targetAgent = targetAgent;
		}

		public override void OnTick(float dt)
		{
			if (!Agent.Mission.AllowAiTicking || !Agent.IsAIControlled || _targetAgent == null)
			{
				return;
			}
			bool flag = _targetAgent.State != AgentState.Routed && _targetAgent.State != AgentState.Deleted;
			if (!_isInDialogueRange)
			{
				float num = _targetAgent.Position.DistanceSquared(Agent.Position);
				_isInDialogueRange = num <= _dialogueTriggerProximity * _dialogueTriggerProximity;
				if (_isInDialogueRange)
				{
					Agent.SetScriptedFlags(Agent.GetScriptedFlags() & ~Agent.AIScriptedFrameFlags.DoNotRun);
					Agent.DisableScriptedMovement();
					if (flag)
					{
						Agent.SetLookAgent(_targetAgent);
					}
					Agent.SetMaximumSpeedLimit(_agentSpeedLimit, isMultiplier: false);
				}
				else
				{
					WorldPosition position = _targetAgent.Position.ToWorldPosition();
					Agent.SetScriptedPosition(ref position, addHumanLikeDelay: false, Agent.AIScriptedFrameFlags.DoNotRun);
				}
			}
			else if (!flag)
			{
				Agent.SetLookAgent(null);
			}
		}

		public bool ShouldConversationStartWithAgent()
		{
			if (_targetAgent != null && _isInDialogueRange)
			{
				return _isCharacterToTalkTo;
			}
			return false;
		}

		public void Reset()
		{
			_targetAgent = null;
			_isInDialogueRange = false;
		}
	}
}
